# ═══════════════════════════════════════════════════════════════════════════════
# ⚡ PATCH QUANTUM PERFORMANCE + ERROS AMIGÁVEIS - SENIOR FULL
# Objetivo:
# - Melhorar agilidade de abertura/fechamento de telas e processos repetitivos.
# - Reduzir travamentos visuais em operações longas.
# - Registrar erros técnicos sem assustar o usuário.
# - Exibir mensagens mais claras e agradáveis.
# - Não apagar nem alterar dados do cliente.
# ═══════════════════════════════════════════════════════════════════════════════
def _quantum_perf_boot_patch():
    try:
        import os as _os, sys as _sys, gc as _gc, logging as _logging, traceback as _traceback
        from logging.handlers import RotatingFileHandler as _RotatingFileHandler

        try:
            _base = r"C:\Quantum\logs"
            _os.makedirs(_base, exist_ok=True)
        except Exception:
            _base = _os.getcwd()

        _log_path = _os.path.join(_base, "quantum_erros_amigaveis.log")
        _logger = _logging.getLogger("quantum_friendly_errors")
        if not _logger.handlers:
            _logger.setLevel(_logging.INFO)
            _handler = _RotatingFileHandler(_log_path, maxBytes=2_000_000, backupCount=5, encoding="utf-8")
            _handler.setFormatter(_logging.Formatter("%(asctime)s | %(levelname)s | %(message)s"))
            _logger.addHandler(_handler)

        globals()["QUANTUM_FRIENDLY_LOGGER"] = _logger
        globals()["QUANTUM_PERFORMANCE_MODE"] = True

        # GC menos agressivo em telas grandes; melhora microtravadas sem desativar segurança.
        try:
            _gc.set_threshold(1200, 20, 20)
        except Exception:
            pass

        def _friendly_message(exc):
            txt = str(exc or "").strip()
            low = txt.lower()
            if "access denied" in low or "permission denied" in low or "1045" in low:
                return "Não foi possível acessar o banco ou arquivo. Verifique usuário, senha, permissão e se o MySQL está ativo."
            if "unknown column" in low or "no such column" in low or "doesn't exist" in low or "no such table" in low:
                return "O banco de dados precisa ser atualizado. Reinicie o sistema para a verificação automática criar tabelas/colunas faltantes."
            if "lost connection" in low or "can't connect" in low or "connection refused" in low or "2003" in low:
                return "A conexão com o banco falhou. Confirme se o servidor MySQL está ligado e se o endereço no config.ini está correto."
            if "duplicate" in low or "already exists" in low:
                return "Já existe um registro com esses dados. Confira código, nome ou cadastro duplicado."
            if "printer" in low or "impress" in low:
                return "Não foi possível imprimir agora. Confira se a impressora está ligada, instalada e definida corretamente."
            if "timeout" in low or "timed out" in low:
                return "A operação demorou demais para responder. Tente novamente ou verifique a conexão/rede."
            return "O sistema encontrou uma falha inesperada, mas ela foi registrada com segurança. Tente novamente; se persistir, envie o log ao suporte."

        globals()["quantum_friendly_error_message"] = _friendly_message

        def _log_exception(origin, exc):
            try:
                _logger.error("%s | %s: %s\n%s", origin, type(exc).__name__, exc, _traceback.format_exc())
            except Exception:
                pass

        globals()["quantum_log_exception"] = _log_exception

        def _sys_excepthook(exc_type, exc, tb):
            try:
                _logger.critical("ERRO GLOBAL | %s: %s\n%s", exc_type.__name__, exc, "".join(_traceback.format_exception(exc_type, exc, tb)))
            except Exception:
                pass
            try:
                # Evita popup técnico em erros de encerramento.
                if "KeyboardInterrupt" not in exc_type.__name__:
                    import tkinter.messagebox as _mb
                    _mb.showerror("Ops, algo não saiu como esperado", _friendly_message(exc))
            except Exception:
                pass

        try:
            _sys.excepthook = _sys_excepthook
        except Exception:
            pass

        try:
            import threading as _threading
            def _thread_excepthook(args):
                try:
                    _logger.error("ERRO EM PROCESSO INTERNO | %s: %s\n%s",
                                  args.exc_type.__name__, args.exc_value,
                                  "".join(_traceback.format_exception(args.exc_type, args.exc_value, args.exc_traceback)))
                except Exception:
                    pass
            _threading.excepthook = _thread_excepthook
        except Exception:
            pass

    except Exception:
        pass

try:
    _quantum_perf_boot_patch()
except Exception:
    pass


def quantum_run_bg(task, on_done=None, on_error=None, description="Processando..."):
    """Executa tarefa pesada em segundo plano para reduzir travamento de tela."""
    try:
        import threading
        def _runner():
            try:
                result = task()
                if callable(on_done):
                    try:
                        on_done(result)
                    except Exception as e:
                        try:
                            quantum_log_exception("callback pós-processo", e)
                        except Exception:
                            pass
            except Exception as e:
                try:
                    quantum_log_exception(description, e)
                except Exception:
                    pass
                if callable(on_error):
                    try:
                        on_error(e)
                    except Exception:
                        pass
        t = threading.Thread(target=_runner, daemon=True)
        t.start()
        return t
    except Exception as e:
        try:
            quantum_log_exception("quantum_run_bg", e)
        except Exception:
            pass
        return None


def quantum_apply_tk_error_handler(root):
    """Aplica tratamento amigável para erros de callbacks Tkinter."""
    try:
        import traceback
        import tkinter.messagebox as messagebox

        def _handler(exc, val, tb):
            try:
                if "QUANTUM_FRIENDLY_LOGGER" in globals():
                    QUANTUM_FRIENDLY_LOGGER.error(
                        "ERRO TKINTER | %s: %s\n%s",
                        getattr(exc, "__name__", str(exc)),
                        val,
                        "".join(traceback.format_exception(exc, val, tb))
                    )
            except Exception:
                pass
            try:
                msg = quantum_friendly_error_message(val) if "quantum_friendly_error_message" in globals() else "Ocorreu uma falha inesperada."
                messagebox.showerror("Ops, algo não saiu como esperado", msg, parent=root)
            except Exception:
                pass

        root.report_callback_exception = _handler
    except Exception:
        pass


def quantum_optimize_tk_window(win):
    """Ajustes leves para abertura/fechamento de janelas mais suave."""
    try:
        win.update_idletasks()
    except Exception:
        pass
    try:
        win.resizable(True, True)
    except Exception:
        pass
    try:
        # Evita que operações pendentes fiquem acumuladas na abertura.
        win.after_idle(lambda: None)
    except Exception:
        pass


def quantum_db_apply_speed_pragmas_if_sqlite(conn):
    """Otimização segura para SQLite, quando o sistema estiver usando SQLite."""
    try:
        cur = conn.cursor()
        cur.execute("PRAGMA journal_mode=WAL")
        cur.execute("PRAGMA synchronous=NORMAL")
        cur.execute("PRAGMA temp_store=MEMORY")
        cur.execute("PRAGMA cache_size=-12000")
    except Exception:
        pass


def quantum_db_create_safe_indexes(db_execute):
    """Cria índices seguros para consultas comuns, sem apagar dados."""
    indexes = [
        ("idx_produtos_codigo", "produtos", "codigo"),
        ("idx_produtos_nome", "produtos", "nome"),
        ("idx_clientes_nome", "clientes", "nome"),
        ("idx_vendas_data", "vendas", "data"),
        ("idx_vendas_usuario", "vendas", "usuario"),
        ("idx_itens_venda_id", "itens_venda", "venda_id"),
        ("idx_caixa_data", "caixa_movimentos", "data"),
    ]
    for idx, table, col in indexes:
        try:
            db_execute(f"CREATE INDEX IF NOT EXISTS {idx} ON {table} ({col})")
        except Exception:
            pass


