QUANTUM_ULTIMATE_FULL_SENIOR = True
QUANTUM_ULTIMATE_BUILD = "2026.06.16 - Ultimate Full Senior OneFile"

def quantum_ultimate_safe_str(value, default=""):
    try:
        if value is None:
            return default
        return str(value)
    except Exception:
        return default

def quantum_ultimate_money(value):
    try:
        return "R$ {:,.2f}".format(float(value)).replace(",", "X").replace(".", ",").replace("X", ".")
    except Exception:
        return "R$ 0,00"

def quantum_ultimate_now():
    try:
        import datetime
        return datetime.datetime.now().strftime("%d/%m/%Y %H:%M:%S")
    except Exception:
        return ""

def quantum_ultimate_slug(text):
    try:
        import re, unicodedata
        text = unicodedata.normalize("NFKD", quantum_ultimate_safe_str(text))
        text = "".join(c for c in text if not unicodedata.combining(c))
        text = re.sub(r"[^a-zA-Z0-9_-]+", "_", text).strip("_")
        return text or "quantum"
    except Exception:
        return "quantum"

def quantum_ultimate_log(msg, tipo="INFO"):
    try:
        import os, logging
        from logging.handlers import RotatingFileHandler
        log_dir = r"C:\Quantum\logs"
        try:
            os.makedirs(log_dir, exist_ok=True)
        except Exception:
            log_dir = os.getcwd()
        logger = logging.getLogger("quantum_ultimate_full_senior")
        if not logger.handlers:
            logger.setLevel(logging.INFO)
            h = RotatingFileHandler(os.path.join(log_dir, "quantum_ultimate_full_senior.log"), maxBytes=3_000_000, backupCount=8, encoding="utf-8")
            h.setFormatter(logging.Formatter("%(asctime)s | %(levelname)s | %(message)s"))
            logger.addHandler(h)
        level = getattr(logging, str(tipo).upper(), logging.INFO)
        logger.log(level, str(msg))
    except Exception:
        pass

def quantum_ultimate_exception(origin, exc):
    try:
        import traceback
        quantum_ultimate_log("%s | %s: %s\n%s" % (origin, type(exc).__name__, exc, traceback.format_exc()), "ERROR")
    except Exception:
        pass

def quantum_ultimate_friendly_error(exc):
    txt = quantum_ultimate_safe_str(exc).lower()
    if "1045" in txt or "access denied" in txt or "permission denied" in txt:
        return "Acesso negado. Confira usuário, senha, permissão e configuração do banco."
    if "2003" in txt or "can't connect" in txt or "connection refused" in txt:
        return "Não foi possível conectar ao banco. Verifique se o MySQL está ligado e se o config.ini está correto."
    if "unknown column" in txt or "no such column" in txt:
        return "Existe coluna faltando no banco. Reinicie o sistema para a atualização automática ajustar a estrutura."
    if "doesn't exist" in txt or "no such table" in txt:
        return "Existe tabela faltando no banco. Reinicie o sistema para a atualização automática criar a estrutura."
    if "duplicate" in txt:
        return "Já existe um cadastro com esses dados. Verifique código, nome, documento ou usuário duplicado."
    if "printer" in txt or "impress" in txt:
        return "Não foi possível imprimir. Confira impressora, papel, conexão e configuração."
    if "timeout" in txt:
        return "A operação demorou demais. Verifique rede, banco ou tente novamente."
    return "Algo não saiu como esperado, mas o sistema registrou o detalhe técnico em log para suporte."

def quantum_ultimate_apply_error_handlers(root=None):
    try:
        import sys, traceback, tkinter.messagebox as messagebox

        def _hook(exc_type, exc, tb):
            try:
                quantum_ultimate_log("ERRO GLOBAL | %s: %s\n%s" % (getattr(exc_type, "__name__", exc_type), exc, "".join(traceback.format_exception(exc_type, exc, tb))), "CRITICAL")
            except Exception:
                pass
            try:
                messagebox.showerror("Quantum - Aviso amigável", quantum_ultimate_friendly_error(exc), parent=root)
            except Exception:
                pass

        sys.excepthook = _hook
    except Exception:
        pass

    try:
        import threading, traceback
        def _thread_hook(args):
            try:
                quantum_ultimate_log("ERRO THREAD | %s: %s\n%s" % (args.exc_type.__name__, args.exc_value, "".join(traceback.format_exception(args.exc_type, args.exc_value, args.exc_traceback))), "ERROR")
            except Exception:
                pass
        threading.excepthook = _thread_hook
    except Exception:
        pass

    if root is not None:
        try:
            import traceback, tkinter.messagebox as messagebox
            def _tk_err(exc, val, tb):
                try:
                    quantum_ultimate_log("ERRO TELA | %s: %s\n%s" % (getattr(exc, "__name__", exc), val, "".join(traceback.format_exception(exc, val, tb))), "ERROR")
                except Exception:
                    pass
                try:
                    messagebox.showerror("Quantum - Aviso amigável", quantum_ultimate_friendly_error(val), parent=root)
                except Exception:
                    pass
            root.report_callback_exception = _tk_err
        except Exception:
            pass

