def quantum_ultimate_run_background(task, callback=None, error_callback=None):
    try:
        import threading
        def _runner():
            try:
                res = task()
                if callback:
                    try:
                        callback(res)
                    except Exception as e:
                        quantum_ultimate_exception("callback background", e)
            except Exception as e:
                quantum_ultimate_exception("processo em segundo plano", e)
                if error_callback:
                    try:
                        error_callback(e)
                    except Exception:
                        pass
        t = threading.Thread(target=_runner, daemon=True)
        t.start()
        return t
    except Exception as e:
        quantum_ultimate_exception("iniciar background", e)
        return None

