def quantum_visual_patch_messageboxes():
    try:
        import tkinter.messagebox as _mb
        if getattr(_mb, "_quantum_visual_patched", False):
            return
        _orig_error, _orig_warning, _orig_info = _mb.showerror, _mb.showwarning, _mb.showinfo
        def _nice(title, prefix):
            try:
                title = quantum_ultimate_safe_str(title, "Aviso")
            except Exception:
                title = str(title or "Aviso")
            return title if title.startswith(prefix) else f"{prefix} {title}"
        def showerror(title=None, message=None, *args, **kwargs):
            try:
                if message and "Traceback" in str(message):
                    message = "O sistema encontrou uma falha técnica e registrou os detalhes no log. Tente novamente ou envie o log ao suporte."
            except Exception:
                pass
            return _orig_error(_nice(title, "⚠️"), message, *args, **kwargs)
        def showwarning(title=None, message=None, *args, **kwargs):
            return _orig_warning(_nice(title, "🔔"), message, *args, **kwargs)
        def showinfo(title=None, message=None, *args, **kwargs):
            return _orig_info(_nice(title, "✅"), message, *args, **kwargs)
        _mb.showerror, _mb.showwarning, _mb.showinfo = showerror, showwarning, showinfo
        _mb._quantum_visual_patched = True
    except Exception:
        pass

