try:
    TRATAMENTOS_FILE = os.path.join(DATA_DIR, "tratamentos_continuos.json")
except Exception:
    TRATAMENTOS_FILE = "tratamentos_continuos.json"


def _farmacia_tc_parse_date(valor):
    """Interpreta datas nos formatos mais comuns usados no sistema."""
    try:
        if isinstance(valor, datetime.date):
            return valor
        texto = str(valor or '').strip()
        if not texto:
            return None
        formatos = (
            '%d/%m/%Y', '%Y-%m-%d', '%d-%m-%Y', '%Y/%m/%d',
            '%d/%m/%Y %H:%M:%S', '%Y-%m-%d %H:%M:%S'
        )
        for fmt in formatos:
            try:
                return datetime.datetime.strptime(texto[:19], fmt).date()
            except Exception:
                pass
    except Exception:
        return None
    return None


def _farmacia_tc_date_str(data):
    try:
        if isinstance(data, datetime.datetime):
            data = data.date()
        if isinstance(data, datetime.date):
            return data.strftime('%d/%m/%Y')
    except Exception:
        pass
    return ''


def _farmacia_tc_float(valor, padrao=0.0):
    try:
        if valor is None:
            return padrao
        return float(str(valor).strip().replace('.', '').replace(',', '.'))
    except Exception:
        try:
            return float(valor)
        except Exception:
            return padrao


def _farmacia_tc_load():
    try:
        dados = load_data(TRATAMENTOS_FILE, {})
        return dados if isinstance(dados, dict) else {}
    except Exception:
        try:
            if os.path.exists(TRATAMENTOS_FILE):
                with open(TRATAMENTOS_FILE, 'r', encoding='utf-8') as f:
                    dados = json.load(f)
                    return dados if isinstance(dados, dict) else {}
        except Exception:
            pass
    return {}


def _farmacia_tc_save(dados):
    try:
        return bool(save_data(TRATAMENTOS_FILE, dados if isinstance(dados, dict) else {}))
    except Exception:
        try:
            os.makedirs(os.path.dirname(TRATAMENTOS_FILE), exist_ok=True)
            with open(TRATAMENTOS_FILE, 'w', encoding='utf-8') as f:
                json.dump(dados if isinstance(dados, dict) else {}, f, indent=4, ensure_ascii=False)
            return True
        except Exception:
            return False


def _farmacia_tc_calcular_datas(trat):
    """Calcula dias de duração, data de fim e data de lembrete do tratamento."""
    inicio = _farmacia_tc_parse_date(trat.get('data_inicio') or trat.get('data_ultima_compra')) or datetime.date.today()
    qtd_comprada = _farmacia_tc_float(trat.get('quantidade_comprada'), 0)
    qtd_dia = _farmacia_tc_float(trat.get('quantidade_por_dia'), 0)
    avisar_antes = int(_farmacia_tc_float(trat.get('avisar_antes_dias'), 3))

    if qtd_dia <= 0 or qtd_comprada <= 0:
        dias_duracao = int(_farmacia_tc_float(trat.get('intervalo_compra_dias'), 30) or 30)
    else:
        dias_duracao = max(1, int(qtd_comprada / qtd_dia))

    data_fim = inicio + datetime.timedelta(days=dias_duracao)
    data_lembrete = data_fim - datetime.timedelta(days=max(0, avisar_antes))
    trat['dias_duracao_estimado'] = dias_duracao
    trat['data_fim_prevista'] = _farmacia_tc_date_str(data_fim)
    trat['data_lembrete'] = _farmacia_tc_date_str(data_lembrete)
    return trat


def _farmacia_tc_status(trat):
    hoje = datetime.date.today()
    if not bool(trat.get('ativo', True)):
        return 'Inativo', 99999
    if not bool(trat.get('tratamento_continuo', True)):
        return 'Não contínuo', 99999
    fim = _farmacia_tc_parse_date(trat.get('data_fim_prevista'))
    lembrete = _farmacia_tc_parse_date(trat.get('data_lembrete'))
    if not fim:
        return 'Sem previsão', 99999
    dias_fim = (fim - hoje).days
    if dias_fim < 0:
        return f'Atrasado há {abs(dias_fim)} dia(s)', dias_fim
    if dias_fim == 0:
        return 'Acaba hoje', 0
    if lembrete and hoje >= lembrete:
        return f'Comprar em breve ({dias_fim} dia(s))', dias_fim
    return f'Em dia ({dias_fim} dia(s))', dias_fim


def _farmacia_tc_alertas_pendentes(dados=None):
    dados = dados if isinstance(dados, dict) else _farmacia_tc_load()
    alertas = []
    hoje = datetime.date.today()
    for tid, trat in (dados or {}).items():
        try:
            if not bool(trat.get('ativo', True)) or not bool(trat.get('tratamento_continuo', True)):
                continue
            trat = _farmacia_tc_calcular_datas(dict(trat))
            lembrete = _farmacia_tc_parse_date(trat.get('data_lembrete'))
            fim = _farmacia_tc_parse_date(trat.get('data_fim_prevista'))
            if not lembrete or not fim:
                continue
            if hoje >= lembrete:
                status, dias = _farmacia_tc_status(trat)
                alertas.append((dias, tid, trat, status))
        except Exception:
            pass
    alertas.sort(key=lambda x: x[0])
    return alertas


def _farmacia_tc_mensagem_whatsapp(trat):
    cliente = trat.get('cliente_nome') or 'cliente'
    medicamento = trat.get('medicamento_nome') or trat.get('medicamento') or 'seu medicamento'
    fim = trat.get('data_fim_prevista') or '-'
    empresa = 'nossa farmácia'
    try:
        empresa = (getattr(globals().get('_FARMACIA_APP_REF', None), 'empresa_data', {}) or {}).get('nome') or empresa
    except Exception:
        pass
    return (f"Olá {cliente}! Tudo bem?\n\n"
            f"Estamos passando para lembrar da reposição do medicamento de uso contínuo: {medicamento}.\n"
            f"Pela previsão cadastrada, o tratamento/estoque atual acaba em {fim}.\n\n"
            f"Evite ficar sem o medicamento. {empresa} está à disposição.")




