def _farmacia_maximizar_janela_segura(win):
    """Maximiza uma janela Toplevel sem ativar fullscreen obrigatório."""
    try:
        win.resizable(True, True)
    except Exception:
        pass
    def _do_max():
        try:
            win.update_idletasks()
        except Exception:
            pass
        # Windows/Tk padrão
        try:
            win.state('zoomed')
            return
        except Exception:
            pass
        # Linux em alguns gerenciadores de janela
        try:
            win.attributes('-zoomed', True)
            return
        except Exception:
            pass
        # Fallback: ocupa a tela útil
        try:
            sw = win.winfo_screenwidth()
            sh = win.winfo_screenheight()
            win.geometry(f"{sw}x{max(600, sh-40)}+0+0")
        except Exception:
            try:
                win.geometry('1366x768+0+0')
            except Exception:
                pass
    try:
        win.after(80, _do_max)
    except Exception:
        _do_max()

class FarmaciaTratamentoContinuoWindow:
    """Janela de cadastro e acompanhamento de tratamentos contínuos."""

    def __init__(self, app, parent=None):
        self.app = app
        self.parent = parent or getattr(app, 'root', None)
        self.dados = _farmacia_tc_load()
        self.selected_id = None
        self.win = tk.Toplevel(self.parent)
        self.win.title('💊 Cadastro de Tratamento Contínuo - Lembrete de Compra')
        try:
            responsive_geometry(self.win, 1180, 760)
        except Exception:
            self.win.geometry('1180x760')
        _farmacia_maximizar_janela_segura(self.win)
        self.win.transient(self.parent)
        self.win.grab_set()
        self._build()
        self._carregar_lista()

    def _build(self):
        main = ttk.Frame(self.win, padding=14)
        main.pack(fill=tk.BOTH, expand=True)
        ttk.Label(main, text='💊 TRATAMENTO CONTÍNUO E LEMBRANÇA DE COMPRA', font=('Segoe UI', 16, 'bold')).pack(anchor='w')
        ttk.Label(main, text='Cadastre medicamentos de uso contínuo por cliente/paciente. O sistema calcula quando lembrar a próxima compra.', foreground='#475569').pack(anchor='w', pady=(2, 10))

        body = ttk.Frame(main)
        body.pack(fill=tk.BOTH, expand=True)
        form = ttk.LabelFrame(body, text='Dados do tratamento')
        form.pack(side=tk.LEFT, fill=tk.Y, padx=(0, 10))
        lista = ttk.LabelFrame(body, text='Tratamentos cadastrados e alertas')
        lista.pack(side=tk.RIGHT, fill=tk.BOTH, expand=True)

        self.var_ativo = tk.BooleanVar(value=True)
        self.var_continuo = tk.BooleanVar(value=True)
        self.var_cliente = tk.StringVar()
        self.var_cliente_id = tk.StringVar(value='')
        self.var_telefone = tk.StringVar()
        self.var_medicamento = tk.StringVar()
        self.var_produto_id = tk.StringVar(value='')
        self.var_dose = tk.StringVar()
        self.var_qtd_dia = tk.StringVar(value='1')
        self.var_qtd_comprada = tk.StringVar(value='30')
        self.var_intervalo = tk.StringVar(value='30')
        self.var_avisar = tk.StringVar(value='3')
        self.var_inicio = tk.StringVar(value=datetime.date.today().strftime('%d/%m/%Y'))
        self.var_obs = tk.StringVar()

        r = 0
        ttk.Checkbutton(form, text='Tratamento ativo', variable=self.var_ativo).grid(row=r, column=0, sticky='w', pady=3)
        ttk.Checkbutton(form, text='Tratamento contínuo / uso permanente', variable=self.var_continuo).grid(row=r, column=1, sticky='w', pady=3)
        r += 1

        ttk.Label(form, text='Cliente/Paciente:').grid(row=r, column=0, sticky='w', pady=(8, 2))
        clientes = self._clientes_opcoes()
        self.cmb_cliente = ttk.Combobox(form, textvariable=self.var_cliente, values=clientes, width=36)
        self.cmb_cliente.grid(row=r, column=1, sticky='ew', pady=(8, 2))
        self.cmb_cliente.bind('<<ComboboxSelected>>', self._on_cliente)
        r += 1
        ttk.Label(form, text='Telefone/WhatsApp:').grid(row=r, column=0, sticky='w', pady=2)
        ttk.Entry(form, textvariable=self.var_telefone, width=38).grid(row=r, column=1, sticky='ew', pady=2)
        r += 1

        ttk.Label(form, text='Medicamento/Produto:').grid(row=r, column=0, sticky='w', pady=(8, 2))
        produtos = self._produtos_opcoes()
        self.cmb_produto = ttk.Combobox(form, textvariable=self.var_medicamento, values=produtos, width=36)
        self.cmb_produto.grid(row=r, column=1, sticky='ew', pady=(8, 2))
        self.cmb_produto.bind('<<ComboboxSelected>>', self._on_produto)
        r += 1
        ttk.Label(form, text='Dose/Posologia:').grid(row=r, column=0, sticky='w', pady=2)
        ttk.Entry(form, textvariable=self.var_dose, width=38).grid(row=r, column=1, sticky='ew', pady=2)
        r += 1

        ttk.Label(form, text='Consumo por dia:').grid(row=r, column=0, sticky='w', pady=(8, 2))
        ttk.Entry(form, textvariable=self.var_qtd_dia, width=14).grid(row=r, column=1, sticky='w', pady=(8, 2))
        r += 1
        ttk.Label(form, text='Quantidade comprada:').grid(row=r, column=0, sticky='w', pady=2)
        ttk.Entry(form, textvariable=self.var_qtd_comprada, width=14).grid(row=r, column=1, sticky='w', pady=2)
        r += 1
        ttk.Label(form, text='Intervalo manual em dias:').grid(row=r, column=0, sticky='w', pady=2)
        ttk.Entry(form, textvariable=self.var_intervalo, width=14).grid(row=r, column=1, sticky='w', pady=2)
        r += 1
        ttk.Label(form, text='Avisar quantos dias antes:').grid(row=r, column=0, sticky='w', pady=2)
        ttk.Entry(form, textvariable=self.var_avisar, width=14).grid(row=r, column=1, sticky='w', pady=2)
        r += 1
        ttk.Label(form, text='Data da compra/início:').grid(row=r, column=0, sticky='w', pady=2)
        try:
            self.dt_inicio = DateEntry(form, bootstyle='success', dateformat='%d/%m/%Y', width=12)
            self.dt_inicio.grid(row=r, column=1, sticky='w', pady=2)
        except Exception:
            self.dt_inicio = ttk.Entry(form, textvariable=self.var_inicio, width=14)
            self.dt_inicio.grid(row=r, column=1, sticky='w', pady=2)
        r += 1
        ttk.Label(form, text='Observação:').grid(row=r, column=0, sticky='w', pady=(8, 2))
        ttk.Entry(form, textvariable=self.var_obs, width=38).grid(row=r, column=1, sticky='ew', pady=(8, 2))
        r += 1

        preview = ttk.LabelFrame(form, text='Previsão automática')
        preview.grid(row=r, column=0, columnspan=2, sticky='ew', pady=(10, 6))
        self.var_previsao = tk.StringVar(value='Preencha os dados e clique em Calcular.')
        ttk.Label(preview, textvariable=self.var_previsao, foreground='#047857', wraplength=240).pack(anchor='w')
        r += 1

        btns = ttk.Frame(form)
        btns.grid(row=r, column=0, columnspan=2, sticky='ew', pady=(10, 0))
        ttk.Button(btns, text='🧮 Calcular', command=self._calcular_preview, bootstyle='info').pack(side=tk.LEFT, padx=3)
        ttk.Button(btns, text='💾 Salvar', command=self._salvar, bootstyle='success').pack(side=tk.LEFT, padx=3)
        ttk.Button(btns, text='🧹 Novo', command=self._limpar, bootstyle='secondary').pack(side=tk.LEFT, padx=3)
        ttk.Button(btns, text='🗑️ Excluir', command=self._excluir, bootstyle='danger').pack(side=tk.LEFT, padx=3)

        filtro_frame = ttk.Frame(lista)
        filtro_frame.pack(fill=tk.X, pady=(0, 8))
        self.var_filtro = tk.StringVar()
        ttk.Label(filtro_frame, text='Buscar:').pack(side=tk.LEFT)
        ent = ttk.Entry(filtro_frame, textvariable=self.var_filtro, width=34)
        ent.pack(side=tk.LEFT, padx=5)
        ent.bind('<KeyRelease>', lambda e: self._carregar_lista())
        ttk.Button(filtro_frame, text='🔔 Ver alertas', command=self._mostrar_alertas, bootstyle='warning').pack(side=tk.LEFT, padx=4)
        ttk.Button(filtro_frame, text='📱 WhatsApp', command=self._abrir_whatsapp, bootstyle='success').pack(side=tk.LEFT, padx=4)
        ttk.Button(filtro_frame, text='🛒 Marcar compra feita', command=self._marcar_compra, bootstyle='primary').pack(side=tk.LEFT, padx=4)

        cols = ('id', 'cliente', 'medicamento', 'fim', 'lembrete', 'status')
        self.tree = ttk.Treeview(lista, columns=cols, show='headings', height=18)
        headers = [('id','ID',70),('cliente','Cliente',190),('medicamento','Medicamento',220),('fim','Acaba em',100),('lembrete','Lembrar em',100),('status','Status',180)]
        for c,t,w in headers:
            self.tree.heading(c, text=t)
            self.tree.column(c, width=w, anchor=tk.W if c in ('cliente','medicamento','status') else tk.CENTER)
        scr = ttk.Scrollbar(lista, orient=tk.VERTICAL, command=self.tree.yview)
        self.tree.configure(yscrollcommand=scr.set)
        self.tree.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scr.pack(side=tk.RIGHT, fill=tk.Y)
        self.tree.bind('<<TreeviewSelect>>', self._selecionar)
        self.tree.bind('<Double-1>', self._selecionar)

        rodape = ttk.Frame(main)
        rodape.pack(fill=tk.X, pady=(10, 0))
        self.var_info = tk.StringVar(value='')
        ttk.Label(rodape, textvariable=self.var_info, foreground='#64748b').pack(side=tk.LEFT)
        ttk.Button(rodape, text='Fechar', command=self.win.destroy, bootstyle='secondary').pack(side=tk.RIGHT)

    def _clientes_opcoes(self):
        opcoes = []
        try:
            for cid, c in sorted((getattr(self.app, 'customers', {}) or {}).items(), key=lambda kv: str(kv[1].get('nome','')).lower()):
                nome = c.get('nome') or ''
                if nome:
                    opcoes.append(f'{cid} - {nome}')
        except Exception:
            pass
        return opcoes

    def _produtos_opcoes(self):
        opcoes = []
        try:
            for pid, p in sorted((getattr(self.app, 'products', {}) or {}).items(), key=lambda kv: str(kv[1].get('nome','')).lower()):
                nome = p.get('nome') or ''
                if nome:
                    opcoes.append(f'{pid} - {nome}')
        except Exception:
            pass
        return opcoes

    def _on_cliente(self, event=None):
        texto = self.var_cliente.get()
        cid = texto.split(' - ', 1)[0].strip() if ' - ' in texto else ''
        self.var_cliente_id.set(cid)
        try:
            c = (getattr(self.app, 'customers', {}) or {}).get(cid, {})
            self.var_telefone.set(c.get('telefone') or c.get('whatsapp') or '')
        except Exception:
            pass

    def _on_produto(self, event=None):
        texto = self.var_medicamento.get()
        pid = texto.split(' - ', 1)[0].strip() if ' - ' in texto else ''
        self.var_produto_id.set(pid)

    def _get_inicio(self):
        try:
            return self.dt_inicio.entry.get().strip()
        except Exception:
            return self.var_inicio.get().strip()

    def _set_inicio(self, data_txt):
        try:
            self.dt_inicio.entry.delete(0, tk.END)
            self.dt_inicio.entry.insert(0, data_txt)
        except Exception:
            self.var_inicio.set(data_txt)

    def _montar_tratamento(self):
        medicamento_nome = self.var_medicamento.get().split(' - ', 1)[1].strip() if ' - ' in self.var_medicamento.get() else self.var_medicamento.get().strip()
        cliente_nome = self.var_cliente.get().split(' - ', 1)[1].strip() if ' - ' in self.var_cliente.get() else self.var_cliente.get().strip()
        trat = {
            'id': self.selected_id or datetime.datetime.now().strftime('TC%Y%m%d%H%M%S'),
            'ativo': bool(self.var_ativo.get()),
            'tratamento_continuo': bool(self.var_continuo.get()),
            'cliente_id': self.var_cliente_id.get().strip(),
            'cliente_nome': cliente_nome,
            'telefone': self.var_telefone.get().strip(),
            'produto_id': self.var_produto_id.get().strip(),
            'medicamento_nome': medicamento_nome,
            'dose': self.var_dose.get().strip(),
            'quantidade_por_dia': self.var_qtd_dia.get().strip(),
            'quantidade_comprada': self.var_qtd_comprada.get().strip(),
            'intervalo_compra_dias': self.var_intervalo.get().strip(),
            'avisar_antes_dias': self.var_avisar.get().strip(),
            'data_inicio': self._get_inicio(),
            'data_ultima_compra': self._get_inicio(),
            'observacao': self.var_obs.get().strip(),
            'criado_em': datetime.datetime.now().strftime('%d/%m/%Y %H:%M:%S'),
            'atualizado_em': datetime.datetime.now().strftime('%d/%m/%Y %H:%M:%S'),
        }
        return _farmacia_tc_calcular_datas(trat)

    def _calcular_preview(self):
        try:
            trat = self._montar_tratamento()
            self.var_previsao.set(
                f"Duração estimada: {trat.get('dias_duracao_estimado')} dia(s). "
                f"Acaba em: {trat.get('data_fim_prevista')}. "
                f"Lembrar compra em: {trat.get('data_lembrete')}."
            )
        except Exception as e:
            self.var_previsao.set(f'Não foi possível calcular: {e}')

    def _validar(self, trat):
        if not trat.get('cliente_nome'):
            messagebox.showerror('Tratamento contínuo', 'Informe o cliente/paciente.', parent=self.win); return False
        if not trat.get('medicamento_nome'):
            messagebox.showerror('Tratamento contínuo', 'Informe o medicamento/produto.', parent=self.win); return False
        if not _farmacia_tc_parse_date(trat.get('data_inicio')):
            messagebox.showerror('Tratamento contínuo', 'Informe uma data de compra/início válida.', parent=self.win); return False
        if _farmacia_tc_float(trat.get('quantidade_por_dia'), 0) <= 0 and _farmacia_tc_float(trat.get('intervalo_compra_dias'), 0) <= 0:
            messagebox.showerror('Tratamento contínuo', 'Informe consumo por dia ou intervalo manual em dias.', parent=self.win); return False
        return True

    def _salvar(self):
        trat = self._montar_tratamento()
        if not self._validar(trat):
            return
        self.dados[trat['id']] = trat
        if _farmacia_tc_save(self.dados):
            self.selected_id = trat['id']
            self._carregar_lista()
            self._calcular_preview()
            messagebox.showinfo('Tratamento contínuo', 'Tratamento salvo com sucesso.', parent=self.win)
        else:
            messagebox.showerror('Tratamento contínuo', 'Não foi possível salvar o tratamento.', parent=self.win)

    def _limpar(self):
        self.selected_id = None
        for var in (self.var_cliente, self.var_cliente_id, self.var_telefone, self.var_medicamento, self.var_produto_id, self.var_dose, self.var_obs):
            var.set('')
        self.var_ativo.set(True); self.var_continuo.set(True)
        self.var_qtd_dia.set('1'); self.var_qtd_comprada.set('30'); self.var_intervalo.set('30'); self.var_avisar.set('3')
        self._set_inicio(datetime.date.today().strftime('%d/%m/%Y'))
        self.var_previsao.set('Preencha os dados e clique em Calcular.')

    def _excluir(self):
        if not self.selected_id:
            messagebox.showwarning('Tratamento contínuo', 'Selecione um tratamento para excluir.', parent=self.win); return
        if messagebox.askyesno('Confirmar exclusão', 'Deseja excluir este tratamento?', parent=self.win):
            self.dados.pop(self.selected_id, None)
            _farmacia_tc_save(self.dados)
            self._limpar(); self._carregar_lista()

    def _carregar_lista(self):
        try:
            self.tree.delete(*self.tree.get_children())
        except Exception:
            return
        filtro = self.var_filtro.get().strip().lower() if hasattr(self, 'var_filtro') else ''
        total = alertas = 0
        for tid, trat in sorted((self.dados or {}).items(), key=lambda kv: str(kv[1].get('cliente_nome','')).lower()):
            trat = _farmacia_tc_calcular_datas(dict(trat))
            texto = ' '.join([str(trat.get('cliente_nome','')), str(trat.get('medicamento_nome','')), str(trat.get('telefone',''))]).lower()
            if filtro and filtro not in texto:
                continue
            status, dias = _farmacia_tc_status(trat)
            if dias <= int(_farmacia_tc_float(trat.get('avisar_antes_dias'), 3)):
                alertas += 1
            total += 1
            self.tree.insert('', tk.END, iid=tid, values=(tid, trat.get('cliente_nome',''), trat.get('medicamento_nome',''), trat.get('data_fim_prevista',''), trat.get('data_lembrete',''), status))
        self.var_info.set(f'{total} tratamento(s) listado(s). {alertas} com lembrete/atenção.')

    def _selecionar(self, event=None):
        sel = self.tree.selection()
        if not sel:
            return
        tid = sel[0]
        trat = self.dados.get(tid)
        if not trat:
            return
        self.selected_id = tid
        self.var_ativo.set(bool(trat.get('ativo', True)))
        self.var_continuo.set(bool(trat.get('tratamento_continuo', True)))
        self.var_cliente_id.set(str(trat.get('cliente_id','')))
        self.var_produto_id.set(str(trat.get('produto_id','')))
        self.var_cliente.set((str(trat.get('cliente_id','')) + ' - ' if trat.get('cliente_id') else '') + str(trat.get('cliente_nome','')))
        self.var_medicamento.set((str(trat.get('produto_id','')) + ' - ' if trat.get('produto_id') else '') + str(trat.get('medicamento_nome','')))
        self.var_telefone.set(str(trat.get('telefone','')))
        self.var_dose.set(str(trat.get('dose','')))
        self.var_qtd_dia.set(str(trat.get('quantidade_por_dia','1')))
        self.var_qtd_comprada.set(str(trat.get('quantidade_comprada','30')))
        self.var_intervalo.set(str(trat.get('intervalo_compra_dias','30')))
        self.var_avisar.set(str(trat.get('avisar_antes_dias','3')))
        self._set_inicio(str(trat.get('data_ultima_compra') or trat.get('data_inicio') or datetime.date.today().strftime('%d/%m/%Y')))
        self.var_obs.set(str(trat.get('observacao','')))
        self._calcular_preview()

    def _mostrar_alertas(self):
        alertas = _farmacia_tc_alertas_pendentes(self.dados)
        if not alertas:
            messagebox.showinfo('Tratamento contínuo', 'Nenhum tratamento contínuo precisa de lembrete de compra agora.', parent=self.win)
            return
        linhas = []
        for dias, tid, trat, status in alertas[:60]:
            linhas.append(f"• {trat.get('cliente_nome','')} - {trat.get('medicamento_nome','')}\n  {status} | Comprar até/acaba em: {trat.get('data_fim_prevista')} | Lembrar desde: {trat.get('data_lembrete')}")
        messagebox.showwarning('🔔 Lembretes de compra de medicamentos', '\n\n'.join(linhas), parent=self.win)

    def _abrir_whatsapp(self):
        if not self.selected_id:
            messagebox.showwarning('WhatsApp', 'Selecione um tratamento.', parent=self.win); return
        trat = _farmacia_tc_calcular_datas(dict(self.dados.get(self.selected_id, {})))
        telefone = ''.join(filter(str.isdigit, str(trat.get('telefone',''))))
        if not telefone:
            messagebox.showwarning('WhatsApp', 'Cliente sem telefone/WhatsApp cadastrado.', parent=self.win); return
        if not telefone.startswith('55') and len(telefone) >= 10:
            telefone = '55' + telefone
        try:
            import urllib.parse, webbrowser
            webbrowser.open(f"https://wa.me/{telefone}?text={urllib.parse.quote(_farmacia_tc_mensagem_whatsapp(trat))}")
        except Exception as e:
            messagebox.showerror('WhatsApp', f'Erro ao abrir WhatsApp:\n{e}', parent=self.win)

    def _marcar_compra(self):
        if not self.selected_id:
            messagebox.showwarning('Compra', 'Selecione um tratamento.', parent=self.win); return
        trat = self.dados.get(self.selected_id, {})
        hoje = datetime.date.today().strftime('%d/%m/%Y')
        qtd = simpledialog.askstring('Nova compra', 'Quantidade comprada nesta reposição:', initialvalue=str(trat.get('quantidade_comprada','30')), parent=self.win)
        if qtd is None:
            return
        trat['quantidade_comprada'] = qtd
        trat['data_ultima_compra'] = hoje
        trat['data_inicio'] = hoje
        trat['atualizado_em'] = datetime.datetime.now().strftime('%d/%m/%Y %H:%M:%S')
        trat = _farmacia_tc_calcular_datas(trat)
        self.dados[self.selected_id] = trat
        _farmacia_tc_save(self.dados)
        self._selecionar(); self._carregar_lista()
        messagebox.showinfo('Compra registrada', f'Compra marcada. Próximo lembrete em {trat.get("data_lembrete")}.', parent=self.win)


def _farmacia_tc_mostrar_alertas_inicio(app, forcar=False):
    """Exibe alertas de tratamentos contínuos na abertura do sistema, no máximo uma vez por dia."""
    try:
        hoje = datetime.date.today().isoformat()
        chave = '_farmacia_tc_alertas_exibidos_em'
        if not forcar and getattr(app, chave, None) == hoje:
            return
        alertas = _farmacia_tc_alertas_pendentes()
        if not alertas:
            return
        setattr(app, chave, hoje)
        linhas = []
        for dias, tid, trat, status in alertas[:20]:
            linhas.append(f"• {trat.get('cliente_nome','')} - {trat.get('medicamento_nome','')}\n  {status} | previsão de término: {trat.get('data_fim_prevista')}")
        parent = getattr(app, 'root', None)
        messagebox.showwarning('🔔 Lembretes de compra - Tratamentos contínuos', '\n\n'.join(linhas), parent=parent)
    except Exception as e:
        print(f'[TRATAMENTO CONTÍNUO] Erro ao exibir alertas: {e}')


def _farmacia_tc_open_window(self):
    try:
        globals()['_FARMACIA_APP_REF'] = self
    except Exception:
        pass
    return FarmaciaTratamentoContinuoWindow(self, getattr(self, 'root', None))


def _farmacia_tc_patch_app():
    try:
        if 'PDVSuperApp' not in globals():
            return
        if getattr(PDVSuperApp, '_farmacia_tc_patch_aplicado', False):
            return
        PDVSuperApp.open_tratamentos_continuos = _farmacia_tc_open_window

        _orig_create_menu = PDVSuperApp._create_menu
        def _patched_create_menu(self, *args, **kwargs):
            resultado = _orig_create_menu(self, *args, **kwargs)
            try:
                if not _fq_farma_menu_visivel(self, "menu_tratamento_visivel"):
                    return resultado
                menubar = self.root.nametowidget(self.root.cget('menu'))
                tratamentos_menu = tk.Menu(menubar, tearoff=0)
                tratamentos_menu.add_command(label='💊 Cadastro de Tratamento Contínuo', command=self.open_tratamentos_continuos, accelerator='Ctrl+Alt+M')
                tratamentos_menu.add_command(label='🔔 Ver lembretes de compra agora', command=lambda: _farmacia_tc_mostrar_alertas_inicio(self, forcar=True))
                menubar.add_cascade(label='💊 Tratamentos', menu=tratamentos_menu)
                self.root.bind('<Control-Alt-m>', lambda event: self.open_tratamentos_continuos())
                self.root.bind('<Control-Alt-M>', lambda event: self.open_tratamentos_continuos())
            except Exception as e:
                print(f'[TRATAMENTO CONTÍNUO] Aviso ao adicionar menu: {e}')
            return resultado
        PDVSuperApp._create_menu = _patched_create_menu

        _orig_init = PDVSuperApp.__init__
        def _patched_init(self, *args, **kwargs):
            _orig_init(self, *args, **kwargs)
            try:
                globals()['_FARMACIA_APP_REF'] = self
                self.root.after(4500, lambda: _farmacia_tc_mostrar_alertas_inicio(self, forcar=False))
            except Exception:
                pass
        PDVSuperApp.__init__ = _patched_init
        PDVSuperApp._farmacia_tc_patch_aplicado = True
        print('[TRATAMENTO CONTÍNUO] Patch aplicado com sucesso.')
    except Exception as e:
        print(f'[TRATAMENTO CONTÍNUO] Falha ao aplicar patch: {e}')


_farmacia_tc_patch_app()


# ═══════════════════════════════════════════════════════════════════════════════
# 🏥 PATCH FARMÁCIA - PRONTUÁRIO ROBUSTO DE ATENDIMENTO AMBULATORIAL
# ═══════════════════════════════════════════════════════════════════════════════
# Recurso adicionado:
# - Cadastro completo de atendimento ambulatorial na farmácia.
# - Prontuário com identificação, triagem, sinais vitais, anamnese, avaliação,
#   conduta farmacêutica, medicamentos orientados, encaminhamento e retorno.
# - Classificação de risco e alertas de encaminhamento.
# - Histórico pesquisável por paciente, telefone, atendimento, risco e data.
# - Exportação/impressão em TXT para anexar, imprimir ou salvar em PDF.
# - Armazenamento local em JSON com fallback robusto, sem quebrar o PDV.
# ═══════════════════════════════════════════════════════════════════════════════

try:
    PRONTUARIO_AMBULATORIO_FILE = os.path.join(DATA_DIR, "prontuarios_ambulatorio_farmacia.json")
except Exception:
    PRONTUARIO_AMBULATORIO_FILE = "prontuarios_ambulatorio_farmacia.json"


def _farmacia_amb_now():
    try:
        return datetime.datetime.now().strftime('%d/%m/%Y %H:%M:%S')
    except Exception:
        return ''


def _farmacia_amb_load():
    try:
        dados = load_data(PRONTUARIO_AMBULATORIO_FILE, {})
        return dados if isinstance(dados, dict) else {}
    except Exception:
        try:
            if os.path.exists(PRONTUARIO_AMBULATORIO_FILE):
                with open(PRONTUARIO_AMBULATORIO_FILE, 'r', encoding='utf-8') as f:
                    dados = json.load(f)
                    return dados if isinstance(dados, dict) else {}
        except Exception:
            pass
    return {}


def _farmacia_amb_save(dados):
    try:
        return bool(save_data(PRONTUARIO_AMBULATORIO_FILE, dados if isinstance(dados, dict) else {}))
    except Exception:
        try:
            pasta = os.path.dirname(PRONTUARIO_AMBULATORIO_FILE)
            if pasta:
                os.makedirs(pasta, exist_ok=True)
            with open(PRONTUARIO_AMBULATORIO_FILE, 'w', encoding='utf-8') as f:
                json.dump(dados if isinstance(dados, dict) else {}, f, indent=4, ensure_ascii=False)
            return True
        except Exception:
            return False


def _farmacia_amb_id():
    try:
        return 'AMB' + datetime.datetime.now().strftime('%Y%m%d%H%M%S%f')
    except Exception:
        import time
        return 'AMB' + str(int(time.time() * 1000))


def _farmacia_amb_limpar_numero(valor):
    try:
        return ''.join(ch for ch in str(valor or '') if ch.isdigit())
    except Exception:
        return ''


def _farmacia_amb_resumo(pront):
    linhas = []
    add = linhas.append
    add('=' * 86)
    add('PRONTUÁRIO DE ATENDIMENTO AMBULATORIAL - FARMÁCIA')
    add('=' * 86)
    add(f"ID: {pront.get('id','')}")
    add(f"Data/Hora: {pront.get('data_hora','')}")
    add(f"Profissional: {pront.get('profissional','')} | Registro: {pront.get('registro_profissional','')}")
    add('-' * 86)
    add('IDENTIFICAÇÃO DO PACIENTE')
    add(f"Nome: {pront.get('paciente_nome','')}")
    add(f"Documento/CPF: {pront.get('documento','')} | Nascimento/Idade: {pront.get('nascimento_idade','')}")
    add(f"Telefone/WhatsApp: {pront.get('telefone','')} | Endereço: {pront.get('endereco','')}")
    add(f"Responsável: {pront.get('responsavel','')}")
    add('-' * 86)
    add('TRIAGEM E SINAIS VITAIS')
    add(f"Tipo de atendimento: {pront.get('tipo_atendimento','')} | Classificação de risco: {pront.get('risco','')}")
    add(f"PA: {pront.get('pa','')} | FC: {pront.get('fc','')} | Temperatura: {pront.get('temperatura','')} | SpO2: {pront.get('spo2','')}")
    add(f"Glicemia: {pront.get('glicemia','')} | Peso: {pront.get('peso','')} | Altura: {pront.get('altura','')} | IMC: {pront.get('imc','')}")
    add('-' * 86)
    add('DADOS CLÍNICOS E FARMACÊUTICOS')
    add(f"Queixa principal: {pront.get('queixa','')}")
    add(f"História/Anamnese: {pront.get('anamnese','')}")
    add(f"Alergias: {pront.get('alergias','')}")
    add(f"Doenças/Condições conhecidas: {pront.get('condicoes','')}")
    add(f"Medicamentos em uso: {pront.get('medicamentos_uso','')}")
    add(f"Suspeita de reação adversa/interação: {pront.get('reacao_interacao','')}")
    add('-' * 86)
    add('AVALIAÇÃO, CONDUTA E ORIENTAÇÃO')
    add(f"Avaliação farmacêutica: {pront.get('avaliacao','')}")
    add(f"Conduta realizada: {pront.get('conduta','')}")
    add(f"Medicamentos/produtos orientados: {pront.get('medicamentos_orientados','')}")
    add(f"Orientações ao paciente: {pront.get('orientacoes','')}")
    add(f"Encaminhamento: {pront.get('encaminhamento','')}")
    add(f"Retorno/monitoramento: {pront.get('retorno','')}")
    add('-' * 86)
    add(f"Observações internas: {pront.get('observacoes','')}")
    add(f"Termo/Consentimento: {pront.get('consentimento','')}")
    add('=' * 86)
    return '\n'.join(linhas)


class FarmaciaAmbulatorioProntuarioWindow:
    """Prontuário completo de atendimento ambulatorial para farmácia."""

    TIPOS = [
        'Atenção farmacêutica', 'Aferição de pressão arterial', 'Glicemia capilar',
        'Aplicação de injetável', 'Nebulização/Inalação', 'Curativo simples',
        'Orientação de medicamento', 'Revisão de farmacoterapia', 'Triagem rápida',
        'Outro atendimento ambulatorial'
    ]
    RISCOS = ['Verde - rotina', 'Amarelo - atenção', 'Laranja - urgente', 'Vermelho - emergência/encaminhar']

    def __init__(self, app, parent=None):
        self.app = app
        self.parent = parent or getattr(app, 'root', None)
        self.dados = _farmacia_amb_load()
        self.selected_id = None
        self.win = tk.Toplevel(self.parent)
        self.win.title('🏥 Prontuário Ambulatorial da Farmácia')
        try:
            responsive_geometry(self.win, 1360, 820)
        except Exception:
            self.win.geometry('1360x820')
        _farmacia_maximizar_janela_segura(self.win)
        self.win.transient(self.parent)
        self.win.grab_set()
        self._build()
        self._carregar_lista()
        self._novo()

    def _mk_var(self, value=''):
        return tk.StringVar(value=value)

    def _build(self):
        main = ttk.Frame(self.win, padding=12)
        main.pack(fill=tk.BOTH, expand=True)
        ttk.Label(main, text='🏥 PRONTUÁRIO ROBUSTO DE ATENDIMENTO AMBULATORIAL', font=('Segoe UI', 16, 'bold')).pack(anchor='w')
        ttk.Label(main, text='Registro completo para serviços clínicos farmacêuticos, triagem, sinais vitais, orientação e encaminhamento.', foreground='#475569').pack(anchor='w', pady=(2, 8))

        content = ttk.Frame(main)
        content.pack(fill=tk.BOTH, expand=True)

        left = ttk.LabelFrame(content, text='Atendimento / Prontuário')
        left.pack(side=tk.LEFT, fill=tk.BOTH, expand=True, padx=(0, 8))
        right = ttk.LabelFrame(content, text='Histórico de atendimentos')
        right.pack(side=tk.RIGHT, fill=tk.BOTH, expand=True)

        canvas = tk.Canvas(left, highlightthickness=0)
        scroll = ttk.Scrollbar(left, orient='vertical', command=canvas.yview)
        self.form_frame = ttk.Frame(canvas)
        self.form_frame.bind('<Configure>', lambda e: canvas.configure(scrollregion=canvas.bbox('all')))
        canvas.create_window((0, 0), window=self.form_frame, anchor='nw')
        canvas.configure(yscrollcommand=scroll.set)
        canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scroll.pack(side=tk.RIGHT, fill=tk.Y)
        try:
            canvas.bind_all('<MouseWheel>', lambda e: canvas.yview_scroll(int(-1 * (e.delta / 120)), 'units') if self.win.focus_get() else None)
        except Exception:
            pass

        self._vars()
        self._build_form(self.form_frame)
        self._build_list(right)

    def _vars(self):
        self.var_id = self._mk_var()
        self.var_data = self._mk_var(_farmacia_amb_now())
        self.var_profissional = self._mk_var()
        self.var_registro = self._mk_var()
        self.var_paciente = self._mk_var()
        self.var_documento = self._mk_var()
        self.var_nascimento = self._mk_var()
        self.var_telefone = self._mk_var()
        self.var_endereco = self._mk_var()
        self.var_responsavel = self._mk_var()
        self.var_tipo = self._mk_var(self.TIPOS[0])
        self.var_risco = self._mk_var(self.RISCOS[0])
        self.var_pa = self._mk_var()
        self.var_fc = self._mk_var()
        self.var_temperatura = self._mk_var()
        self.var_spo2 = self._mk_var()
        self.var_glicemia = self._mk_var()
        self.var_peso = self._mk_var()
        self.var_altura = self._mk_var()
        self.var_imc = self._mk_var()
        self.var_consentimento = self._mk_var('Paciente/Responsável orientado e ciente do atendimento farmacêutico.')
        self.var_filtro = self._mk_var()
        self.var_info = self._mk_var('')

    def _entry(self, parent, label, var, row, col=0, width=26):
        ttk.Label(parent, text=label).grid(row=row, column=col, sticky='w', padx=4, pady=(5, 1))
        ent = ttk.Entry(parent, textvariable=var, width=width)
        ent.grid(row=row+1, column=col, sticky='ew', padx=4, pady=(0, 5))
        return ent

    def _combo(self, parent, label, var, values, row, col=0, width=28):
        ttk.Label(parent, text=label).grid(row=row, column=col, sticky='w', padx=4, pady=(5, 1))
        cb = ttk.Combobox(parent, textvariable=var, values=values, width=width, state='readonly')
        cb.grid(row=row+1, column=col, sticky='ew', padx=4, pady=(0, 5))
        return cb

    def _text(self, parent, label, row, height=4):
        ttk.Label(parent, text=label).grid(row=row, column=0, columnspan=4, sticky='w', padx=4, pady=(7, 1))
        txt = tk.Text(parent, height=height, wrap='word')
        txt.grid(row=row+1, column=0, columnspan=4, sticky='ew', padx=4, pady=(0, 6))
        return txt

    def _build_form(self, f):
        for c in range(4):
            f.grid_columnconfigure(c, weight=1)
        lf0 = ttk.LabelFrame(f, text='Identificação e dados do atendimento')
        lf0.grid(row=0, column=0, columnspan=4, sticky='ew', pady=(0, 8))
        for c in range(4): lf0.grid_columnconfigure(c, weight=1)
        self._entry(lf0, 'ID:', self.var_id, 0, 0, 22).configure(state='readonly')
        self._entry(lf0, 'Data/Hora:', self.var_data, 0, 1, 22)
        self._entry(lf0, 'Profissional:', self.var_profissional, 0, 2, 24)
        self._entry(lf0, 'Registro/CRF:', self.var_registro, 0, 3, 18)
        self._entry(lf0, 'Paciente/Cliente:', self.var_paciente, 2, 0, 34)
        self._entry(lf0, 'CPF/Documento:', self.var_documento, 2, 1, 20)
        self._entry(lf0, 'Nascimento/Idade:', self.var_nascimento, 2, 2, 20)
        self._entry(lf0, 'Telefone/WhatsApp:', self.var_telefone, 2, 3, 20)
        self._entry(lf0, 'Endereço:', self.var_endereco, 4, 0, 40)
        self._entry(lf0, 'Responsável:', self.var_responsavel, 4, 1, 30)
        self._combo(lf0, 'Tipo de atendimento:', self.var_tipo, self.TIPOS, 4, 2, 30)
        self._combo(lf0, 'Classificação de risco:', self.var_risco, self.RISCOS, 4, 3, 28)

        lf1 = ttk.LabelFrame(f, text='Triagem e sinais vitais')
        lf1.grid(row=1, column=0, columnspan=4, sticky='ew', pady=(0, 8))
        for c in range(4): lf1.grid_columnconfigure(c, weight=1)
        self._entry(lf1, 'PA (ex: 120x80):', self.var_pa, 0, 0, 18)
        self._entry(lf1, 'FC bpm:', self.var_fc, 0, 1, 12)
        self._entry(lf1, 'Temperatura °C:', self.var_temperatura, 0, 2, 14)
        self._entry(lf1, 'SpO2 %:', self.var_spo2, 0, 3, 12)
        self._entry(lf1, 'Glicemia mg/dL:', self.var_glicemia, 2, 0, 16)
        ent_peso = self._entry(lf1, 'Peso kg:', self.var_peso, 2, 1, 12)
        ent_altura = self._entry(lf1, 'Altura m:', self.var_altura, 2, 2, 12)
        self._entry(lf1, 'IMC:', self.var_imc, 2, 3, 12)
        ttk.Button(lf1, text='Calcular IMC', command=self._calcular_imc).grid(row=4, column=3, sticky='e', padx=4, pady=4)
        try:
            ent_peso.bind('<KeyRelease>', lambda e: self._calcular_imc(silencioso=True))
            ent_altura.bind('<KeyRelease>', lambda e: self._calcular_imc(silencioso=True))
        except Exception:
            pass

        lf2 = ttk.LabelFrame(f, text='Dados clínicos, avaliação e conduta')
        lf2.grid(row=2, column=0, columnspan=4, sticky='ew', pady=(0, 8))
        for c in range(4): lf2.grid_columnconfigure(c, weight=1)
        self.txt_queixa = self._text(lf2, 'Queixa principal / motivo do atendimento:', 0, 3)
        self.txt_anamnese = self._text(lf2, 'História/Anamnese resumida:', 2, 4)
        self.txt_alergias = self._text(lf2, 'Alergias conhecidas:', 4, 2)
        self.txt_condicoes = self._text(lf2, 'Doenças/condições conhecidas:', 6, 2)
        self.txt_medicamentos_uso = self._text(lf2, 'Medicamentos em uso contínuo/atual:', 8, 3)
        self.txt_reacao = self._text(lf2, 'Reação adversa suspeita / interação / contraindicação observada:', 10, 3)
        self.txt_avaliacao = self._text(lf2, 'Avaliação farmacêutica:', 12, 4)
        self.txt_conduta = self._text(lf2, 'Conduta realizada no ambulatório:', 14, 4)
        self.txt_medicamentos_orientados = self._text(lf2, 'Medicamentos/produtos orientados ou administrados:', 16, 3)
        self.txt_orientacoes = self._text(lf2, 'Orientações dadas ao paciente:', 18, 4)
        self.txt_encaminhamento = self._text(lf2, 'Encaminhamento / sinais de alerta / procurar serviço de saúde:', 20, 3)
        self.txt_retorno = self._text(lf2, 'Retorno / acompanhamento / monitoramento:', 22, 2)
        self.txt_observacoes = self._text(lf2, 'Observações internas:', 24, 2)
        self._entry(lf2, 'Consentimento/ciência:', self.var_consentimento, 26, 0, 80).grid(columnspan=4, sticky='ew')

        bar = ttk.Frame(f)
        bar.grid(row=3, column=0, columnspan=4, sticky='ew', pady=8)
        ttk.Button(bar, text='Novo', command=self._novo).pack(side=tk.LEFT, padx=4)
        ttk.Button(bar, text='Salvar prontuário', command=self._salvar).pack(side=tk.LEFT, padx=4)
        ttk.Button(bar, text='Excluir', command=self._excluir).pack(side=tk.LEFT, padx=4)
        ttk.Button(bar, text='Resumo / imprimir TXT', command=self._exportar_txt).pack(side=tk.LEFT, padx=4)
        ttk.Button(bar, text='WhatsApp orientação', command=self._whatsapp).pack(side=tk.LEFT, padx=4)

    def _build_list(self, parent):
        top = ttk.Frame(parent)
        top.pack(fill=tk.X, pady=(0, 6))
        ttk.Label(top, text='Buscar:').pack(side=tk.LEFT)
        ent = ttk.Entry(top, textvariable=self.var_filtro, width=36)
        ent.pack(side=tk.LEFT, fill=tk.X, expand=True, padx=5)
        ent.bind('<KeyRelease>', lambda e: self._carregar_lista())
        ttk.Button(top, text='Atualizar', command=self._carregar_lista).pack(side=tk.LEFT, padx=3)

        cols = ('id', 'data', 'paciente', 'tipo', 'risco', 'profissional')
        self.tree = ttk.Treeview(parent, columns=cols, show='headings', height=22)
        widths = {'id':120, 'data':135, 'paciente':190, 'tipo':160, 'risco':150, 'profissional':150}
        for c in cols:
            self.tree.heading(c, text=c.upper())
            self.tree.column(c, width=widths.get(c, 120), anchor='w')
        sy = ttk.Scrollbar(parent, orient='vertical', command=self.tree.yview)
        sx = ttk.Scrollbar(parent, orient='horizontal', command=self.tree.xview)
        self.tree.configure(yscrollcommand=sy.set, xscrollcommand=sx.set)
        self.tree.pack(side=tk.TOP, fill=tk.BOTH, expand=True)
        sy.pack(side=tk.RIGHT, fill=tk.Y)
        sx.pack(side=tk.BOTTOM, fill=tk.X)
        self.tree.bind('<<TreeviewSelect>>', self._selecionar)
        ttk.Label(parent, textvariable=self.var_info, foreground='#475569').pack(anchor='w', pady=(6, 0))

    def _get_text(self, widget):
        try:
            return widget.get('1.0', tk.END).strip()
        except Exception:
            return ''

    def _set_text(self, widget, valor):
        try:
            widget.delete('1.0', tk.END)
            widget.insert('1.0', str(valor or ''))
        except Exception:
            pass

    def _calcular_imc(self, silencioso=False):
        try:
            peso = _farmacia_tc_float(self.var_peso.get(), 0)
            altura = _farmacia_tc_float(self.var_altura.get(), 0)
            if altura > 3:
                altura = altura / 100.0
            if peso > 0 and altura > 0:
                self.var_imc.set(f'{peso / (altura * altura):.2f}'.replace('.', ','))
            elif not silencioso:
                messagebox.showwarning('IMC', 'Informe peso e altura válidos.', parent=self.win)
        except Exception as e:
            if not silencioso:
                messagebox.showerror('IMC', f'Erro ao calcular IMC:\n{e}', parent=self.win)

    def _novo(self):
        self.selected_id = None
        self.var_id.set(_farmacia_amb_id())
        self.var_data.set(_farmacia_amb_now())
        for var in (self.var_paciente, self.var_documento, self.var_nascimento, self.var_telefone, self.var_endereco,
                    self.var_responsavel, self.var_pa, self.var_fc, self.var_temperatura, self.var_spo2,
                    self.var_glicemia, self.var_peso, self.var_altura, self.var_imc):
            var.set('')
        self.var_tipo.set(self.TIPOS[0]); self.var_risco.set(self.RISCOS[0])
        for w in (self.txt_queixa, self.txt_anamnese, self.txt_alergias, self.txt_condicoes,
                  self.txt_medicamentos_uso, self.txt_reacao, self.txt_avaliacao, self.txt_conduta,
                  self.txt_medicamentos_orientados, self.txt_orientacoes, self.txt_encaminhamento,
                  self.txt_retorno, self.txt_observacoes):
            self._set_text(w, '')

    def _montar(self):
        return {
            'id': self.var_id.get().strip() or _farmacia_amb_id(),
            'data_hora': self.var_data.get().strip() or _farmacia_amb_now(),
            'profissional': self.var_profissional.get().strip(),
            'registro_profissional': self.var_registro.get().strip(),
            'paciente_nome': self.var_paciente.get().strip(),
            'documento': self.var_documento.get().strip(),
            'nascimento_idade': self.var_nascimento.get().strip(),
            'telefone': self.var_telefone.get().strip(),
            'endereco': self.var_endereco.get().strip(),
            'responsavel': self.var_responsavel.get().strip(),
            'tipo_atendimento': self.var_tipo.get().strip(),
            'risco': self.var_risco.get().strip(),
            'pa': self.var_pa.get().strip(), 'fc': self.var_fc.get().strip(), 'temperatura': self.var_temperatura.get().strip(),
            'spo2': self.var_spo2.get().strip(), 'glicemia': self.var_glicemia.get().strip(), 'peso': self.var_peso.get().strip(),
            'altura': self.var_altura.get().strip(), 'imc': self.var_imc.get().strip(),
            'queixa': self._get_text(self.txt_queixa),
            'anamnese': self._get_text(self.txt_anamnese),
            'alergias': self._get_text(self.txt_alergias),
            'condicoes': self._get_text(self.txt_condicoes),
            'medicamentos_uso': self._get_text(self.txt_medicamentos_uso),
            'reacao_interacao': self._get_text(self.txt_reacao),
            'avaliacao': self._get_text(self.txt_avaliacao),
            'conduta': self._get_text(self.txt_conduta),
            'medicamentos_orientados': self._get_text(self.txt_medicamentos_orientados),
            'orientacoes': self._get_text(self.txt_orientacoes),
            'encaminhamento': self._get_text(self.txt_encaminhamento),
            'retorno': self._get_text(self.txt_retorno),
            'observacoes': self._get_text(self.txt_observacoes),
            'consentimento': self.var_consentimento.get().strip(),
            'atualizado_em': _farmacia_amb_now(),
        }

    def _salvar(self):
        pront = self._montar()
        if not pront.get('paciente_nome'):
            messagebox.showerror('Prontuário ambulatorial', 'Informe o nome do paciente.', parent=self.win); return
        if not pront.get('queixa') and not pront.get('tipo_atendimento'):
            messagebox.showerror('Prontuário ambulatorial', 'Informe pelo menos o tipo de atendimento ou queixa principal.', parent=self.win); return
        if pront.get('risco','').startswith('Vermelho'):
            messagebox.showwarning('Classificação de risco', 'Risco VERMELHO: orientar encaminhamento imediato para serviço de urgência/emergência.', parent=self.win)
        self.dados[pront['id']] = pront
        if _farmacia_amb_save(self.dados):
            self.selected_id = pront['id']
            self._carregar_lista()
            messagebox.showinfo('Prontuário ambulatorial', 'Prontuário salvo com sucesso.', parent=self.win)
        else:
            messagebox.showerror('Prontuário ambulatorial', 'Não foi possível salvar o prontuário.', parent=self.win)

    def _carregar_lista(self):
        try:
            self.tree.delete(*self.tree.get_children())
        except Exception:
            return
        filtro = self.var_filtro.get().strip().lower() if hasattr(self, 'var_filtro') else ''
        total = 0
        for pid, p in sorted((self.dados or {}).items(), key=lambda kv: str(kv[1].get('data_hora','')), reverse=True):
            texto = ' '.join(str(p.get(k,'')) for k in ('paciente_nome','telefone','documento','tipo_atendimento','risco','profissional','data_hora')).lower()
            if filtro and filtro not in texto:
                continue
            total += 1
            self.tree.insert('', tk.END, iid=pid, values=(pid, p.get('data_hora',''), p.get('paciente_nome',''), p.get('tipo_atendimento',''), p.get('risco',''), p.get('profissional','')))
        self.var_info.set(f'{total} prontuário(s) listado(s).')

    def _selecionar(self, event=None):
        sel = self.tree.selection()
        if not sel:
            return
        pid = sel[0]
        p = self.dados.get(pid)
        if not p:
            return
        self.selected_id = pid
        self.var_id.set(p.get('id',''))
        self.var_data.set(p.get('data_hora',''))
        self.var_profissional.set(p.get('profissional',''))
        self.var_registro.set(p.get('registro_profissional',''))
        self.var_paciente.set(p.get('paciente_nome',''))
        self.var_documento.set(p.get('documento',''))
        self.var_nascimento.set(p.get('nascimento_idade',''))
        self.var_telefone.set(p.get('telefone',''))
        self.var_endereco.set(p.get('endereco',''))
        self.var_responsavel.set(p.get('responsavel',''))
        self.var_tipo.set(p.get('tipo_atendimento', self.TIPOS[0]))
        self.var_risco.set(p.get('risco', self.RISCOS[0]))
        self.var_pa.set(p.get('pa','')); self.var_fc.set(p.get('fc','')); self.var_temperatura.set(p.get('temperatura',''))
        self.var_spo2.set(p.get('spo2','')); self.var_glicemia.set(p.get('glicemia','')); self.var_peso.set(p.get('peso',''))
        self.var_altura.set(p.get('altura','')); self.var_imc.set(p.get('imc',''))
        self.var_consentimento.set(p.get('consentimento',''))
        mapping = [
            (self.txt_queixa,'queixa'), (self.txt_anamnese,'anamnese'), (self.txt_alergias,'alergias'),
            (self.txt_condicoes,'condicoes'), (self.txt_medicamentos_uso,'medicamentos_uso'),
            (self.txt_reacao,'reacao_interacao'), (self.txt_avaliacao,'avaliacao'), (self.txt_conduta,'conduta'),
            (self.txt_medicamentos_orientados,'medicamentos_orientados'), (self.txt_orientacoes,'orientacoes'),
            (self.txt_encaminhamento,'encaminhamento'), (self.txt_retorno,'retorno'), (self.txt_observacoes,'observacoes')
        ]
        for w, k in mapping:
            self._set_text(w, p.get(k,''))

    def _excluir(self):
        if not self.selected_id:
            messagebox.showwarning('Prontuário ambulatorial', 'Selecione um prontuário para excluir.', parent=self.win); return
        if messagebox.askyesno('Confirmar exclusão', 'Deseja excluir este prontuário?', parent=self.win):
            self.dados.pop(self.selected_id, None)
            _farmacia_amb_save(self.dados)
            self._novo(); self._carregar_lista()

    def _exportar_txt(self):
        pront = self._montar()
        if self.selected_id and self.selected_id in self.dados:
            pront = self.dados[self.selected_id]
        resumo = _farmacia_amb_resumo(pront)
        try:
            from tkinter import filedialog
            nome = f"prontuario_ambulatorio_{pront.get('id','sem_id')}.txt"
            path = filedialog.asksaveasfilename(parent=self.win, title='Salvar prontuário', defaultextension='.txt', initialfile=nome, filetypes=[('Texto', '*.txt'), ('Todos', '*.*')])
            if path:
                with open(path, 'w', encoding='utf-8') as f:
                    f.write(resumo)
                messagebox.showinfo('Prontuário', f'Arquivo salvo em:\n{path}', parent=self.win)
            else:
                messagebox.showinfo('Resumo do prontuário', resumo[:4000], parent=self.win)
        except Exception as e:
            messagebox.showerror('Prontuário', f'Erro ao exportar:\n{e}', parent=self.win)

    def _whatsapp(self):
        pront = self._montar()
        telefone = _farmacia_amb_limpar_numero(pront.get('telefone'))
        if not telefone:
            messagebox.showwarning('WhatsApp', 'Informe o telefone/WhatsApp do paciente.', parent=self.win); return
        if not telefone.startswith('55') and len(telefone) >= 10:
            telefone = '55' + telefone
        msg = (f"Olá {pront.get('paciente_nome','')}, segue orientação do atendimento na farmácia:\n\n"
               f"Atendimento: {pront.get('tipo_atendimento','')}\n"
               f"Orientações: {pront.get('orientacoes','')}\n"
               f"Retorno/encaminhamento: {pront.get('retorno','') or pront.get('encaminhamento','')}\n\n"
               "Em caso de piora, procure atendimento médico/urgência.")
        try:
            import urllib.parse, webbrowser
            webbrowser.open(f"https://wa.me/{telefone}?text={urllib.parse.quote(msg)}")
        except Exception as e:
            messagebox.showerror('WhatsApp', f'Erro ao abrir WhatsApp:\n{e}', parent=self.win)


def _farmacia_amb_open_window(self):
    return FarmaciaAmbulatorioProntuarioWindow(self, getattr(self, 'root', None))


def _farmacia_amb_patch_app():
    try:
        if 'PDVSuperApp' not in globals():
            return
        if getattr(PDVSuperApp, '_farmacia_amb_patch_aplicado', False):
            return
        PDVSuperApp.open_prontuario_ambulatorio = _farmacia_amb_open_window
        _orig_create_menu = PDVSuperApp._create_menu
        def _patched_create_menu(self, *args, **kwargs):
            resultado = _orig_create_menu(self, *args, **kwargs)
            try:
                if not _fq_farma_menu_visivel(self, "menu_ambulatorio_visivel"):
                    return resultado
                menubar = self.root.nametowidget(self.root.cget('menu'))
                amb_menu = tk.Menu(menubar, tearoff=0)
                amb_menu.add_command(label='🏥 Prontuário Ambulatorial Completo', command=self.open_prontuario_ambulatorio, accelerator='Ctrl+Alt+A')
                menubar.add_cascade(label='🏥 Ambulatório', menu=amb_menu)
                self.root.bind('<Control-Alt-a>', lambda event: self.open_prontuario_ambulatorio())
                self.root.bind('<Control-Alt-A>', lambda event: self.open_prontuario_ambulatorio())
            except Exception as e:
                print(f'[PRONTUÁRIO AMBULATÓRIO] Aviso ao adicionar menu: {e}')
            return resultado
        PDVSuperApp._create_menu = _patched_create_menu
        PDVSuperApp._farmacia_amb_patch_aplicado = True
        print('[PRONTUÁRIO AMBULATÓRIO] Patch aplicado com sucesso.')
    except Exception as e:
        print(f'[PRONTUÁRIO AMBULATÓRIO] Falha ao aplicar patch: {e}')



# ═══════════════════════════════════════════════════════════════════════════════
# 🏪 PATCH FARMÁCIA PRO - RECURSOS COMERCIAIS MODERNOS PARA DROGARIAS
# ═══════════════════════════════════════════════════════════════════════════════
# Recursos adicionados sem alterar a lógica principal do PDV:
# - Receituário / controlados / antibióticos / retenção de receita / SNGPC.
# - PBM, convênios, cartões de desconto e autorizações comerciais.
# - Campanhas, ofertas, combos, encartes e validade promocional.
# - Serviços farmacêuticos: vacinação, aplicação, testes rápidos e agenda.
# - Pós-venda/CRM: retorno ativo, WhatsApp, tele-entrega e fidelização.
# - Dashboard de alertas: receitas vencendo, campanhas vencendo e serviços do dia.
# - Armazenamento local robusto em JSON para não quebrar o banco atual.
# ═══════════════════════════════════════════════════════════════════════════════

try:
    FARMACIA_PRO_FILE = os.path.join(DATA_DIR, "farmacia_pro_comercial.json")
except Exception:
    FARMACIA_PRO_FILE = "farmacia_pro_comercial.json"


def _farma_pro_now():
    try:
        return datetime.datetime.now().strftime('%d/%m/%Y %H:%M:%S')
    except Exception:
        return ''


def _farma_pro_today_iso():
    try:
        return datetime.date.today().isoformat()
    except Exception:
        return ''


def _farma_pro_parse_date(valor):
    txt = str(valor or '').strip()
    if not txt:
        return None
    for fmt in ('%d/%m/%Y', '%Y-%m-%d', '%d-%m-%Y'):
        try:
            return datetime.datetime.strptime(txt, fmt).date()
        except Exception:
            pass
    return None


def _farma_pro_fmt_date(d):
    try:
        if isinstance(d, datetime.date):
            return d.strftime('%d/%m/%Y')
    except Exception:
        pass
    return str(d or '')


def _farma_pro_add_days(valor, dias):
    base = _farma_pro_parse_date(valor) or datetime.date.today()
    try:
        return (base + datetime.timedelta(days=int(dias or 0))).strftime('%d/%m/%Y')
    except Exception:
        return base.strftime('%d/%m/%Y')


def _farma_pro_load():
    base = {
        'receitas': {},
        'pbm': {},
        'campanhas': {},
        'servicos': {},
        'posvenda': {},
        'config': {'versao': '1.0', 'criado_em': _farma_pro_now()}
    }
    try:
        dados = load_data(FARMACIA_PRO_FILE, base)
        if not isinstance(dados, dict):
            dados = base
    except Exception:
        try:
            if os.path.exists(FARMACIA_PRO_FILE):
                with open(FARMACIA_PRO_FILE, 'r', encoding='utf-8') as f:
                    dados = json.load(f)
                    if not isinstance(dados, dict):
                        dados = base
            else:
                dados = base
        except Exception:
            dados = base
    for k in base:
        dados.setdefault(k, base[k] if isinstance(base[k], dict) else {})
    return dados


def _farma_pro_save(dados):
    try:
        return bool(save_data(FARMACIA_PRO_FILE, dados if isinstance(dados, dict) else {}))
    except Exception:
        try:
            pasta = os.path.dirname(FARMACIA_PRO_FILE)
            if pasta:
                os.makedirs(pasta, exist_ok=True)
            with open(FARMACIA_PRO_FILE, 'w', encoding='utf-8') as f:
                json.dump(dados if isinstance(dados, dict) else {}, f, indent=4, ensure_ascii=False)
            return True
        except Exception:
            return False


def _farma_pro_id(prefixo):
    try:
        return prefixo + datetime.datetime.now().strftime('%Y%m%d%H%M%S%f')
    except Exception:
        import time
        return prefixo + str(int(time.time() * 1000))


def _farma_pro_so_numero(valor):
    try:
        return ''.join(ch for ch in str(valor or '') if ch.isdigit())
    except Exception:
        return ''


def _farma_pro_whatsapp(telefone, mensagem):
    tel = _farma_pro_so_numero(telefone)
    if not tel:
        try:
            messagebox.showwarning('WhatsApp', 'Telefone/WhatsApp não informado.')
        except Exception:
            pass
        return
    if len(tel) in (10, 11):
        tel = '55' + tel
    try:
        import urllib.parse, webbrowser
        webbrowser.open(f"https://wa.me/{tel}?text={urllib.parse.quote(str(mensagem or ''))}")
    except Exception as e:
        try:
            messagebox.showerror('WhatsApp', f'Erro ao abrir WhatsApp:\n{e}')
        except Exception:
            pass


def _farma_pro_alertas(dados=None):
    dados = dados or _farma_pro_load()
    hoje = datetime.date.today()
    alertas = []

    for rid, r in (dados.get('receitas') or {}).items():
        if str(r.get('status','Ativa')).lower().startswith('final'):
            continue
        validade = _farma_pro_parse_date(r.get('validade_receita'))
        if validade:
            dias = (validade - hoje).days
            if dias < 0:
                alertas.append(('CRÍTICO', f"Receita vencida há {abs(dias)} dia(s): {r.get('paciente','')} - {r.get('medicamento','')}"))
            elif dias <= 5:
                alertas.append(('ATENÇÃO', f"Receita vence em {dias} dia(s): {r.get('paciente','')} - {r.get('medicamento','')}"))

    for cid, c in (dados.get('campanhas') or {}).items():
        fim = _farma_pro_parse_date(c.get('data_fim'))
        if fim and str(c.get('status','Ativa')).lower().startswith('ativa'):
            dias = (fim - hoje).days
            if dias < 0:
                alertas.append(('INFO', f"Campanha encerrada: {c.get('titulo','')}"))
            elif dias <= 3:
                alertas.append(('ATENÇÃO', f"Campanha termina em {dias} dia(s): {c.get('titulo','')}"))

    for sid, s in (dados.get('servicos') or {}).items():
        data = _farma_pro_parse_date(s.get('data_servico'))
        if data and str(s.get('status','Agendado')).lower() in ('agendado','confirmado','pendente'):
            dias = (data - hoje).days
            if dias == 0:
                alertas.append(('HOJE', f"Serviço hoje: {s.get('tipo_servico','')} - {s.get('paciente','')} às {s.get('hora','')}"))
            elif dias == 1:
                alertas.append(('AMANHÃ', f"Serviço amanhã: {s.get('tipo_servico','')} - {s.get('paciente','')}"))

    for pid, p in (dados.get('posvenda') or {}).items():
        data = _farma_pro_parse_date(p.get('data_retorno'))
        if data and str(p.get('status','Pendente')).lower() in ('pendente','agendado','aberto'):
            dias = (data - hoje).days
            if dias <= 0:
                alertas.append(('CRM', f"Retorno pendente: {p.get('cliente','')} - {p.get('motivo','')}"))
    return alertas


class FarmaciaProComercialWindow:
    def __init__(self, app=None, master=None):
        self.app = app
        self.master = master or getattr(app, 'root', None)
        self.dados = _farma_pro_load()
        self.selected = {'receitas': None, 'pbm': None, 'campanhas': None, 'servicos': None, 'posvenda': None}
        self.vars = {}
        self.trees = {}
        self.win = tk.Toplevel(self.master) if self.master is not None else tk.Tk()
        self.win.title('🏪 Farmácia Pro - Recursos Comerciais Avançados')
        try:
            self.win.state('zoomed')
        except Exception:
            try:
                self.win.attributes('-zoomed', True)
            except Exception:
                pass
        self.win.minsize(1100, 680)
        try:
            self.win.configure(bg='#f8fafc')
        except Exception:
            pass
        self._build()
        self._refresh_all()

    def _title(self, parent, titulo, subtitulo):
        top = tk.Frame(parent, bg='#f8fafc')
        top.pack(fill='x', padx=12, pady=(10, 6))
        tk.Label(top, text=titulo, font=('Segoe UI', 18, 'bold'), fg='#064e3b', bg='#f8fafc').pack(anchor='w')
        tk.Label(top, text=subtitulo, font=('Segoe UI', 10), fg='#334155', bg='#f8fafc').pack(anchor='w')

    def _build(self):
        self._title(self.win, '🏪 FARMÁCIA PRO - GESTÃO COMERCIAL AVANÇADA',
                    'Receituário, controlados, PBM, convênios, campanhas, serviços farmacêuticos, CRM e alertas comerciais.')
        bar = tk.Frame(self.win, bg='#ecfdf5')
        bar.pack(fill='x', padx=12, pady=(0, 8))
        ttk.Button(bar, text='🔔 Dashboard / Alertas', command=self._dashboard).pack(side='left', padx=4, pady=6)
        ttk.Button(bar, text='📤 Exportar relatório TXT', command=self._exportar_relatorio).pack(side='left', padx=4, pady=6)
        ttk.Button(bar, text='🔄 Atualizar tudo', command=self._refresh_all).pack(side='left', padx=4, pady=6)

        self.nb = ttk.Notebook(self.win)
        self.nb.pack(fill='both', expand=True, padx=12, pady=(0, 5))
        self._tab_receitas()
        self._tab_pbm()
        self._tab_campanhas()
        self._tab_servicos()
        self._tab_posvenda()

    def _entry(self, parent, key, label, row, col=0, width=28, combo=None, check=False):
        tk.Label(parent, text=label, bg='#ffffff', fg='#0f172a', font=('Segoe UI', 9)).grid(row=row, column=col*2, sticky='w', padx=6, pady=3)
        if check:
            var = tk.BooleanVar(value=False)
            w = ttk.Checkbutton(parent, variable=var)
        elif combo:
            var = tk.StringVar()
            w = ttk.Combobox(parent, textvariable=var, values=combo, width=width, state='readonly')
        else:
            var = tk.StringVar()
            w = ttk.Entry(parent, textvariable=var, width=width)
        w.grid(row=row, column=col*2+1, sticky='ew', padx=6, pady=3)
        self.vars[key] = var
        return w

    def _text(self, parent, key, label, row, col=0, height=4, width=46):
        tk.Label(parent, text=label, bg='#ffffff', fg='#0f172a', font=('Segoe UI', 9)).grid(row=row, column=col*2, sticky='nw', padx=6, pady=3)
        txt = tk.Text(parent, height=height, width=width, wrap='word')
        txt.grid(row=row, column=col*2+1, sticky='nsew', padx=6, pady=3)
        self.vars[key] = txt
        return txt

    def _frame_split(self, tab):
        body = tk.Frame(tab, bg='#f8fafc')
        body.pack(fill='both', expand=True, padx=8, pady=8)
        left = tk.LabelFrame(body, text='Cadastro / edição', bg='#ffffff', fg='#0f172a')
        right = tk.LabelFrame(body, text='Registros', bg='#ffffff', fg='#0f172a')
        left.pack(side='left', fill='both', expand=False, padx=(0, 8))
        right.pack(side='left', fill='both', expand=True)
        return left, right

    def _make_tree(self, parent, key, columns, widths=None):
        search = tk.Frame(parent, bg='#ffffff')
        search.pack(fill='x', padx=6, pady=6)
        tk.Label(search, text='Buscar:', bg='#ffffff').pack(side='left')
        var = tk.StringVar()
        ent = ttk.Entry(search, textvariable=var)
        ent.pack(side='left', fill='x', expand=True, padx=4)
        ttk.Button(search, text='Atualizar', command=lambda: self._refresh_tree(key, var.get())).pack(side='left', padx=3)
        tree = ttk.Treeview(parent, columns=columns, show='headings')
        for i, c in enumerate(columns):
            tree.heading(c, text=c.upper())
            tree.column(c, width=(widths or {}).get(c, 120), anchor='w')
        y = ttk.Scrollbar(parent, orient='vertical', command=tree.yview)
        x = ttk.Scrollbar(parent, orient='horizontal', command=tree.xview)
        tree.configure(yscrollcommand=y.set, xscrollcommand=x.set)
        tree.pack(side='left', fill='both', expand=True, padx=(6,0), pady=(0,6))
        y.pack(side='right', fill='y', pady=(0,6))
        x.pack(side='bottom', fill='x', padx=6)
        tree.bind('<<TreeviewSelect>>', lambda e, k=key: self._on_select(k))
        self.trees[key] = tree
        return tree

