try:
    RELATORIOS_FARMA_DIR = os.path.join(DATA_DIR, "relatorios_farmacia")
except Exception:
    RELATORIOS_FARMA_DIR = os.path.join(os.getcwd(), "relatorios_farmacia")


def _rf_now():
    return datetime.datetime.now().strftime('%d/%m/%Y %H:%M:%S')


def _rf_today_iso():
    return datetime.date.today().isoformat()


def _rf_parse_date(valor):
    if isinstance(valor, datetime.date):
        return valor
    if valor is None:
        return None
    s = str(valor).strip()
    if not s:
        return None
    for fmt in ('%Y-%m-%d', '%d/%m/%Y', '%d-%m-%Y', '%Y/%m/%d', '%d/%m/%Y %H:%M:%S'):
        try:
            return datetime.datetime.strptime(s[:19], fmt).date()
        except Exception:
            pass
    try:
        return datetime.date.fromisoformat(s[:10])
    except Exception:
        return None


def _rf_fmt_date(valor):
    d = _rf_parse_date(valor)
    return d.strftime('%d/%m/%Y') if d else (str(valor) if valor not in (None, '') else '')


def _rf_safe_money(valor):
    try:
        if isinstance(valor, str):
            valor = valor.replace('R$', '').replace('.', '').replace(',', '.').strip()
        return float(valor or 0)
    except Exception:
        return 0.0


def _rf_money(valor):
    return ('R$ %.2f' % _rf_safe_money(valor)).replace('.', ',')


def _rf_load_json(path, default):
    try:
        if not path:
            return default
        if 'load_data' in globals():
            dados = load_data(path, default)
            return dados if dados is not None else default
        if os.path.exists(path):
            with open(path, 'r', encoding='utf-8') as f:
                return json.load(f)
    except Exception:
        pass
    return default


def _rf_load_all():
    def g(nome, default_path=''):
        return globals().get(nome, default_path)
    dados = {
        'produtos': _rf_load_json(g('PRODUCTS_FILE'), {}),
        'clientes': _rf_load_json(g('CUSTOMERS_FILE'), {}),
        'vendas': _dedup_vendas_por_cupom(_rf_load_json(g('SALES_FILE'), [])),
        'tratamentos': _rf_load_json(g('TRATAMENTOS_FILE'), {}),
        'prontuarios': _rf_load_json(g('PRONTUARIO_AMBULATORIO_FILE'), {}),
        'farmacia_pro': _rf_load_json(g('FARMACIA_PRO_FILE'), {'receitas':{}, 'pbm':{}, 'campanhas':{}, 'servicos':{}, 'posvenda':{}}),
        'notas': _rf_load_json(g('NOTAS_ENTRADA_FILE'), {}),
        'caixa': _rf_load_json(g('CAIXA_FILE'), {}),
        'empresa': _rf_load_json(g('EMPRESA_FILE'), {}),
    }
    return dados


def _rf_iter_values(obj):
    if isinstance(obj, dict):
        return list(obj.values())
    if isinstance(obj, list):
        return obj
    return []


def _dedup_vendas_por_cupom(vendas):
    """Remove registros de venda duplicados que tenham o mesmo numero de cupom.

    Registros duplicados (mesmo coupon_number) inflavam o relatorio de PRODUTOS
    VENDIDOS e o de VENDAS, pois cada item da venda era contado varias vezes.
    Como cada venda finalizada recebe um numero de cupom unico e crescente, a
    presenca do mesmo cupom mais de uma vez significa duplicidade: mantemos
    apenas a ultima ocorrencia (a mais completa/recente) preservando a ordem.
    Registros sem numero de cupom sao mantidos como estao (nao ha como
    deduplicar com seguranca)."""
    if not isinstance(vendas, list):
        return vendas
    vistos = {}
    ordem = []
    sem_cupom = []
    for v in vendas:
        if not isinstance(v, dict):
            sem_cupom.append(v)
            continue
        cup = v.get('coupon_number', v.get('numero_venda',
              v.get('cupom', v.get('numero_cupom', v.get('numero')))))
        if cup in (None, ''):
            sem_cupom.append(v)
            continue
        chave = str(cup).strip()
        if chave not in vistos:
            ordem.append(chave)
        vistos[chave] = v  # mantem a ultima ocorrencia do cupom
    resultado = [vistos[c] for c in ordem]
    resultado.extend(sem_cupom)
    return resultado


def _rf_get(item, *keys):
    if not isinstance(item, dict):
        return ''
    for k in keys:
        if k in item and item.get(k) not in (None, ''):
            return item.get(k)
    return ''


def _rf_empresa_nome(dados=None):
    try:
        emp = (dados or _rf_load_all()).get('empresa') or {}
        if isinstance(emp, dict):
            return emp.get('nome_fantasia') or emp.get('razao_social') or emp.get('nome') or 'FARMA QUANTUM'
    except Exception:
        pass
    return 'FARMA QUANTUM'


def _rf_alertas_vencimentos_produtos(dados=None, dias=30):
    dados = dados or _rf_load_all()
    hoje = datetime.date.today()
    linhas = []
    for p in _rf_iter_values(dados.get('produtos')):
        validade = _rf_get(p, 'data_validade', 'validade', 'validade_lote')
        d = _rf_parse_date(validade)
        if not d:
            continue
        restante = (d - hoje).days
        if restante < 0:
            status = 'VENCIDO'
        elif restante == 0:
            status = 'VENCE HOJE'
        elif restante <= int(dias):
            status = f'VENCE EM {restante} DIA(S)'
        else:
            continue
        linhas.append({
            'Produto': _rf_get(p, 'nome', 'descricao', 'produto', 'name'),
            'Lote': _rf_get(p, 'lote', 'numero_lote'),
            'Validade': _rf_fmt_date(d),
            'Status': status,
            'Estoque': _rf_get(p, 'estoque', 'quantidade', 'stock'),
        })
    return linhas


def _rf_estoque_baixo(dados=None):
    dados = dados or _rf_load_all()
    linhas = []
    for p in _rf_iter_values(dados.get('produtos')):
        estoque = _rf_safe_money(_rf_get(p, 'estoque', 'quantidade', 'stock'))
        minimo = _rf_safe_money(_rf_get(p, 'estoque_minimo', 'minimo', 'minimum_stock'))
        if minimo <= 0:
            minimo = 5
        if estoque <= minimo:
            linhas.append({
                'Produto': _rf_get(p, 'nome', 'descricao', 'produto', 'name'),
                'Estoque': estoque,
                'Mínimo': minimo,
                'Grupo': _rf_get(p, 'grupo', 'categoria', 'category'),
                'Preço': _rf_money(_rf_get(p, 'preco_venda', 'valor_venda', 'price')),
            })
    return linhas


def _rf_tratamentos_alerta(dados=None):
    dados = dados or _rf_load_all()
    hoje = datetime.date.today()
    linhas = []
    for t in _rf_iter_values(dados.get('tratamentos')):
        if isinstance(t, dict) and not t.get('ativo', True):
            continue
        aviso = _rf_parse_date(_rf_get(t, 'data_lembrar_compra', 'data_aviso', 'lembrar_em'))
        acabar = _rf_parse_date(_rf_get(t, 'data_prevista_acabar', 'data_fim', 'acaba_em'))
        status = ''
        if aviso and aviso <= hoje:
            status = 'LEMBRAR COMPRA'
        elif acabar and (acabar - hoje).days <= 3:
            status = 'MEDICAMENTO ACABANDO'
        else:
            continue
        linhas.append({
            'Cliente': _rf_get(t, 'cliente', 'paciente', 'nome_cliente'),
            'Telefone': _rf_get(t, 'telefone', 'whatsapp'),
            'Medicamento': _rf_get(t, 'medicamento', 'produto'),
            'Acaba em': _rf_fmt_date(acabar),
            'Aviso': _rf_fmt_date(aviso),
            'Status': status,
        })
    return linhas


def _rf_farmacia_pro_relatorio(tipo, dados=None):
    dados = dados or _rf_load_all()
    fp = dados.get('farmacia_pro') or {}
    hoje = datetime.date.today()
    linhas = []
    if tipo == 'receitas':
        for r in _rf_iter_values(fp.get('receitas')):
            val = _rf_parse_date(_rf_get(r, 'validade_receita'))
            status = _rf_get(r, 'status') or 'Ativa'
            if val and val < hoje:
                status = 'VENCIDA'
            elif val and (val - hoje).days <= 7:
                status = 'VENCENDO'
            linhas.append({'Paciente':_rf_get(r,'paciente'), 'Medicamento':_rf_get(r,'medicamento'), 'Tipo':_rf_get(r,'tipo'), 'Receita':_rf_get(r,'numero_receita'), 'Prescritor':_rf_get(r,'prescritor'), 'CRM':_rf_get(r,'crm'), 'Validade':_rf_fmt_date(val), 'Status':status})
    elif tipo == 'pbm':
        for p in _rf_iter_values(fp.get('pbm')):
            linhas.append({'Cliente':_rf_get(p,'cliente'), 'Programa':_rf_get(p,'programa'), 'Operadora':_rf_get(p,'operadora'), 'Medicamento':_rf_get(p,'medicamento'), 'Autorização':_rf_get(p,'autorizacao'), 'Desconto':_rf_get(p,'desconto'), 'Validade':_rf_fmt_date(_rf_get(p,'validade')), 'Status':_rf_get(p,'status')})
    elif tipo == 'campanhas':
        for c in _rf_iter_values(fp.get('campanhas')):
            linhas.append({'Campanha':_rf_get(c,'titulo'), 'Tipo':_rf_get(c,'tipo'), 'Produto':_rf_get(c,'produto'), 'Condição':_rf_get(c,'preco'), 'Início':_rf_fmt_date(_rf_get(c,'data_inicio')), 'Fim':_rf_fmt_date(_rf_get(c,'data_fim')), 'Canal':_rf_get(c,'canal'), 'Status':_rf_get(c,'status')})
    elif tipo == 'servicos':
        for s in _rf_iter_values(fp.get('servicos')):
            linhas.append({'Paciente':_rf_get(s,'paciente'), 'Telefone':_rf_get(s,'telefone'), 'Serviço':_rf_get(s,'tipo_servico'), 'Profissional':_rf_get(s,'profissional'), 'Data':_rf_fmt_date(_rf_get(s,'data_servico')), 'Hora':_rf_get(s,'hora'), 'Valor':_rf_money(_rf_get(s,'valor')), 'Status':_rf_get(s,'status')})
    elif tipo == 'crm':
        for c in _rf_iter_values(fp.get('posvenda')):
            linhas.append({'Cliente':_rf_get(c,'cliente'), 'Telefone':_rf_get(c,'telefone'), 'Motivo':_rf_get(c,'motivo'), 'Produto':_rf_get(c,'produto'), 'Retorno':_rf_fmt_date(_rf_get(c,'data_retorno')), 'Status':_rf_get(c,'status')})
    return linhas


def _rf_prontuarios_resumo(dados=None):
    dados = dados or _rf_load_all()
    linhas = []
    for p in _rf_iter_values(dados.get('prontuarios')):
        linhas.append({'ID':_rf_get(p,'id'), 'Data':_rf_get(p,'data_hora','data'), 'Paciente':_rf_get(p,'paciente','cliente'), 'Tipo':_rf_get(p,'tipo_atendimento'), 'Risco':_rf_get(p,'risco','classificacao_risco'), 'PA':_rf_get(p,'pa'), 'Glicemia':_rf_get(p,'glicemia'), 'Conduta':_rf_get(p,'conduta')})
    return linhas


def _rf_vendas_resumo(dados=None):
    dados = dados or _rf_load_all()
    vendas = _rf_iter_values(dados.get('vendas'))
    linhas = []
    total = 0.0
    for v in vendas[-300:]:
        valor = _rf_safe_money(_rf_get(v, 'total', 'valor_total', 'subtotal'))
        total += valor
        linhas.append({'Data':_rf_get(v,'data','data_venda','created_at'), 'Cupom':_rf_get(v,'cupom','numero_cupom','id'), 'Cliente':_rf_get(v,'cliente','customer'), 'Forma':_rf_get(v,'forma_pagamento','pagamento'), 'Total':_rf_money(valor)})
    return linhas, total


def _rf_produto_categoria_lookup(dados=None):
    """Monta índices de categoria dos produtos por id/código e por nome.

    Como o item da venda normalmente não guarda a categoria, buscamos a
    categoria no cadastro de produtos usando o id ou o nome do produto."""
    dados = dados or _rf_load_all()
    by_id = {}
    by_nome = {}
    produtos = dados.get('produtos')

    def _reg(p, chave_dict=None):
        if not isinstance(p, dict):
            return
        cat = _rf_get(p, 'categoria', 'grupo', 'category', 'categoria_nome')
        if chave_dict not in (None, ''):
            by_id[str(chave_dict)] = cat
        pid = _rf_get(p, 'id', 'codigo', 'codigo_barras', 'produto_id')
        if pid not in (None, ''):
            by_id[str(pid)] = cat
        nome = _rf_get(p, 'nome', 'descricao', 'produto', 'name')
        if nome:
            by_nome[str(nome).strip().lower()] = cat

    if isinstance(produtos, dict):
        for pid, p in produtos.items():
            _reg(p, pid)
    elif isinstance(produtos, list):
        for p in produtos:
            _reg(p)
    return by_id, by_nome


def _rf_produtos_vendidos(dados=None, data_ini=None, data_fim=None,
                          filtro_produto='', filtro_categoria='', filtro_num_venda=''):
    """Gera as linhas do relatório de PRODUTOS VENDIDOS (uma linha por item vendido).

    Filtros suportados:
      - data_ini / data_fim: intervalo de datas (inclusivo);
      - filtro_produto: parte do nome do produto (contém);
      - filtro_categoria: parte da categoria/grupo (contém);
      - filtro_num_venda: parte do número da venda/cupom (contém).
    Retorna (linhas, total_qtd, total_valor)."""
    dados = dados or _rf_load_all()
    vendas = _rf_iter_values(dados.get('vendas'))
    by_id, by_nome = _rf_produto_categoria_lookup(dados)

    di = _rf_parse_date(data_ini) if data_ini else None
    df = _rf_parse_date(data_fim) if data_fim else None
    fp = (filtro_produto or '').strip().lower()
    fc = (filtro_categoria or '').strip().lower()
    fnv = (filtro_num_venda or '').strip().lower()

    linhas = []
    total_qtd = 0.0
    total_valor = 0.0

    for v in vendas:
        if not isinstance(v, dict):
            continue
        data_raw = _rf_get(v, 'data', 'data_venda', 'timestamp', 'created_at')
        data_venda = _rf_parse_date(data_raw)
        num_venda = str(_rf_get(v, 'coupon_number', 'numero_venda', 'numero',
                                'cupom', 'numero_cupom', 'id') or '')
        usuario = _rf_get(v, 'usuario', 'operador', 'vendedor_nome', 'vendedor') or ''
        cliente = _rf_get(v, 'cliente_nome', 'cliente', 'customer') or ''
        forma = _rf_get(v, 'forma_pagamento', 'pagamento') or ''
        status = _rf_get(v, 'status') or 'finalizada'

        # Filtro por intervalo de datas.
        if di and (not data_venda or data_venda < di):
            continue
        if df and (not data_venda or data_venda > df):
            continue
        # Filtro por número da venda/cupom.
        if fnv and fnv not in num_venda.lower():
            continue

        itens = v.get('itens')
        if isinstance(itens, dict):
            item_pairs = list(itens.items())
        elif isinstance(itens, list):
            item_pairs = [(None, it) for it in itens]
        else:
            item_pairs = []

        for chave, item in item_pairs:
            if not isinstance(item, dict):
                continue
            nome = _rf_get(item, 'nome', 'descricao', 'produto', 'name') or ''
            qtd = _rf_safe_money(_rf_get(item, 'quantidade', 'qtd',
                                         'quantidade_peso', 'quantity'))
            if qtd == 0:
                qtd = 1
            preco = _rf_safe_money(_rf_get(item, 'preco_unit', 'preco',
                                           'preco_unitario', 'valor_unitario', 'price'))
            subtotal = _rf_safe_money(_rf_get(item, 'subtotal', 'total'))
            if subtotal == 0 and preco:
                subtotal = preco * qtd

            # Categoria: tenta no próprio item; senão busca no cadastro por id/nome.
            cat = _rf_get(item, 'categoria', 'grupo', 'category')
            if not cat:
                pid = _rf_get(item, 'id', 'produto_id', 'codigo', 'codigo_barras')
                if pid in (None, '') and chave is not None:
                    pid = chave
                if pid not in (None, '') and str(pid) in by_id:
                    cat = by_id.get(str(pid), '')
                if not cat and nome:
                    cat = by_nome.get(str(nome).strip().lower(), '')

            # Filtros por produto e categoria.
            if fp and fp not in str(nome).lower():
                continue
            if fc and fc not in str(cat or '').lower():
                continue

            total_qtd += qtd
            total_valor += subtotal
            try:
                qtd_disp = int(qtd) if float(qtd).is_integer() else round(qtd, 3)
            except Exception:
                qtd_disp = qtd

            linhas.append({
                'Produto': nome or '(sem nome)',
                'Qtd': qtd_disp,
                'Data': _rf_fmt_date(data_raw) or str(data_raw or ''),
                'Nº Venda': num_venda or '-',
                'Usuário': usuario or '-',
                'Status': status,
                'Categoria': cat or '-',
                'Preço Unit.': _rf_money(preco),
                'Subtotal': _rf_money(subtotal),
                'Cliente': cliente or '-',
                'Pagamento': forma or '-',
            })

    # Ordena por data (mais recentes primeiro) mantendo estabilidade.
    def _chave_ordem(l):
        d = _rf_parse_date(l.get('Data'))
        return d or datetime.date.min
    try:
        linhas.sort(key=_chave_ordem, reverse=True)
    except Exception:
        pass

    return linhas, total_qtd, total_valor


def _rf_html_escape(s):
    return str(s).replace('&','&amp;').replace('<','&lt;').replace('>','&gt;').replace('"','&quot;')


def _rf_ensure_dir():
    try:
        os.makedirs(RELATORIOS_FARMA_DIR, exist_ok=True)
    except Exception:
        pass


def _rf_make_a4_html(titulo, linhas, resumo=''):
    _rf_ensure_dir()
    nome = 'A4_' + ''.join(ch if ch.isalnum() else '_' for ch in titulo)[:50] + '_' + datetime.datetime.now().strftime('%Y%m%d_%H%M%S') + '.html'
    caminho = os.path.join(RELATORIOS_FARMA_DIR, nome)
    cols = []
    for row in linhas:
        if isinstance(row, dict):
            for k in row.keys():
                if k not in cols: cols.append(k)
    if not cols:
        cols = ['Informação']
        linhas = [{'Informação':'Nenhum registro encontrado para este relatório.'}]
    rows = []
    for row in linhas:
        rows.append('<tr>' + ''.join('<td>%s</td>' % _rf_html_escape(row.get(c,'')) for c in cols) + '</tr>')
    html = f'''<!doctype html>
<html lang="pt-br"><head><meta charset="utf-8"><title>{_rf_html_escape(titulo)}</title>
<style>
@page {{ size: A4; margin: 12mm; }}
body {{ font-family: Arial, Helvetica, sans-serif; color:#111827; font-size: 11px; }}
h1 {{ font-size: 20px; margin:0 0 4px; color:#064e3b; }}
.sub {{ font-size: 11px; color:#475569; margin-bottom: 12px; }}
.resumo {{ background:#ecfdf5; border:1px solid #a7f3d0; padding:8px; margin:8px 0 12px; border-radius:6px; }}
table {{ width:100%; border-collapse: collapse; }}
th {{ background:#065f46; color:white; text-align:left; padding:6px; font-size:10px; }}
td {{ border:1px solid #d1d5db; padding:5px; vertical-align:top; }}
tr:nth-child(even) {{ background:#f8fafc; }}
.footer {{ margin-top:12px; font-size:10px; color:#64748b; border-top:1px solid #cbd5e1; padding-top:6px; }}
@media print {{ .no-print {{ display:none; }} body {{ -webkit-print-color-adjust: exact; print-color-adjust: exact; }} }}
</style></head><body>
<button class="no-print" onclick="window.print()" style="padding:10px 18px;background:#059669;color:white;border:0;border-radius:6px;margin-bottom:10px;cursor:pointer">Imprimir A4</button>
<h1>{_rf_html_escape(titulo)}</h1>
<div class="sub">{_rf_html_escape(_rf_empresa_nome())} • Gerado em {_rf_now()}</div>
<div class="resumo">{_rf_html_escape(resumo or ('Total de registros: %s' % len(linhas)))}</div>
<table><thead><tr>{''.join('<th>%s</th>' % _rf_html_escape(c) for c in cols)}</tr></thead><tbody>{''.join(rows)}</tbody></table>
<div class="footer">Relatório gerado pelo Farma Quantum • Formato A4</div>
<script>setTimeout(function(){{}}, 300);</script>
</body></html>'''
    with open(caminho, 'w', encoding='utf-8') as f:
        f.write(html)
    return caminho


def _rf_wrap(texto, largura):
    import textwrap
    texto = str(texto or '')
    if not texto:
        return ['']
    linhas = []
    for parte in texto.splitlines() or ['']:
        linhas.extend(textwrap.wrap(parte, width=largura, replace_whitespace=False) or [''])
    return linhas


def _rf_center(texto, largura):
    texto = str(texto or '')[:largura]
    return texto.center(largura)


def _rf_make_bobina_txt(titulo, linhas, largura=48, resumo=''):
    _rf_ensure_dir()
    modelo = '80mm' if largura >= 42 else '58mm'
    nome = modelo + '_' + ''.join(ch if ch.isalnum() else '_' for ch in titulo)[:45] + '_' + datetime.datetime.now().strftime('%Y%m%d_%H%M%S') + '.txt'
    caminho = os.path.join(RELATORIOS_FARMA_DIR, nome)
    sep = '-' * largura
    out = []
    out.append(_rf_center(_rf_empresa_nome(), largura))
    out.append(_rf_center(titulo.upper(), largura))
    out.append(_rf_center('Gerado: ' + _rf_now(), largura))
    out.append(sep)
    if resumo:
        for l in _rf_wrap(resumo, largura): out.append(l)
        out.append(sep)
    if not linhas:
        out.append('Nenhum registro encontrado.'.center(largura))
    for i, row in enumerate(linhas, 1):
        out.append(('ITEM %03d' % i).ljust(largura, '-'))
        if isinstance(row, dict):
            for k, v in row.items():
                txt = f'{k}: {v}'
                for l in _rf_wrap(txt, largura):
                    out.append(l)
        else:
            for l in _rf_wrap(str(row), largura): out.append(l)
    out.append(sep)
    out.append(_rf_center('FARMA QUANTUM', largura))
    out.append('\n\n')
    with open(caminho, 'w', encoding='utf-8') as f:
        f.write('\n'.join(out))
    return caminho


def _rf_open_or_print(caminho, imprimir=False):
    try:
        if sys.platform.startswith('win'):
            if imprimir:
                try:
                    os.startfile(caminho, 'print')
                    return True
                except Exception:
                    os.startfile(caminho)
                    return True
            os.startfile(caminho)
            return True
        import subprocess
        subprocess.Popen(['xdg-open', caminho])
        return True
    except Exception:
        return False


class FarmaciaRelatoriosImpressoesWindow:
    def __init__(self, app=None, parent=None):
        self.app = app
        self.parent = parent or getattr(app, 'root', None)
        self.dados = _rf_load_all()
        self.win = tk.Toplevel(self.parent) if self.parent else tk.Toplevel()
        self.win.title('📊 Relatórios e Impressões da Farmácia')
        try:
            self.win.state('zoomed')
        except Exception:
            try: self.win.attributes('-zoomed', True)
            except Exception: self.win.geometry('1180x720')
        self.win.resizable(True, True)
        self.report_var = tk.StringVar(value='vencimentos')
        self.formato_var = tk.StringVar(value='A4')
        self.acao_var = tk.StringVar(value='abrir')
        self.dias_var = tk.StringVar(value='30')
        # Filtros do relatório "Produtos vendidos".
        self.f_data_ini = tk.StringVar(value='')
        self.f_data_fim = tk.StringVar(value='')
        self.f_produto = tk.StringVar(value='')
        self.f_categoria = tk.StringVar(value='')
        self.f_num_venda = tk.StringVar(value='')
        self._last_path = ''
        self._build()
        self._preview()

    def _build(self):
        main = ttk.Frame(self.win)
        main.pack(fill='both', expand=True, padx=12, pady=10)
        ttk.Label(main, text='📊 RELATÓRIOS E IMPRESSÕES PROFISSIONAIS DA FARMÁCIA', font=('Segoe UI', 16, 'bold')).pack(anchor='w')
        ttk.Label(main, text='Gere relatórios comerciais, clínicos, fiscais, operacionais e imprima em A4, bobina 80mm ou 58mm.', font=('Segoe UI', 9)).pack(anchor='w', pady=(2,8))
        top = ttk.Frame(main); top.pack(fill='x', pady=(0,8))
        left = ttk.Frame(top); left.pack(side='left', fill='x', expand=True)
        right = ttk.Frame(top); right.pack(side='right')
        ttk.Label(left, text='Relatório:').grid(row=0, column=0, sticky='w')
        opts = [
            ('Produtos vencidos/vencendo por lote', 'vencimentos'),
            ('Estoque baixo / reposição', 'estoque_baixo'),
            ('Tratamentos contínuos - lembretes de compra', 'tratamentos'),
            ('Prontuário ambulatorial - atendimentos', 'prontuarios'),
            ('Receituário / controlados / SNGPC', 'receitas'),
            ('PBM / convênios / Farmácia Popular', 'pbm'),
            ('Campanhas / ofertas / encartes', 'campanhas'),
            ('Serviços farmacêuticos agendados', 'servicos'),
            ('Pós-venda / CRM / WhatsApp', 'crm'),
            ('Vendas recentes / fechamento comercial', 'vendas'),
            ('Produtos vendidos (com filtros)', 'produtos_vendidos'),
            ('Dashboard executivo da farmácia', 'dashboard'),
        ]
        combo = ttk.Combobox(left, textvariable=self.report_var, values=[v for t,v in opts], state='readonly', width=34)
        combo.grid(row=1, column=0, sticky='we', padx=(0,8))
        self._report_names = {v:t for t,v in opts}
        ttk.Label(left, text='Formato de impressão:').grid(row=0, column=1, sticky='w')
        ttk.Combobox(left, textvariable=self.formato_var, values=['A4', 'Bobina 80mm', 'Bobina 58mm'], state='readonly', width=16).grid(row=1, column=1, sticky='w', padx=(0,8))
        ttk.Label(left, text='Produtos vencendo em até dias:').grid(row=0, column=2, sticky='w')
        ttk.Entry(left, textvariable=self.dias_var, width=8).grid(row=1, column=2, sticky='w', padx=(0,8))
        ttk.Label(left, text='Ação:').grid(row=0, column=3, sticky='w')
        ttk.Combobox(left, textvariable=self.acao_var, values=['abrir', 'imprimir'], state='readonly', width=10).grid(row=1, column=3, sticky='w')
        for i in range(4):
            try: left.grid_columnconfigure(i, weight=1 if i == 0 else 0)
            except Exception: pass
        ttk.Button(right, text='🔄 Atualizar prévia', command=self._preview).pack(side='left', padx=3)
        ttk.Button(right, text='🧾 Gerar/Imprimir', command=self._gerar).pack(side='left', padx=3)
        ttk.Button(right, text='📂 Abrir último', command=self._abrir_ultimo).pack(side='left', padx=3)
        ttk.Button(right, text='❌ Fechar', command=self.win.destroy).pack(side='left', padx=3)
        # ── Filtros do relatório "Produtos vendidos" ──────────────────────────
        filtros = ttk.LabelFrame(main, text='🔎 Filtros (Produtos vendidos)')
        filtros.pack(fill='x', pady=(0, 6))
        ttk.Label(filtros, text='Data inicial (dd/mm/aaaa):').grid(row=0, column=0, sticky='w', padx=4, pady=2)
        ttk.Entry(filtros, textvariable=self.f_data_ini, width=14).grid(row=1, column=0, sticky='w', padx=4, pady=(0, 4))
        ttk.Label(filtros, text='Data final (dd/mm/aaaa):').grid(row=0, column=1, sticky='w', padx=4, pady=2)
        ttk.Entry(filtros, textvariable=self.f_data_fim, width=14).grid(row=1, column=1, sticky='w', padx=4, pady=(0, 4))
        ttk.Label(filtros, text='Nome do produto:').grid(row=0, column=2, sticky='w', padx=4, pady=2)
        ttk.Entry(filtros, textvariable=self.f_produto, width=22).grid(row=1, column=2, sticky='we', padx=4, pady=(0, 4))
        ttk.Label(filtros, text='Categoria:').grid(row=0, column=3, sticky='w', padx=4, pady=2)
        ttk.Entry(filtros, textvariable=self.f_categoria, width=18).grid(row=1, column=3, sticky='we', padx=4, pady=(0, 4))
        ttk.Label(filtros, text='Nº da venda:').grid(row=0, column=4, sticky='w', padx=4, pady=2)
        ttk.Entry(filtros, textvariable=self.f_num_venda, width=12).grid(row=1, column=4, sticky='w', padx=4, pady=(0, 4))
        ttk.Button(filtros, text='🔎 Aplicar filtros', command=self._preview).grid(row=1, column=5, sticky='w', padx=6, pady=(0, 4))
        ttk.Button(filtros, text='🧹 Limpar filtros', command=self._limpar_filtros).grid(row=1, column=6, sticky='w', padx=2, pady=(0, 4))
        for _c in (2, 3):
            try: filtros.grid_columnconfigure(_c, weight=1)
            except Exception: pass
        info = ttk.Frame(main); info.pack(fill='x', pady=(0,6))
        self.status_var = tk.StringVar(value='')
        ttk.Label(info, textvariable=self.status_var, foreground='#065f46').pack(anchor='w')
        paned = ttk.Panedwindow(main, orient='horizontal')
        paned.pack(fill='both', expand=True)
        frame_preview = ttk.Frame(paned); paned.add(frame_preview, weight=3)
        frame_help = ttk.Frame(paned); paned.add(frame_help, weight=1)
        ttk.Label(frame_preview, text='Prévia do relatório', font=('Segoe UI', 10, 'bold')).pack(anchor='w')
        cols = ('c1','c2','c3','c4','c5','c6')
        self.tree = ttk.Treeview(frame_preview, columns=cols, show='headings')
        for c in cols:
            self.tree.heading(c, text=c.upper())
            self.tree.column(c, width=140, anchor='w')
        y = ttk.Scrollbar(frame_preview, orient='vertical', command=self.tree.yview)
        x = ttk.Scrollbar(frame_preview, orient='horizontal', command=self.tree.xview)
        self.tree.configure(yscrollcommand=y.set, xscrollcommand=x.set)
        self.tree.pack(side='left', fill='both', expand=True)
        y.pack(side='right', fill='y'); x.pack(side='bottom', fill='x')
        ttk.Label(frame_help, text='Modelos disponíveis', font=('Segoe UI', 10, 'bold')).pack(anchor='w')
        help_txt = tk.Text(frame_help, height=12, wrap='word')
        help_txt.pack(fill='both', expand=True)
        help_txt.insert('1.0', 'A4: gera HTML em página A4 com botão de impressão.\n\nBobina 80mm: texto térmico com largura aproximada de 48 colunas.\n\nBobina 58mm: texto térmico com largura aproximada de 32 colunas.\n\nOs arquivos são salvos na pasta relatorios_farmacia dentro da pasta de dados do sistema.\n\nRelatórios incluídos: validade/lote, estoque baixo, tratamentos contínuos, prontuário, controlados/SNGPC, PBM/convênios, campanhas, serviços, CRM, vendas e PRODUTOS VENDIDOS.\n\nPRODUTOS VENDIDOS: lista uma linha por item vendido com produto, quantidade, data, nº da venda, usuário que vendeu, status, categoria, preço unitário, subtotal, cliente e forma de pagamento. Use os campos de Filtros para restringir por período (data inicial/final), nome do produto, categoria e número da venda. Deixe os filtros em branco para trazer tudo.')
        help_txt.config(state='disabled')

    def _montar(self):
        self.dados = _rf_load_all()
        tipo = self.report_var.get()
        titulo = self._report_names.get(tipo, tipo)
        resumo = ''
        try:
            dias = int(float(self.dias_var.get() or 30))
        except Exception:
            dias = 30
        if tipo == 'vencimentos':
            linhas = _rf_alertas_vencimentos_produtos(self.dados, dias=dias)
            resumo = f'Produtos vencidos, vencendo hoje ou vencendo nos próximos {dias} dias. Total: {len(linhas)}.'
        elif tipo == 'estoque_baixo':
            linhas = _rf_estoque_baixo(self.dados)
            resumo = f'Produtos com estoque no mínimo ou abaixo do mínimo. Total: {len(linhas)}.'
        elif tipo == 'tratamentos':
            linhas = _rf_tratamentos_alerta(self.dados)
            resumo = f'Lembretes de recompra e tratamentos contínuos pendentes. Total: {len(linhas)}.'
        elif tipo == 'prontuarios':
            linhas = _rf_prontuarios_resumo(self.dados)
            resumo = f'Atendimentos ambulatoriais cadastrados. Total: {len(linhas)}.'
        elif tipo in ('receitas','pbm','campanhas','servicos','crm'):
            linhas = _rf_farmacia_pro_relatorio(tipo, self.dados)
            resumo = f'Relatório Farmácia Pro: {titulo}. Total: {len(linhas)}.'
        elif tipo == 'vendas':
            linhas, total = _rf_vendas_resumo(self.dados)
            resumo = f'Vendas recentes listadas: {len(linhas)}. Total aproximado: {_rf_money(total)}.'
        elif tipo == 'produtos_vendidos':
            linhas, tot_qtd, tot_valor = _rf_produtos_vendidos(
                self.dados,
                data_ini=self.f_data_ini.get(),
                data_fim=self.f_data_fim.get(),
                filtro_produto=self.f_produto.get(),
                filtro_categoria=self.f_categoria.get(),
                filtro_num_venda=self.f_num_venda.get(),
            )
            filtros_txt = []
            if self.f_data_ini.get().strip() or self.f_data_fim.get().strip():
                filtros_txt.append('período %s a %s' % (self.f_data_ini.get().strip() or '...', self.f_data_fim.get().strip() or '...'))
            if self.f_produto.get().strip():
                filtros_txt.append('produto "%s"' % self.f_produto.get().strip())
            if self.f_categoria.get().strip():
                filtros_txt.append('categoria "%s"' % self.f_categoria.get().strip())
            if self.f_num_venda.get().strip():
                filtros_txt.append('venda nº "%s"' % self.f_num_venda.get().strip())
            filtro_desc = (' • Filtros: ' + '; '.join(filtros_txt)) if filtros_txt else ' • Sem filtros aplicados'
            try:
                qtd_disp = int(tot_qtd) if float(tot_qtd).is_integer() else round(tot_qtd, 3)
            except Exception:
                qtd_disp = tot_qtd
            resumo = (f'Produtos vendidos: {len(linhas)} item(ns). '
                      f'Quantidade total: {qtd_disp}. '
                      f'Valor total: {_rf_money(tot_valor)}.{filtro_desc}')
        elif tipo == 'dashboard':
            venc = len(_rf_alertas_vencimentos_produtos(self.dados, dias=dias))
            est = len(_rf_estoque_baixo(self.dados))
            trat = len(_rf_tratamentos_alerta(self.dados))
            pront = len(_rf_prontuarios_resumo(self.dados))
            rec = len(_rf_farmacia_pro_relatorio('receitas', self.dados))
            pbm = len(_rf_farmacia_pro_relatorio('pbm', self.dados))
            serv = len(_rf_farmacia_pro_relatorio('servicos', self.dados))
            crm = len(_rf_farmacia_pro_relatorio('crm', self.dados))
            vendas, total = _rf_vendas_resumo(self.dados)
            linhas = [
                {'Indicador':'Produtos vencidos/vencendo', 'Quantidade':venc, 'Observação':f'Janela de {dias} dias'},
                {'Indicador':'Estoque baixo', 'Quantidade':est, 'Observação':'Reposição sugerida'},
                {'Indicador':'Tratamentos com recompra pendente', 'Quantidade':trat, 'Observação':'Contato ativo'},
                {'Indicador':'Prontuários ambulatoriais', 'Quantidade':pront, 'Observação':'Histórico clínico'},
                {'Indicador':'Receitas/controlados cadastrados', 'Quantidade':rec, 'Observação':'Controle/SNGPC'},
                {'Indicador':'PBM/convênios cadastrados', 'Quantidade':pbm, 'Observação':'Benefícios comerciais'},
                {'Indicador':'Serviços farmacêuticos', 'Quantidade':serv, 'Observação':'Agenda e execução'},
                {'Indicador':'CRM/pós-venda', 'Quantidade':crm, 'Observação':'Retorno ao cliente'},
                {'Indicador':'Vendas recentes', 'Quantidade':len(vendas), 'Observação':'Total: ' + _rf_money(total)},
            ]
            resumo = 'Dashboard executivo para gestão diária da farmácia/drogaria.'
        else:
            linhas = []
        return titulo, linhas, resumo

    def _limpar_filtros(self):
        """Limpa os filtros do relatório de produtos vendidos e atualiza a prévia."""
        try:
            self.f_data_ini.set('')
            self.f_data_fim.set('')
            self.f_produto.set('')
            self.f_categoria.set('')
            self.f_num_venda.set('')
            self._preview()
        except Exception:
            pass

    def _preview(self):
        try:
            titulo, linhas, resumo = self._montar()
            for i in self.tree.get_children(): self.tree.delete(i)
            cols = []
            for row in linhas[:200]:
                if isinstance(row, dict):
                    for k in row.keys():
                        if k not in cols: cols.append(k)
            cols = (cols or ['Informação'])[:8]
            self.tree.configure(columns=cols)
            for c in cols:
                self.tree.heading(c, text=c)
                self.tree.column(c, width=150, anchor='w')
            for row in linhas[:500]:
                if isinstance(row, dict):
                    self.tree.insert('', 'end', values=[row.get(c,'') for c in cols])
                else:
                    self.tree.insert('', 'end', values=[str(row)])
            self.status_var.set(f'{titulo} • {len(linhas)} registro(s). {resumo}')
        except Exception as e:
            messagebox.showerror('Relatórios', f'Erro ao montar prévia:\n{e}', parent=self.win)

    def _gerar(self):
        try:
            titulo, linhas, resumo = self._montar()
            formato = self.formato_var.get()
            if formato == 'A4':
                caminho = _rf_make_a4_html(titulo, linhas, resumo)
            elif formato == 'Bobina 58mm':
                caminho = _rf_make_bobina_txt(titulo, linhas, largura=32, resumo=resumo)
            else:
                caminho = _rf_make_bobina_txt(titulo, linhas, largura=48, resumo=resumo)
            self._last_path = caminho
            imprimir = self.acao_var.get() == 'imprimir'
            _rf_open_or_print(caminho, imprimir=imprimir)
            messagebox.showinfo('Relatório gerado', f'Arquivo gerado com sucesso:\n{caminho}', parent=self.win)
        except Exception as e:
            messagebox.showerror('Relatórios', f'Erro ao gerar/imprimir:\n{e}', parent=self.win)

    def _abrir_ultimo(self):
        if self._last_path and os.path.exists(self._last_path):
            _rf_open_or_print(self._last_path, imprimir=False)
        else:
            messagebox.showinfo('Relatórios', 'Nenhum relatório foi gerado nesta tela ainda.', parent=self.win)


def _rf_open_window(self):
    return FarmaciaRelatoriosImpressoesWindow(self, getattr(self, 'root', None))


def _rf_patch_app():
    try:
        if 'PDVSuperApp' not in globals():
            return
        if getattr(PDVSuperApp, '_relatorios_farma_patch_aplicado', False):
            return
        PDVSuperApp.open_relatorios_farmacia = _rf_open_window
        _orig_create_menu = PDVSuperApp._create_menu
        def _patched_create_menu(self, *args, **kwargs):
            resultado = _orig_create_menu(self, *args, **kwargs)
            try:
                if not _fq_farma_menu_visivel(self, "menu_relatorios_farma_visivel"):
                    return resultado
                menubar = self.root.nametowidget(self.root.cget('menu'))
                menu = tk.Menu(menubar, tearoff=0)
                menu.add_command(label='📊 Central de relatórios e impressões', command=self.open_relatorios_farmacia, accelerator='Ctrl+Alt+R')
                menu.add_separator()
                menu.add_command(label='🧾 Produtos vencidos/vencendo - A4/Bobina', command=self.open_relatorios_farmacia)
                menu.add_command(label='📦 Estoque baixo / reposição', command=self.open_relatorios_farmacia)
                menu.add_command(label='💊 Tratamentos contínuos / recompra', command=self.open_relatorios_farmacia)
                menu.add_command(label='🏥 Prontuários ambulatoriais', command=self.open_relatorios_farmacia)
                menu.add_command(label='📋 Controlados / PBM / Serviços / CRM', command=self.open_relatorios_farmacia)
                menu.add_command(label='🛒 Produtos vendidos (filtros: data, produto, categoria, nº venda)', command=self.open_relatorios_farmacia)
                menubar.add_cascade(label='📊 Relatórios Farma', menu=menu)
                self.root.bind('<Control-Alt-r>', lambda event: self.open_relatorios_farmacia())
                self.root.bind('<Control-Alt-R>', lambda event: self.open_relatorios_farmacia())
            except Exception as e:
                print(f'[RELATÓRIOS FARMA] Aviso ao adicionar menu: {e}')
            return resultado
        PDVSuperApp._create_menu = _patched_create_menu
        PDVSuperApp._relatorios_farma_patch_aplicado = True
        print('[RELATÓRIOS FARMA] Patch aplicado com sucesso.')
    except Exception as e:
        print(f'[RELATÓRIOS FARMA] Falha ao aplicar patch: {e}')



