# ═══════════════════════════════════════════════════════════════════════════════
# PATCH DEFINITIVO - VISIBILIDADE DOS MENUS FARMÁCIA COM PERSISTÊNCIA NO MYSQL
# Regras:
# - Checkbox desmarcado: menu fica invisível.
# - Checkbox marcado: menu fica visível.
# - Cria tabela/colunas em configuracoes automaticamente.
# - Persiste no banco e recarrega antes da criação do menu.
# ═══════════════════════════════════════════════════════════════════════════════
_FQ_FARMA_MENU_KEYS = (
    "menu_relatorios_farma_visivel",
    "menu_farmacia_pro_visivel",
    "menu_ambulatorio_visivel",
    "menu_tratamento_visivel",
)

try:
    for _fq_k in _FQ_FARMA_MENU_KEYS:
        DEFAULT_CONFIG.setdefault(_fq_k, False)
except Exception:
    pass


def _fq_bool_config(valor, padrao=False):
    try:
        if isinstance(valor, bool):
            return valor
        if valor is None:
            return padrao
        return str(valor).strip().lower() in ("1", "true", "sim", "yes", "on", "marcado")
    except Exception:
        return padrao


def _fq_farma_menu_ensure_db():
    """Garante a estrutura mínima da tabela configuracoes sem apagar dados."""
    try:
        db = get_db()
        try:
            db.execute(
                "CREATE TABLE IF NOT EXISTS configuracoes ("
                "id INT AUTO_INCREMENT PRIMARY KEY, "
                "chave VARCHAR(191) NOT NULL, "
                "valor TEXT NULL, "
                "categoria VARCHAR(80) NULL DEFAULT 'sistema', "
                "descricao TEXT NULL, "
                "atualizado_em TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP"
                ") ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"
            )
        except Exception as e:
            print(f"[FARMA-MENUS] Aviso ao criar tabela configuracoes: {e}")
        for ddl in (
            "ALTER TABLE configuracoes ADD COLUMN chave VARCHAR(191) NOT NULL",
            "ALTER TABLE configuracoes ADD COLUMN valor TEXT NULL",
            "ALTER TABLE configuracoes ADD COLUMN categoria VARCHAR(80) NULL DEFAULT 'sistema'",
            "ALTER TABLE configuracoes ADD COLUMN descricao TEXT NULL",
            "ALTER TABLE configuracoes ADD COLUMN atualizado_em TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP",
        ):
            try:
                db.execute(ddl)
            except Exception:
                pass
        try:
            db.execute("CREATE INDEX idx_configuracoes_chave ON configuracoes(chave)")
        except Exception:
            pass
        return db
    except Exception as e:
        print(f"[FARMA-MENUS] Banco indisponível para configurações: {e}")
        return None


def _fq_farma_menu_seed_defaults():
    db = _fq_farma_menu_ensure_db()
    if not db:
        return False
    descricoes = {
        "menu_relatorios_farma_visivel": "Exibe/oculta o menu Relatórios Farma",
        "menu_farmacia_pro_visivel": "Exibe/oculta o menu Farmácia Pro",
        "menu_ambulatorio_visivel": "Exibe/oculta o menu Ambulatório",
        "menu_tratamento_visivel": "Exibe/oculta o menu Tratamentos",
    }
    for chave in _FQ_FARMA_MENU_KEYS:
        try:
            existe = db.fetchone("SELECT chave FROM configuracoes WHERE chave=%s LIMIT 1", (chave,))
            if not existe:
                db.execute(
                    "INSERT INTO configuracoes (chave, valor, categoria, descricao) VALUES (%s, %s, %s, %s)",
                    (chave, "0", "menus_farmacia", descricoes.get(chave, chave))
                )
        except Exception as e:
            print(f"[FARMA-MENUS] Aviso ao criar configuração {chave}: {e}")
    return True


def _fq_farma_menu_load_db(cfg=None):
    if cfg is None:
        cfg = {}
    try:
        _fq_farma_menu_seed_defaults()
        db = _fq_farma_menu_ensure_db()
        if not db:
            return cfg
        rows = db.fetchall(
            "SELECT chave, valor FROM configuracoes WHERE chave IN (%s,%s,%s,%s)",
            _FQ_FARMA_MENU_KEYS
        )
        for row in rows or []:
            try:
                chave = row.get("chave") if isinstance(row, dict) else row[0]
                valor = row.get("valor") if isinstance(row, dict) else row[1]
                if chave in _FQ_FARMA_MENU_KEYS:
                    cfg[chave] = _fq_bool_config(valor, False)
            except Exception:
                pass
    except Exception as e:
        print(f"[FARMA-MENUS] Aviso ao carregar configurações do banco: {e}")
    return cfg


def _fq_farma_menu_persist_db(cfg):
    try:
        _fq_farma_menu_seed_defaults()
        db = _fq_farma_menu_ensure_db()
        if not db:
            return False
        for chave in _FQ_FARMA_MENU_KEYS:
            valor = "1" if _fq_bool_config((cfg or {}).get(chave), False) else "0"
            existe = db.fetchone("SELECT chave FROM configuracoes WHERE chave=%s LIMIT 1", (chave,))
            if existe:
                db.execute("UPDATE configuracoes SET valor=%s WHERE chave=%s", (valor, chave))
            else:
                db.execute(
                    "INSERT INTO configuracoes (chave, valor, categoria, descricao) VALUES (%s, %s, %s, %s)",
                    (chave, valor, "menus_farmacia", "Configuração de visibilidade dos menus da farmácia")
                )
        return True
    except Exception as e:
        print(f"[FARMA-MENUS] Aviso ao salvar configurações no banco: {e}")
        return False


# Compatibilidade com chamadas já existentes dentro da tela de Configurações.
def _fq_extras_ensure_db():
    return _fq_farma_menu_ensure_db()

def _fq_extras_persist_db(cfg):
    return _fq_farma_menu_persist_db(cfg)

def _fq_extras_load_db(cfg):
    return _fq_farma_menu_load_db(cfg)


def _fq_farma_menu_visivel(app, chave):
    try:
        cfg = getattr(app, "config_data", {}) or {}
        return _fq_bool_config(cfg.get(chave), False)
    except Exception:
        return False


def _fq_farma_menu_remover_cascatas(app):
    """Cinto de segurança: remove cascatas caso algum patch antigo as tenha adicionado."""
    try:
        import unicodedata
        def norm(txt):
            txt = unicodedata.normalize("NFKD", str(txt or ""))
            return "".join(c for c in txt if not unicodedata.combining(c)).lower()
        alvos = (
            ("menu_relatorios_farma_visivel", ("relatorios farma",)),
            ("menu_farmacia_pro_visivel", ("farmacia pro", "farma pro")),
            ("menu_ambulatorio_visivel", ("ambulatorio",)),
            ("menu_tratamento_visivel", ("tratamentos", "tratamento")),
        )
        menubar = app.root.nametowidget(app.root.cget("menu"))
        fim = menubar.index("end")
        if fim is None:
            return
        for i in range(fim, -1, -1):
            try:
                label = norm(menubar.entrycget(i, "label"))
            except Exception:
                continue
            for chave, palavras in alvos:
                if any(p in label for p in palavras) and not _fq_farma_menu_visivel(app, chave):
                    try:
                        menubar.delete(i)
                    except Exception:
                        pass
                    break
    except Exception as e:
        print(f"[FARMA-MENUS] Aviso ao aplicar limpeza visual: {e}")


def _fq_farma_menu_patch_runtime():
    try:
        if 'PDVSuperApp' not in globals():
            return
        if getattr(PDVSuperApp, '_fq_farma_menu_runtime_patch', False):
            return

        _orig_create_menu = PDVSuperApp._create_menu
        def _fq_create_menu_patched(self, *args, **kwargs):
            try:
                if not hasattr(self, 'config_data') or self.config_data is None:
                    self.config_data = {}
                _fq_farma_menu_load_db(self.config_data)
            except Exception as e:
                print(f"[FARMA-MENUS] Aviso ao carregar antes do menu: {e}")
            resultado = _orig_create_menu(self, *args, **kwargs)
            try:
                self.root.after(50, lambda: _fq_farma_menu_remover_cascatas(self))
                self.root.after(600, lambda: _fq_farma_menu_remover_cascatas(self))
                self.root.after(1800, lambda: _fq_farma_menu_remover_cascatas(self))
            except Exception:
                pass
            return resultado
        PDVSuperApp._create_menu = _fq_create_menu_patched

        # Todo salvamento do config.json também replica no MySQL.
        if 'quantum_salvar_config_rapido' in globals():
            _orig_salvar = globals().get('quantum_salvar_config_rapido')
            if callable(_orig_salvar) and not getattr(_orig_salvar, '_fq_farma_menu_wrap', False):
                def _fq_salvar_config_patched(cfg, *args, **kwargs):
                    ok = _orig_salvar(cfg, *args, **kwargs)
                    try:
                        _fq_farma_menu_persist_db(cfg or {})
                    except Exception as e:
                        print(f"[FARMA-MENUS] Aviso ao persistir após salvar config: {e}")
                    return ok
                _fq_salvar_config_patched._fq_farma_menu_wrap = True
                globals()['quantum_salvar_config_rapido'] = _fq_salvar_config_patched

        PDVSuperApp._fq_farma_menu_runtime_patch = True
        print('[FARMA-MENUS] Patch de visibilidade e persistência aplicado.')
    except Exception as e:
        print(f"[FARMA-MENUS] Falha ao aplicar patch runtime: {e}")


try:
    _fq_farma_menu_seed_defaults()
except Exception:
    pass
try:
    _fq_farma_menu_patch_runtime()
except Exception:
    pass

