# SISTEMA DE LOGS AVANÇADO
# ═══════════════════════════════════════════════════════════════════════════════════════

class AdvancedLogger:
    """
    Sistema de Logs Avançado com Rotação e Níveis.
    """
    
    LEVELS = {
        'DEBUG': 10,
        'INFO': 20,
        'WARNING': 30,
        'ERROR': 40,
        'CRITICAL': 50
    }
    
    def __init__(self, log_dir=None, max_size_mb=10, max_files=5, min_level='INFO'):
        self._log_dir = log_dir or os.path.join(os.path.dirname(__file__), 'logs')
        self._max_size = max_size_mb * 1024 * 1024
        self._max_files = max_files
        self._min_level = self.LEVELS.get(min_level, 20)
        self._current_file = None
        self._buffer = []
        self._buffer_size = 100
        self._lock = threading.Lock()
        
        os.makedirs(self._log_dir, exist_ok=True)
        self._init_log_file()
    
    def _init_log_file(self):
        """Inicializa arquivo de log."""
        timestamp = datetime.datetime.now().strftime('%Y%m%d')
        self._current_file = os.path.join(self._log_dir, f'pdv_{timestamp}.log')
    
    def _should_rotate(self):
        """Verifica se deve rotacionar o arquivo."""
        if not os.path.exists(self._current_file):
            return False
        return os.path.getsize(self._current_file) >= self._max_size
    
    def _rotate_logs(self):
        """Rotaciona arquivos de log."""
        log_files = sorted([
            f for f in os.listdir(self._log_dir)
            if f.startswith('pdv_') and f.endswith('.log')
        ], reverse=True)
        
        for old_file in log_files[self._max_files:]:
            try:
                os.remove(os.path.join(self._log_dir, old_file))
            except:
                pass
        
        self._init_log_file()
    
    def _format_message(self, level, message, category=None, extra=None):
        """Formata mensagem de log."""
        timestamp = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S.%f')[:-3]
        category_str = f"[{category}]" if category else ""
        extra_str = f" | {extra}" if extra else ""
        
        return f"{timestamp} | {level:8} | {category_str} {message}{extra_str}"
    
    def _write(self, formatted_message):
        """Escreve no arquivo de log."""
        with self._lock:
            self._buffer.append(formatted_message)
            
            if len(self._buffer) >= self._buffer_size:
                self._flush()
    
    def _flush(self):
        """Descarrega buffer para arquivo."""
        if not self._buffer:
            return
        
        if self._should_rotate():
            self._rotate_logs()
        
        try:
            with open(self._current_file, 'a', encoding='utf-8') as f:
                f.write('\n'.join(self._buffer) + '\n')
            self._buffer.clear()
        except Exception as e:
            try:
                AUDITORIA.erro(f"Erro no sistema: {e}")
            except Exception:
                pass
            print(f"Erro ao escrever log: {e}")
    
    def log(self, level, message, category=None, extra=None):
        """Registra uma mensagem de log."""
        level_value = self.LEVELS.get(level, 20)
        
        if level_value < self._min_level:
            return
        
        formatted = self._format_message(level, message, category, extra)
        self._write(formatted)
    
    def debug(self, message, category=None, extra=None):
        self.log('DEBUG', message, category, extra)
    
    def info(self, message, category=None, extra=None):
        self.log('INFO', message, category, extra)
    
    def warning(self, message, category=None, extra=None):
        self.log('WARNING', message, category, extra)
    
    def error(self, message, category=None, extra=None):
        self.log('ERROR', message, category, extra)
    
    def critical(self, message, category=None, extra=None):
        self.log('CRITICAL', message, category, extra)
        self._flush()
    
    def close(self):
        """Fecha o logger."""
        self._flush()


