# SISTEMA DE MONITORAMENTO DE SAÚDE DO SISTEMA
# ═══════════════════════════════════════════════════════════════════════════════════════

class SystemHealthMonitor:
    """
    Monitor de Saúde do Sistema.
    """
    
    def __init__(self, check_interval=60):
        self._check_interval = check_interval
        self._last_check = None
        self._health_data = {}
        self._alerts = []
        self._thresholds = {
            'cpu_percent': 80,
            'memory_percent': 85,
            'disk_percent': 90
        }
    
    def check_health(self):
        """Executa verificação de saúde."""
        health = {
            'timestamp': datetime.datetime.now().isoformat(),
            'status': 'healthy',
            'checks': {}
        }
        
        try:
            import psutil
            memory = psutil.virtual_memory()
            health['checks']['memory'] = {
                'total': memory.total,
                'available': memory.available,
                'percent': memory.percent,
                'status': 'ok' if memory.percent < self._thresholds['memory_percent'] else 'warning'
            }
            
            cpu_percent = psutil.cpu_percent(interval=1)
            health['checks']['cpu'] = {
                'percent': cpu_percent,
                'status': 'ok' if cpu_percent < self._thresholds['cpu_percent'] else 'warning'
            }
            
            disk = psutil.disk_usage('/')
            health['checks']['disk'] = {
                'total': disk.total,
                'free': disk.free,
                'percent': disk.percent,
                'status': 'ok' if disk.percent < self._thresholds['disk_percent'] else 'warning'
            }
        except ImportError:
            health['checks']['system'] = {'status': 'unknown', 'message': 'psutil não disponível'}
        
        health['checks']['database'] = {
            'status': 'ok',
            'message': 'Conexão disponível'
        }
        
        statuses = [check.get('status', 'ok') for check in health['checks'].values()]
        if 'error' in statuses:
            health['status'] = 'critical'
        elif 'warning' in statuses:
            health['status'] = 'warning'
        
        self._health_data = health
        self._last_check = datetime.datetime.now()
        
        return health
    
    def get_health(self):
        """Retorna dados de saúde."""
        if self._last_check is None:
            self.check_health()
        return self._health_data
    
    def get_alerts(self, clear=False):
        """Retorna alertas."""
        alerts = list(self._alerts)
        if clear:
            self._alerts.clear()
        return alerts
    
    def set_threshold(self, metric, value):
        """Define threshold para uma métrica."""
        if metric in self._thresholds:
            self._thresholds[metric] = value
    
    def get_summary(self):
        """Retorna resumo de saúde."""
        health = self.get_health()
        
        status_emoji = {
            'healthy': '✅',
            'warning': '⚠️',
            'critical': '❌',
            'unknown': '❓'
        }
        
        summary = f"{status_emoji.get(health['status'], '❓')} Sistema: {health['status'].upper()}\n"
        
        for check_name, check_data in health['checks'].items():
            check_status = check_data.get('status', 'unknown')
            summary += f"  {status_emoji.get(check_status, '❓')} {check_name}: {check_status}\n"
        
        return summary


