def _persist_log(tipo, mensagem):
    """Log seguro para persistência sem quebrar o sistema caso a auditoria falhe."""
    try:
        if tipo == 'erro':
            AUDITORIA.erro(mensagem)
        elif tipo == 'config':
            AUDITORIA.configuracao(mensagem)
        else:
            AUDITORIA.banco_dados(mensagem)
    except Exception:
        try:
            print(f"[PERSISTENCIA] {mensagem}")
        except Exception:
            pass


def _ensure_parent_dir(filepath):
    """Cria a pasta pai do arquivo antes de salvar."""
    try:
        pasta = os.path.dirname(os.path.abspath(str(filepath)))
        if pasta and not os.path.exists(pasta):
            os.makedirs(pasta, exist_ok=True)
    except Exception as e:
        _persist_log('erro', f"Falha ao criar pasta de persistência para {filepath}: {e}")


def _load_json_fallback(filepath, default_data=None):
    """Carrega qualquer JSON fora do roteamento MySQL, com backup contra corrupção."""
    if default_data is None:
        default_data = {}
    try:
        if not filepath:
            return default_data
        filepath = str(filepath)
        if os.path.exists(filepath):
            with open(filepath, 'r', encoding='utf-8') as f:
                loaded = json.load(f)
            _persist_log('bd', f"JSON fallback carregado com sucesso: {os.path.basename(filepath)}")
            return loaded
    except Exception as e:
        _persist_log('erro', f"Erro ao carregar JSON fallback ({filepath}): {e}")
        try:
            bak = str(filepath) + '.corrompido.bak'
            if os.path.exists(filepath):
                shutil.copy2(filepath, bak)
                _persist_log('erro', f"Backup de JSON possivelmente corrompido criado: {bak}")
        except Exception:
            pass
    return default_data


def _normalize_bool_config_value(valor):
    """Converte strings comuns de configuração para booleano real."""
    if isinstance(valor, bool):
        return valor
    if isinstance(valor, (int, float)):
        return bool(valor)
    if isinstance(valor, str):
        return valor.strip().lower() in ('true', '1', 'sim', 's', 'yes', 'y', 'on', 'marcado', 'checked')
    return bool(valor)


def _normalize_int_config_value(valor, default=0):
    try:
        if valor is None or valor == '':
            return default
        return int(float(str(valor).replace(',', '.')))
    except Exception:
        return default


def get_label_config_file():
    """Arquivo único e fixo para configurações visuais de etiquetas."""
    try:
        base = globals().get('DATA_DIR') or globals().get('PERSISTENCE_DIR') or os.getcwd()
        return os.path.join(base, 'label_config.json')
    except Exception:
        return os.path.join(os.getcwd(), 'label_config.json')

# ═══════════════════════════════════════════════════════════════════════════
# SISTEMA DE ARQUIVO DE CONFIGURAÇÃO (config.ini)
# ═══════════════════════════════════════════════════════════════════════════
# O arquivo config.ini armazena as credenciais do MySQL e outras
# configurações do sistema. Se não existir, será solicitada a
# configuração ao usuário no primeiro acesso via interface gráfica.
# ═══════════════════════════════════════════════════════════════════════════

MYSQL_CONFIG_FILE = os.path.join(PERSISTENCE_DIR, "config.ini")


# ═══════════════════════════════════════════════════════════════════════════
# PATCH FARMA QUANTUM - CONFIG.INI ROBUSTO / SENHA NÃO VAZIA
# ═══════════════════════════════════════════════════════════════════════════
# Alguns Windows abrem o .py/.exe em uma pasta diferente da pasta onde o
# usuário colocou o config.ini. Por isso o sistema agora procura config.ini em
# várias pastas seguras: pasta do executável/script, pasta atual e pasta do
# arquivo .py. Também reaproveita a senha do config.ini quando a tela fica vazia.

def _fq_config_paths():
    """Retorna caminhos prováveis do config.ini sem duplicar."""
    caminhos = []
    def add(path):
        try:
            path = os.path.abspath(path)
            if path not in caminhos:
                caminhos.append(path)
        except Exception:
            pass
    try:
        add(os.path.join(PERSISTENCE_DIR, 'config.ini'))
    except Exception:
        pass
    try:
        add(os.path.join(os.getcwd(), 'config.ini'))
    except Exception:
        pass
    try:
        if getattr(sys, 'frozen', False):
            add(os.path.join(os.path.dirname(sys.executable), 'config.ini'))
        else:
            add(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'config.ini'))
    except Exception:
        pass
    try:
        # pasta do atalho/execução e sua pasta pai, útil quando abre por Explorer
        add(os.path.join(os.path.expanduser('~'), 'Downloads', 'Quantum', 'config.ini'))
    except Exception:
        pass
    return caminhos


def _fq_ler_config_de_qualquer_pasta():
    """Carrega o primeiro config.ini válido encontrado."""
    for caminho in _fq_config_paths():
        try:
            if os.path.exists(caminho):
                cfg = configparser.ConfigParser()
                cfg.read(caminho, encoding='utf-8')
                if cfg.has_section('mysql'):
                    print(f"[CONFIG] config.ini encontrado em: {caminho}")
                    return cfg, caminho
        except Exception as e:
            print(f"[CONFIG] Ignorando config.ini inválido em {caminho}: {e}")
    return None, None


def _fq_get_config_value(campo, default=''):
    try:
        cfg, _caminho = _fq_ler_config_de_qualquer_pasta()
        if cfg is not None and cfg.has_section('mysql'):
            return cfg.get('mysql', campo, fallback=default)
    except Exception:
        pass
    return default


def _fq_get_password_fallback(user='', database=''):
    """Busca senha no config.ini quando a tela/variável chega vazia."""
    try:
        cfg, caminho = _fq_ler_config_de_qualquer_pasta()
        if cfg is not None and cfg.has_section('mysql'):
            senha = cfg.get('mysql', 'password', fallback='')
            if senha:
                print(f"[CONFIG] Senha reutilizada do config.ini: {caminho}")
                return senha
    except Exception:
        pass
    return ''

def carregar_config():
    """Carrega as configurações do arquivo config.ini.

    PATCH Farma Quantum:
    procura o config.ini também na pasta atual e na pasta do executável/script,
    evitando a mensagem falsa de "arquivo não encontrado" quando o usuário já
    criou o config.ini ao lado do sistema.
    """
    config, caminho = _fq_ler_config_de_qualquer_pasta()
    if config is not None:
        globals()['MYSQL_CONFIG_FILE_USADO'] = caminho
        return config
    return None


def salvar_config(host, port, user, password, database):
    """Salva as configurações do MySQL no config.ini.

    PATCH DEFINITIVO FARMA QUANTUM - SENHA NO CONFIG.INI:
    - Grava a senha digitada exatamente no campo Senha.
    - Não usa interpolação do ConfigParser para gravar, evitando perda com caracteres especiais.
    - Se o campo vier vazio, preserva a senha já existente no config.ini.
    - Grava em múltiplos destinos seguros: C:\Quantum, pasta do EXE/script,
      pasta atual e PERSISTENCE_DIR.
    - Lê novamente após gravar para validar se a senha realmente ficou salva.
    """
    def _norm(v, padrao=''):
        try:
            return str(v if v is not None else padrao).replace('\r', '').replace('\n', '').strip()
        except Exception:
            return str(padrao)

    host = _norm(host, '127.0.0.1') or '127.0.0.1'
    port = _norm(port, '3306') or '3306'
    user = _norm(user, 'usuario') or 'usuario'
    database = _norm(database, 'farmacia') or 'farmacia'

    # IMPORTANTE: não aplicar .strip() agressivo antes de capturar senha,
    # porque alguns usuários podem usar espaço como parte da senha.
    try:
        password_raw = '' if password is None else str(password).replace('\r', '').replace('\n', '')
    except Exception:
        password_raw = ''

    # Se a tela devolver senha vazia, preserva senha existente para não apagar config.ini.
    if password_raw == '':
        try:
            senha_existente = _fq_get_password_fallback(user=user, database=database)
            if senha_existente:
                password_raw = str(senha_existente).replace('\r', '').replace('\n', '')
                print("[CONFIG] Campo senha vazio: preservando senha já existente no config.ini.")
        except Exception:
            pass

    # Monta destinos robustos, priorizando C:\Quantum quando existir/for usado.
    destinos = []

    def add_destino(caminho):
        try:
            caminho = os.path.abspath(caminho)
            if caminho not in destinos:
                destinos.append(caminho)
        except Exception:
            pass

    try:
        add_destino(os.path.join(PERSISTENCE_DIR, 'config.ini'))
    except Exception:
        pass

    try:
        add_destino(MYSQL_CONFIG_FILE)
    except Exception:
        pass

    try:
        add_destino(os.path.join(os.getcwd(), 'config.ini'))
    except Exception:
        pass

    try:
        if getattr(sys, 'frozen', False):
            add_destino(os.path.join(os.path.dirname(sys.executable), 'config.ini'))
        else:
            add_destino(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'config.ini'))
    except Exception:
        pass

    try:
        add_destino(os.path.join('C:\\Quantum', 'config.ini'))
    except Exception:
        pass

    for caminho in _fq_config_paths():
        add_destino(caminho)

    conteudo = (
        "[mysql]\n"
        f"host = {host}\n"
        f"port = {port}\n"
        f"user = {user}\n"
        f"password = {password_raw}\n"
        f"database = {database}\n"
    )

    ok_algum = False
    erros = []
    for caminho in destinos:
        try:
            pasta = os.path.dirname(caminho)
            if pasta:
                os.makedirs(pasta, exist_ok=True)
            with open(caminho, 'w', encoding='utf-8', newline='\n') as f:
                f.write(conteudo)
                f.flush()
            # valida leitura imediata
            cfg_check = configparser.ConfigParser()
            cfg_check.read(caminho, encoding='utf-8')
            senha_lida = cfg_check.get('mysql', 'password', fallback=None)
            if senha_lida != password_raw:
                raise RuntimeError("validação falhou: senha gravada diferente da senha lida")
            print(f"[CONFIG] Configurações salvas em: {caminho} | senha={'PREENCHIDA' if password_raw else 'VAZIA'}")
            ok_algum = True
        except Exception as e:
            erros.append(f"{caminho}: {e}")

    if not ok_algum:
        print("[CONFIG] Erro ao salvar config.ini: " + " | ".join(erros))
        try:
            AUDITORIA.erro("Falha ao salvar config.ini com senha", exception=Exception(" | ".join(erros)))
        except Exception:
            pass
    else:
        try:
            globals()['MYSQL_CONFIG_FILE_USADO'] = destinos[0] if destinos else MYSQL_CONFIG_FILE
            AUDITORIA.configuracao(f"config.ini salvo com senha {'preenchida' if password_raw else 'vazia'} em {len(destinos)} destino(s)")
        except Exception:
            pass

    return ok_algum


def testar_conexao_mysql(host, port, user, password, database='', tentar_127=True):
    """Testa a conexão com o servidor MySQL com diagnóstico claro.

    Correção Farma Quantum:
    - Usa exatamente a senha digitada na tela.
    - Se host=localhost falhar, tenta 127.0.0.1 para evitar conflito entre
      contas MySQL root@localhost, root@127.0.0.1 e autenticação por socket/plugin.
    - Mostra se a senha chegou vazia ou preenchida, sem revelar a senha.
    """
    import mysql.connector as _mc
    host = (host or '127.0.0.1').strip()
    port = int(port or 3306)
    user = (user or '').strip()
    password = '' if password is None else str(password)
    database = (database or '').strip()
    if not password:
        password = _fq_get_password_fallback(user=user, database=database)

    hosts_para_tentar = [host]
    if tentar_127 and host.lower() == 'localhost':
        hosts_para_tentar.append('127.0.0.1')

    erros = []
    for h in hosts_para_tentar:
        try:
            conn_params = {
                'host': h,
                'port': port,
                'user': user,
                'password': password,
                'connect_timeout': 10,
                'use_pure': True,
            }
            if database:
                conn_params['database'] = database
            conn = _mc.connect(**conn_params)
            conn.close()
            return True, f"Conexão estabelecida com sucesso em {h}!"
        except Exception as e:
            erros.append(f"[{h}] {e}")

    msg = "\n".join(erros)
    senha_status = "PREENCHIDA" if len(password) > 0 else "VAZIA"
    if 'Access denied' in msg or '1045' in msg:
        msg += (
            f"\n\nDIAGNÓSTICO: senha recebida pela tela = {senha_status}."
            "\nO MySQL recusou o usuário/senha. Isso não é erro de layout: o usuário precisa existir no MySQL "
            "e ter permissão no banco informado."
            "\nDICA: confira se você sabe a senha correta do root do MySQL. "
            "Se não souber, redefina a senha do root no instalador/MySQL Workbench ou crie o banco manualmente."
        )
    return False, msg


def criar_banco_e_usuario_mysql(admin_host, admin_port, admin_user, admin_password, novo_usuario, nova_senha, database):
    """Cria/autoriza automaticamente o banco e o usuário informado na tela.

    Versão reforçada:
    - Tenta localhost e 127.0.0.1 quando necessário.
    - Não esconde o diagnóstico da senha: informa se a senha do admin chegou vazia.
    - Usa SQL escapado corretamente para CREATE USER/GRANT.
    """
    def _q_ident(nome):
        return '`' + str(nome).replace('`', '``') + '`'

    def _q_str(valor):
        return "'" + str(valor).replace("\\", "\\\\").replace("'", "''") + "'"

    try:
        import mysql.connector as _mc
        admin_port = int(admin_port or 3306)
        admin_host = (admin_host or '127.0.0.1').strip()
        admin_user = (admin_user or 'root').strip()
        admin_password = '' if admin_password is None else str(admin_password)
        database = (database or 'farmacia').strip()
        novo_usuario = (novo_usuario or 'usuario').strip()
        nova_senha = '' if nova_senha is None else str(nova_senha)

        if not database or not novo_usuario:
            return False, "Informe o nome do banco e o usuário que será autorizado."

        hosts_admin = [admin_host]
        if admin_host.lower() == 'localhost':
            hosts_admin.append('127.0.0.1')
        elif admin_host == '127.0.0.1':
            hosts_admin.append('localhost')

        ultimo_erro = None
        conn = None
        host_conectado = None
        for h in hosts_admin:
            try:
                conn = _mc.connect(
                    host=h,
                    port=admin_port,
                    user=admin_user,
                    password=admin_password,
                    connect_timeout=10,
                    use_pure=True,
                )
                host_conectado = h
                break
            except Exception as e:
                ultimo_erro = e

        if conn is None:
            senha_status = "PREENCHIDA" if len(admin_password) > 0 else "VAZIA"
            msg = str(ultimo_erro)
            if 'Access denied' in msg or '1045' in msg:
                msg += (
                    f"\n\nDIAGNÓSTICO: senha do administrador recebida pela tela = {senha_status}."
                    "\nO MySQL recusou o login administrador. Use a senha real do root definida na instalação."
                    "\nSe você não lembra a senha, abra o MySQL Installer/Workbench e redefina a senha do root, ou execute o SQL manual abaixo com um usuário administrador."
                )
            return False, msg

        cur = conn.cursor()
        cur.execute(f"CREATE DATABASE IF NOT EXISTS {_q_ident(database)} CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci")

        # Autoriza para os hosts mais comuns no Windows/MySQL local.
        for host_alvo in ('localhost', '127.0.0.1', '%'):
            usuario_sql = _q_str(novo_usuario)
            host_sql = _q_str(host_alvo)
            senha_sql = _q_str(nova_senha)
            try:
                cur.execute(f"CREATE USER IF NOT EXISTS {usuario_sql}@{host_sql} IDENTIFIED BY {senha_sql}")
            except Exception:
                pass
            try:
                cur.execute(f"ALTER USER {usuario_sql}@{host_sql} IDENTIFIED BY {senha_sql}")
            except Exception:
                pass
            try:
                cur.execute(f"GRANT ALL PRIVILEGES ON {_q_ident(database)}.* TO {usuario_sql}@{host_sql}")
            except Exception as grant_err:
                print(f"[MySQL] Aviso GRANT {novo_usuario}@{host_alvo}: {grant_err}")

        cur.execute("FLUSH PRIVILEGES")
        conn.commit()
        cur.close()
        conn.close()

        # Confirma conexão final com o usuário normal, tentando o host usado pelo admin e o host da tela.
        ok, msg = testar_conexao_mysql(host_conectado or admin_host, admin_port, novo_usuario, nova_senha, database)
        if ok:
            return True, f"Banco '{database}' criado/autorizado e usuário '{novo_usuario}' conectado com sucesso em {host_conectado}."
        return False, "Banco/usuário foram criados, mas o teste final ainda falhou:\n" + str(msg)
    except Exception as e:
        msg = str(e)
        if 'mysql_native_password' in msg:
            msg += ("\n\nFIX AUTH PLUGIN MYSQL_NATIVE_PASSWORD: o conector MySQL instalado é incompatível com o método de autenticação do seu MySQL. "
                    "Execute CORRIGIR_MYSQL_NATIVE_PASSWORD.bat, compile novamente e abra o novo EXE.")
        if 'Access denied' in msg or '1045' in msg:
            msg += "\n\nO usuário administrador informado também foi recusado. Use a senha correta do root do MySQL."
        return False, msg


def gerar_sql_criacao_banco_usuario(host, port, user, password, database):
    """Gera um arquivo .sql para criar o banco/usuário manualmente no MySQL Workbench."""
    def _q_ident(nome):
        return '`' + str(nome).replace('`', '``') + '`'
    def _q_str(valor):
        return "'" + str(valor).replace("\\", "\\\\").replace("'", "''") + "'"
    try:
        base = globals().get('PERSISTENCE_DIR') or os.getcwd()
        caminho = os.path.join(base, 'CRIAR_BANCO_FARMACIA.sql')
        database = (database or 'farmacia').strip()
        user = (user or 'usuario').strip()
        password = '' if password is None else str(password)
        conteudo = f"""-- FARMA QUANTUM - Criar banco e liberar usuário
-- Execute este script no MySQL Workbench conectado como root/administrador.

CREATE DATABASE IF NOT EXISTS {_q_ident(database)}
CHARACTER SET utf8mb4
COLLATE utf8mb4_unicode_ci;

CREATE USER IF NOT EXISTS {_q_str(user)}@'localhost' IDENTIFIED BY {_q_str(password)};
ALTER USER {_q_str(user)}@'localhost' IDENTIFIED BY {_q_str(password)};
GRANT ALL PRIVILEGES ON {_q_ident(database)}.* TO {_q_str(user)}@'localhost';

CREATE USER IF NOT EXISTS {_q_str(user)}@'127.0.0.1' IDENTIFIED BY {_q_str(password)};
ALTER USER {_q_str(user)}@'127.0.0.1' IDENTIFIED BY {_q_str(password)};
GRANT ALL PRIVILEGES ON {_q_ident(database)}.* TO {_q_str(user)}@'127.0.0.1';

CREATE USER IF NOT EXISTS {_q_str(user)}@'%' IDENTIFIED BY {_q_str(password)};
ALTER USER {_q_str(user)}@'%' IDENTIFIED BY {_q_str(password)};
GRANT ALL PRIVILEGES ON {_q_ident(database)}.* TO {_q_str(user)}@'%';

FLUSH PRIVILEGES;
"""
        with open(caminho, 'w', encoding='utf-8') as f:
            f.write(conteudo)
        return True, caminho
    except Exception as e:
        return False, str(e)



# ═══════════════════════════════════════════════════════════════════════════
# ASSISTENTE AVANÇADO DE LIBERAÇÕES MYSQL / ACESSO EM REDE
# ═══════════════════════════════════════════════════════════════════════════

def _fq_mysql_q_ident(nome):
    return '`' + str(nome).replace('`', '``') + '`'


def _fq_mysql_q_str(valor):
    return "'" + str(valor if valor is not None else '').replace("\\", "\\\\").replace("'", "''") + "'"


def _fq_mysql_conectar_admin(admin_host, admin_port, admin_user, admin_password):
    """Conecta ao MySQL com usuário administrador, tentando 127.0.0.1 e localhost."""
    import mysql.connector as _mc
    admin_port = int(admin_port or 3306)
    admin_user = (admin_user or 'root').strip()
    admin_password = '' if admin_password is None else str(admin_password)
    hosts = []
    for h in [admin_host, '127.0.0.1', 'localhost']:
        h = (h or '').strip()
        if h and h not in hosts:
            hosts.append(h)
    ultimo_erro = None
    for h in hosts:
        try:
            conn = _mc.connect(host=h, port=admin_port, user=admin_user, password=admin_password, connection_timeout=8, autocommit=False)
            return conn, h
        except Exception as e:
            ultimo_erro = e
    raise ultimo_erro


def liberar_usuario_todos_bancos_mysql(admin_host, admin_port, admin_user, admin_password, usuario, senha):
    """Libera o usuário escolhido para acessar qualquer banco (*.*) em hosts comuns e rede."""
    try:
        conn, host_ok = _fq_mysql_conectar_admin(admin_host, admin_port, admin_user, admin_password)
        cur = conn.cursor()
        usuario = (usuario or 'usuario').strip()
        senha = '' if senha is None else str(senha)
        for host_alvo in ('localhost', '127.0.0.1', '%'):
            try:
                cur.execute(f"CREATE USER IF NOT EXISTS {_fq_mysql_q_str(usuario)}@{_fq_mysql_q_str(host_alvo)} IDENTIFIED BY {_fq_mysql_q_str(senha)}")
            except Exception:
                pass
            try:
                cur.execute(f"ALTER USER {_fq_mysql_q_str(usuario)}@{_fq_mysql_q_str(host_alvo)} IDENTIFIED BY {_fq_mysql_q_str(senha)}")
            except Exception:
                pass
            cur.execute(f"GRANT ALL PRIVILEGES ON *.* TO {_fq_mysql_q_str(usuario)}@{_fq_mysql_q_str(host_alvo)} WITH GRANT OPTION")
        cur.execute("FLUSH PRIVILEGES")
        conn.commit()
        cur.close(); conn.close()
        return True, f"Usuário '{usuario}' liberado para TODOS os bancos em localhost, 127.0.0.1 e rede (%) usando admin em {host_ok}."
    except Exception as e:
        return False, str(e)


def liberar_banco_para_todos_usuarios_mysql(admin_host, admin_port, admin_user, admin_password, database):
    """Libera o banco informado para todos os usuários existentes no servidor MySQL."""
    try:
        conn, host_ok = _fq_mysql_conectar_admin(admin_host, admin_port, admin_user, admin_password)
        cur = conn.cursor()
        database = (database or 'farmacia').strip()
        cur.execute(f"CREATE DATABASE IF NOT EXISTS {_fq_mysql_q_ident(database)} CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci")
        cur.execute("SELECT User, Host FROM mysql.user WHERE User IS NOT NULL AND User <> ''")
        contas = cur.fetchall() or []
        aplicados = 0
        erros = []
        for user_name, host_name in contas:
            try:
                cur.execute(f"GRANT ALL PRIVILEGES ON {_fq_mysql_q_ident(database)}.* TO {_fq_mysql_q_str(user_name)}@{_fq_mysql_q_str(host_name)}")
                aplicados += 1
            except Exception as grant_err:
                erros.append(f"{user_name}@{host_name}: {grant_err}")
        cur.execute("FLUSH PRIVILEGES")
        conn.commit()
        cur.close(); conn.close()
        msg = f"Banco '{database}' liberado para {aplicados} conta(s) MySQL existente(s), usando admin em {host_ok}."
        if erros:
            msg += "\n\nAvisos:\n" + "\n".join(erros[:10])
        return True, msg
    except Exception as e:
        return False, str(e)


def gerar_sql_liberacoes_avancadas(user, password, database):
    """Gera SQL manual com as liberações solicitadas para execução no MySQL Workbench."""
    try:
        base = globals().get('PERSISTENCE_DIR') or os.getcwd()
        caminho = os.path.join(base, 'LIBERACOES_AVANCADAS_MYSQL_FARMACIA.sql')
        user = (user or 'usuario').strip()
        password = '' if password is None else str(password)
        database = (database or 'farmacia').strip()
        conteudo = f"""-- FARMA QUANTUM - Liberações avançadas do MySQL
-- Execute no MySQL Workbench conectado como root/administrador.
-- ATENÇÃO: estas permissões são amplas. Use somente em rede confiável.

CREATE DATABASE IF NOT EXISTS {_fq_mysql_q_ident(database)}
CHARACTER SET utf8mb4
COLLATE utf8mb4_unicode_ci;

-- 1) Liberar o usuário escolhido para qualquer banco:
CREATE USER IF NOT EXISTS {_fq_mysql_q_str(user)}@'localhost' IDENTIFIED BY {_fq_mysql_q_str(password)};
ALTER USER {_fq_mysql_q_str(user)}@'localhost' IDENTIFIED BY {_fq_mysql_q_str(password)};
GRANT ALL PRIVILEGES ON *.* TO {_fq_mysql_q_str(user)}@'localhost' WITH GRANT OPTION;

CREATE USER IF NOT EXISTS {_fq_mysql_q_str(user)}@'127.0.0.1' IDENTIFIED BY {_fq_mysql_q_str(password)};
ALTER USER {_fq_mysql_q_str(user)}@'127.0.0.1' IDENTIFIED BY {_fq_mysql_q_str(password)};
GRANT ALL PRIVILEGES ON *.* TO {_fq_mysql_q_str(user)}@'127.0.0.1' WITH GRANT OPTION;

CREATE USER IF NOT EXISTS {_fq_mysql_q_str(user)}@'%' IDENTIFIED BY {_fq_mysql_q_str(password)};
ALTER USER {_fq_mysql_q_str(user)}@'%' IDENTIFIED BY {_fq_mysql_q_str(password)};
GRANT ALL PRIVILEGES ON *.* TO {_fq_mysql_q_str(user)}@'%' WITH GRANT OPTION;

-- 2) Liberar o banco informado para todos os usuários existentes:
-- Rode este bloco no Workbench para gerar e executar GRANTs dinamicamente.
SET @db_name := {_fq_mysql_q_str(database)};
SET SESSION group_concat_max_len = 1000000;
SELECT GROUP_CONCAT(CONCAT('GRANT ALL PRIVILEGES ON `', REPLACE(@db_name, '`', '``'), '`.* TO ', QUOTE(User), '@', QUOTE(Host), ';') SEPARATOR ' ')
INTO @sql_grants
FROM mysql.user
WHERE User IS NOT NULL AND User <> '';
PREPARE stmt FROM @sql_grants;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

FLUSH PRIVILEGES;

-- 3) bind-address = 0.0.0.0 não é SQL. Deve ser configurado no arquivo my.ini/my.cnf do MySQL:
-- [mysqld]
-- bind-address = 0.0.0.0
-- Depois reinicie o serviço MySQL pelo services.msc ou prompt admin.
"""
        with open(caminho, 'w', encoding='utf-8') as f:
            f.write(conteudo)
        return True, caminho
    except Exception as e:
        return False, str(e)


def configurar_mysql_bind_address_0000():
    """Tenta localizar e alterar o my.ini/my.cnf para bind-address=0.0.0.0."""
    import glob
    candidatos = []
    envs = ['MYSQL_HOME', 'PROGRAMDATA']
    for env in envs:
        v = os.environ.get(env)
        if v:
            candidatos.extend(glob.glob(os.path.join(v, '**', 'my.ini'), recursive=True))
            candidatos.extend(glob.glob(os.path.join(v, '**', 'my.cnf'), recursive=True))
    candidatos.extend([
        r'C:\\ProgramData\\MySQL\\MySQL Server 8.0\\my.ini',
        r'C:\\ProgramData\\MySQL\\MySQL Server 5.7\\my.ini',
        r'C:\\xampp\\mysql\\bin\\my.ini',
        r'C:\\wamp64\\bin\\mysql\\mysql*\\my.ini',
        r'C:\\laragon\\bin\\mysql\\mysql*\\my.ini',
        '/etc/mysql/mysql.conf.d/mysqld.cnf',
        '/etc/mysql/my.cnf',
    ])
    expandidos = []
    for c in candidatos:
        expandidos.extend(glob.glob(c))
    vistos = []
    for c in expandidos:
        if c and c not in vistos and os.path.isfile(c):
            vistos.append(c)
    if not vistos:
        base = globals().get('PERSISTENCE_DIR') or os.getcwd()
        snippet = os.path.join(base, 'MYSQL_BIND_ADDRESS_0000_INSTRUCOES.txt')
        with open(snippet, 'w', encoding='utf-8') as f:
            f.write('Não encontrei my.ini/my.cnf automaticamente.\n\n')
            f.write('Abra o arquivo de configuração do MySQL como administrador e ajuste:\n\n[mysqld]\nbind-address = 0.0.0.0\n\n')
            f.write('Depois reinicie o serviço MySQL.\n')
        return False, 'Arquivo my.ini/my.cnf não encontrado automaticamente. Instruções geradas em:\n' + snippet
    caminho = vistos[0]
    try:
        with open(caminho, 'r', encoding='utf-8', errors='ignore') as f:
            linhas = f.readlines()
        backup = caminho + '.backup_farma_quantum'
        if not os.path.exists(backup):
            with open(backup, 'w', encoding='utf-8') as f:
                f.writelines(linhas)
        out = []
        em_mysqld = False
        achou_mysqld = False
        alterou = False
        inseriu = False
        for linha in linhas:
            stripped = linha.strip()
            if stripped.lower() == '[mysqld]':
                if em_mysqld and not inseriu:
                    out.append('bind-address = 0.0.0.0\n')
                    inseriu = True
                em_mysqld = True
                achou_mysqld = True
                out.append(linha)
                continue
            if stripped.startswith('[') and stripped.endswith(']') and em_mysqld:
                if not inseriu:
                    out.append('bind-address = 0.0.0.0\n')
                    inseriu = True
                em_mysqld = False
            if em_mysqld and stripped.lower().startswith('bind-address'):
                out.append('bind-address = 0.0.0.0\n')
                alterou = True
            else:
                out.append(linha)
        if not achou_mysqld:
            out.append('\n[mysqld]\nbind-address = 0.0.0.0\n')
        elif em_mysqld and not inseriu and not alterou:
            out.append('bind-address = 0.0.0.0\n')
        with open(caminho, 'w', encoding='utf-8') as f:
            f.writelines(out)
        return True, f'bind-address configurado para 0.0.0.0 em:\n{caminho}\n\nBackup criado em:\n{backup}\n\nReinicie o serviço MySQL para aplicar.'
    except PermissionError:
        return False, f'Sem permissão para alterar:\n{caminho}\n\nExecute o sistema como Administrador ou edite manualmente como admin:\n[mysqld]\nbind-address = 0.0.0.0'
    except Exception as e:
        return False, str(e)

def solicitar_configuracao_mysql():
    """Exibe uma janela gráfica para o usuário configurar o MySQL.
    
    Esta função é chamada automaticamente quando o arquivo config.ini
    não existe (primeiro acesso) ou quando as credenciais estão inválidas.
    Permite ao usuário informar host, porta, usuário, senha e banco de dados,
    testar a conexão e salvar as configurações.
    
    Returns:
        bool: True se a configuração foi salva com sucesso, False se cancelou.
    """
    import tkinter as _tk
    from tkinter import messagebox as _mb
    
    config_salva = [False]  # Usa lista para permitir mutação dentro do closure
    
    # Cria janela de configuração
    cfg_win = _tk.Tk()
    cfg_win.title("Configuração Inicial do MySQL - Farma Quantum")
    cfg_win.resizable(True, True)
    
    # Centraliza a janela na tela com tamanho adequado
    largura_janela = 900
    altura_janela = 760
    largura_tela = cfg_win.winfo_screenwidth()
    altura_tela = cfg_win.winfo_screenheight()
    pos_x = (largura_tela - largura_janela) // 2
    pos_y = (altura_tela - altura_janela) // 2
    cfg_win.geometry(f"{largura_janela}x{altura_janela}+{pos_x}+{pos_y}")
    cfg_win.minsize(760, 700)
    cfg_win.configure(bg='#f0f0f0')
    
    # Tenta colocar a janela no topo
    try:
        cfg_win.attributes('-topmost', True)
    except Exception:
        pass
    
    # Frame dos botões FIXO na parte inferior da janela
    btn_frame = _tk.Frame(cfg_win, bg='#f0f0f0', padx=30, pady=15)
    btn_frame.pack(side='bottom', fill='x')
    
    # Separador acima dos botões
    _tk.Frame(cfg_win, height=1, bg='#d0d0d0').pack(side='bottom', fill='x', padx=30)
    
    # Label de status FIXO acima dos botões
    status_label = _tk.Label(
        cfg_win,
        text="",
        font=("Segoe UI", 9),
        bg='#f0f0f0',
        fg='#64748b',
        wraplength=820
    )
    status_label.pack(side='bottom', pady=(5, 5))
    
    # Frame principal (área de scroll se necessário)
    main_frame = _tk.Frame(cfg_win, bg='#f0f0f0', padx=30, pady=20)
    main_frame.pack(fill='both', expand=True)
    
    # Título
    titulo = _tk.Label(
        main_frame,
        text="Configuração do Banco de Dados MySQL - Farmácia",
        font=("Segoe UI", 14, "bold"),
        bg='#f0f0f0',
        fg='#1e293b'
    )
    titulo.pack(pady=(0, 5))
    
    subtitulo = _tk.Label(
        main_frame,
        text="Arquivo config.ini não encontrado.\nPreencha os dados de conexão abaixo:",
        font=("Segoe UI", 9),
        bg='#f0f0f0',
        fg='#64748b',
        justify='center'
    )
    subtitulo.pack(pady=(0, 15))
    
    # Frame dos campos
    campos_frame = _tk.Frame(main_frame, bg='#f0f0f0')
    campos_frame.pack(fill='x')
    
    # Variáveis
    # Prefill: usa config.ini existente em qualquer pasta encontrada.
    _cfg_existente, _cfg_caminho = _fq_ler_config_de_qualquer_pasta()
    if _cfg_existente is not None and _cfg_existente.has_section('mysql'):
        _host_padrao = _cfg_existente.get('mysql', 'host', fallback='127.0.0.1')
        _port_padrao = _cfg_existente.get('mysql', 'port', fallback='3306')
        _user_padrao = _cfg_existente.get('mysql', 'user', fallback='usuario')
        _pass_padrao = _cfg_existente.get('mysql', 'password', fallback='')
        _db_padrao = _cfg_existente.get('mysql', 'database', fallback='farmacia')
    else:
        _host_padrao, _port_padrao, _user_padrao, _pass_padrao, _db_padrao = '127.0.0.1', '3306', 'usuario', '', 'farmacia'

    var_host = _tk.StringVar(value=_host_padrao)
    var_port = _tk.StringVar(value=_port_padrao)
    var_user = _tk.StringVar(value=_user_padrao)
    var_pass = _tk.StringVar(value=_pass_padrao)
    var_db = _tk.StringVar(value=_db_padrao)
    
    campos = [
        ("Host (Servidor):", var_host),
        ("Porta:", var_port),
        ("Usuário:", var_user),
        ("Senha:", var_pass),
        ("Nome do Banco de Dados:", var_db),
    ]
    
    entries = []
    for i, (label_text, var) in enumerate(campos):
        lbl = _tk.Label(
            campos_frame,
            text=label_text,
            font=("Segoe UI", 10),
            bg='#f0f0f0',
            fg='#334155',
            anchor='w'
        )
        lbl.pack(fill='x', pady=(6, 1))
        
        show_char = '*' if 'Senha' in label_text else ''
        entry = _tk.Entry(
            campos_frame,
            textvariable=var,
            font=("Segoe UI", 11),
            relief='solid',
            bd=1,
            show=show_char
        )
        entry.pack(fill='x', ipady=4)
        entries.append(entry)
    
    def ao_testar():
        """Testa a conexão com os dados informados."""
        host = var_host.get().strip()
        port = var_port.get().strip()
        user = var_user.get().strip()
        password = entries[3].get() if len(entries) > 3 else var_pass.get()
        if password is not None:
            var_pass.set(password)
        if not password:
            password = _fq_get_password_fallback(user=user, database=var_db.get().strip())
            if password:
                var_pass.set(password)
        
        if not host or not port or not user:
            _mb.showwarning("Aviso", "Preencha pelo menos Host, Porta e Usuário.", parent=cfg_win)
            return
        
        status_label.config(text="Testando conexão...", fg='#2563eb')
        cfg_win.update_idletasks()
        
        database = var_db.get().strip()
        sucesso, msg = testar_conexao_mysql(host, port, user, password, database)
        
        if sucesso:
            status_label.config(text="Conexão OK!", fg='#10b981')
            _mb.showinfo("Sucesso", "Conexão com o MySQL estabelecida com sucesso!", parent=cfg_win)
        else:
            status_label.config(text=f"Falha: {msg}", fg='#ef4444')
            _mb.showerror("Erro de Conexão", f"Não foi possível conectar ao MySQL:\n\n{msg}", parent=cfg_win)
    
    def ao_criar_banco_usuario():
        """Cria o banco e autoriza o usuário informado usando login administrador do MySQL."""
        host = var_host.get().strip() or 'localhost'
        port = var_port.get().strip() or '3306'
        user = var_user.get().strip() or 'usuario'
        password = entries[3].get() if len(entries) > 3 else var_pass.get()
        if password is not None:
            var_pass.set(password)
        database = var_db.get().strip() or 'farmacia'

        if not user or not database:
            _mb.showwarning("Aviso", "Informe o Usuário e o Nome do Banco de Dados.", parent=cfg_win)
            return

        admin_win = _tk.Toplevel(cfg_win)
        admin_win.title("Criar banco/autorizar usuário")
        admin_win.configure(bg='#f0f0f0')
        admin_win.resizable(False, False)
        admin_win.transient(cfg_win)
        admin_win.grab_set()
        try:
            admin_win.attributes('-topmost', True)
        except Exception:
            pass
        admin_win.geometry("460x310")

        frame = _tk.Frame(admin_win, bg='#f0f0f0', padx=22, pady=18)
        frame.pack(fill='both', expand=True)
        _tk.Label(frame, text="Criar banco e liberar usuário", font=("Segoe UI", 13, "bold"), bg='#f0f0f0', fg='#0f172a').pack(anchor='w')
        _tk.Label(
            frame,
            text=("Use um usuário administrador do MySQL somente para criar o banco e liberar permissões.\n"
                  "Normalmente é root com a senha definida na instalação do MySQL."),
            font=("Segoe UI", 9), bg='#f0f0f0', fg='#475569', justify='left', wraplength=410
        ).pack(anchor='w', pady=(6, 12))

