# ═══════════════════════════════════════════════════════════════════════════

def _quantum_require_mysql_connector():
    """Garante dependência MySQL antes de operações reais de banco."""
    try:
        if not globals().get('MYSQL_CONNECTOR_AVAILABLE', True) or globals().get('mysql') is None:
            raise RuntimeError('mysql-connector-python não está instalado. Execute: pip install mysql-connector-python')
    except NameError:
        pass


def table_exists(db, table_name):
    """Verifica se uma tabela existe no banco de dados MySQL."""
    try:
        row = db.fetchone(
            "SELECT TABLE_NAME FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = %s",
            (table_name,)
        )
        return row is not None
    except Exception:
        return False

def column_exists(db, table_name, column_name):
    """Verifica se uma coluna existe em uma tabela (MySQL)."""
    try:
        rows = db.fetchall(
            "SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = %s AND COLUMN_NAME = %s",
            (table_name, column_name)
        )
        return len(rows) > 0
    except Exception:
        return False

def ensure_column(db, table_name, column_name, column_type, default_value=None):
    """Garante que uma coluna existe na tabela, criando-a se necessário."""
    if not column_exists(db, table_name, column_name):
        try:
            tipo_upper = str(column_type).upper()
            if default_value is not None and not any(t in tipo_upper for t in ("TEXT", "BLOB", "JSON")):
                if isinstance(default_value, str):
                    default_clause = f"DEFAULT '{default_value}'"
                else:
                    default_clause = f"DEFAULT {default_value}"
            else:
                default_clause = ""
            db.execute(f"ALTER TABLE {table_name} ADD COLUMN {column_name} {column_type} {default_clause}")
            print(f"[MIGRAÇÃO] Coluna '{column_name}' adicionada à tabela '{table_name}'")
            return True
        except Exception as e:
            print(f"[MIGRAÇÃO] Erro ao adicionar coluna '{column_name}' à tabela '{table_name}': {e}")
            return False
    return True

def ensure_table(db, table_name, create_sql):
    """Garante que uma tabela existe, criando-a se necessário."""
    if not table_exists(db, table_name):
        try:
            db.execute(create_sql)
            print(f"[MIGRAÇÃO] Tabela '{table_name}' criada com sucesso")
            return True
        except Exception as e:
            print(f"[MIGRAÇÃO] Erro ao criar tabela '{table_name}': {e}")
            return False
    return True

def ensure_column_type(db, table_name, column_name, column_type, default_value=None):
    """Garante que uma coluna existente tenha o tipo correto."""
    try:
        row = db.fetchone(
            "SELECT COLUMN_TYPE, DATA_TYPE FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = %s AND COLUMN_NAME = %s",
            (table_name, column_name)
        )
        if not row:
            return ensure_column(db, table_name, column_name, column_type, default_value)

        current_column_type = str(row.get('COLUMN_TYPE') or row.get('column_type') or '').strip().lower()
        target_column_type = str(column_type).strip().lower()

        if current_column_type == target_column_type:
            return True

        if default_value is not None:
            if isinstance(default_value, str):
                default_literal = default_value.replace("'", "''")
                default_clause = f"DEFAULT '{default_literal}'"
            else:
                default_clause = f"DEFAULT {default_value}"
        else:
            default_clause = ""

        db.execute(f"ALTER TABLE {table_name} MODIFY COLUMN {column_name} {column_type} {default_clause}")
        print(f"[MIGRAÇÃO] Coluna '{column_name}' da tabela '{table_name}' ajustada para {column_type}")
        return True
    except Exception as e:
        print(f"[MIGRAÇÃO] Erro ao ajustar tipo da coluna '{column_name}' da tabela '{table_name}': {e}")
        return False


def _serialize_cash_transactions(transacoes):
    """Serializa transações do caixa em JSON compacto para evitar crescimento desnecessário."""
    if transacoes is None:
        transacoes = []
    if isinstance(transacoes, dict):
        transacoes = [transacoes]
    elif not isinstance(transacoes, list):
        transacoes = list(transacoes) if isinstance(transacoes, tuple) else []
    return json.dumps(transacoes, ensure_ascii=False, separators=(',', ':'))


def _deserialize_cash_transactions(raw_value, contexto='caixa'):
    """Desserializa transações do caixa com tratamento robusto para dados antigos ou corrompidos."""
    if raw_value in (None, '', b''):
        return []

    if isinstance(raw_value, list):
        return raw_value
    if isinstance(raw_value, tuple):
        return list(raw_value)
    if isinstance(raw_value, dict):
        return [raw_value]

    # Garantir que raw_value seja string (MySQL pode retornar bytes/bytearray)
    if isinstance(raw_value, (bytes, bytearray)):
        try:
            raw_value = raw_value.decode('utf-8')
        except (UnicodeDecodeError, AttributeError):
            try:
                raw_value = raw_value.decode('latin-1')
            except Exception:
                logging.error(f"Erro ao decodificar bytes das transações do {contexto}")
                return []

    # Garantir que é string antes de prosseguir
    if not isinstance(raw_value, str):
        try:
            raw_value = str(raw_value)
        except Exception:
            return []

    raw_value = raw_value.strip()
    if not raw_value:
        return []

    try:
        transacoes_raw = json.loads(raw_value)
        if isinstance(transacoes_raw, list):
            return transacoes_raw
        if isinstance(transacoes_raw, dict):
            return [transacoes_raw]
    except (json.JSONDecodeError, TypeError) as e:
        logging.error(f"Erro ao decodificar transacoes do {contexto}: {e}")
        logging.warning(f"JSON inválido nas transações do {contexto}: {e}. Tentando recuperar...")

        # ─── TENTATIVA DE RECUPERAÇÃO DE JSON TRUNCADO ───
        # O erro "Unterminated string" indica que o JSON foi cortado no meio.
        # Estratégia: encontrar todos os objetos JSON completos {...} dentro do
        # valor bruto e reconstruir uma lista válida a partir deles.
        try:
            recuperados = []
            profundidade = 0
            inicio_obj = -1
            dentro_string = False
            escape_next = False

            for i, ch in enumerate(raw_value):
                if escape_next:
                    escape_next = False
                    continue
                if ch == '\\' and dentro_string:
                    escape_next = True
                    continue
                if ch == '"' and not escape_next:
                    dentro_string = not dentro_string
                    continue
                if dentro_string:
                    continue
                if ch == '{':
                    if profundidade == 0:
                        inicio_obj = i
                    profundidade += 1
                elif ch == '}':
                    profundidade -= 1
                    if profundidade == 0 and inicio_obj >= 0:
                        fragmento = raw_value[inicio_obj:i + 1]
                        try:
                            obj = json.loads(fragmento)
                            if isinstance(obj, dict):
                                recuperados.append(obj)
                        except (json.JSONDecodeError, ValueError):
                            pass
                        inicio_obj = -1

            if recuperados:
                logging.info(
                    f"Recuperadas {len(recuperados)} transação(ões) de JSON corrompido do {contexto}"
                )
                return recuperados
        except Exception as e2:
            logging.error(f"Falha na tentativa de recuperação do JSON do {contexto}: {e2}")

    return []


def repair_cash_transactions_column(db, table_name, id_column='id', column_name='transacoes'):
    """Repara registros com JSON inválido ou em formato incompatível na coluna de transações."""
    try:
        rows = db.fetchall(f"SELECT {id_column}, {column_name} FROM {table_name}")
    except Exception as e:
        print(f"[MIGRAÇÃO] Não foi possível verificar a tabela '{table_name}' para reparo: {e}")
        return False

    reparados = 0
    for row in rows or []:
        row_id = row.get(id_column) if isinstance(row, dict) else row[id_column]
        valor_atual = row.get(column_name) if isinstance(row, dict) else row[column_name]

        # Converter bytes para string antes de comparar
        valor_str = valor_atual
        if isinstance(valor_str, (bytes, bytearray)):
            try:
                valor_str = valor_str.decode('utf-8')
            except Exception:
                valor_str = ''

        transacoes = _deserialize_cash_transactions(valor_atual, f"{table_name}.{column_name}")
        valor_corrigido = _serialize_cash_transactions(transacoes)
        if (valor_str or '') != valor_corrigido:
            try:
                db.execute(
                    f"UPDATE {table_name} SET {column_name} = %s WHERE {id_column} = %s",
                    (valor_corrigido, row_id)
                )
                reparados += 1
            except Exception as e:
                print(f"[MIGRAÇÃO] Falha ao reparar registro {row_id} em '{table_name}': {e}")

    if reparados:
        print(f"[MIGRAÇÃO] {reparados} registro(s) reparado(s) na coluna '{column_name}' da tabela '{table_name}'")
    return True


def _auto_repair_transacoes(db, tabela, row_id, raw_transacoes, transacoes_recuperadas):
    """
    Repara automaticamente o JSON corrompido no banco de dados quando detectado.
    Compara o valor bruto (raw) com o valor recuperado pela desserialização.
    Se o JSON original era inválido mas conseguimos recuperar dados, salva a versão limpa.
    """
    if row_id is None:
        return
    # Se raw_transacoes já era válido (None, lista vazia, ou JSON limpo), não precisa reparar
    if raw_transacoes is None or raw_transacoes == '' or raw_transacoes == b'':
        return
    if isinstance(raw_transacoes, (list, dict)):
        return

    # Converte raw para string para testar se é JSON válido
    raw_str = raw_transacoes
    if isinstance(raw_str, (bytes, bytearray)):
        try:
            raw_str = raw_str.decode('utf-8')
        except Exception:
            raw_str = ''
    if not isinstance(raw_str, str):
        raw_str = str(raw_str)

    # Tenta parsear o JSON original - se falhar, precisa reparar
    try:
        json.loads(raw_str)
        return  # JSON original é válido, nada a fazer
    except (json.JSONDecodeError, TypeError, ValueError):
        pass  # JSON corrompido - precisa reparar

    # Salva a versão recuperada no banco
    valor_corrigido = _serialize_cash_transactions(transacoes_recuperadas)
    try:
        db.execute(
            f"UPDATE {tabela} SET transacoes = %s WHERE id = %s",
            (valor_corrigido, row_id)
        )
        qtd = len(transacoes_recuperadas)
        logging.info(
            f"[REPARO AUTO] JSON corrompido na tabela '{tabela}' (id={row_id}) "
            f"reparado automaticamente. {qtd} transação(ões) recuperada(s)."
        )
        print(
            f"[REPARO AUTO] Tabela '{tabela}' id={row_id}: JSON corrompido reparado. "
            f"{qtd} transação(ões) salva(s)."
        )
    except Exception as e:
        logging.error(f"[REPARO AUTO] Falha ao reparar tabela '{tabela}' id={row_id}: {e}")


