# ⚛️ CAMADA QUÂNTICA/ATÔMICA DE CONCORRÊNCIA, TRANSACÕES E SINCRONIZAÇÃO MYSQL
# ═══════════════════════════════════════════════════════════════════════════════
# Objetivo:
# - Tornar gravações e leituras críticas mais seguras em várias máquinas.
# - Evitar perda de dados por deadlock, timeout, conexão perdida ou corrida local.
# - Serializar gravações por tabela usando MySQL named locks, funcionando entre PCs.
# - Criar eventos no banco para que telas de outras máquinas atualizem em tempo real.
# - Fornecer bloco transacional atômico: commit/rollback garantido.
# ═══════════════════════════════════════════════════════════════════════════════

import contextlib as _ctx_quantum_db
import random as _random_quantum_db
import re as _re_quantum_db
import time as _time_quantum_db

_QUANTUM_DB_PATCH_APPLIED = False
_QUANTUM_SYNC_EVENT_GUARD = threading.local()
_QUANTUM_RESOURCE_LOCKS = {}
_QUANTUM_RESOURCE_LOCKS_GUARD = threading.RLock()


def _quantum_local_lock(resource_name: str):
    """Retorna lock local por recurso/arquivo/tabela."""
    key = str(resource_name or 'global')
    with _QUANTUM_RESOURCE_LOCKS_GUARD:
        lock = _QUANTUM_RESOURCE_LOCKS.get(key)
        if lock is None:
            lock = threading.RLock()
            _QUANTUM_RESOURCE_LOCKS[key] = lock
        return lock


def _quantum_is_write_sql(sql: str) -> bool:
    q = str(sql or '').lstrip().lower()
    return q.startswith(('insert ', 'update ', 'delete ', 'replace ', 'create ', 'alter ', 'drop ', 'truncate '))


def _quantum_extract_table(sql: str) -> str:
    """Extrai tabela principal de INSERT/UPDATE/DELETE/ALTER/CREATE com tolerância."""
    q = ' '.join(str(sql or '').replace('`', '').split())
    patterns = [
        r'^insert\s+into\s+([a-zA-Z0-9_]+)',
        r'^replace\s+into\s+([a-zA-Z0-9_]+)',
        r'^update\s+([a-zA-Z0-9_]+)',
        r'^delete\s+from\s+([a-zA-Z0-9_]+)',
        r'^alter\s+table\s+([a-zA-Z0-9_]+)',
        r'^create\s+table\s+(?:if\s+not\s+exists\s+)?([a-zA-Z0-9_]+)',
        r'^drop\s+table\s+(?:if\s+exists\s+)?([a-zA-Z0-9_]+)',
        r'^truncate\s+table\s+([a-zA-Z0-9_]+)',
    ]
    ql = q.lower()
    for pat in patterns:
        m = _re_quantum_db.search(pat, ql, _re_quantum_db.I)
        if m:
            return m.group(1).lower()
    return 'geral'


def _quantum_data_key_from_sql(sql: str) -> str:
    table = _quantum_extract_table(sql)
    mapper = {
        'produtos': 'products',
        'categorias': 'categories',
        'clientes': 'customers',
        'fornecedores': 'fornecedores',
        'entregadores': 'entregadores',
        'bairros': 'bairros',
        'cartoes': 'cartoes',
        'vendas': 'sales',
        'vendas_itens': 'sales',
        'contas_pagar': 'contas_pagar',
        'contas_receber': 'contas_receber',
        'notas_entrada': 'notas_entrada',
        'notas_entrada_itens': 'notas_entrada',
        'comandas': 'comandas',
        'comanda_itens': 'comandas',
        'caixa': 'caixa',
        'fechamentos_caixa': 'fechamentos_caixa',
        'configuracoes': 'config',
        'empresa': 'empresa',
        'usuarios': 'users',
        'vendedores': 'vendedores',
        'servicos': 'servicos',
        'ordens_servico': 'ordens_servico',
        'tamanhos': 'tamanhos',
        'mesas': 'mesas',
        'garcons': 'garcons',
        'sync_events': 'sync_events',
        'schema_migrations': 'schema',
    }
    return mapper.get(table, table or 'all')


def _quantum_is_transient_mysql_error(exc) -> bool:
    errno = getattr(exc, 'errno', None)
    if errno in (1205, 1213, 2006, 2013, 2055, 1047, 1158, 1159, 1160, 1161):
        return True
    msg = str(exc).lower()
    return any(x in msg for x in (
        'deadlock', 'lock wait timeout', 'lost connection', 'server has gone away',
        'connection not available', 'try restarting transaction', 'temporarily unavailable'
    ))


def _quantum_backoff(attempt: int):
    delay = min(1.8, 0.06 * (2 ** attempt)) + _random_quantum_db.uniform(0, 0.08)
    _time_quantum_db.sleep(delay)


def _quantum_ensure_sync_table():
    """Cria tabela de eventos de sincronização usada por todas as máquinas."""
    try:
        conn = MySQLDB.get_connection()
        cur = conn.cursor(dictionary=True)
        cur.execute("""
            CREATE TABLE IF NOT EXISTS sync_events (
                id BIGINT AUTO_INCREMENT PRIMARY KEY,
                data_key VARCHAR(120) NOT NULL,
                operation VARCHAR(40) DEFAULT '',
                origin VARCHAR(120) DEFAULT '',
                details TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                INDEX idx_sync_events_id (id),
                INDEX idx_sync_events_created_at (created_at),
                INDEX idx_sync_events_data_key (data_key)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
        """)
        cur.close()
        try:
            if not conn.autocommit:
                conn.commit()
        except Exception:
            pass
        return True
    except Exception as e:
        try:
            AUDITORIA.erro(f"Não foi possível garantir tabela sync_events: {e}")
        except Exception:
            pass
        return False


def _quantum_record_sync_event(data_key='all', operation='write', details=''):
    """Grava evento no MySQL sem usar MySQLDB.execute para evitar recursão."""
    if getattr(_QUANTUM_SYNC_EVENT_GUARD, 'recording', False):
        return False
    if str(data_key or '') == 'sync_events':
        return False
    try:
        _QUANTUM_SYNC_EVENT_GUARD.recording = True
        conn = MySQLDB.get_connection()
        cur = conn.cursor(dictionary=True)
        origin = os.environ.get('COMPUTERNAME') or os.environ.get('HOSTNAME') or 'pdv'
        cur.execute(
            "INSERT INTO sync_events (data_key, operation, origin, details) VALUES (%s, %s, %s, %s)",
            (str(data_key or 'all')[:120], str(operation or 'write')[:40], str(origin)[:120], str(details or '')[:1000])
        )
        cur.close()
        try:
            if not conn.autocommit and not getattr(MySQLDB._local, 'quantum_atomic_depth', 0):
                conn.commit()
        except Exception:
            pass
        return True
    except Exception:
        return False
    finally:
        try:
            _QUANTUM_SYNC_EVENT_GUARD.recording = False
        except Exception:
            pass


def _quantum_install_mysql_concurrency_patch():
    """Instala patch de concorrência/retry/locks/eventos na classe MySQLDB."""
    global _QUANTUM_DB_PATCH_APPLIED
    if _QUANTUM_DB_PATCH_APPLIED:
        return
    _QUANTUM_DB_PATCH_APPLIED = True

    def _connect_fresh(cls):
        try:
            cls._local.connection = None
        except Exception:
            pass
        return cls.get_connection()

    @classmethod
    def quantum_execute(cls, query, params=()):
        sql = str(query or '')
        is_write = _quantum_is_write_sql(sql)
        table = _quantum_extract_table(sql) if is_write else 'select'
        data_key = _quantum_data_key_from_sql(sql) if is_write else None
        max_attempts = 6 if is_write else 4
        last_exc = None

        for attempt in range(max_attempts):
            mysql_named_lock_acquired = False
            cur_lock = None
            try:
                conn = cls.get_connection()
                # Em transação atômica não pegamos named lock por query; a transação já controla commit/rollback.
                in_atomic = bool(getattr(cls._local, 'quantum_atomic_depth', 0))

                # Lock local por tabela para evitar corrida dentro da mesma instância.
                local_lock_name = f"mysql:{table}" if is_write else 'mysql:read'
                with _quantum_local_lock(local_lock_name):
                    # Lock distribuído MySQL por tabela, válido para várias máquinas.
                    if is_write and not in_atomic and table not in ('sync_events',):
                        cur_lock = conn.cursor(dictionary=True)
                        lock_name = f"pdv_quantum:{get_mysql_config().get('database', 'pdv')}:{table}"[:64]
                        cur_lock.execute("SELECT GET_LOCK(%s, 12) AS got_lock", (lock_name,))
                        row_lock = cur_lock.fetchone() or {}
                        mysql_named_lock_acquired = int(row_lock.get('got_lock') or 0) == 1
                        if not mysql_named_lock_acquired:
                            raise RuntimeError(f"Timeout ao obter lock distribuído da tabela {table}")

                    cursor = conn.cursor(dictionary=True)
                    cursor.execute(query, params)

                    # Fora de bloco atômico, preserva comportamento antigo: autocommit já grava.
                    # Dentro de bloco atômico, commit fica por conta do context manager.
                    if not conn.autocommit and not in_atomic:
                        conn.commit()

                    if is_write and table not in ('sync_events',):
                        try:
                            _quantum_record_sync_event(data_key, table, sql[:350])
                        except Exception:
                            pass
                        try:
                            qs = get_quantum_sync()
                            if qs:
                                qs.notify_change(data_key or 'all')
                        except Exception:
                            pass
                    return cursor
            except Exception as e:
                last_exc = e
                if not _quantum_is_transient_mysql_error(e) and 'Timeout ao obter lock distribuído' not in str(e):
                    raise
                try:
                    if getattr(cls._local, 'connection', None) is not None:
                        try:
                            cls._local.connection.rollback()
                        except Exception:
                            pass
                    if getattr(e, 'errno', None) in (2006, 2013, 2055):
                        _connect_fresh(cls)
                except Exception:
                    pass
                if attempt >= max_attempts - 1:
                    try:
                        AUDITORIA.erro(f"Falha definitiva após retries SQL | tabela={table} | erro={type(e).__name__}: {e}")
                    except Exception:
                        pass
                    raise
                _quantum_backoff(attempt)
            finally:
                if mysql_named_lock_acquired:
                    try:
                        conn = cls.get_connection()
                        c = conn.cursor(dictionary=True)
                        lock_name = f"pdv_quantum:{get_mysql_config().get('database', 'pdv')}:{table}"[:64]
                        c.execute("SELECT RELEASE_LOCK(%s)", (lock_name,))
                        c.close()
                    except Exception:
                        pass
                try:
                    if cur_lock:
                        cur_lock.close()
                except Exception:
                    pass
        if last_exc:
            raise last_exc

    @classmethod
    def quantum_fetchone(cls, query, params=()):
        for attempt in range(4):
            try:
                conn = cls.get_connection()
                cursor = conn.cursor(dictionary=True)
                cursor.execute(query, params)
                row = cursor.fetchone()
                cursor.close()
                return dict(row) if row else None
            except Exception as e:
                if not _quantum_is_transient_mysql_error(e) or attempt >= 3:
                    raise
                try:
                    cls._local.connection = None
                except Exception:
                    pass
                _quantum_backoff(attempt)

    @classmethod
    def quantum_fetchall(cls, query, params=()):
        for attempt in range(4):
            try:
                conn = cls.get_connection()
                cursor = conn.cursor(dictionary=True)
                cursor.execute(query, params)
                rows = cursor.fetchall()
                cursor.close()
                return [dict(row) for row in rows]
            except Exception as e:
                if not _quantum_is_transient_mysql_error(e) or attempt >= 3:
                    raise
                try:
                    cls._local.connection = None
                except Exception:
                    pass
                _quantum_backoff(attempt)

    @_ctx_quantum_db.contextmanager
    def quantum_transaction(cls, name='transacao', retries=4):
        """Bloco transacional atômico: rollback em erro, commit somente no final."""
        last_exc = None
        for attempt in range(max(1, int(retries or 1))):
            conn = None
            try:
                conn = cls.get_connection()
                old_autocommit = conn.autocommit
                cls._local.quantum_atomic_depth = getattr(cls._local, 'quantum_atomic_depth', 0) + 1
                conn.autocommit = False
                try:
                    conn.start_transaction()
                except Exception:
                    pass
                yield conn
                conn.commit()
                try:
                    _quantum_record_sync_event('all', 'transaction', name)
                    qs = get_quantum_sync()
                    if qs:
                        qs.notify_change('all')
                except Exception:
                    pass
                return
            except Exception as e:
                last_exc = e
                try:
                    if conn:
                        conn.rollback()
                except Exception:
                    pass
                if not _quantum_is_transient_mysql_error(e) or attempt >= int(retries or 1) - 1:
                    raise
                _quantum_backoff(attempt)
            finally:
                try:
                    if conn:
                        conn.autocommit = old_autocommit
                except Exception:
                    pass
                try:
                    cls._local.quantum_atomic_depth = max(0, getattr(cls._local, 'quantum_atomic_depth', 1) - 1)
                except Exception:
                    pass
        if last_exc:
            raise last_exc

    def _commit(cls):
        try:
            conn = cls.get_connection()
            conn.commit()
        except Exception:
            pass

    def _rollback(cls):
        try:
            conn = cls.get_connection()
            conn.rollback()
        except Exception:
            pass

    # Substitui as operações centrais por versões concorrentes e atômicas.
    MySQLDB.execute = quantum_execute
    MySQLDB.fetchone = quantum_fetchone
    MySQLDB.fetchall = quantum_fetchall
    MySQLDB.transaction = classmethod(quantum_transaction)
    MySQLDB.atomic = classmethod(quantum_transaction)
    MySQLDB.commit = classmethod(_commit)
    MySQLDB.rollback = classmethod(_rollback)

    try:
        AUDITORIA.banco_dados("Camada quântica/atômica de concorrência MySQL instalada")
    except Exception:
        pass


_quantum_install_mysql_concurrency_patch()


def get_db():
    return MySQLDB


def reabrir_comanda_deletada(numero_comanda, app_instance):
    """
    Reabilita uma comanda que foi deletada quando foi fechada.
    Chamada quando garçom tenta adicionar item em comanda deletada.
    """
    try:
        db = get_db()
        
        # Verifica se comanda existe no banco
        cursor = db.execute("SELECT * FROM comandas WHERE numero = %s", (numero_comanda,))
        row = cursor.fetchone()
        
        if row:
            # Comanda existe no banco, apenas muda status para aberta
            db.execute(
                "UPDATE comandas SET status = 'aberta', updated_at = CURRENT_TIMESTAMP WHERE numero = %s",
                (numero_comanda,)
            )
            db.commit()
            print(f"[REABRIR] Comanda #{numero_comanda} mudou para ABERTA")
            return True
        else:
            print(f"[REABRIR] Comanda #{numero_comanda} não encontrada no banco")
            return False
    except Exception as e:
        try:
            AUDITORIA.erro(f"Erro no sistema: {e}")
        except Exception:
            pass
        print(f"[ERRO] Ao reabrir comanda: {e}")
        return False

