def _mysql_load_users():
    try:
        fq_runtime_fix_preco_tamanhos()
    except Exception:
        pass
    try:
        _cfg_pw_guard = fq_mysql_password_no_guard(get_mysql_config(), contexto='_mysql_load_users')
        if _cfg_pw_guard.get('_mysql_password_missing'):
            print('[CONFIG] _mysql_load_users fallback por senha vazia.')
            return {}
    except Exception:
        pass
    try:
        fq_preboot_total_banco_antes_de_tudo()
    except Exception:
        pass
    try:
        fq_preboot_obrigatorio_antes_dos_processos()
    except Exception:
        pass
    try:
        fq_fix_schema_usuarios_password_hash()
    except Exception:
        pass
    db = get_db()
    rows = db.fetchall("SELECT * FROM usuarios WHERE ativo = 1")
    result = {}
    for row in rows:
        # FIX: JSON corrompido/truncado no campo permissoes → retorna lista vazia
        try:
            permissoes = json.loads(row['permissoes']) if row['permissoes'] else []
        except (json.JSONDecodeError, ValueError, TypeError):
            permissoes = []
        # Compatibilidade com bancos antigos: alguns registros podem ter usuario preenchido
        # e username vazio/nulo. O login real passa a ser resolvido com fallback seguro.
        _login_key = str(row.get('username') or row.get('usuario') or '').strip().lower()
        if not _login_key:
            continue
        result[_login_key] = {
            'usuario': row.get('usuario') or _login_key,
            'nome': row.get('nome') or row.get('usuario') or _login_key,
            'password': row.get('password_hash') or row.get('senha') or '',
            'nivel_acesso': row.get('nivel_acesso') or row.get('nivel') or 'caixa',
            'permissoes': permissoes
        }
    # Revisa usuários existentes para receber permissões criadas após os níveis antigos.
    try:
        if "sincronizar_todos_usuarios_com_niveis" in globals():
            result = sincronizar_todos_usuarios_com_niveis(result, salvar=True)
    except Exception as e:
        print(f"[PERMISSÕES] Aviso ao sincronizar usuários existentes: {e}")
    return result

# ═══════════════════════════════════════════════════════════════════════════
# FUNÇÕES DE SALVAMENTO (Dict -> MySQL)
# ═══════════════════════════════════════════════════════════════════════════

_FQ_PRODUTOS_COLS_VERIFICADAS = False


def save_data_single(filepath, item_id, item_data, full_data=None):
    """Salva (upsert) APENAS um registro, sem reescrever a tabela inteira.

    Acelera o botão Salvar dos cadastros: em vez de regravar todos os
    registros (lento em tabelas grandes), grava só o item alterado.
    Faz fallback para o save_data() completo quando a entidade não tem
    rota incremental conhecida ou quando ocorre algum erro.
    """
    fp = str(filepath or '').lower()
    one = {str(item_id): item_data}
    try:
        if 'products' in fp or 'produtos' in fp:
            return _mysql_save_products_single(item_id, item_data)
        if 'categories' in fp or 'categorias' in fp:
            return _mysql_save_categories(one, prune=False)
        if 'customers' in fp or 'clientes' in fp:
            return _mysql_save_customers(one, prune=False)
        if 'fornecedores' in fp or 'suppliers' in fp:
            return _mysql_save_suppliers(one, prune=False)
        if 'entregadores' in fp:
            return _mysql_save_entregadores(one, prune=False)
        if 'tamanhos' in fp:
            return _mysql_save_tamanhos(one, prune=False)
        if 'bairros' in fp:
            return _mysql_save_bairros(one, prune=False)
        if 'cartoes' in fp:
            return _mysql_save_cartoes(one, prune=False)
        if 'vendedores' in fp:
            return _mysql_save_vendedores(one, prune=False)
        if 'servicos' in fp:
            return _mysql_save_servicos(one, prune=False)
    except Exception as _e:
        try:
            print(f"[SAVE-INCREMENTAL] Fallback para save completo ({fp}): {_e}")
        except Exception:
            pass
    # Fallback seguro: comportamento antigo (salva o dicionário inteiro).
    return save_data(filepath, full_data if full_data is not None else one)


def _mysql_save_products_single(prod_id, prod_data):
    """Salva um único produto no banco de dados de forma otimizada."""
    db = get_db()
    # Garante compatibilidade com bancos antigos antes de gravar lote/validade.
    # Executado apenas UMA vez por processo (antes rodava 4 ALTER TABLE a cada
    # salvamento, gerando round-trips desnecessários ao MySQL).
    global _FQ_PRODUTOS_COLS_VERIFICADAS
    if not _FQ_PRODUTOS_COLS_VERIFICADAS:
        for _col_name, _col_sql in [
            ("controlar_lote_validade", "INTEGER DEFAULT 0"),
            ("lote", "VARCHAR(500) DEFAULT ''"),
            ("validade", "VARCHAR(500) DEFAULT ''"),
            ("data_validade", "VARCHAR(500) DEFAULT ''"),
        ]:
            try:
                db.execute(f"ALTER TABLE produtos ADD COLUMN {_col_name} {_col_sql}")
            except Exception:
                pass
        _FQ_PRODUTOS_COLS_VERIFICADAS = True
    existing = db.fetchone("SELECT id FROM produtos WHERE id = %s", (int(prod_id),))
    categoria_id = prod_data.get('categoria_id') or prod_data.get('category_id') or '1'
    
    tamanho_id_raw = prod_data.get('tamanho_id')
    tamanho_id = None
    if tamanho_id_raw is not None and tamanho_id_raw != '' and tamanho_id_raw != 'None':
        try:
            tamanho_id = int(tamanho_id_raw)
        except (ValueError, TypeError):
            tamanho_id = None
    
    if existing:
        db.execute("""
            UPDATE produtos SET 
                nome = %s, codigo_barras = %s, categoria_id = %s, preco = %s,
                preco_atacado = %s, atacado_qtd_minima = %s, preco_promocional = %s,
                promocao_ativa = %s, promocao_inicio = %s, promocao_fim = %s, preco_compra = %s, tipo = %s, 
                estoque = %s, estoque_minimo = %s, fidelidade_pontos = %s, tamanho_id = %s,
                controlar_lote_validade = %s, lote = %s, validade = %s, data_validade = %s,
                imagem = %s,
                ativo = 1, updated_at = CURRENT_TIMESTAMP
            WHERE id = %s
        """, (
            prod_data.get('nome', ''),
            prod_data.get('codigo_barras', ''),
            int(categoria_id) if categoria_id else 1,
            parse_br_float(prod_data.get('preco', 0)),
            parse_br_float(prod_data.get('preco_atacado', 0)),
            parse_br_float(prod_data.get('atacado_qtd_minima', 10)),
            parse_br_float(prod_data.get('preco_promocional', 0)),
            1 if prod_data.get('promocao_ativa', False) else 0,
            prod_data.get('promocao_inicio', ''),
            prod_data.get('promocao_fim', ''),
            parse_br_float(prod_data.get('preco_compra', 0)),
            prod_data.get('tipo', 'unidade'),
            parse_br_float(prod_data.get('estoque', 0)),
            parse_br_float(prod_data.get('estoque_minimo', 5)),
            int(prod_data.get('fidelidade_pontos', 0)),
            tamanho_id,
            1 if prod_data.get('controlar_lote_validade', False) else 0,
            prod_data.get('lote', '') or '',
            prod_data.get('validade', '') or prod_data.get('data_validade', '') or '',
            prod_data.get('data_validade', '') or prod_data.get('validade', '') or '',
            json.dumps(prod_data.get('imagens', [])) if prod_data.get('imagens') else (prod_data.get('imagem', '') or ''),
            int(prod_id)
        ))
    else:
        db.execute("""
            INSERT INTO produtos (id, nome, codigo_barras, categoria_id, preco, preco_atacado, 
                atacado_qtd_minima, preco_promocional, promocao_ativa, promocao_inicio, promocao_fim,
                preco_compra, tipo, estoque, estoque_minimo, fidelidade_pontos, tamanho_id,
                controlar_lote_validade, lote, validade, data_validade, imagem, ativo)
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, 1)
        """, (
            int(prod_id),
            prod_data.get('nome', ''),
            prod_data.get('codigo_barras', ''),
            int(categoria_id) if categoria_id else 1,
            parse_br_float(prod_data.get('preco', 0)),
            parse_br_float(prod_data.get('preco_atacado', 0)),
            parse_br_float(prod_data.get('atacado_qtd_minima', 10)),
            parse_br_float(prod_data.get('preco_promocional', 0)),
            1 if prod_data.get('promocao_ativa', False) else 0,
            prod_data.get('promocao_inicio', ''),
            prod_data.get('promocao_fim', ''),
            parse_br_float(prod_data.get('preco_compra', 0)),
            prod_data.get('tipo', 'unidade'),
            parse_br_float(prod_data.get('estoque', 0)),
            parse_br_float(prod_data.get('estoque_minimo', 5)),
            int(prod_data.get('fidelidade_pontos', 0)),
            tamanho_id,
            1 if prod_data.get('controlar_lote_validade', False) else 0,
            prod_data.get('lote', '') or '',
            prod_data.get('validade', '') or prod_data.get('data_validade', '') or '',
            prod_data.get('data_validade', '') or prod_data.get('validade', '') or '',
            json.dumps(prod_data.get('imagens', [])) if prod_data.get('imagens') else (prod_data.get('imagem', '') or '')
        ))
    return True

def _mysql_delete_product(prod_id):
    """Marca um produto como inativo no banco de dados de forma otimizada."""
    db = get_db()
    try:
        db.execute('UPDATE produtos SET ativo = 0 WHERE id = %s', (int(prod_id),))
        return True
    except Exception as e:
        print(f"Erro ao excluir produto {prod_id}: {e}")
        return False

def _mysql_save_products(data):
    db = get_db()
    existing_rows = db.fetchall("SELECT id FROM produtos")
    existing_ids = set(str(row['id']) for row in existing_rows) if existing_rows else set()
    data_ids = set(str(prod_id) for prod_id in data.keys())
    ids_to_delete = existing_ids - data_ids
    for prod_id in ids_to_delete:
        _mysql_delete_product(prod_id)
    for prod_id, prod_data in data.items():
        _mysql_save_products_single(prod_id, prod_data)
    return True

def _mysql_save_categories(data, prune=True):
    db = get_db()
    
    # Obtém todos os IDs de categorias existentes no banco
    existing_rows = db.fetchall("SELECT id FROM categorias")
    existing_ids = set(str(row['id']) for row in existing_rows) if existing_rows else set()
    
    # IDs que devem permanecer (os que estão no dicionário data)
    data_ids = set(str(cat_id) for cat_id in data.keys())
    
    # IDs a serem excluídos (existem no banco mas não estão mais no dicionário)
    ids_to_delete = existing_ids - data_ids
    
    # Exclui as categorias removidas (marca como inativo)
    if prune:
        for cat_id in ids_to_delete:
            db.execute('UPDATE categorias SET ativo = 0 WHERE id = %s', (int(cat_id),))
    
    # Insere ou atualiza as categorias do dicionário
    for cat_id, cat_data in data.items():
        existing = db.fetchone("SELECT id FROM categorias WHERE id = %s", (int(cat_id),))
        if existing:
            db.execute('UPDATE categorias SET nome = %s, descricao = %s, ativo = 1 WHERE id = %s',
                (cat_data.get('nome', ''), cat_data.get('descricao', ''), int(cat_id)))
        else:
            db.execute('INSERT INTO categorias (id, nome, descricao, ativo) VALUES (%s, %s, %s, 1)',
                (int(cat_id), cat_data.get('nome', ''), cat_data.get('descricao', '')))
    return True

