def _mysql_save_contas_receber(data):
    db = get_db()
    
    # Obtém todos os IDs de contas a receber existentes no banco
    existing_rows = db.fetchall("SELECT id FROM contas_receber")
    existing_ids = set(str(row['id']) for row in existing_rows) if existing_rows else set()
    
    # IDs que devem permanecer (os que estão no dicionário data)
    data_ids = set(str(conta_id) for conta_id in data.keys())
    
    # IDs a serem excluídos (existem no banco mas não estão mais no dicionário)
    ids_to_delete = existing_ids - data_ids
    
    # Exclui as contas a receber removidas (exclusão real do banco)
    for conta_id in ids_to_delete:
        db.execute('DELETE FROM contas_receber WHERE id = %s', (int(conta_id),))
    
    # Insere ou atualiza as contas a receber do dicionário
    for conta_id, conta_data in data.items():
        existing = db.fetchone("SELECT id FROM contas_receber WHERE id = %s", (int(conta_id),))
        cliente_id = conta_data.get('cliente_id')
        cliente_id = int(cliente_id) if cliente_id and str(cliente_id).isdigit() else None
        
        if existing:
            db.execute("""
                UPDATE contas_receber SET 
                    descricao = %s, valor = %s, data_vencimento = %s,
                    cliente_id = %s, status = %s, data_recebimento = %s,
                    forma_pagamento = %s, observacao = %s, venda_id = %s
                WHERE id = %s
            """, (
                conta_data.get('descricao', ''),
                parse_br_float(conta_data.get('valor', 0)),
                conta_data.get('data_vencimento', ''),
                cliente_id,
                conta_data.get('status', 'Pendente'),
                conta_data.get('data_recebimento', ''),
                conta_data.get('forma_pagamento', ''),
                conta_data.get('observacao', ''),
                conta_data.get('venda_id'),
                int(conta_id)
            ))
        else:
            db.execute("""
                INSERT INTO contas_receber (id, descricao, valor, data_vencimento, cliente_id, status, data_recebimento, forma_pagamento, observacao, venda_id)
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
            """, (
                int(conta_id),
                conta_data.get('descricao', ''),
                parse_br_float(conta_data.get('valor', 0)),
                conta_data.get('data_vencimento', ''),
                cliente_id,
                conta_data.get('status', 'Pendente'),
                conta_data.get('data_recebimento', ''),
                conta_data.get('forma_pagamento', ''),
                conta_data.get('observacao', ''),
                conta_data.get('venda_id')
            ))
    return True

