def _mysql_save_users(data):
    try:
        fq_runtime_fix_preco_tamanhos()
    except Exception:
        pass
    try:
        fq_preboot_total_banco_antes_de_tudo()
    except Exception:
        pass
    try:
        fq_preboot_obrigatorio_antes_dos_processos()
    except Exception:
        pass
    try:
        fq_fix_schema_usuarios_password_hash()
    except Exception:
        pass
    db = get_db()

    # Correção para bancos antigos: garante colunas necessárias da tabela usuarios
    # antes de salvar/criar o administrador padrão. Isso evita erro:
    # 1054 (42S22): Unknown column 'updated_at' in 'field list'
    try:
        _usuario_cols_necessarias = {
            "username": "VARCHAR(80) DEFAULT ''",
            "usuario": "VARCHAR(80) DEFAULT ''",
            "nome": "VARCHAR(160) DEFAULT ''",
            "password_hash": "VARCHAR(255) DEFAULT ''",
            "senha": "VARCHAR(255) DEFAULT ''",
            "nivel_acesso": "VARCHAR(50) DEFAULT 'caixa'",
            "nivel": "VARCHAR(50) DEFAULT 'caixa'",
            "permissoes": "LONGTEXT NULL",
            "ativo": "TINYINT DEFAULT 1",
            "created_at": "DATETIME DEFAULT CURRENT_TIMESTAMP",
            "updated_at": "DATETIME NULL",
        }
        for _col, _def in _usuario_cols_necessarias.items():
            try:
                db.execute(f"ALTER TABLE usuarios ADD COLUMN {_col} {_def}")
            except Exception:
                pass
    except Exception as _e_cols_usuarios:
        try:
            print(f"[USUÁRIOS] Aviso ao conferir colunas da tabela usuarios: {_e_cols_usuarios}")
        except Exception:
            pass

    # Mantém a tabela sincronizada com o dicionário recebido.
    # Isso garante persistência correta de edição, exclusão e renomeação.
    usernames_ativos = set()

    for username, user_data in data.items():
        username = str(username).strip().lower()
        if not username:
            continue

        usernames_ativos.add(username)
        permissoes_json = json.dumps(user_data.get('permissoes', []), ensure_ascii=False)
        nome_exibido = str(user_data.get('nome') or user_data.get('usuario') or username).strip()
        usuario_login = str(user_data.get('usuario') or username).strip().lower()

        # Correção sênior: em bancos antigos pode existir o login em usuarios.usuario,
        # mesmo que usuarios.username esteja vazio/diferente. Procurar pelos dois evita
        # erro 1062 Duplicate entry 'adm' for key 'usuarios.usuario'.
        existing = db.fetchone(
            "SELECT id FROM usuarios WHERE username = %s OR usuario = %s LIMIT 1",
            (username, usuario_login)
        )

        if existing:
            db.execute("""
                UPDATE usuarios SET
                    username = %s,
                    usuario = %s,
                    nome = %s,
                    password_hash = %s,
                    senha = %s,
                    nivel_acesso = %s,
                    nivel = %s,
                    permissoes = %s,
                    ativo = 1,
                    updated_at = CURRENT_TIMESTAMP
                WHERE id = %s
            """, (
                username,
                usuario_login,
                nome_exibido,
                user_data.get('password', ''),
                user_data.get('password', ''),
                user_data.get('nivel_acesso', 'caixa'),
                user_data.get('nivel_acesso', 'caixa'),
                permissoes_json,
                existing.get('id') if isinstance(existing, dict) else existing[0]
            ))
        else:
            db.execute("""
                INSERT INTO usuarios (username, usuario, nome, password_hash, senha, nivel_acesso, nivel, permissoes, ativo)
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, 1)
                ON DUPLICATE KEY UPDATE
                    nome = VALUES(nome),
                    password_hash = VALUES(password_hash),
                    senha = VALUES(senha),
                    nivel_acesso = VALUES(nivel_acesso),
                    nivel = VALUES(nivel),
                    permissoes = VALUES(permissoes),
                    ativo = 1,
                    updated_at = CURRENT_TIMESTAMP
            """, (
                username,
                usuario_login,
                nome_exibido,
                user_data.get('password', ''),
                user_data.get('password', ''),
                user_data.get('nivel_acesso', 'caixa'),
                user_data.get('nivel_acesso', 'caixa'),
                permissoes_json
            ))

    # Desativa usuários que não existem mais no dicionário atual.
    # Protege os usuários de sistema contra desativação acidental.
    existentes = db.fetchall("SELECT username FROM usuarios WHERE ativo = 1") or []
    # Protege apenas os administradores totais que continuam no dicionário atual.
    # Assim o antigo 'adm' pode ser renomeado sem ser recriado/duplicado.
    protegidos = set(str(u).strip().lower() for u, d in data.items() if _quantum_is_admin_blindado(u, d))
    for row in existentes:
        username_db = str(row.get('username', '')).strip().lower()
        if username_db and username_db not in usernames_ativos and username_db not in protegidos:
            db.execute("""
                UPDATE usuarios
                SET ativo = 0, updated_at = CURRENT_TIMESTAMP
                WHERE username = %s
            """, (username_db,))

    return True


