# PATCH PENTE-FINO 2026-06-05:
# Camada defensiva para diferenças entre tkinter.ttk e ttkbootstrap.
# Não remove funcionalidades; apenas ignora opções que certas versões do Tk/ttkbootstrap
# não reconhecem, evitando erros como "unknown option -padding" e variações de PanedWindow.
def _quantum_safe_ttk_constructor(_cls, _strip_options=()):
    try:
        if getattr(_cls, '_quantum_safe_constructor', False):
            return _cls
    except Exception:
        pass
    class _SafeWidget(_cls):
        _quantum_safe_constructor = True
        def __init__(self, master=None, **kw):
            for _opt in _strip_options:
                try:
                    kw.pop(_opt, None)
                except Exception:
                    pass
            try:
                super().__init__(master, **kw)
            except Exception as _e:
                msg = str(_e).lower()
                # Fallback extra: remove opções de estilo do ttkbootstrap quando o fallback for tkinter.ttk.
                if ('unknown option' in msg or 'unknown color name' in msg) and kw:
                    _kw2 = dict(kw)
