# 🛠️ Funções Auxiliares para Serviços (SQL)
def load_servicos_sql():
    """Carrega todos os serviços do banco de dados SQL."""
    try:
        db = get_db()
        rows = db.fetchall("SELECT * FROM servicos WHERE ativo = 1 ORDER BY nome")
        servicos = {}
        for row in rows:
            servico_id = str(row['id'])
            servicos[servico_id] = dict(row)
        return servicos
    except Exception as e:
        try:
            AUDITORIA.erro(f"Erro no sistema: {e}")
        except Exception:
            pass
        print(f"[ERRO] Ao carregar serviços do SQL: {e}")
        return {}

def save_servico_sql(servico_id, servico_data):
    """Salva um serviço no banco de dados SQL."""
    try:
        db = get_db()
        
        if servico_id and db.fetchone("SELECT id FROM servicos WHERE id = %s", (servico_id,)):
            # Atualizar
            db.execute("""
                UPDATE servicos SET
                    nome = %s, descricao = %s, categoria = %s, preco = %s,
                    duracao_estimada = %s, unidade_cobranca = %s, status = %s,
                    codigo = %s, garantia = %s, observacao = %s,
                    updated_at = CURRENT_TIMESTAMP
                WHERE id = %s
            """, (
                servico_data.get('nome', ''), servico_data.get('descricao', ''),
                servico_data.get('categoria', 'Outros'), float(servico_data.get('preco', 0)),
                servico_data.get('duracao_estimada', 'A combinar'), servico_data.get('unidade_cobranca', 'Por serviço'),
                servico_data.get('status', 'Ativo'), servico_data.get('codigo', ''),
                servico_data.get('garantia', 'Sem garantia'), servico_data.get('observacao', ''),
                servico_id
            ))
            return servico_id
        else:
            # Inserir novo
            cursor = db.execute("""
                INSERT INTO servicos (nome, descricao, categoria, preco, duracao_estimada, unidade_cobranca, status, codigo, garantia, observacao)
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
            """, (
                servico_data.get('nome', ''), servico_data.get('descricao', ''),
                servico_data.get('categoria', 'Outros'), float(servico_data.get('preco', 0)),
                servico_data.get('duracao_estimada', 'A combinar'), servico_data.get('unidade_cobranca', 'Por serviço'),
                servico_data.get('status', 'Ativo'), servico_data.get('codigo', ''),
                servico_data.get('garantia', 'Sem garantia'), servico_data.get('observacao', '')
            ))
            return str(cursor.lastrowid)
    except Exception as e:
        try:
            AUDITORIA.erro(f"Erro no sistema: {e}")
        except Exception:
            pass
        print(f"[ERRO] Ao salvar serviço no SQL: {e}")
        return None

def delete_servico_sql(servico_id):
    """Exclui (desativa) um serviço do banco SQL."""
    try:
        db = get_db()
        db.execute("UPDATE servicos SET ativo = 0, updated_at = CURRENT_TIMESTAMP WHERE id = %s", (servico_id,))
        return True
    except Exception as e:
        try:
            AUDITORIA.erro(f"Erro no sistema: {e}")
        except Exception:
            pass
        print(f"[ERRO] Ao excluir serviço #{servico_id}: {e}")
        return False


def hash_password(password):
    """Hash de senha com bcrypt."""
    """Gera um hash de senha seguro. Usa bcrypt se disponível, senão SHA256."""
    if bcrypt:
        salt = bcrypt.gensalt(rounds=12)
        return bcrypt.hashpw(password.encode('utf-8'), salt).decode('utf-8')
    return hashlib.sha256(password.encode('utf-8')).hexdigest()

def verify_password(password, hashed):
    """Verifica senha contra hash."""
    """Verifica a senha com suporte a múltiplos algoritmos e arquiteturas."""
    try:
        if not hashed.startswith('$2b$'): 
             return hashlib.sha256(password.encode('utf-8')).hexdigest() == hashed
        if bcrypt:
            return bcrypt.checkpw(password.encode('utf-8'), hashed.encode('utf-8'))
        return False # Bcrypt necessário para este hash mas não disponível
    except Exception:
        return False


