def safe_save_json(filepath, data):
    """Salva um arquivo JSON com retentativas para lidar com concorrência de rede."""
    max_retries = 5
    for i in range(max_retries):
        try:
            # Salva em um arquivo temporário primeiro para evitar corrupção
            temp_file = filepath + ".tmp"
            with open(temp_file, 'w', encoding='utf-8') as f:
                json.dump(data, f, indent=4, ensure_ascii=False)
            
            # Substitui o arquivo original (atômico no SO)
            if os.path.exists(filepath):
                os.remove(filepath)
            os.rename(temp_file, filepath)
            return True
        except Exception as e:
            if i == max_retries - 1:
                print(f"Erro crítico ao salvar {filepath}: {e}")
                return False
            time.sleep(0.2 * (i + 1)) # Espera progressiva
    return False

