# ═══════════════════════════════════════════════════════════════════════
# FARMA QUANTUM - PATCH RUNTIME COLUNAS PRECO/TAMANHOS
# Corrige automaticamente Unknown column 'preco' e tabelas de tamanhos.
# ═══════════════════════════════════════════════════════════════════════
def fq_runtime_fix_preco_tamanhos():
    try:
        import mysql.connector
        cfg = get_mysql_config()
        if cfg.get('_mysql_password_missing'):
            return False
        conn = mysql.connector.connect(
            host=cfg.get('host','127.0.0.1'),
            port=int(cfg.get('port',3306)),
            user=cfg.get('user','usuario'),
            password=cfg.get('password',''),
            database=cfg.get('database','farmacia'),
            use_pure=True,
            autocommit=True,
            connect_timeout=10,
        )
        cur = conn.cursor()
        def q(n): return "`" + str(n).replace("`","``") + "`"
        def cols(t):
            try:
                cur.execute(f"SHOW COLUMNS FROM {q(t)}")
                return {r[0].lower() for r in cur.fetchall()}
            except Exception:
                return set()
        def exec_safe(sql):
            try: cur.execute(sql)
            except Exception as e: print(f"[DB-FIX] Aviso: {e}")
        def add(t,c,ddl):
            if c.lower() not in cols(t):
                exec_safe(f"ALTER TABLE {q(t)} ADD COLUMN {ddl}")
                print(f"[DB-FIX] Coluna criada: {t}.{c}")
        exec_safe("CREATE TABLE IF NOT EXISTS produtos (id INT AUTO_INCREMENT PRIMARY KEY) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci")
        for c, ddl in {
            'preco':'preco DECIMAL(15,2) DEFAULT 0',
            'preco_venda':'preco_venda DECIMAL(15,2) DEFAULT 0',
            'preco_custo':'preco_custo DECIMAL(15,2) DEFAULT 0',
            'preco_compra':'preco_compra DECIMAL(15,2) DEFAULT 0',
            'valor':'valor DECIMAL(15,2) DEFAULT 0',
            'valor_venda':'valor_venda DECIMAL(15,2) DEFAULT 0',
            'custo':'custo DECIMAL(15,2) DEFAULT 0',
            'tamanho':'tamanho VARCHAR(120)',
            'tamanho_id':'tamanho_id INT NULL',
        }.items():
            add('produtos', c, ddl)
        exec_safe("CREATE TABLE IF NOT EXISTS tamanhos (id INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(120) NOT NULL, descricao VARCHAR(255), ordem INT DEFAULT 0, ativo TINYINT DEFAULT 1, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci")
        exec_safe("CREATE TABLE IF NOT EXISTS produto_tamanhos (id INT AUTO_INCREMENT PRIMARY KEY, produto_id INT, tamanho_id INT, tamanho VARCHAR(120), codigo_barras VARCHAR(80), estoque DECIMAL(15,3) DEFAULT 0, preco DECIMAL(15,2) DEFAULT 0, preco_venda DECIMAL(15,2) DEFAULT 0, ativo TINYINT DEFAULT 1, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci")
        exec_safe("CREATE TABLE IF NOT EXISTS tamanhos_produtos (id INT AUTO_INCREMENT PRIMARY KEY, produto_id INT, nome VARCHAR(120), tamanho VARCHAR(120), descricao VARCHAR(255), estoque DECIMAL(15,3) DEFAULT 0, preco DECIMAL(15,2) DEFAULT 0, preco_venda DECIMAL(15,2) DEFAULT 0, ativo TINYINT DEFAULT 1, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci")
        for t in ['produto_tamanhos','tamanhos_produtos','vendas_itens','notas_entrada']:
            exec_safe(f"CREATE TABLE IF NOT EXISTS {q(t)} (id INT AUTO_INCREMENT PRIMARY KEY) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci")
        for t in ['produto_tamanhos','tamanhos_produtos','vendas_itens','notas_entrada']:
            for c, ddl in {'preco':'preco DECIMAL(15,2) DEFAULT 0','preco_venda':'preco_venda DECIMAL(15,2) DEFAULT 0','tamanho':'tamanho VARCHAR(120)','tamanho_id':'tamanho_id INT NULL'}.items():
                add(t,c,ddl)
        cur.close(); conn.close()
        return True
    except Exception as e:
        print(f"[DB-FIX] Falha não fatal no patch preco/tamanhos: {e}")
        return False


# ═══════════════════════════════════════════════════════════════════════
# FARMA QUANTUM - PATCH RUNTIME TABELAS OPERACIONAIS
# Corrige automaticamente colunas/tabelas operacionais ausentes:
# comandas, entregadores, servicos, bairros, cartoes, vendedores,
# customers.cpf e tamanhos.sigla.
# ═══════════════════════════════════════════════════════════════════════
def fq_runtime_fix_tabelas_operacionais():
    try:
        import mysql.connector
        cfg = get_mysql_config()
        if cfg.get('_mysql_password_missing'):
            return False
        conn = mysql.connector.connect(
            host=cfg.get('host','127.0.0.1'),
            port=int(cfg.get('port',3306)),
            user=cfg.get('user','usuario'),
            password=cfg.get('password',''),
            database=cfg.get('database','farmacia'),
            use_pure=True,
            autocommit=True,
            connect_timeout=10,
        )
        cur = conn.cursor()
        def q(n): return "`" + str(n).replace("`","``") + "`"
        def exec_safe(sql):
            try: cur.execute(sql)
            except Exception as e: print(f"[DB-OPS-FIX] Aviso: {e}")
        def cols(t):
            try:
                cur.execute(f"SHOW COLUMNS FROM {q(t)}")
                return {r[0].lower() for r in cur.fetchall()}
            except Exception:
                return set()
        def add(t,c,ddl):
            if c.lower() not in cols(t):
                exec_safe(f"ALTER TABLE {q(t)} ADD COLUMN {ddl}")
                print(f"[DB-OPS-FIX] Coluna criada: {t}.{c}")
        exec_safe("CREATE TABLE IF NOT EXISTS tamanhos (id INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(120) NOT NULL, sigla VARCHAR(30), descricao VARCHAR(255), ordem INT DEFAULT 0, ativo TINYINT DEFAULT 1, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci")
        add('tamanhos','sigla','sigla VARCHAR(30)')
        exec_safe("UPDATE tamanhos SET sigla = nome WHERE (sigla IS NULL OR sigla = '') AND nome IS NOT NULL")
        exec_safe("CREATE TABLE IF NOT EXISTS customers (id INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(255), name VARCHAR(255), cpf VARCHAR(40), telefone VARCHAR(80), phone VARCHAR(80), whatsapp VARCHAR(80), endereco VARCHAR(255), bairro VARCHAR(120), observacao TEXT, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci")
        add('customers','cpf','cpf VARCHAR(40)')
        for t, ddl in {
            'comandas': "CREATE TABLE IF NOT EXISTS comandas (id INT AUTO_INCREMENT PRIMARY KEY, numero VARCHAR(80), nome VARCHAR(255), cliente_id INT NULL, cliente_nome VARCHAR(255), status VARCHAR(80) DEFAULT 'ABERTA', total DECIMAL(15,2) DEFAULT 0, observacao TEXT, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
            'entregadores': "CREATE TABLE IF NOT EXISTS entregadores (id INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(255), telefone VARCHAR(80), whatsapp VARCHAR(80), ativo TINYINT DEFAULT 1, observacao TEXT, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
            'servicos': "CREATE TABLE IF NOT EXISTS servicos (id INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(255), descricao TEXT, preco DECIMAL(15,2) DEFAULT 0, valor DECIMAL(15,2) DEFAULT 0, ativo TINYINT DEFAULT 1, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
            'bairros': "CREATE TABLE IF NOT EXISTS bairros (id INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(255), taxa_entrega DECIMAL(15,2) DEFAULT 0, valor_entrega DECIMAL(15,2) DEFAULT 0, ativo TINYINT DEFAULT 1, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
            'cartoes': "CREATE TABLE IF NOT EXISTS cartoes (id INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(255), bandeira VARCHAR(120), tipo VARCHAR(80), taxa DECIMAL(15,2) DEFAULT 0, ativo TINYINT DEFAULT 1, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
            'vendedores': "CREATE TABLE IF NOT EXISTS vendedores (id INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(255), telefone VARCHAR(80), comissao DECIMAL(15,2) DEFAULT 0, ativo TINYINT DEFAULT 1, observacao TEXT, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        }.items():
            exec_safe(ddl)
        cur.close(); conn.close()
        return True
    except Exception as e:
        print(f"[DB-OPS-FIX] Falha não fatal: {e}")
        return False


def _quantum_admin_total_data(user_data):
    """Retorna True para qualquer usuário administrador blindado, mesmo após renomear o antigo adm."""
    try:
        if not isinstance(user_data, dict):
            return False
        nivel = str(user_data.get('nivel_acesso') or user_data.get('nivel') or '').strip().lower()
        perms = user_data.get('permissoes') or []
        if isinstance(perms, str):
            try:
                import json as _json
                perms = _json.loads(perms) if perms else []
            except Exception:
                perms = [perms]
        return nivel == 'admin' and '*' in perms
    except Exception:
        return False

def _quantum_is_admin_blindado(username=None, user_data=None):
    """Identifica administradores protegidos: adm/phda ou qualquer admin total renomeado."""
    try:
        u = str(username or '').strip().lower()
        if u in ('adm', 'phda'):
            return True
        return _quantum_admin_total_data(user_data or {})
    except Exception:
        return False

def create_default_admin():
    try:
        fq_runtime_fix_tabelas_operacionais()
    except Exception:
        pass
    try:
        fq_runtime_fix_preco_tamanhos()
    except Exception:
        pass
    try:
        fq_preboot_total_banco_antes_de_tudo()
    except Exception:
        pass
    try:
        fq_preboot_obrigatorio_antes_dos_processos()
    except Exception:
        pass
    AUDITORIA.processo("Verificando/criando usuário administrador padrão")
    users = load_users()
    users_modified = False
    
    # Garante administrador total no sistema.
    # Se o usuário adm foi renomeado pelo próprio sistema, NÃO recria adm.
    _tem_admin_total_renomeado = any(_quantum_admin_total_data(u) for u in users.values())
    _tem_adm_por_usuario = any(str((u or '')).strip().lower() == 'adm' or str((d or {}).get('usuario', '')).strip().lower() == 'adm' for u, d in users.items())
    if "adm" not in users and not _tem_admin_total_renomeado and not _tem_adm_por_usuario:
        users["adm"] = {
            "usuario": "adm",
            "nome": "Administrador",
            "password": hash_password("9652"),
            "nivel_acesso": "admin",
            "permissoes": ["*"]
        }
        users_modified = True
    elif "adm" in users:
        # Se o adm já existir, mantém a senha existente.
        # Porém, se ela estiver vazia/nula, grava automaticamente a padrão 9652.
        adm_atual = users.get("adm", {}) or {}
        adm_changed = False
        if not str(adm_atual.get("password", "") or "").strip():
            adm_atual["password"] = hash_password("9652")
            adm_changed = True
            try:
                print("[ADM] Senha do usuário adm estava vazia; senha padrão 9652 gravada automaticamente.")
            except Exception:
                pass
        if adm_atual.get("permissoes") != ["*"]:
            adm_atual["permissoes"] = ["*"]
            adm_changed = True
        if adm_atual.get("nivel_acesso") != "admin":
            adm_atual["nivel_acesso"] = "admin"
            adm_changed = True
        if not str(adm_atual.get("usuario", "") or "").strip():
            adm_atual["usuario"] = "adm"
            adm_changed = True
        if not str(adm_atual.get("nome", "") or "").strip():
            adm_atual["nome"] = "Administrador"
            adm_changed = True
        users["adm"] = adm_atual
        if adm_changed:
            users_modified = True
    
    # Garante que o usuário phda exista com senha 4872 e permissão total '*'.
    # CORREÇÃO DE PERFORMANCE: bcrypt usa salt; comparar hash novo com hash salvo
    # sempre dá diferente e forçava regravação no banco em toda inicialização.
    # Agora só recria se não existir ou se a senha salva realmente não validar.
    if "phda" not in users:
        users["phda"] = {
            "password": hash_password("4872"),
            "nivel_acesso": "admin",
            "permissoes": ["*"]
        }
        users_modified = True
    else:
        phda_atual = users.get("phda", {})
        # BOOT TURBO: bcrypt pode travar segundos em máquinas lentas.
        # Se o usuário já existe, não revalida hash no boot; validação real ocorre no login.
        senha_ok = True
        if str(os.environ.get('QUANTUM_REVALIDAR_PHDA_BOOT', '0')).strip().lower() in ('1','true','sim','yes'):
            senha_ok = verify_password("4872", phda_atual.get("password", ""))
            if not senha_ok:
                phda_atual["password"] = hash_password("4872")
                users_modified = True
        if phda_atual.get("permissoes") != ["*"] or phda_atual.get("nivel_acesso") != "admin":
            phda_atual["nivel_acesso"] = "admin"
            phda_atual["permissoes"] = ["*"]
            users_modified = True
        users["phda"] = phda_atual
    
    # Remove o usuário 'admin' antigo se existir (migração para 'adm')
    if "admin" in users:
        del users["admin"]
        users_modified = True
    
    if users_modified:
        save_users(users)

logged_user = None
logged_user_data = None

def check_permission(permission_name):
    """
    Verifica se o usuário logado tem uma permissão específica.
    
    Suporta verificação hierárquica:
    - Permissão exata: 'vendas.aplicar_desconto'
    - Permissão de módulo: 'vendas.*' (concede todas as permissões de vendas)
    - Permissão total: '*' (concede todas as permissões)
    
    Também suporta fallback para permissões genéricas:
    
    Nota: Verificações de permissão são registradas na auditoria quando negadas.
    - Se 'vendas.aplicar_desconto_item' não existe, verifica 'vendas.aplicar_desconto'
    - Se 'produtos.editar_nome' não existe, verifica 'produtos.editar'
    
    Args:
        permission_name: Nome da permissão a verificar (ex: 'vendas.aplicar_desconto')
    
    Returns:
        bool: True se o usuário tem a permissão, False caso contrário
    """
    global logged_user, logged_user_data
    
    # Administrador blindado tem TODAS as permissões, mesmo se o antigo adm for renomeado.
    if _quantum_is_admin_blindado(logged_user, logged_user_data):
        return True
    
    if not logged_user_data or "permissoes" not in logged_user_data:
        return False
    
    # IMPORTANTE: O campo 'nivel_acesso' NÃO concede acesso automático.
    # As permissões são verificadas EXCLUSIVAMENTE pela lista de permissões individuais.
    # Apenas os usuários 'adm' e 'phda' têm acesso total incondicional.
    
    user_perms = logged_user_data["permissoes"]
    
    # Se a lista de permissões está vazia, nega tudo
    if not user_perms:
        return False
    
    # Admin total (para usuários com permissão * na lista de permissões)
    if "*" in user_perms:
        return True
    
    # Verificação direta
    if permission_name in user_perms:
        return True
    
    # Verificação por módulo (ex: vendas.*)
    parts = permission_name.split('.')
    if len(parts) >= 1:
        module = parts[0]
        if f"{module}.*" in user_perms:
            return True
    
    # Verificação de aliases/compatibilidade entre permissões antigas e novas.
    # Ex.: vendas.devolucao <-> devolucoes.acessar; vendas.reimprimir_cupom <-> cupons.reimprimir.
    try:
        aliases_map = globals().get("PERMISSION_ALIASES", {})
        aliases = list(aliases_map.get(permission_name, []))
        # Compatibilidade reversa automática: se a permissão consultada aparece
        # como alias de outra, também considera a permissão principal equivalente.
        for _perm_base, _aliases_base in aliases_map.items():
            try:
                if permission_name in (_aliases_base or []) and _perm_base not in aliases:
                    aliases.append(_perm_base)
            except Exception:
                pass
        for alias_perm in aliases:
            if alias_perm in user_perms:
                return True
            alias_parts = alias_perm.split(".")
            if alias_parts and f"{alias_parts[0]}.*" in user_perms:
                return True
    except Exception:
        pass

    # Verificação hierárquica (fallback para permissões genéricas)
    # Ex: 'vendas.aplicar_desconto_item' -> verifica 'vendas.aplicar_desconto'
    # Ex: 'produtos.editar_nome' -> verifica 'produtos.editar'
    if len(parts) >= 2:
        action = parts[1]
        # Tenta encontrar uma permissão pai
        action_parts = action.split('_')
        for i in range(len(action_parts) - 1, 0, -1):
            parent_action = '_'.join(action_parts[:i])
            parent_perm = f"{parts[0]}.{parent_action}"
            if parent_perm in user_perms:
                return True
    
    # Registra na auditoria que a permissão foi NEGADA
    try:
        AUDITORIA.seguranca(f"Permissão NEGADA: '{permission_name}' para usuário '{logged_user}'")
    except Exception:
        pass
    return False


def check_permission_any(*permission_names):
    """
    Verifica se o usuário tem QUALQUER UMA das permissões listadas.
    
    Args:
        *permission_names: Lista de permissões a verificar
    
    Returns:
        bool: True se o usuário tem pelo menos uma das permissões
    """
    return any(check_permission(perm) for perm in permission_names)


def check_permission_all(*permission_names):
    """
    Verifica se o usuário tem TODAS as permissões listadas.
    
    Args:
        *permission_names: Lista de permissões a verificar
    
    Returns:
        bool: True se o usuário tem todas as permissões
    """
    return all(check_permission(perm) for perm in permission_names)


def get_user_permissions():
    """
    Retorna a lista de permissões do usuário logado.
    
    Returns:
        list: Lista de permissões do usuário
    """
    global logged_user_data
    if not logged_user_data:
        return []
    return logged_user_data.get('permissoes', [])

def authenticate_user():
    """Janela de login com lista de seleção de usuários"""
    users = load_users()
    
    # Criar janela de login como Toplevel do root existente
    login_win = tk.Toplevel()
