def _permissoes_catalogo_existentes():
    catalogo = set()
    try:
        for grupo in PERMISSION_GROUPS.values():
            catalogo.update(grupo.keys())
    except Exception:
        pass
    return catalogo

def _permissao_valida_no_catalogo(perm, catalogo=None):
    if perm == "*":
        return True
    catalogo = catalogo or _permissoes_catalogo_existentes()
    if perm in catalogo:
        return True
    if isinstance(perm, str) and perm.endswith(".*"):
        prefixo = perm[:-2] + "."
        return any(p.startswith(prefixo) for p in catalogo)
    return False

def _normalizar_lista_permissoes(permissoes):
    catalogo = _permissoes_catalogo_existentes()
    filtradas = []
    for perm in permissoes or []:
        if _permissao_valida_no_catalogo(perm, catalogo):
            filtradas.append(perm)
    return sorted(set(filtradas))

def _aplicar_matriz_final_permissoes_20260501():
    for role_key, permissions in ROLE_PERMISSION_PATCH_20260501.items():
        if role_key not in ROLES:
            ROLES[role_key] = {"description": role_key.title(), "permissions": []}
        if role_key == "admin":
            ROLES[role_key]["permissions"] = ["*"]
        else:
            ROLES[role_key]["permissions"] = _normalizar_lista_permissoes(permissions)
    try:
        AUDITORIA.seguranca("Matriz final de permissões v2026.05.01 aplicada aos níveis padrão")
    except Exception:
        pass

def _auditar_permissoes_usadas_no_codigo():
    """Audita permissões usadas por menus/atalhos/botões e registra inconsistências sem travar o sistema."""
    try:
        catalogo = _permissoes_catalogo_existentes()
        usadas = set()
        import re as _re_perm_audit
        try:
            with open(__file__, "r", encoding="utf-8", errors="ignore") as _fp_perm_audit:
                _src_perm_audit = _fp_perm_audit.read()
            for _m_perm in _re_perm_audit.finditer(r"check_permission(?:_any|_all)?\(([^\)]*)\)", _src_perm_audit):
                for _m_str_perm in _re_perm_audit.finditer(r"['\"]([a-zA-Z0-9_]+\.[a-zA-Z0-9_*]+)['\"]", _m_perm.group(1)):
                    usadas.add(_m_str_perm.group(1))
        except Exception:
            usadas = set()
        faltantes = sorted(p for p in usadas if not _permissao_valida_no_catalogo(p, catalogo))
        if faltantes:
            AUDITORIA.seguranca("Permissões usadas no código sem cadastro no catálogo: " + ", ".join(faltantes))
        else:
            AUDITORIA.seguranca("Auditoria de permissões: todas as permissões usadas no código estão no catálogo")
    except Exception:
        pass

_aplicar_matriz_final_permissoes_20260501()
try:
    _early_boot_update("Permissões carregadas; preparando arquivos de dados...")
except Exception:
    pass
# Auditoria pesada de permissões não deve rodar durante import/boot inicial.
# Ela pode ler o arquivo inteiro e atrasar ou travar a abertura em máquinas lentas.
# Para executar manualmente no boot, defina QUANTUM_AUDIT_PERMISSIONS_ON_BOOT=1.
try:
    if str(os.environ.get("QUANTUM_AUDIT_PERMISSIONS_ON_BOOT", "0")).strip().lower() in ("1", "true", "sim", "yes", "on"):
        _auditar_permissoes_usadas_no_codigo()
    else:
        try:
            AUDITORIA.seguranca("Auditoria completa de permissões adiada para não bloquear o boot")
        except Exception:
            pass
except Exception:
    pass




