        self.tree.configure(yscroll=tree_scrollbar.set)
        tree_scrollbar.grid(row=1, column=1, sticky='ns')
        self.tree.grid(row=1, column=0, sticky='nsew')
        self.tree.bind('<<TreeviewSelect>>', self._on_user_select)
        
