class DateRangeDialog(simpledialog.Dialog):
    def body(self, master):
        self.title("Selecionar Período")
        ttk.Label(master, text="Data Inicial:").grid(row=0, column=0, padx=5, pady=5)
        self.cal_inicio = ttk.DateEntry(master, width=15, dateformat="%d/%m/%Y")
        self.cal_inicio.grid(row=0, column=1, padx=5, pady=5)
        
        ttk.Label(master, text="Data Final:").grid(row=1, column=0, padx=5, pady=5)
        self.cal_fim = ttk.DateEntry(master, width=15, dateformat="%d/%m/%Y")
        self.cal_fim.grid(row=1, column=1, padx=5, pady=5)
        return self.cal_inicio

    def apply(self):
        self.result = (self.cal_inicio.entry.get(), self.cal_fim.entry.get())

class AskFloatDialog(simpledialog.Dialog):
    """
    Diálogo compacto para quantidade/peso.
    Correção reforçada:
    - impede barra de status automática dentro desta janela;
    - impede auto-polimento visual que aumenta diálogos pequenos;
    - força tamanho compacto antigo;
    - centraliza sobre a janela pai;
    - mantém OK/Cancel visíveis.
    """
    _skip_auto_statusbar = True
    _skip_visual_autopolish = True

    def __init__(self, parent, title, prompt, initialvalue=None, minvalue=None, maxvalue=None):
        self.prompt = prompt
        self.initialvalue = initialvalue
        self.minvalue = minvalue
        self.maxvalue = maxvalue
        self.result = None
        self._parent_ref = parent
        self._skip_auto_statusbar = True
        self._skip_visual_autopolish = True
        super().__init__(parent, title)
        try:
            self._skip_auto_statusbar = True
            self._skip_visual_autopolish = True
            self.after(50, self._remove_statusbar_and_compact)
            self.after(650, self._remove_statusbar_and_compact)
            self.after(1400, self._remove_statusbar_and_compact)
        except Exception:
            pass

    def body(self, master):
        try:
            self._skip_auto_statusbar = True
            self._skip_visual_autopolish = True
            master.columnconfigure(0, weight=1)
        except Exception:
            pass

        self.prompt_label = ttk.Label(master, text=self.prompt, justify=tk.LEFT, wraplength=320)
        self.prompt_label.grid(row=0, column=0, padx=8, pady=(8, 6), sticky='w')

        self.entry = ttk.Entry(master, width=24)
        self.entry.grid(row=1, column=0, padx=8, pady=(0, 8), sticky='ew')

        if self.initialvalue is not None:
            self.entry.insert(0, format_br_float(self.initialvalue, precision=3))

        self.entry.select_range(0, tk.END)

        def validate_input(action, value_if_allowed, text):
            if action == '1':
                if text in '0123456789,.':
                    current_text = self.entry.get()
                    if text in ',.' and (',' in current_text or '.' in current_text):
                        return False
                    return True
                return False
            return True

        vcmd = (self.register(validate_input), '%d', '%P', '%S')
        self.entry.config(validate='key', validatecommand=vcmd)

        self.after(10, self._remove_statusbar_and_compact)
        return self.entry

    def buttonbox(self):
        box = ttk.Frame(self)

        btn_ok = ttk.Button(box, text="OK", width=10, command=self.ok, default=tk.ACTIVE)
        btn_ok.pack(side=tk.LEFT, padx=6, pady=8)

        btn_cancel = ttk.Button(box, text="Cancel", width=10, command=self.cancel)
        btn_cancel.pack(side=tk.LEFT, padx=6, pady=8)

        self.bind("<Return>", self.ok)
        self.bind("<Escape>", self.cancel)

        box.pack(padx=8, pady=(0, 8))

    def _remove_statusbar_and_compact(self):
        """Remove barra automática se algum patch global tentar adicionar e reaplica tamanho compacto."""
        try:
            self._skip_auto_statusbar = True
            self._skip_visual_autopolish = True
        except Exception:
            pass

        for attr in ("status_bar", "status_bar_frame", "_quantum_ultimate_statusbar", "_quantum_visual_statusbar"):
            try:
                obj = getattr(self, attr, None)
                if hasattr(obj, "destroy"):
                    obj.destroy()
                setattr(self, attr, None)
            except Exception:
                pass

        # Remove possíveis frames de status criados no rodapé.
        try:
            for child in list(self.winfo_children()):
                try:
                    cls_name = child.__class__.__name__.lower()
                    txt = ""
                    try:
                        txt = str(child.cget("text")).lower()
                    except Exception:
                        pass
                    if "statusbar" in cls_name or "conectado" in txt or "adm" == txt.strip():
                        child.destroy()
                except Exception:
                    pass
        except Exception:
            pass

        self._apply_compact_geometry()

    def _apply_compact_geometry(self):
        try:
            self.update_idletasks()

            width = 330
            height = 165

            parent = self._parent_ref
            if parent is not None and hasattr(parent, 'winfo_rootx'):
                try:
                    px = parent.winfo_rootx()
                    py = parent.winfo_rooty()
                    pw = parent.winfo_width()
                    ph = parent.winfo_height()
                    if pw <= 1:
                        pw = parent.winfo_reqwidth()
                    if ph <= 1:
                        ph = parent.winfo_reqheight()
                    x = px + max(0, (pw - width) // 2)
                    y = py + max(0, (ph - height) // 2)
                except Exception:
                    sw = self.winfo_screenwidth()
                    sh = self.winfo_screenheight()
                    x = max(0, (sw - width) // 2)
                    y = max(0, (sh - height) // 2)
            else:
                sw = self.winfo_screenwidth()
                sh = self.winfo_screenheight()
                x = max(0, (sw - width) // 2)
                y = max(0, (sh - height) // 2)

            self.geometry(f"{width}x{height}+{x}+{y}")
            self.minsize(width, height)
            self.maxsize(width, height)
            self.resizable(False, False)
            try:
                self.transient(self._parent_ref)
            except Exception:
                pass
        except Exception:
            try:
                self.geometry("330x165")
                self.resizable(False, False)
            except Exception:
                pass

    def validate(self):
        value_str = self.entry.get().strip()
        if not value_str:
            messagebox.showwarning("Valor Inválido", "Informe um valor.", parent=self)
            return 0

        value_float = parse_br_float(value_str)
        if value_float is None:
            messagebox.showwarning("Valor Inválido", "Digite um número válido.", parent=self)
            return 0

        if self.minvalue is not None and value_float < self.minvalue:
            messagebox.showwarning(
                "Valor Inválido",
                f"O valor deve ser no mínimo {format_br_float(self.minvalue, 3)}.",
                parent=self
            )
            return 0

        if self.maxvalue is not None and value_float > self.maxvalue:
            messagebox.showwarning(
                "Valor Inválido",
                f"O valor deve ser no máximo {format_br_float(self.maxvalue, 3)}.",
                parent=self
            )
            return 0

        self.result = value_float
        return 1

    def apply(self):
        pass


def ask_br_float(parent, title, prompt, **kwargs):
    """Função wrapper para chamar o diálogo customizado."""
    d = AskFloatDialog(parent, title, prompt, **kwargs)
    return d.result

# --- Janelas de Cadastro (Revisadas com Novos Campos e Virgula) ---

class BaseCadastroWindow(tk.Toplevel):
    def __init__(self, parent, title, data_dict, filepath, fields_config, tree_columns, tree_headings, log_action=None, app=None):
        super().__init__(parent)
        self.status_bar = StatusBar(self, user_name=getattr(self, 'current_user', 'Usuário'))
        self.parent_app = app if app else parent
        self.title(title)
        self.state('zoomed') # Maximiza a janela
        self.transient(parent)
        self.grab_set()
        self.resizable(True, True)

        self.data_dict = data_dict
        self.filepath = filepath
        self.fields_config = fields_config
        self.tree_columns = tree_columns
        self.tree_headings = tree_headings
        self.log_action = log_action # Nova variável para armazenar a ação de log

        self.entries = {}
        self.vars = {}
        self.selected_item_id = None

        self._setup_ui()
        self._load_items_to_tree()
        self.protocol("WM_DELETE_WINDOW", self.destroy)
        
        # Vincular atalhos de teclado
        self.bind("<Control-s>", lambda e: self._save_item())
        self.bind("<Control-S>", lambda e: self._save_item())
        self.bind("<Control-n>", lambda e: self._clear_form())
        self.bind("<Control-N>", lambda e: self._clear_form())
        self.bind("<Delete>", lambda e: self._delete_item())
        self.bind("<Escape>", lambda e: self.destroy())
        
        # Definir foco inicial no primeiro campo
        self.after(100, self._set_initial_focus)

        # ⚛️ Quantum Sync - Atualização em tempo real
        self._quantum_sync = get_quantum_sync()
        if self._quantum_sync and hasattr(self, 'app') and self.app:
            # Detectar tipo de dado baseado na classe
            self._quantum_data_key = self._detect_data_key()
            if self._quantum_data_key:
                self._quantum_sync.subscribe(self._quantum_data_key, self._quantum_auto_refresh)
        
        # Bind para limpar subscriber ao fechar
        self.protocol("WM_DELETE_WINDOW", self._quantum_on_close)
    
    def _detect_data_key(self):
        """Detecta a chave de dados baseada no tipo de janela."""
        class_name = self.__class__.__name__.lower()
        key_map = {
            "produto": "products", "categoria": "categories", "cliente": "customers",
            "fornecedor": "fornecedores", "entregador": "entregadores", "bairro": "bairros",
            "tamanho": "tamanhos", "cartao": "cartoes", "cartoes": "cartoes",
            "servico": "servicos", "vendedor": "vendedores", "mesa": "mesas"
        }
        for keyword, key in key_map.items():
            if keyword in class_name:
                return key
        return None
    
    def _quantum_auto_refresh(self):
        """Callback de atualização quântica - recarrega dados da tela."""
        try:
            if self.winfo_exists():
                # Recarrega dados do arquivo
                if hasattr(self, 'data_file') and self.data_file:
                    new_data = load_data(self.data_file, {})
                    if new_data != self.data:
                        self.data = new_data
                        if hasattr(self, 'app') and self.app:
                            # Atualiza referência no app principal
                            attr_map = {
                                "products": "products", "categories": "categories",
                                "customers": "customers", "fornecedores": "fornecedores",
                                "entregadores": "entregadores", "bairros": "bairros",
                                "cartoes": "cartoes", "vendedores": "vendedores",
                                "tamanhos": "tamanhos", "servicos": "servicos", "mesas": "mesas"
                            }
                            if self._quantum_data_key in attr_map:
                                attr = attr_map[self._quantum_data_key]
                                if hasattr(self.app, attr):
                                    setattr(self.app, attr, new_data)
                        # Atualiza a treeview se existir
                        if hasattr(self, '_load_data_to_tree'):
                            self._load_data_to_tree()
                        elif hasattr(self, '_refresh_tree'):
                            self._refresh_tree()
                        elif hasattr(self, '_carregar_dados'):
                            self._carregar_dados()
        except Exception:
            pass
    
    def _quantum_on_close(self):
        """Limpa subscribers ao fechar a janela."""
        try:
            sync = get_quantum_sync()
            if sync:
                sync.unsubscribe_all(self._quantum_auto_refresh)
        except Exception:
            pass
        try:
            self.destroy()
        except Exception:
            pass

    def _set_initial_focus(self):
        if self.entries:
            # Pega o primeiro campo definido na configuração
            first_field = list(self.fields_config.keys())[0]
            widget = self.entries.get(first_field)
            if widget:
                try:
                    widget.focus_set()
                    if isinstance(widget, (ttk.Entry, tk.Entry)):
                        widget.select_range(0, tk.END)
                except: pass

    def _setup_ui(self):
        main_frame = ttk.Frame(self, padding="10")
        main_frame.pack(expand=True, fill=tk.BOTH)
        main_frame.rowconfigure(1, weight=1)
        main_frame.columnconfigure(0, weight=1)

        # Frame do Formulário com Scrollbar Vertical
        form_outer_frame = ttk.Labelframe(main_frame, text="Detalhes", padding="10")
        form_outer_frame.grid(row=0, column=0, sticky="nsew", pady=5)
        form_outer_frame.columnconfigure(0, weight=1)
        form_outer_frame.rowconfigure(0, weight=1)
        
        # Canvas para permitir scroll
        form_canvas = tk.Canvas(form_outer_frame, highlightthickness=0, height=scale_value(350))
        form_canvas.grid(row=0, column=0, sticky="nsew")
        
        # Scrollbar vertical para o formulário
        form_scrollbar = ttk.Scrollbar(form_outer_frame, orient=tk.VERTICAL, command=form_canvas.yview)
        form_scrollbar.grid(row=0, column=1, sticky="ns")
        form_canvas.configure(yscrollcommand=form_scrollbar.set)
        
        # Frame interno que contém os campos do formulário
        form_frame = ttk.Frame(form_canvas)
        form_frame.columnconfigure(1, weight=1)
        
        # Cria janela no canvas
        form_canvas_window = form_canvas.create_window((0, 0), window=form_frame, anchor="nw")
        
        # Função para atualizar a região de scroll
        def _configure_form_scroll(event):
            form_canvas.configure(scrollregion=form_canvas.bbox("all"))
            # Ajusta a largura do frame interno para preencher o canvas
            form_canvas.itemconfig(form_canvas_window, width=form_canvas.winfo_width())
        
        form_frame.bind("<Configure>", _configure_form_scroll)
        form_canvas.bind("<Configure>", lambda e: form_canvas.itemconfig(form_canvas_window, width=e.width))
        
        # Habilita scroll com roda do mouse
        def _on_mousewheel(event):
            form_canvas.yview_scroll(int(-1*(event.delta/120)), "units")
        
        form_canvas.bind_all("<MouseWheel>", _on_mousewheel)
        
        # Armazena referências para uso posterior
        self.form_canvas = form_canvas
        self.form_scrollbar = form_scrollbar

        row_num = 0
        for field_name, config in self.fields_config.items():
            ttk.Label(form_frame, text=config['label'] + ":").grid(row=row_num, column=0, padx=5, pady=5, sticky=tk.W)
            field_type = config.get('type', 'entry')
            widget = None
            var = None
            sticky_opt = tk.EW if field_type in ['entry', 'combo', 'text'] else tk.W

            if field_type == 'entry':
                var = tk.StringVar()
                widget = ttk.Entry(form_frame, textvariable=var, width=config.get('width', 40))
            elif field_type == 'combo':
                var = tk.StringVar()
                widget = ttk.Combobox(form_frame, textvariable=var, values=config.get('options', []), state='readonly', width=config.get('width', 38))
            elif field_type == 'spin_float':
                var = tk.StringVar() # Usar StringVar para lidar com vírgula na UI
                # A validação será feita ao salvar
                widget = ttk.Entry(form_frame, textvariable=var, width=15, justify=tk.RIGHT)
                # Poderia adicionar validação na digitação aqui também
            elif field_type == 'spin_int':
                 var = tk.IntVar(value=config.get('default', 0))
                 # Usar Spinbox normal para inteiros
                 widget = ttk.Spinbox(form_frame, from_=config.get('from', 0), to=config.get('to', 1000000),
                                      increment=config.get('increment', 1), textvariable=var, width=15, wrap=True)
            
            elif field_type == 'date':
                # Seletor de data com calendário
                widget = DateEntry(form_frame, width=15, bootstyle="primary", dateformat="%d/%m/%Y")
                # O DateEntry do ttkbootstrap já vem com a data de hoje por padrão
            elif field_type == 'check':
                 var = tk.BooleanVar(value=config.get('default', False))
                 widget = ttk.Checkbutton(form_frame, variable=var, text=config.get('check_text', ''))
            elif field_type == 'text': # Novo tipo para campos de texto maiores (Observação)
                 var = None # Text widget não usa StringVar diretamente
                 widget = tk.Text(form_frame, height=config.get('height', 3), width=config.get('width', 40), wrap=tk.WORD, relief=tk.SUNKEN, borderwidth=1)
                 # Adicionar scrollbar para o Text widget
                 text_scroll = ttk.Scrollbar(form_frame, orient=tk.VERTICAL, command=widget.yview)
                 widget.configure(yscrollcommand=text_scroll.set)
                 widget.grid(row=row_num, column=1, padx=(5,0), pady=5, sticky=sticky_opt)
                 text_scroll.grid(row=row_num, column=2, padx=(0,5), pady=5, sticky='ns')
                 # Não adiciona scrollbar ao grid principal, só ao lado do Text

            if widget and field_type != 'text': # Text já foi posicionado com scrollbar
                widget.grid(row=row_num, column=1, padx=5, pady=5, sticky=sticky_opt)

            if widget: self.entries[field_name] = widget
            if var: self.vars[field_name] = var
            row_num += 1

        # Frame de Botões do Formulário
        self.form_buttons_frame = ttk.Frame(main_frame)
        self.form_buttons_frame.grid(row=0, column=1, sticky="ns", padx=10, pady=5)
        self.novo_btn = ttk.Button(self.form_buttons_frame, text="Novo (Ctrl+N)", underline=0, command=self._clear_form, width=14, bootstyle="info")
        self.novo_btn.pack(pady=2, fill=tk.X)
        self.salvar_btn = ttk.Button(self.form_buttons_frame, text="Salvar (Ctrl+S)", underline=0, command=self._save_item, width=14, bootstyle="success")
        self.salvar_btn.pack(pady=2, fill=tk.X)
        self.alterar_btn = ttk.Button(self.form_buttons_frame, text="Alterar (Ctrl+S)", underline=0, command=self._save_item, width=14, bootstyle="warning", state="disabled")
        self.alterar_btn.pack(pady=2, fill=tk.X)
        self.excluir_btn = ttk.Button(self.form_buttons_frame, text="Excluir (Del)", underline=0, command=self._delete_item, width=14, bootstyle="danger")
        # self.excluir_btn.pack(pady=2, fill=tk.X) # O pack será feito na classe filha para permitir a inserção de outros botões) # O pack será feito na classe filha para permitir a inserção de outros botões

        # Frame da Lista (Treeview)
        list_frame = ttk.Labelframe(main_frame, text="Itens Cadastrados", padding="10")
        list_frame.grid(row=1, column=0, columnspan=2, sticky="nsew", pady=5)
        list_frame.rowconfigure(1, weight=1)
        list_frame.columnconfigure(0, weight=1)

        # Campo de Busca
        search_frame = ttk.Frame(list_frame)
        search_frame.grid(row=0, column=0, sticky="ew", pady=(0, 5))
        ttk.Label(search_frame, text="🔍 Buscar (Ctrl+F):").pack(side=tk.LEFT, padx=(0, 5))
        self.search_var = tk.StringVar()
        self.search_var.trace_add("write", lambda *args: self._load_items_to_tree())
        self.search_entry = ttk.Entry(search_frame, textvariable=self.search_var)
        self.search_entry.pack(side=tk.LEFT, fill=tk.X, expand=True)
        ttk.Button(search_frame, text="Limpar (Ctrl+L)", underline=0, command=lambda: self.search_var.set(""), bootstyle="secondary-outline").pack(side=tk.LEFT, padx=(5, 0))
        
        # Atalhos adicionais para busca
        self.bind("<Control-f>", lambda e: self.search_entry.focus_set())
        self.bind("<Control-F>", lambda e: self.search_entry.focus_set())
        self.bind("<Control-l>", lambda e: self.search_var.set(""))
        self.bind("<Control-L>", lambda e: self.search_var.set(""))

        self.tree = ttk.Treeview(list_frame, columns=self.tree_columns, show='headings', height=12)
        for col, heading in zip(self.tree_columns, self.tree_headings):
            is_id_col = (col == 'id')
            anchor = tk.CENTER if is_id_col else tk.W
            stretch = tk.NO if is_id_col else tk.YES
            width = 50 if is_id_col else 120 # Ajuste padrão
            if col == 'nome': width = 200
            elif col == 'preco': width = 100; anchor=tk.E
            elif col == 'cpf': width = 110
            elif col == 'telefone': width = 100
            elif col == 'endereco': width = 250
            elif col == 'estoque': width = 100; anchor=tk.E
            elif col == 'pagamento': width = 120
            elif col == 'status': width = 100
            self.tree.heading(col, text=heading, anchor=anchor)
            self.tree.column(col, width=width, anchor=anchor, stretch=stretch)

        scrollbar = ttk.Scrollbar(list_frame, orient=tk.VERTICAL, command=self.tree.yview)
        self.tree.configure(yscroll=scrollbar.set)
        scrollbar.grid(row=1, column=1, sticky='ns')
        self.tree.grid(row=1, column=0, sticky='nsew')
        self.tree.bind('<<TreeviewSelect>>', self._on_item_select)

        # Botão Fechar Janela (ESC) removido a pedido do usuário para ganhar espaço vertical para a lista
        # ttk.Button(main_frame, text="Fechar Janela (ESC)", underline=0, command=self.destroy, bootstyle="secondary").grid(row=2, column=0, columnspan=2, pady=10)

    def _load_items_to_tree(self):
        """Carrega itens na Treeview de forma otimizada para evitar travamentos."""
        # Cancela carregamento anterior se houver
        if hasattr(self, '_after_id') and self._after_id:
            self.after_cancel(self._after_id)
            self._after_id = None

        for i in self.tree.get_children(): self.tree.delete(i)
        
        search_term = self.search_var.get().lower() if hasattr(self, 'search_var') else ""
        sorted_ids = sorted(self.data_dict.keys(), key=lambda x: int(x) if x.isdigit() else float('inf'))
        
        # Filtra os IDs primeiro se houver busca para economizar processamento no loop de inserção
        if search_term:
            filtered_ids = []
            for item_id in sorted_ids:
                item_data = self.data_dict[item_id]
                # Busca rápida no nome e código de barras antes de processar tudo
                if search_term in str(item_data.get('nome', '')).lower() or \
                   search_term in str(item_data.get('codigo_barras', '')).lower() or \
                   search_term in str(item_id).lower():
                    filtered_ids.append(item_id)
            sorted_ids = filtered_ids

        # Inicia o carregamento progressivo (chunking)
        self._load_chunks(sorted_ids, 0)

    def _load_chunks(self, ids, start_index, chunk_size=50):
        """Insere itens na Treeview em pequenos blocos para manter a UI responsiva."""
        end_index = min(start_index + chunk_size, len(ids))
        
        for i in range(start_index, end_index):
            item_id = ids[i]
            item_data = self.data_dict[item_id]
            values = [item_id] + self._get_item_values_for_tree(item_data)
            
            try:
                str_values = [str(v) for v in values]
                self.tree.insert('', tk.END, iid=item_id, values=str_values)
            except tk.TclError:
                pass

        if end_index < len(ids):
            # Agenda o próximo bloco para daqui a 10ms, permitindo que a UI processe eventos
            self._after_id = self.after(10, lambda: self._load_chunks(ids, end_index, chunk_size))
        else:
            self._after_id = None

    def _get_item_values_for_tree(self, item_data):
        # Pega valores na ordem das colunas (exceto 'id')
        # Formata números com vírgula se necessário (ex: preço, estoque)
        values = []
        for col in self.tree_columns[1:]: # Pula a coluna 'id'
            value = item_data.get(col, '')
            # Formatação específica pode ser feita aqui se necessário
            # Ex: if col == 'preco': value = format_br_currency(parse_br_float(value))
            values.append(value)
        return values

    def _on_item_select(self, event):
        selected_items = self.tree.selection()
        if not selected_items:
            self._clear_form()
            return
        self.selected_item_id = selected_items[0]
        item_data = self.data_dict.get(self.selected_item_id)
        if item_data:
            self._fill_form(item_data)
            self.salvar_btn.config(state="disabled")
            self.alterar_btn.config(state="normal")
        else:
            self._clear_form()

    def _fill_form(self, item_data):
        for field_name, widget in self.entries.items():
            value = item_data.get(field_name)
            var = self.vars.get(field_name)
            config = self.fields_config.get(field_name, {})
            field_type = config.get('type')

            # Limpa valor padrão se for None
            if value is None:
                if isinstance(var, tk.BooleanVar): var.set(False)
                elif isinstance(var, tk.IntVar): var.set(0)
                elif isinstance(var, tk.StringVar): var.set('')
                elif isinstance(widget, tk.Text): widget.delete('1.0', tk.END)
                continue # Pula para próximo campo

            # Preenche com valor existente
            try:
                if isinstance(var, tk.BooleanVar): var.set(bool(value))
                elif isinstance(var, tk.IntVar): var.set(int(value))
                elif isinstance(var, tk.StringVar):
                    # Formata float com vírgula para spin_float
                    if field_type == 'spin_float':
                        var.set(format_br_float(parse_br_float(value), 2))
                    # Para Combobox (combo), precisamos encontrar o formato "ID - Nome" ou valor simples
                    elif field_type == 'combo':
                        # Se o valor é um ID, precisamos encontrar o rótulo completo no Combobox
                        options = config.get('options', [])
                        # Primeiro tenta encontrar opção no formato "ID - Nome"
                        selected_option = next((opt for opt in options if opt.startswith(str(value) + ' - ')), None)
                        # Se não encontrou, tenta encontrar o valor exato nas opções (para combos simples como 'unidade', 'peso')
                        if selected_option is None:
                            selected_option = next((opt for opt in options if opt == str(value)), str(value))
                        var.set(selected_option)
                    else:
                        var.set(str(value))
                elif isinstance(widget, tk.Text):
                    widget.delete('1.0', tk.END)
                    widget.insert('1.0', str(value))
                elif isinstance(widget, DateEntry):
                    _set_dateentry_br(widget, value)
            except (ValueError, TypeError, tk.TclError) as e:
                print(f"Erro ao preencher campo {field_name}: {e}. Valor: {value}")
                # Limpa o campo em caso de erro
                if isinstance(var, tk.StringVar): var.set('')
                elif isinstance(widget, tk.Text): widget.delete('1.0', tk.END)

    def _clear_form(self):
        # Reset button states
        if hasattr(self, 'salvar_btn'):
            self.salvar_btn.config(text="Salvar Novo", state="normal") # Volta para Salvar Novo
        if hasattr(self, 'alterar_btn'):
            self.alterar_btn.config(state="disabled")
        self._set_initial_focus() # Desativa Alterar

        for field_name, widget in self.entries.items():
            var = self.vars.get(field_name)
            config = self.fields_config.get(field_name, {})
            default_value = config.get('default')

            if isinstance(var, tk.BooleanVar): var.set(default_value if default_value is not None else False)
            elif isinstance(var, tk.IntVar): var.set(default_value if default_value is not None else 0)
            elif isinstance(var, tk.StringVar):
                 # Formata default float com vírgula
                 if config.get('type') == 'spin_float':
                     var.set(format_br_float(parse_br_float(default_value if default_value is not None else 0.0), 2))
                 else:
                     var.set(str(default_value) if default_value is not None else '')
            elif isinstance(widget, tk.Text):
                 widget.delete('1.0', tk.END)
                 if default_value: widget.insert('1.0', str(default_value))
            elif isinstance(widget, DateEntry):
                 # Limpa/preenche o campo de data no formato brasileiro
                 _set_dateentry_br(widget, default_value or '')

        self.selected_item_id = None
        selection = self.tree.selection()
        if selection: self.tree.selection_remove(selection)

    def _validate_fields(self, data):
         for field_name, config in self.fields_config.items():
             value = data.get(field_name)
             if config.get('required', False):
                 is_empty = value is None or (isinstance(value, str) and not value.strip())
                 if is_empty and not (isinstance(value, (int, float, bool)) and value == 0 or value is False):
                     messagebox.showwarning("Campo Obrigatório", f"O campo '{config['label']}' é obrigatório.", parent=self)
                     return False
             # Validação de float com vírgula
             if config.get('type') == 'spin_float':
                 float_val = parse_br_float(value)
                 if float_val is None:
                     messagebox.showwarning("Valor Inválido", f"Valor inválido para '{config['label']}'. Use vírgula para decimais.", parent=self)
                     return False
                 # Valida min/max se definidos
                 min_val = config.get('from')
                 max_val = config.get('to')
                 if min_val is not None and float_val < min_val:
                      messagebox.showwarning("Valor Inválido", f"'{config['label']}' deve ser no mínimo {min_val}.", parent=self)
                      return False
                 if max_val is not None and float_val > max_val:
                      messagebox.showwarning("Valor Inválido", f"'{config['label']}' deve ser no máximo {max_val}.", parent=self)
                      return False
         return True

    def _get_unique_fields(self):
        """Retorna uma lista de campos que devem ser únicos.
        
        Subclasses devem sobrescrever este método para definir seus campos únicos.
        Cada item pode ser:
        - Uma string com o nome do campo (ex: 'nome')
        - Uma tupla (campo, label_amigável) (ex: ('cpf', 'CPF/CNPJ'))
        """
        return []
    
    def _check_duplicate(self, data, current_id=None):
        """Verifica se já existe um registro com os mesmos valores nos campos únicos.
        
        Args:
            data: Dicionário com os dados do formulário
            current_id: ID do item sendo editado (None se for novo)
            
        Returns:
            tuple: (is_duplicate, message) - Se é duplicado e mensagem de erro
        """
        unique_fields = self._get_unique_fields()
        if not unique_fields:
            return False, ""
        
        for field_info in unique_fields:
            # Extrai nome do campo e label
            if isinstance(field_info, tuple):
                field_name, field_label = field_info
            else:
                field_name = field_info
                # Tenta pegar o label da configuração do campo
                field_label = self.fields_config.get(field_name, {}).get('label', field_name)
            
            new_value = data.get(field_name)
            
            # Ignora campos vazios (a menos que seja obrigatório, que já foi validado)
            if new_value is None or (isinstance(new_value, str) and not new_value.strip()):
                continue
            
            # Normaliza o valor para comparação
            if isinstance(new_value, str):
                new_value_normalized = new_value.strip().upper()
            else:
                new_value_normalized = new_value
            
            # Verifica em todos os registros existentes
            for item_id, item_data in self.data_dict.items():
                # Ignora o próprio item se estiver editando
                if current_id and str(item_id) == str(current_id):
                    continue
                
                existing_value = item_data.get(field_name)
                if existing_value is None:
                    continue
                
                # Normaliza o valor existente para comparação
                if isinstance(existing_value, str):
                    existing_value_normalized = existing_value.strip().upper()
                else:
                    existing_value_normalized = existing_value
                
                # Compara os valores
                if new_value_normalized == existing_value_normalized:
                    item_name = item_data.get('nome', f'ID {item_id}')
                    return True, f"Já existe um registro com o mesmo {field_label}: '{new_value}'\n\nRegistro existente: {item_name} (ID: {item_id})"
        
        return False, ""

    def _collect_form_data(self):
        item_data = {}
        for field_name, widget in self.entries.items():
            var = self.vars.get(field_name)
            config = self.fields_config.get(field_name, {})
            field_type = config.get('type')
            try:
                if isinstance(var, tk.Variable): # BooleanVar, IntVar, StringVar, DoubleVar (não usado diretamente)
                    value = var.get()
                    # Converte string de spin_float para float real
                    if field_type == 'spin_float':
                        float_val = parse_br_float(value)
                        if float_val is None:
                             raise ValueError("Invalid float format")
                        item_data[field_name] = float_val
                    # Extrai o ID do formato "ID - Nome" para campos combo
                    elif field_type == 'combo' and value and ' - ' in str(value):
                        item_data[field_name] = str(value).split(' - ')[0]
                    else:
                        item_data[field_name] = value
                elif isinstance(widget, tk.Text):
                    item_data[field_name] = widget.get('1.0', tk.END).strip()
                elif isinstance(widget, DateEntry):
                    item_data[field_name] = widget.entry.get().strip()
            except (tk.TclError, ValueError) as e:
                 print(f"Erro ao coletar dado para {field_name}: {e}")
                 # Define como None ou vazio para validação pegar
                 item_data[field_name] = None if field_type == 'spin_float' else ''
        return item_data

    def _save_item(self):
        item_data = self._collect_form_data()
        if not self._validate_fields(item_data):
            return

        # Limpeza/Conversão final já feita em _collect_form_data e _validate_fields

        current_id = self.selected_item_id
        
        # Decide se está salvando um novo ou alterando um existente
        is_new = not current_id or self.salvar_btn.cget("state") == "normal" # Se não tem ID ou se o botão "Salvar Novo" está ativo
        
        # ========== VERIFICAÇÃO DE DUPLICIDADE ==========
        # Verifica se já existe um registro com os mesmos valores nos campos únicos
        check_id = None if is_new else current_id
        is_duplicate, duplicate_msg = self._check_duplicate(item_data, check_id)
        if is_duplicate:
            messagebox.showerror("Cadastro Duplicado", f"⚠️ ERRO: Cadastro duplicado detectado!\n\n{duplicate_msg}\n\nPor favor, verifique os dados e tente novamente.", parent=self)
            return
        # ==================================================
        
        if is_new: # Novo
            new_id = str(get_next_id(self.data_dict))
            self.data_dict[new_id] = item_data
            item_id_to_update = new_id
            log_action = "Criado"
        else: # Editando
            self.data_dict[current_id] = item_data
            item_id_to_update = current_id
            log_action = "Alterado"

        if save_data_single(self.filepath, item_id_to_update, item_data, self.data_dict):
            messagebox.showinfo("Sucesso", "Item salvo com sucesso!", parent=self)
            self._load_items_to_tree()
            if current_id:
                if self.tree.exists(item_id_to_update):
                    self.tree.selection_set(item_id_to_update)
                    self.tree.focus(item_id_to_update)
                    self.tree.see(item_id_to_update)
            else:
                self._clear_form()
            if hasattr(self.parent_app, 'refresh_data_views'):
                # Atualiza as telas principais fora do caminho crítico, para que a
                # janela de cadastro responda imediatamente após salvar (o reload
                # completo de todas as tabelas era a maior fonte de lentidão).
                try:
                    self.after(50, lambda: self.parent_app.refresh_data_views(full=False))
                except Exception:
                    self.parent_app.refresh_data_views(full=False)
        else:
            messagebox.showerror("Erro", "Falha ao salvar o item.", parent=self)
            self.data_dict = load_data(self.filepath, self.data_dict)

    def _get_tipo_registro(self):
        """Retorna o tipo de registro para o log de exclusões baseado no título da janela."""
        titulo = self.title() if callable(getattr(self, 'title', None)) else ''
        titulo_lower = titulo.lower()
        if 'produto' in titulo_lower:
            return 'Produto'
        elif 'categoria' in titulo_lower:
            return 'Categoria'
        elif 'cliente' in titulo_lower:
            return 'Cliente'
        elif 'fornecedor' in titulo_lower:
            return 'Fornecedor'
        elif 'entregador' in titulo_lower:
            return 'Entregador'
        elif 'bairro' in titulo_lower:
            return 'Bairro'
        elif 'tamanho' in titulo_lower:
            return 'Tamanho'
        elif 'cart' in titulo_lower:
            return 'Cartão'
        elif 'vendedor' in titulo_lower:
            return 'Vendedor'
        elif 'servi' in titulo_lower:
            return 'Serviço'
        else:
            return titulo.replace('Cadastro de ', '').strip() if titulo else 'Registro'

    def _delete_item(self):
        if not self.selected_item_id: messagebox.showwarning("Seleção", "Nenhum item selecionado.", parent=self); return
        item_data = self.data_dict.get(self.selected_item_id, {})
        item_name = item_data.get('nome', self.selected_item_id)
        if not messagebox.askyesno("Confirmar Exclusão", f"Excluir '{item_name}' (ID: {self.selected_item_id})%s", parent=self): return
        if not self._check_deletion_constraints(self.selected_item_id): return
        try:
            # ─── REGISTRAR EXCLUSÃO NO LOG ANTES DE REMOVER ───
            dados_para_log = dict(item_data)  # Cópia dos dados antes da exclusão
            dados_para_log['id'] = self.selected_item_id
            tipo_registro = self._get_tipo_registro()
            # ─────────────────────────────────────────────────
            # Otimização: Exclusão individual no banco
            del_id = self.selected_item_id
            del self.data_dict[del_id]
            
            save_success = False
            if 'products' in self.filepath or 'produtos' in self.filepath:
                save_success = _mysql_delete_product(del_id)
            else:
                save_success = save_data(self.filepath, self.data_dict)

            if save_success:
                try:
                    log_exclusion(tipo_registro, dados_para_log)
                except Exception as e:
                    print(f"[AVISO] Falha ao registrar exclusão no log: {e}")
                self._clear_form()
                self._load_items_to_tree()
                messagebox.showinfo("Sucesso", "Item excluído com sucesso!", parent=self)
                if hasattr(self.parent_app, 'refresh_data_views'): self.parent_app.refresh_data_views()
            else:
                messagebox.showerror("Erro", "Falha ao salvar após excluir.", parent=self)
                self.data_dict = load_data(self.filepath, self.data_dict)
        except KeyError: messagebox.showerror("Erro", "Item não encontrado.", parent=self); self._load_items_to_tree()

    def _check_deletion_constraints(self, item_id_to_delete): return True

