class CadastroCategoriasWindow(BaseCadastroWindow):
    def __init__(self, parent, data_dict, filepath, app=None):
        fields = {'nome': {'label': 'Nome da Categoria', 'required': True}}
        tree_cols = ('id', 'nome')
        tree_headings = ('ID', 'Nome')
        super().__init__(parent, "Cadastro de Categorias", data_dict, filepath, fields, tree_cols, tree_headings, app=app)
        
        # Empacota o botão de exclusão (criado na BaseCadastroWindow)
        self.excluir_btn.pack(pady=2, fill=tk.X)
    
    def _get_unique_fields(self):
        """Define campos únicos para Categorias: nome deve ser único."""
        return [('nome', 'Nome da Categoria')]
    
    def _get_item_values_for_tree(self, item_data): return [item_data.get('nome', '')]
    def _check_deletion_constraints(self, cat_id):
        if str(cat_id) == "1": messagebox.showerror("Bloqueado", "Categoria 'Geral' não pode ser excluída.", parent=self); return False
        for prod_data in self.parent_app.products.values():
            if str(prod_data.get('category_id')) == str(cat_id):
                messagebox.showerror("Bloqueado", f"Categoria '{self.data_dict[cat_id]['nome']}' usada por '{prod_data['nome']}'.", parent=self); return False
        return True
    
    def _setup_ui(self):
        """Sobrescreve para adicionar botão de troca de categoria em lote."""
        super()._setup_ui()
        
        # Adiciona botão de troca de categoria em lote
        self.btn_trocar_categoria = ttk.Button(
            self.form_buttons_frame, 
            text="🔄 Trocar Categoria", 
            command=self._abrir_troca_categoria_lote,
            bootstyle="warning",
            width=15
        )
        self.btn_trocar_categoria.pack(pady=5, fill=tk.X)
    
    def _abrir_troca_categoria_lote(self):
        """Abre janela para trocar categoria de produtos em lote."""
        if not self.parent_app:
            messagebox.showerror("Erro", "Referência ao aplicativo principal não encontrada.", parent=self)
            return
        
        # Cria janela de troca
        troca_win = tk.Toplevel(self)
        troca_win.title("🔄 Trocar Categoria de Produtos em Lote")
        troca_win.state('zoomed')
        troca_win.resizable(True, True)
        troca_win.minsize(600, 600)
        troca_win.transient(self)
        troca_win.grab_set()
        
        # Frame principal
        main_frame = ttk.Frame(troca_win, padding=20)
        main_frame.pack(fill=tk.BOTH, expand=True)
        
        # Título
        ttk.Label(main_frame, text="Trocar Categoria de Produtos em Lote", 
                  font=("Segoe UI", 14, "bold")).pack(pady=(0, 15))
        
        # Descrição
        ttk.Label(main_frame, text="Selecione os produtos que deseja mover para outra categoria.",
                  wraplength=550, foreground="gray").pack(pady=(0, 5))
        
        # Prepara lista de categorias
        categorias_list = sorted([f"{cat_id} - {data['nome']}" for cat_id, data in self.data_dict.items()])
        
        # Frame de seleção de categorias
        select_frame = ttk.Frame(main_frame)
        select_frame.pack(fill=tk.X, pady=10)
        
        # Categoria de origem
        ttk.Label(select_frame, text="Categoria de ORIGEM:", font=("Segoe UI", 10, "bold")).grid(row=0, column=0, sticky="w", pady=5)
        origem_var = tk.StringVar()
        origem_combo = ttk.Combobox(select_frame, textvariable=origem_var, values=categorias_list, state="readonly", width=40)
        origem_combo.grid(row=0, column=1, padx=10, pady=5, sticky="ew")
        
        # Categoria de destino
        ttk.Label(select_frame, text="Categoria de DESTINO:", font=("Segoe UI", 10, "bold")).grid(row=1, column=0, sticky="w", pady=5)
        destino_var = tk.StringVar()
        destino_combo = ttk.Combobox(select_frame, textvariable=destino_var, values=categorias_list, state="readonly", width=40)
        destino_combo.grid(row=1, column=1, padx=10, pady=5, sticky="ew")
        
        select_frame.columnconfigure(1, weight=1)
        
        # Frame de seleção de produtos
        preview_frame = ttk.Labelframe(main_frame, text="Selecione os produtos para mover", padding=10)
        preview_frame.pack(fill=tk.BOTH, expand=True, pady=10)
        
        # Frame para botões de seleção
        sel_btn_frame = ttk.Frame(preview_frame)
        sel_btn_frame.pack(fill=tk.X, pady=(0, 5))
        
        # Variável para controlar seleção
        selecionar_todos_var = tk.BooleanVar(value=True)
        
        # Checkbox para selecionar todos
        chk_todos = ttk.Checkbutton(sel_btn_frame, text="Selecionar TODOS", 
                                     variable=selecionar_todos_var, bootstyle="primary-round-toggle")
        chk_todos.pack(side=tk.LEFT, padx=5)
        
        # Label de contagem
        lbl_contagem = ttk.Label(sel_btn_frame, text="", font=("Segoe UI", 9))
        lbl_contagem.pack(side=tk.RIGHT, padx=5)
        
        # Frame para lista com scroll
        list_frame = ttk.Frame(preview_frame)
        list_frame.pack(fill=tk.BOTH, expand=True)
        
        # Canvas e Scrollbar para checkboxes
        canvas = tk.Canvas(list_frame, highlightthickness=0)
        scrollbar = ttk.Scrollbar(list_frame, orient="vertical", command=canvas.yview)
        scrollable_frame = ttk.Frame(canvas)
        
        scrollable_frame.bind(
            "<Configure>",
            lambda e: canvas.configure(scrollregion=canvas.bbox("all"))
        )
        
        canvas.create_window((0, 0), window=scrollable_frame, anchor="nw")
        canvas.configure(yscrollcommand=scrollbar.set)
        
        canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        
        # Bind mousewheel
        def _on_mousewheel(event):
            canvas.yview_scroll(int(-1*(event.delta/120)), "units")
        canvas.bind_all("<MouseWheel>", _on_mousewheel)
        
        # Dicionário para armazenar checkboxes dos produtos
        produto_vars = {}
        produto_checkboxes = []
        
        # Função para atualizar lista de produtos
        def atualizar_lista_produtos(*args):
            nonlocal produto_vars, produto_checkboxes
            
            # Limpa checkboxes anteriores
            for widget in scrollable_frame.winfo_children():
                widget.destroy()
            produto_vars.clear()
            produto_checkboxes.clear()
            
            origem_sel = origem_var.get()
            if not origem_sel:
                lbl_contagem.config(text="")
                return
            
            origem_id = origem_sel.split(" - ")[0]
            count = 0
            
            for prod_id, prod_data in sorted(self.parent_app.products.items(), key=lambda x: x[1].get('nome', '')):
                if str(prod_data.get('category_id')) == str(origem_id):
                    var = tk.BooleanVar(value=selecionar_todos_var.get())
                    produto_vars[prod_id] = var
                    
                    chk = ttk.Checkbutton(
                        scrollable_frame, 
                        text=f"{prod_id} - {prod_data.get('nome', 'N/A')}",
                        variable=var,
                        bootstyle="primary"
                    )
                    chk.pack(anchor="w", pady=2, padx=5)
                    produto_checkboxes.append((prod_id, var, chk))
                    count += 1
            
            if count == 0:
                lbl_contagem.config(text="⚠️ Nenhum produto nesta categoria", foreground="orange")
                ttk.Label(scrollable_frame, text="Nenhum produto encontrado nesta categoria.", 
                          foreground="gray").pack(pady=20)
            else:
                lbl_contagem.config(text=f"✅ {count} produto(s) disponíveis", foreground="green")
            
            # Atualiza o canvas
            canvas.update_idletasks()
            canvas.configure(scrollregion=canvas.bbox("all"))
        
        # Função para selecionar/desselecionar todos
        def toggle_selecao_todos(*args):
            valor = selecionar_todos_var.get()
            for prod_id, var, chk in produto_checkboxes:
                var.set(valor)
        
        selecionar_todos_var.trace_add("write", toggle_selecao_todos)
        origem_var.trace_add("write", atualizar_lista_produtos)
        
        # Função de confirmação
        def confirmar_troca():
            origem_sel = origem_var.get()
            destino_sel = destino_var.get()
            
            if not origem_sel:
                messagebox.showerror("Erro", "Selecione a categoria de ORIGEM.", parent=troca_win)
                return
            
            if not destino_sel:
                messagebox.showerror("Erro", "Selecione a categoria de DESTINO.", parent=troca_win)
                return
            
            origem_id = origem_sel.split(" - ")[0]
            destino_id = destino_sel.split(" - ")[0]
            
            if origem_id == destino_id:
                messagebox.showerror("Erro", "As categorias de origem e destino devem ser diferentes.", parent=troca_win)
                return
            
            # Coleta produtos selecionados
            produtos_para_mover = []
            for prod_id, var, chk in produto_checkboxes:
                if var.get():
                    produtos_para_mover.append((prod_id, self.parent_app.products[prod_id].get('nome', 'N/A')))
            
            if not produtos_para_mover:
                messagebox.showwarning("Atenção", "Selecione pelo menos um produto para mover.", parent=troca_win)
                return
            
            # Confirmação
            origem_nome = self.data_dict.get(origem_id, {}).get('nome', origem_id)
            destino_nome = self.data_dict.get(destino_id, {}).get('nome', destino_id)
            
            msg = f"Confirma a troca de categoria de {len(produtos_para_mover)} produto(s)%s\n\n"
            msg += f"DE: {origem_nome}\n"
            msg += f"PARA: {destino_nome}\n\n"
            if len(produtos_para_mover) <= 5:
                msg += "Produtos:\n"
                for pid, pnome in produtos_para_mover:
                    msg += f"  • {pnome}\n"
            msg += "\nEsta ação não pode ser desfeita!"
            
            if not messagebox.askyesno("Confirmar Troca", msg, parent=troca_win):
                return
            
            # Executa a troca
            try:
                count = 0
                for prod_id, _ in produtos_para_mover:
                    self.parent_app.products[prod_id]['category_id'] = destino_id
                    if 'categoria_id' in self.parent_app.products[prod_id]:
                        self.parent_app.products[prod_id]['categoria_id'] = destino_id
                    count += 1
                
                if save_data(PRODUCTS_FILE, self.parent_app.products):
                    messagebox.showinfo("Sucesso", 
                        f"{count} produto(s) movido(s) com sucesso!\n\n"
                        f"De: {origem_nome}\n"
                        f"Para: {destino_nome}", 
                        parent=troca_win)
                    
                    log_user_action("Troca de Categoria em Lote", 
                        f"Movidos {count} produtos de '{origem_nome}' para '{destino_nome}'")
                    
                    if hasattr(self.parent_app, 'refresh_data_views'):
                        self.parent_app.refresh_data_views()
                    
                    troca_win.destroy()
                else:
                    messagebox.showerror("Erro", "Falha ao salvar as alterações.", parent=troca_win)
            except Exception as e:
                messagebox.showerror("Erro", f"Erro ao trocar categorias: {e}", parent=troca_win)
        
        # Botões - Frame separado para garantir visibilidade
        btn_frame = ttk.Frame(main_frame)
        btn_frame.pack(fill=tk.X, pady=(15, 10), side=tk.BOTTOM)
        
        ttk.Button(btn_frame, text="✅ Confirmar Troca", command=confirmar_troca, 
                   bootstyle="success", width=20).pack(side=tk.LEFT, padx=5)
        ttk.Button(btn_frame, text="❌ Cancelar", command=troca_win.destroy, 
                   bootstyle="danger", width=15).pack(side=tk.RIGHT, padx=5)
        
        # Força atualização do layout
        troca_win.update_idletasks()


# 👥 Módulo de Cadastro de Clientes
class CadastroClientesWindow(BaseCadastroWindow):
    def __init__(self, parent, data_dict, filepath, app=None):
        # Carrega os bairros cadastrados para o dropdown
        self.bairros_dict = _mysql_load_bairros()
        bairros_options = self._get_bairros_options()
        
        fields = {
            'nome': {'label': 'Nome do Cliente', 'required': True, 'width': 50},
            'cpf': {'label': 'CPF/CNPJ'},
            'telefone': {'label': 'Telefone'},
            'endereco': {'label': 'Endereço'},
            'bairro': {'label': 'Bairro', 'type': 'combo', 'options': bairros_options, 'width': 50},
            'observacao': {'label': 'Observação', 'type': 'text'}
        }
        tree_cols = ('id', 'nome', 'cpf', 'telefone', 'endereco', 'bairro')
        tree_headings = ('ID', 'Nome', 'CPF/CNPJ', 'Telefone', 'Endereço', 'Bairro')
        super().__init__(parent, "Cadastro de Clientes", data_dict, filepath, fields, tree_cols, tree_headings, app=app)
        
        # Configura o combobox de bairro para permitir digitação também
        if 'bairro' in self.entries:
            self.entries['bairro'].configure(state='normal')  # Permite digitação além da seleção
        
        # Empacota o botão de exclusão (criado na BaseCadastroWindow)
        self.excluir_btn.pack(pady=2, fill=tk.X)
    
    def _get_bairros_options(self):
        """Retorna lista de bairros formatados como 'Nome do Bairro - R$ XX,XX'."""
        options = ['']
        for bairro_id, bairro_data in self.bairros_dict.items():
            nome = bairro_data.get('nome', '')
            valor = bairro_data.get('valor_entrega', 0.0)
            try:
                valor_float = float(valor)
                valor_formatado = f"R$ {valor_float:,.2f}".replace(',', 'X').replace('.', ',').replace('X', '.')
            except:
                valor_formatado = "R$ 0,00"
            options.append(f"{nome} - {valor_formatado}")
        return options
    
    def _extract_bairro_name(self, bairro_value):
        """Extrai apenas o nome do bairro do valor formatado 'Nome - R$ XX,XX'."""
        if ' - R$' in bairro_value:
            return bairro_value.split(' - R$')[0].strip()
        return bairro_value.strip()
    
    def _get_unique_fields(self):
        """Define campos únicos para Clientes: CPF/CNPJ deve ser único (se preenchido)."""
        return [('cpf', 'CPF/CNPJ')]

    def _collect_form_data(self):
        """Sobrescreve para extrair apenas o nome do bairro do dropdown."""
        data = super()._collect_form_data()
        
        # Extrai apenas o nome do bairro do formato 'Nome - R$ XX,XX'
        bairro_value = data.get('bairro', '')
        if bairro_value:
            data['bairro'] = self._extract_bairro_name(bairro_value)
        
        return data
    
    def _fill_form(self, item_data):
        """Sobrescreve para preencher o combobox de bairro corretamente."""
        # Primeiro preenche todos os campos normalmente
        for field_name, widget in self.entries.items():
            var = self.vars.get(field_name)
            config = self.fields_config.get(field_name, {})
            field_type = config.get('type')
            value = item_data.get(field_name, config.get('default', ''))
            
            if field_name == 'bairro':
                # Para o campo bairro, busca o valor formatado correspondente
                bairro_nome = str(value).strip() if value else ''
                if bairro_nome:
                    # Procura o bairro no dicionário para obter o valor formatado
                    found = False
                    for bairro_id, bairro_data in self.bairros_dict.items():
                        if bairro_data.get('nome', '').strip().lower() == bairro_nome.lower():
                            valor = bairro_data.get('valor_entrega', 0.0)
                            try:
                                valor_float = float(valor)
                                valor_formatado = f"R$ {valor_float:,.2f}".replace(',', 'X').replace('.', ',').replace('X', '.')
                            except:
                                valor_formatado = "R$ 0,00"
                            var.set(f"{bairro_data.get('nome', '')} - {valor_formatado}")
                            found = True
                            break
                    if not found:
                        # Se não encontrou no cadastro, usa o valor direto
                        var.set(bairro_nome)
                else:
                    var.set('')
            elif isinstance(var, tk.Variable):
                if field_type == 'spin_float':
                    var.set(format_br_float(value, 2) if value else '0,00')
                elif field_type == 'check':
                    var.set(bool(value))
                else:
                    var.set(str(value) if value is not None else '')
            elif isinstance(widget, tk.Text):
                widget.delete('1.0', tk.END)
                widget.insert('1.0', str(value) if value else '')
            elif hasattr(widget, 'entry'):
                widget.entry.delete(0, tk.END)
                widget.entry.insert(0, str(value) if value else '')

    def _get_item_values_for_tree(self, item_data):
        # Retorna os valores na ordem de tree_cols (exceto 'id')
        return [
            item_data.get('nome', ''),
            item_data.get('cpf', ''),
            item_data.get('telefone', ''),
            item_data.get('endereco', ''),
            item_data.get('bairro', '')
        ]

    def _check_deletion_constraints(self, cust_id):
        if str(cust_id) == "1": messagebox.showerror("Bloqueado", "Cliente 'Consumidor Final' não pode ser excluído.", parent=self); return False
        # Verificar histórico de vendas seria ideal aqui
        return True

