        # Cria opções de Centro de Custos (apenas despesas para Contas a Pagar)
        centros_custo_despesas = get_centros_custo_despesas()
        centro_custo_options = sorted([f"{c['id']} - {c['codigo']} - {c['nome']}" for c in centros_custo_despesas])
        
