        # Atualiza a cor da linha na Treeview
        self.tree.tag_configure('pago', background='#d4edda') # Verde claro
        self.tree.tag_configure('atrasado', background='#f8d7da') # Vermelho claro
        self.tree.tag_configure('pendente', background='#fff3cd') # Amarelo claro
        
        # Frame para exibir os totais - posicionado dentro do main_frame usando grid
