def _quantum_label_to_float(value, default=0.0):
    try:
        if 'parse_br_float' in globals():
            parsed = parse_br_float(value)
            return default if parsed is None else float(parsed)
    except Exception:
        pass
    try:
        return float(str(value).replace(',', '.'))
    except Exception:
        return default

def _quantum_label_fmt_money(value):
    try:
        if 'format_br_currency' in globals():
            return format_br_currency(_quantum_label_to_float(value, 0.0))
    except Exception:
        pass
    try:
        return ("R$ %.2f" % _quantum_label_to_float(value, 0.0)).replace('.', ',')
    except Exception:
        return "R$ 0,00"

def _quantum_label_product_text(product_data, key):
    """Obtém texto seguro do produto para impressão em etiqueta."""
    try:
        data = product_data if isinstance(product_data, dict) else {}
        if key == 'estoque':
            return "Estoque: " + str(data.get('estoque', '0'))
        if key == 'lote_validade':
            lote = data.get('lote') or data.get('numero_lote') or data.get('lote_atual') or ''
            validade = data.get('validade') or data.get('data_validade') or data.get('validade_lote') or ''
            partes = []
            if lote:
                partes.append(f"Lote: {lote}")
            if validade:
                partes.append(f"Val: {validade}")
            return " | ".join(partes) if partes else ""
        if key == 'codigo_interno':
            return "Cód: " + str(data.get('codigo') or data.get('id') or '')
        if key == 'marca':
            return str(data.get('marca') or data.get('fabricante') or '')
        if key == 'localizacao':
            return str(data.get('localizacao') or data.get('prateleira') or data.get('corredor') or '')
        if key == 'empresa':
            return str(data.get('empresa') or data.get('nome_empresa') or 'Sua Empresa')
    except Exception:
        pass
    return ""

