def _quantum_label_status_text(self):
    try:
        p = getattr(self, 'product_data', {}) or {}
        nome = p.get('nome', 'Produto')
        preco = _quantum_label_fmt_money(p.get('preco', 0))
        cod = p.get('codigo_barras') or p.get('codigo') or p.get('id') or ''
        estoque = p.get('estoque', '')
        return f"Produto: {nome}\nPreço: {preco} | Código: {cod} | Estoque: {estoque}\nDica: use os layouts prontos ou marque informações extras conforme o tipo do produto."
    except Exception:
        return "Sistema avançado de etiquetas pronto."

def _quantum_label_set_quantity_from_stock(self):
    try:
        estoque = int(max(1, round(_quantum_label_to_float((self.product_data or {}).get('estoque', 1), 1))))
        estoque = min(9999, estoque)
        self.quantity_var.set(estoque)
        messagebox.showinfo("Quantidade pelo estoque", f"Quantidade definida como {estoque}.", parent=self)
    except Exception:
        messagebox.showwarning("Quantidade pelo estoque", "Não foi possível ler o estoque deste produto.", parent=self)

def _quantum_label_validate_barcode(self):
    try:
        p = getattr(self, 'product_data', {}) or {}
        valor, tipo = _label_effective_barcode_value_and_type(p.get('codigo_barras') or p.get('codigo') or p.get('id') or '', fallback=p.get('id') or '000000000001', barcode_type="EAN13")
        msg = f"Código efetivo: {valor}\nTipo usado: {tipo}\n"
        if str(tipo).upper() == 'EAN13':
            msg += "Status: compatível com EAN-13."
        else:
            msg += "Status: será impresso como CODE128 por conter formato incompatível com EAN-13."
        messagebox.showinfo("Validação do Código de Barras", msg, parent=self)
    except Exception as e:
        messagebox.showerror("Validação", f"Erro ao validar código: {e}", parent=self)

def _quantum_label_apply_layout(self, layout_key):
    try:
        if layout_key in LABEL_LAYOUTS:
            nome = LABEL_LAYOUTS[layout_key].get('nome', layout_key)
            self.layout_var.set(f"{layout_key} - {nome}")
            if layout_key == 'farmacia_validade':
                self.label_adv_lote_validade_var.set(True)
                self.label_adv_data_var.set(True)
            if layout_key == 'promocao_de_por':
                self.label_adv_preco_antigo_var.set(True)
            if layout_key == 'qrcode_produto':
                self.label_adv_qrcode_var.set(True)
            try:
                self.notebook.select(0)
            except Exception:
                pass
    except Exception:
        pass

def _quantum_label_add_text_element(config, texto, y, fonte=7, bold=False):
    try:
        if not texto:
            return
        config.setdefault('elementos', [])
        config['elementos'].append({
            'tipo': 'texto_fixo',
            'texto': str(texto)[:80],
            'x': 50,
            'y': float(y),
            'largura': 96,
            'altura': 8,
            'fonte': int(fonte),
            'alinhamento': 'centro',
            'negrito': bool(bold),
        })
    except Exception:
        pass

def _quantum_label_apply_advanced_to_config(self, config):
    """Aplica opções avançadas no layout_config sem alterar o cadastro do produto."""
    try:
        if not isinstance(config, dict):
            return config
        p = getattr(self, 'product_data', {}) or {}

        config['fonte_nome'] = int(getattr(self, 'label_adv_nome_fonte_var', tk.IntVar(value=config.get('fonte_nome', 9))).get())
        config['fonte_preco'] = int(getattr(self, 'label_adv_preco_fonte_var', tk.IntVar(value=config.get('fonte_preco', 16))).get())
        config['altura_codigo'] = int(getattr(self, 'label_adv_barra_altura_var', tk.IntVar(value=config.get('altura_codigo', 12))).get())
        config['margem_mm'] = int(getattr(self, 'label_adv_margem_var', tk.IntVar(value=2)).get())
        config['modo_rapido'] = bool(getattr(self, 'label_adv_modo_rapido_var', tk.BooleanVar(value=True)).get())

        # Garante que há lista própria de elementos para não modificar o catálogo global.
        if 'elementos' not in config:
            layout_key = config.get('layout', 'padrao')
            try:
                config['elementos'] = [dict(e) for e in LABEL_LAYOUTS.get(layout_key, LABEL_LAYOUTS['padrao']).get('elementos', [])]
            except Exception:
                config['elementos'] = []

        if bool(getattr(self, 'label_adv_categoria_var', tk.BooleanVar(value=False)).get()):
            config['elementos'].append({'tipo': 'categoria', 'x': 50, 'y': 78, 'largura': 96, 'altura': 8, 'fonte': 7, 'alinhamento': 'centro', 'negrito': False})
        if bool(getattr(self, 'label_adv_codigo_var', tk.BooleanVar(value=False)).get()):
            config['elementos'].append({'tipo': 'codigo', 'x': 50, 'y': 10, 'largura': 96, 'altura': 8, 'fonte': 7, 'alinhamento': 'centro', 'negrito': False})
        if bool(getattr(self, 'label_adv_data_var', tk.BooleanVar(value=False)).get()):
            config['elementos'].append({'tipo': 'data', 'x': 50, 'y': 5, 'largura': 96, 'altura': 7, 'fonte': 6, 'alinhamento': 'centro', 'negrito': False})
        if bool(getattr(self, 'label_adv_preco_antigo_var', tk.BooleanVar(value=False)).get()):
            config['elementos'].append({'tipo': 'preco_antigo', 'x': 50, 'y': 66, 'largura': 96, 'altura': 8, 'fonte': 8, 'alinhamento': 'centro', 'negrito': False, 'riscado': True})
        if bool(getattr(self, 'label_adv_qrcode_var', tk.BooleanVar(value=False)).get()):
            config['elementos'].append({'tipo': 'qrcode', 'x': 88, 'y': 22, 'largura': 20, 'altura': 26})
        if bool(getattr(self, 'label_adv_lote_validade_var', tk.BooleanVar(value=False)).get()):
            _quantum_label_add_text_element(config, _quantum_label_product_text(p, 'lote_validade'), 14, fonte=6, bold=False)
        if bool(getattr(self, 'label_adv_estoque_var', tk.BooleanVar(value=False)).get()):
            _quantum_label_add_text_element(config, _quantum_label_product_text(p, 'estoque'), 18, fonte=6, bold=False)
        if bool(getattr(self, 'label_adv_empresa_var', tk.BooleanVar(value=False)).get()):
            _quantum_label_add_text_element(config, _quantum_label_product_text(p, 'empresa'), 96, fonte=6, bold=True)
        if bool(getattr(self, 'label_adv_borda_var', tk.BooleanVar(value=False)).get()):
            config['elementos'].append({'tipo': 'retangulo', 'x': 50, 'y': 50, 'largura': 98, 'altura': 96, 'fonte': 6})
        if bool(getattr(self, 'label_adv_linha_var', tk.BooleanVar(value=False)).get()):
            config['elementos'].append({'tipo': 'linha', 'x': 50, 'y': 75, 'largura': 92, 'altura': 1, 'fonte': 5})
    except Exception as e:
        try:
            print("[ETIQUETAS] Erro ao aplicar opções avançadas:", e)
        except Exception:
            pass
    return config

try:
    if "LabelPrintConfigWindow" in globals() and not getattr(LabelPrintConfigWindow, "_quantum_label_senior_patch", False):
        _orig_label_create_interface = LabelPrintConfigWindow._create_interface
        _orig_label_save_config = LabelPrintConfigWindow._save_config
        _orig_label_get_layout_config = LabelPrintConfigWindow._get_layout_config
        _orig_label_preview_pdf = LabelPrintConfigWindow._preview_pdf

        def _patched_label_create_interface(self):
            _orig_label_create_interface(self)
            try:
                _quantum_label_create_advanced_tab(self)
            except Exception as e:
                try:
                    print("[ETIQUETAS] Aba avançada não criada:", e)
                except Exception:
                    pass

        def _patched_label_save_config(self):
            _orig_label_save_config(self)
            try:
                config_file = get_label_config_file()
                data = {}
                if os.path.exists(config_file):
                    with open(config_file, 'r', encoding='utf-8') as f:
                        data = json.load(f)
                data.update({
                    'adv_categoria': bool(getattr(self, 'label_adv_categoria_var', tk.BooleanVar(value=False)).get()),
                    'adv_codigo_interno': bool(getattr(self, 'label_adv_codigo_var', tk.BooleanVar(value=False)).get()),
                    'adv_data': bool(getattr(self, 'label_adv_data_var', tk.BooleanVar(value=False)).get()),
                    'adv_preco_antigo': bool(getattr(self, 'label_adv_preco_antigo_var', tk.BooleanVar(value=False)).get()),
                    'adv_qrcode': bool(getattr(self, 'label_adv_qrcode_var', tk.BooleanVar(value=False)).get()),
                    'adv_lote_validade': bool(getattr(self, 'label_adv_lote_validade_var', tk.BooleanVar(value=False)).get()),
                    'adv_estoque': bool(getattr(self, 'label_adv_estoque_var', tk.BooleanVar(value=False)).get()),
                    'adv_empresa': bool(getattr(self, 'label_adv_empresa_var', tk.BooleanVar(value=False)).get()),
                    'adv_borda': bool(getattr(self, 'label_adv_borda_var', tk.BooleanVar(value=False)).get()),
                    'adv_linha': bool(getattr(self, 'label_adv_linha_var', tk.BooleanVar(value=False)).get()),
                    'adv_auto_preview': bool(getattr(self, 'label_adv_auto_preview_var', tk.BooleanVar(value=False)).get()),
                    'adv_modo_rapido': bool(getattr(self, 'label_adv_modo_rapido_var', tk.BooleanVar(value=True)).get()),
                    'adv_nome_fonte': int(getattr(self, 'label_adv_nome_fonte_var', tk.IntVar(value=9)).get()),
                    'adv_preco_fonte': int(getattr(self, 'label_adv_preco_fonte_var', tk.IntVar(value=16)).get()),
                    'adv_barra_altura': int(getattr(self, 'label_adv_barra_altura_var', tk.IntVar(value=12)).get()),
                    'adv_margem_mm': int(getattr(self, 'label_adv_margem_var', tk.IntVar(value=2)).get()),
                })
                with open(config_file, 'w', encoding='utf-8') as f:
                    json.dump(data, f, indent=2, ensure_ascii=False)
            except Exception:
                pass

        def _patched_label_get_layout_config(self):
            config = _orig_label_get_layout_config(self)
            return _quantum_label_apply_advanced_to_config(self, config)

        def _patched_label_preview_pdf(self):
            try:
                self._save_config()
            except Exception:
                pass
            return _orig_label_preview_pdf(self)

        def _patched_label_on_print(self):
            try:
                if bool(getattr(self, 'label_adv_auto_preview_var', tk.BooleanVar(value=False)).get()):
                    self._preview_pdf()
            except Exception:
                pass
            return LabelPrintConfigWindow._quantum_orig_on_print(self)

        LabelPrintConfigWindow._create_interface = _patched_label_create_interface
        LabelPrintConfigWindow._save_config = _patched_label_save_config
        LabelPrintConfigWindow._get_layout_config = _patched_label_get_layout_config
        LabelPrintConfigWindow._preview_pdf = _patched_label_preview_pdf
        LabelPrintConfigWindow._quantum_orig_on_print = LabelPrintConfigWindow._on_print
        LabelPrintConfigWindow._on_print = _patched_label_on_print
        LabelPrintConfigWindow._quantum_label_senior_patch = True
        try:
            print("[ETIQUETAS] Sistema Avançado de Etiquetas v4.0 Senior aplicado.")
        except Exception:
            pass
except Exception as _e:
    try:
        print("[ETIQUETAS] Patch Senior não aplicado:", _e)
    except Exception:
        pass






