def _qlabel_safe_float(v, default=0.0):
    try:
        if 'parse_br_float' in globals():
            x = parse_br_float(v)
            return default if x is None else float(x)
    except Exception:
        pass
    try:
        return float(str(v).replace(',', '.'))
    except Exception:
        return default

def _qlabel_sanitize_text(text, max_len=120):
    try:
        text = str(text or '').replace('\r', ' ').replace('\n', ' ').strip()
        text = re.sub(r'\s+', ' ', text)
        return text[:max_len]
    except Exception:
        return ''

def _qlabel_money(v):
    try:
        if 'format_br_currency' in globals():
            return format_br_currency(_qlabel_safe_float(v, 0.0))
    except Exception:
        pass
    return ("R$ %.2f" % _qlabel_safe_float(v, 0.0)).replace('.', ',')

# Perfis técnicos por linguagem. A intenção é reduzir erro de escala em impressoras
# térmicas reais: DPI, largura útil, linguagem e densidade.
QUANTUM_LABEL_LANGUAGE_PROFILES = {
    'ZPL': {'nome': 'Zebra ZPL II', 'dpi_padrao': 203, 'comandos': ['^XA', '^PW', '^LL', '^FO', '^A0', '^BC', '^BQN', '^XZ']},
    'EPL': {'nome': 'Eltron EPL2', 'dpi_padrao': 203, 'comandos': ['N', 'q', 'Q', 'A', 'B', 'P']},
    'TSPL': {'nome': 'TSC/Elgin/Argox TSPL', 'dpi_padrao': 203, 'comandos': ['SIZE', 'GAP', 'DENSITY', 'CLS', 'TEXT', 'BARCODE', 'QRCODE', 'PRINT']},
    'CPCL': {'nome': 'Zebra Mobile CPCL', 'dpi_padrao': 203, 'comandos': ['! 0', 'PAGE-WIDTH', 'TEXT', 'BARCODE', 'FORM', 'PRINT']},
    'ESC/POS': {'nome': 'Térmica ESC/POS', 'dpi_padrao': 203, 'comandos': ['ESC @', 'GS k', 'GS ( k']},
    'PDF': {'nome': 'Driver Windows/PDF', 'dpi_padrao': 203, 'comandos': ['ReportLab PDF']},
}

def _qlabel_add_printer(name, marca, modelo, linguagem='ZPL', resolucao=203, largura_max=104, conexoes=None, velocidade='100mm/s', tipo='Térmica Direta'):
    try:
        if conexoes is None:
            conexoes = ['USB']
        LABEL_PRINTERS_CATALOG[name] = {
            'marca': marca,
            'modelo': modelo,
            'tipo': tipo,
            'resolucao': int(resolucao),
            'largura_max': int(largura_max),
            'velocidade': velocidade,
            'conexoes': conexoes,
            'linguagem': linguagem,
            'perfil_oficial': True,
            'engine': 'Quantum Label Engine Ultra v5'
        }
    except Exception:
        pass

