            ('ARGOX iX4-200', 'Argox', 'iX4-200', 'PPLB/TSPL', 203, 108, ['USB','Ethernet','Serial'], '203mm/s'),
            ('ARGOX iX4-250', 'Argox', 'iX4-250', 'PPLB/TSPL', 203, 108, ['USB','Ethernet','Serial'], '203mm/s'),
            ('ARGOX CP-2140EX', 'Argox', 'CP-2140EX', 'PPLB/TSPL', 203, 104, ['USB'], '152mm/s'),
