def _qlabel_v6_safe_text(v, max_len=120):
    try:
        v = str(v if v is not None else '').replace('\r', ' ').replace('\n', ' ').strip()
        v = re.sub(r'\s+', ' ', v)
        return v[:max_len]
    except Exception:
        return ''

def _qlabel_v6_money(v):
    try:
        if 'format_br_currency' in globals():
            return format_br_currency(parse_br_float(v) if 'parse_br_float' in globals() else float(v))
    except Exception:
        pass
    try:
        return ("R$ %.2f" % float(str(v).replace(',', '.'))).replace('.', ',')
    except Exception:
        return "R$ 0,00"

def _qlabel_v6_barcode_value(product_data):
    try:
        p = product_data or {}
        val, kind = _label_effective_barcode_value_and_type(p.get("codigo_barras") or p.get("codigo") or p.get("id") or "", fallback=p.get("id") or p.get("codigo") or "000000000001", barcode_type="EAN13")
        return val
    except Exception:
        try:
            return str((product_data or {}).get('codigo_barras') or (product_data or {}).get('codigo') or (product_data or {}).get('id') or '')
        except Exception:
            return ''

def _qlabel_v6_component_value(product_data, tipo, texto=''):
    p = product_data if isinstance(product_data, dict) else {}
    tipo = str(tipo or '')
    if tipo == 'nome':
        try:
            nome_base = str(p.get("nome", "Produto"))
            tamanho_id = p.get("tamanho_id")
            tamanhos_dict = _mysql_load_tamanhos() if '_mysql_load_tamanhos' in globals() else None
            return get_nome_produto_com_tamanho(nome_base, tamanho_id, tamanhos_dict) if 'get_nome_produto_com_tamanho' in globals() else nome_base
        except Exception:
            return str(p.get("nome", "Produto"))
    if tipo == 'preco':
        return _qlabel_v6_money(p.get('preco', 0))
    if tipo == 'preco_antigo':
        return "De: " + _qlabel_v6_money(p.get('preco_antigo', p.get('preco_custo', 0)))
    if tipo == 'codigo_barras_texto':
        return _qlabel_v6_barcode_value(p)
    if tipo == 'categoria':
        return str(p.get('categoria') or p.get('category_id') or '')
    if tipo == 'codigo':
        return "Cód: " + str(p.get('codigo') or p.get('id') or '')
    if tipo == 'tamanho':
        return "Tam: " + str(p.get('tamanho') or p.get('tamanho_nome') or p.get('tamanho_id') or '')
    if tipo == 'unidade':
        return "Unid: " + str(p.get('tipo') or p.get('unidade') or p.get('unidade_medida') or '')
    if tipo == 'estoque':
        return "Estoque: " + str(p.get('estoque') or '0')
    if tipo == 'marca':
        return str(p.get('marca') or p.get('fabricante') or '')
    if tipo == 'descricao':
        return str(p.get('descricao') or '')
    if tipo == 'validade':
        return "Val: " + str(p.get('validade') or p.get('data_validade') or '')
    if tipo == 'lote':
        return "Lote: " + str(p.get('lote') or p.get('numero_lote') or '')
    if tipo == 'lote_validade':
        lote = str(p.get('lote') or p.get('numero_lote') or '')
        val = str(p.get('validade') or p.get('data_validade') or '')
        return ("Lote: " + lote + (" | " if lote and val else "") + ("Val: " + val if val else "")).strip()
    if tipo == 'empresa':
        return str(p.get('empresa') or p.get('nome_empresa') or 'Sua Empresa')
    if tipo == 'data':
        try:
            return datetime.datetime.now().strftime("%d/%m/%Y")
        except Exception:
            return ''
    if tipo == 'hora':
        try:
            return datetime.datetime.now().strftime("%H:%M")
        except Exception:
            return ''
    if tipo == 'texto_fixo':
        return str(texto or 'TEXTO LIVRE')
    if tipo == 'qrcode':
        return _qlabel_v6_barcode_value(p) or str(p.get('id') or '')
    return str(texto or tipo)

def _qlabel_v6_get_canvas_frame(self):
    try:
        return getattr(self, 'designer_canvas', None)
    except Exception:
        return None

