        ('preco_antigo', 'Preço Antigo'),
        ('codigo_barras', 'CÓD. BARRAS - IMAGEM'),
        ('codigo_barras_texto', 'CÓD. BARRAS - NÚMERO'),
        ('qrcode', 'QR Code'),
