        ('tamanho', 'Tamanho'),
        ('unidade', 'Unidade'),
        ('estoque', 'Estoque'),
        ('lote', 'Lote'),
        ('validade', 'Validade'),
        ('lote_validade', 'Lote + Validade'),
        ('marca', 'Marca/Fabricante'),
        ('descricao', 'Descrição'),
        ('empresa', 'Empresa'),
        ('data', 'Data'),
        ('hora', 'Hora'),
        ('texto_fixo', 'Texto Livre'),
        ('linha', 'Linha'),
