def _qlabel_v6_create_layout_editor_tab(self):
    """Editor Visual/Delphi Ultra v6."""
    tab = ttk.Frame(self.notebook, padding=6)
    self.notebook.add(tab, text="Editor Visual/Delphi")

    self.designer_elements = []
    self.designer_selected_id = None
    self._designer_drag = {'item': None, 'start_x': 0, 'start_y': 0, 'orig': None}
    self._designer_resize = {'item': None, 'handle': None, 'start_x': 0, 'start_y': 0, 'orig': None}
    self._designer_canvas_items = {}
    self._designer_handles = []
    self._designer_clipboard = None
    self._designer_history = []
    self._designer_history_index = -1

    topbar = ttk.Frame(tab)
    topbar.pack(fill=tk.X, pady=(0, 4))
    ttk.Label(topbar, text="Editor Visual/Delphi Ultra v6", font=("Segoe UI", 11, "bold")).pack(side=tk.LEFT)
    ttk.Label(topbar, text="  Componentes separados: preço, valor, código imagem e código número independentes.", font=("Segoe UI", 8), foreground="gray").pack(side=tk.LEFT)

    for label, cmd, style in [
        ("🖨️ Imprimir", self._on_print, "success"),
        ("Preview Formulário", lambda: (self._editor_toolbar_apply_profile(False), self._preview_formulario()), "primary"),
        ("Preview PDF", self._preview_pdf, "info-outline"),
        ("Salvar", self._designer_save_template, "success-outline"),
        ("Carregar", self._designer_load_template, "secondary-outline"),
        ("Layout Base", self._designer_load_selected_layout, "primary-outline"),
        ("Desfazer", self._designer_undo, "warning"),
        ("Excluir Componente", self._designer_delete_selected, "danger"),
        ("Limpar Tudo", self._designer_clear, "danger-outline"),
    ]:
        ttk.Button(topbar, text=label, command=cmd, bootstyle=style).pack(side=tk.RIGHT, padx=2)

    body = ttk.PanedWindow(tab, orient=tk.HORIZONTAL)
    body.pack(fill=tk.BOTH, expand=True)

    # Toolbox com scroll
    toolbox_outer = tk.LabelFrame(body, text="Componentes", padx=4, pady=4)
    body.add(toolbox_outer, weight=0)
    tcanvas = tk.Canvas(toolbox_outer, width=185, highlightthickness=0)
    tscroll = ttk.Scrollbar(toolbox_outer, orient=tk.VERTICAL, command=tcanvas.yview)
    toolbox = ttk.Frame(tcanvas)
    toolbox.bind("<Configure>", lambda e: tcanvas.configure(scrollregion=tcanvas.bbox("all")))
    tcanvas.create_window((0,0), window=toolbox, anchor="nw")
    tcanvas.configure(yscrollcommand=tscroll.set)
    tcanvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
    tscroll.pack(side=tk.RIGHT, fill=tk.Y)

    ttk.Label(toolbox, text="Adicionar", font=("Segoe UI", 9, "bold")).pack(anchor='w', pady=(0,4))
    for tipo, nome in _qlabel_v6_component_catalog():
        style = "primary-outline" if tipo in ('codigo_barras', 'codigo_barras_texto', 'preco') else None
        ttk.Button(toolbox, text=nome, width=24, command=lambda t=tipo: self._designer_add_element(t), bootstyle=style).pack(fill=tk.X, pady=1)

    ttk.Separator(toolbox).pack(fill=tk.X, pady=8)
    ttk.Label(toolbox, text="Ações", font=("Segoe UI", 9, "bold")).pack(anchor='w', pady=(0,4))
    for label, cmd in [
        ("Duplicar", self._designer_duplicate_selected),
        ("Copiar", self._designer_copy_selected),
        ("Colar", self._designer_paste_clipboard),
        ("Excluir Componente", self._designer_delete_selected),
        ("Desfazer", self._designer_undo),
        ("Frente", lambda: self._designer_zorder('front')),
        ("Trás", lambda: self._designer_zorder('back')),
        ("Alinhar Centro H", lambda: self._designer_align('hcenter')),
        ("Alinhar Centro V", lambda: self._designer_align('vcenter')),
        ("Distribuir Vertical", lambda: self._designer_distribute('vertical')),
        ("Distribuir Horizontal", lambda: self._designer_distribute('horizontal')),
        ("Grade 10%", lambda: self._designer_snap_all(10)),
        ("Grade 5%", lambda: self._designer_snap_all(5)),
    ]:
        ttk.Button(toolbox, text=label, width=24, command=cmd).pack(fill=tk.X, pady=1)

    # Área central
    center = ttk.Frame(body)
    body.add(center, weight=1)
    center.rowconfigure(1, weight=1)
    center.columnconfigure(0, weight=1)
    canvas_bar = ttk.Frame(center)
    canvas_bar.grid(row=0, column=0, sticky='ew', pady=(0, 3))
    ttk.Label(canvas_bar, text="Zoom:").pack(side=tk.LEFT)
    self.designer_zoom_var = tk.IntVar(value=8)
    ttk.Scale(canvas_bar, from_=4, to=18, orient=tk.HORIZONTAL, length=130, variable=self.designer_zoom_var, command=lambda e=None: self._designer_redraw()).pack(side=tk.LEFT, padx=5)

    # Controles colocados exatamente na faixa superior do editor visual.
    # Impressora + Modelo/Tamanho + Quantidade ficam visíveis sem precisar abrir o preview.
    try:
        ttk.Separator(canvas_bar, orient=tk.VERTICAL).pack(side=tk.LEFT, fill=tk.Y, padx=4)
    except Exception:
        pass

    ttk.Label(canvas_bar, text="Imp:").pack(side=tk.LEFT, padx=(2, 2))
    self.editor_toolbar_printer_var = tk.StringVar(value=_qlabel_preview_current_printer_display(self) if '_qlabel_preview_current_printer_display' in globals() else str(self.printer_var.get()))
    self.editor_toolbar_printer_cb = ttk.Combobox(
        canvas_bar,
        textvariable=self.editor_toolbar_printer_var,
        values=_qlabel_preview_printer_options() if '_qlabel_preview_printer_options' in globals() else [],
        state="readonly",
        width=22
    )
    self.editor_toolbar_printer_cb.pack(side=tk.LEFT, padx=(0, 4))

    ttk.Label(canvas_bar, text="Etiqueta:").pack(side=tk.LEFT, padx=(2, 2))
    self.editor_toolbar_label_var = tk.StringVar(value=_qlabel_preview_current_label_display(self) if '_qlabel_preview_current_label_display' in globals() else str(self.etiqueta_var.get()))
    self.editor_toolbar_label_cb = ttk.Combobox(
        canvas_bar,
        textvariable=self.editor_toolbar_label_var,
        values=_qlabel_preview_label_options() if '_qlabel_preview_label_options' in globals() else [],
        state="readonly",
        width=22
    )
    self.editor_toolbar_label_cb.pack(side=tk.LEFT, padx=(0, 4))

    ttk.Label(canvas_bar, text="Qtd:").pack(side=tk.LEFT, padx=(2, 2))
    self.editor_toolbar_qty_var = tk.IntVar(value=max(1, int(self.quantity_var.get() or 1)))
    self.editor_toolbar_qty_spin = ttk.Spinbox(canvas_bar, from_=1, to=9999, textvariable=self.editor_toolbar_qty_var, width=5)
    self.editor_toolbar_qty_spin.pack(side=tk.LEFT, padx=(0, 4))

    ttk.Button(canvas_bar, text="Aplicar Perfil", command=lambda: self._editor_toolbar_apply_profile(True), bootstyle="success-outline").pack(side=tk.LEFT, padx=(0, 5))

    try:
        self.editor_toolbar_printer_cb.bind("<<ComboboxSelected>>", lambda e: self._editor_toolbar_apply_profile(True))
        self.editor_toolbar_label_cb.bind("<<ComboboxSelected>>", lambda e: self._editor_toolbar_apply_profile(True))
        self.editor_toolbar_qty_var.trace_add("write", lambda *a: self._editor_toolbar_apply_profile(False))
    except Exception:
        pass

    self.designer_grid_var = tk.BooleanVar(value=True)
    self.designer_snap_var = tk.BooleanVar(value=True)
    ttk.Checkbutton(canvas_bar, text="Grade", variable=self.designer_grid_var, command=self._designer_redraw).pack(side=tk.LEFT, padx=3)
    ttk.Checkbutton(canvas_bar, text="Snap", variable=self.designer_snap_var).pack(side=tk.LEFT, padx=3)
    ttk.Button(canvas_bar, text="Ajustar", command=self._designer_fit_canvas).pack(side=tk.LEFT, padx=3)
    ttk.Button(canvas_bar, text="Desfazer", command=self._designer_undo).pack(side=tk.LEFT, padx=3)
    ttk.Button(canvas_bar, text="Refazer", command=self._designer_redo).pack(side=tk.LEFT, padx=3)

    canvas_wrap = tk.Frame(center, bg="#cbd5e1", bd=1, relief=tk.SUNKEN)
    canvas_wrap.grid(row=1, column=0, sticky="nsew")
    self.designer_canvas = tk.Canvas(canvas_wrap, bg="#e5e7eb", highlightthickness=0, cursor="crosshair")
    self.designer_canvas.pack(fill=tk.BOTH, expand=True)
    self.designer_canvas.bind("<Button-1>", self._designer_canvas_click)
    self.designer_canvas.bind("<B1-Motion>", self._designer_canvas_drag)
    self.designer_canvas.bind("<ButtonRelease-1>", self._designer_canvas_release)
    self.designer_canvas.bind("<Button-3>", self._designer_context_menu)
    self.designer_canvas.bind("<Configure>", lambda e: self._designer_redraw())
    self.designer_canvas.focus_set()

    status = ttk.Frame(center)
    status.grid(row=2, column=0, sticky='ew', pady=(3,0))
    self.designer_status_var = tk.StringVar(value="Pronto. Use Ctrl+C/Ctrl+V, Del, setas, Shift+setas, Ctrl+Z/Ctrl+Y.")
    ttk.Label(status, textvariable=self.designer_status_var, foreground="gray").pack(side=tk.LEFT)

    # Propriedades com scroll
    prop_outer = tk.LabelFrame(body, text="Propriedades", padx=4, pady=4)
    body.add(prop_outer, weight=0)
    pc = tk.Canvas(prop_outer, width=260, highlightthickness=0)
    ps = ttk.Scrollbar(prop_outer, orient=tk.VERTICAL, command=pc.yview)
    prop = ttk.Frame(pc)
    prop.bind("<Configure>", lambda e: pc.configure(scrollregion=pc.bbox("all")))
    pc.create_window((0,0), window=prop, anchor="nw")
    pc.configure(yscrollcommand=ps.set)
    pc.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
    ps.pack(side=tk.RIGHT, fill=tk.Y)

    self.prop_tipo_var = tk.StringVar(value="Nenhum")
    self.prop_texto_var = tk.StringVar()
    self.prop_x_var = tk.DoubleVar(value=50)
    self.prop_y_var = tk.DoubleVar(value=50)
    self.prop_w_var = tk.DoubleVar(value=70)
    self.prop_h_var = tk.DoubleVar(value=15)
    self.prop_font_var = tk.IntVar(value=10)
