# ═══════════════════════════════════════════════════════════════════════════════
# 👁️ PATCH - PREVIEW FORMULÁRIO FIEL AO PDF
# Corrige diferença de posição: PDF usa origem embaixo; Canvas usa origem em cima.
# Agora o preview em formulário inverte o eixo Y para bater com o PDF.
# ═══════════════════════════════════════════════════════════════════════════════

def _qlabel_draw_form_preview_element_fiel_pdf(self, canvas, elem, ox, oy, cw, ch):
    """Desenha componente no preview em formulário seguindo a mesma lógica visual do PDF."""
    try:
        tipo = elem.get('tipo', '')
        x = ox + (float(elem.get('x', 50)) / 100.0) * cw

        # Correção principal:
        # ReportLab/PDF trabalha com origem no rodapé.
        # Tkinter Canvas trabalha com origem no topo.
        # Por isso o eixo Y precisa ser invertido para o formulário ficar igual ao PDF.
        y = oy + ch - (float(elem.get('y', 50)) / 100.0) * ch

        w = (float(elem.get('largura', 50)) / 100.0) * cw
        h = (float(elem.get('altura', 15)) / 100.0) * ch
        fonte = max(5, int(float(elem.get('fonte', 9)) * 1.15))
        color = elem.get('cor', '#111827') or '#111827'
        bold = 'bold' if elem.get('negrito') else 'normal'
        rotation = int(elem.get('rotacao', 0) or 0)
        valor = _qlabel_preview_value_for_form(self, elem)

        if tipo == 'linha':
            canvas.create_line(x - w/2, y, x + w/2, y, fill=color, width=max(1, fonte // 4))
            return

        if tipo == 'retangulo':
            canvas.create_rectangle(x - w/2, y - h/2, x + w/2, y + h/2, outline=color, width=2)
            return

        if tipo == 'elipse':
            canvas.create_oval(x - w/2, y - h/2, x + w/2, y + h/2, outline=color, width=2)
            return

        if tipo == 'codigo_barras':
            # Imagem do código separada do número, igual à regra do PDF/editor.
            canvas.create_rectangle(x - w/2, y - h/2, x + w/2, y + h/2, fill="#ffffff", outline="#334155")
            left = x - w/2 + 5
            right = x + w/2 - 5
            top = y - h/2 + 5
            bottom = y + h/2 - 5
            for i in range(32):
                bx = left + i * (right - left) / 32
                bw = max(1, (i % 5) + 1)
                if i % 6 != 0:
                    canvas.create_rectangle(bx, top, bx + bw, bottom, fill="#111827", outline="")
            return

        if tipo == 'codigo_barras_texto':
            canvas.create_text(x, y, text=str(valor)[:48], fill=color, font=("Segoe UI", fonte, bold), angle=rotation)
            return

        if tipo == 'qrcode':
            canvas.create_rectangle(x - w/2, y - h/2, x + w/2, y + h/2, fill="#ffffff", outline="#334155")
            cell = min(w, h) / 9
            for ix in range(9):
                for iy in range(9):
                    if (ix * iy + ix + iy) % 3 == 0 or (ix in (0, 1, 7, 8) and iy in (0, 1, 7, 8)):
                        canvas.create_rectangle(
                            x - w/2 + ix*cell,
                            y - h/2 + iy*cell,
                            x - w/2 + (ix+1)*cell,
                            y - h/2 + (iy+1)*cell,
                            fill="#111827",
                            outline=""
                        )
            return

        canvas.create_text(
            x, y,
            text=str(valor)[:90],
            fill=color,
            width=max(20, int(w)),
            font=("Segoe UI", fonte, bold),
            angle=rotation
        )
        if elem.get('riscado'):
            canvas.create_line(x - w/2 + 3, y, x + w/2 - 3, y, fill="#b91c1c", width=2)
    except Exception as e:
        try:
            canvas.create_text(ox + 10, oy + 10, text=f"Erro: {e}", anchor="nw", fill="red")
        except Exception:
            pass

# Substitui o desenhador do preview formulário pelo fiel ao PDF.
try:
    _qlabel_draw_form_preview_element = _qlabel_draw_form_preview_element_fiel_pdf
    print("[ETIQUETAS] Preview formulário alinhado ao PDF aplicado.")
except Exception:
    pass






# ═══════════════════════════════════════════════════════════════════════════════
# 🖨️ PATCH - PREVIEW FORMULÁRIO COM IMPRESSORA, MODELO E QUANTIDADE
# Adiciona dropdown de impressora, modelo/tamanho de etiqueta e quantidade.
# Ao trocar a impressora/modelo, aplica perfil técnico, medidas e evita corte.
# ═══════════════════════════════════════════════════════════════════════════════

def _qlabel_preview_option_key(text):
    try:
        text = str(text or '')
        return text.split(' - ', 1)[0].strip()
    except Exception:
        return str(text or '')

def _qlabel_preview_label_options():
    opts = []
    try:
        for key, cfg in sorted(LABEL_TEMPLATES_CATALOG.items(), key=lambda x: str(x[0])):
            nome = cfg.get('nome', key) if isinstance(cfg, dict) else key
            largura = cfg.get('largura', '') if isinstance(cfg, dict) else ''
            altura = cfg.get('altura', '') if isinstance(cfg, dict) else ''
            opts.append(f"{key} - {nome} ({largura}x{altura}mm)")
    except Exception:
        pass
    if 'PERSONALIZADA' not in [o.split(' - ', 1)[0] for o in opts]:
        opts.append('PERSONALIZADA - Tamanho personalizado')
    return opts

def _qlabel_preview_printer_options():
    opts = []
    try:
        if 'LABEL_CONFIGURED_PRINTER_OPTION' in globals():
            opts.append(LABEL_CONFIGURED_PRINTER_OPTION)
        if 'LABEL_OWN_PRINTER_OPTION' in globals():
            opts.append(LABEL_OWN_PRINTER_OPTION)
        for key, cfg in sorted(LABEL_PRINTERS_CATALOG.items(), key=lambda x: str(x[0])):
            if isinstance(cfg, dict):
                marca = cfg.get('marca', '')
                modelo = cfg.get('modelo', '')
                lang = cfg.get('linguagem', '')
                dpi = cfg.get('resolucao', '')
                opts.append(f"{key} - {marca} {modelo} | {lang} | {dpi}dpi")
            else:
                opts.append(str(key))
    except Exception:
        pass
    return opts

def _qlabel_preview_current_label_display(self):
    try:
        cur = str(self.etiqueta_var.get() or '')
        key = _qlabel_preview_option_key(cur)
        for opt in _qlabel_preview_label_options():
            if _qlabel_preview_option_key(opt) == key:
                return opt
        return cur
    except Exception:
        return ''

def _qlabel_preview_current_printer_display(self):
    try:
        cur = str(self.printer_var.get() or '')
        for opt in _qlabel_preview_printer_options():
            if _qlabel_preview_option_key(opt) == cur:
                return opt
        return cur
    except Exception:
        return ''

def _qlabel_preview_get_template_mm(label_key, self_obj=None):
    try:
        if label_key in LABEL_TEMPLATES_CATALOG:
            cfg = LABEL_TEMPLATES_CATALOG[label_key]
            return float(cfg.get('largura', 60)), float(cfg.get('altura', 40))
        if label_key == 'PERSONALIZADA' and self_obj is not None:
            return float(self_obj.largura_var.get()), float(self_obj.altura_var.get())
    except Exception:
        pass
    try:
        if 'x' in str(label_key):
            parts = str(label_key).replace('mm','').split('x')
            return float(parts[0]), float(parts[1])
    except Exception:
        pass
    return 60.0, 40.0

def _qlabel_preview_printer_info_from_display(display):
    try:
        key = _qlabel_preview_option_key(display)
        if key in LABEL_PRINTERS_CATALOG:
            return key, LABEL_PRINTERS_CATALOG.get(key, {})
        if 'LABEL_CONFIGURED_PRINTER_OPTION' in globals() and key == LABEL_CONFIGURED_PRINTER_OPTION:
            return key, {'marca': 'Sistema', 'modelo': 'Configuração atual', 'linguagem': 'PDF/Driver', 'resolucao': 203, 'largura_max': 104}
        if 'LABEL_OWN_PRINTER_OPTION' in globals() and key == LABEL_OWN_PRINTER_OPTION:
            try:
                cfg = _label_load_own_printer_config()
                return key, {'marca': 'Própria', 'modelo': cfg.get('nome',''), 'linguagem': cfg.get('linguagem','PDF/Driver'), 'resolucao': int(cfg.get('dpi',203) or 203), 'largura_max': int(cfg.get('largura_max',104) or 104)}
            except Exception:
                return key, {'marca': 'Própria', 'modelo': 'Etiquetas', 'linguagem': 'PDF/Driver', 'resolucao': 203, 'largura_max': 104}
        return key, {}
    except Exception:
        return str(display or ''), {}

def _qlabel_preview_recommend_layout(label_key, printer_info, product_data=None):
    """
    Escolhe layout coerente com tamanho/modelo para não cortar.
    Usa layouts existentes do sistema quando disponíveis.
    """
    try:
        wmm, hmm = _qlabel_preview_get_template_mm(label_key)
        lang = str((printer_info or {}).get('linguagem','')).upper()
        ptxt = str((product_data or {}).get('nome','') + ' ' + str((product_data or {}).get('categoria',''))).lower()

        if wmm <= 35 or hmm <= 18:
            return 'sem_preco' if 'sem_preco' in LABEL_LAYOUTS else 'compacto'
        if 'farm' in ptxt or 'medic' in ptxt or 'pomada' in ptxt or 'comprim' in ptxt:
            if 'ultra_farmacia' in LABEL_LAYOUTS:
                return 'ultra_farmacia'
            if 'farmacia_validade' in LABEL_LAYOUTS:
                return 'farmacia_validade'
        if wmm >= 90 and hmm <= 35:
            return 'gondola' if 'gondola' in LABEL_LAYOUTS else 'ultra_varejo'
        if wmm >= 95 and hmm >= 80:
            return 'ultra_logistica' if 'ultra_logistica' in LABEL_LAYOUTS else 'qrcode_produto'
        if 'TSPL' in lang or 'ZPL' in lang:
            return 'ultra_varejo' if 'ultra_varejo' in LABEL_LAYOUTS else 'padrao'
    except Exception:
        pass
    return 'ultra_varejo' if 'ultra_varejo' in LABEL_LAYOUTS else 'padrao'

def _qlabel_preview_clamp_elements(self, margin=3.0):
    """
    Evita que componentes fiquem fora da etiqueta.
    Não destrói layout: apenas limita centro e tamanho ao campo útil.
    """
    try:
        changed = False
        for e in list(getattr(self, 'designer_elements', []) or []):
            try:
                w = max(1.0, min(100.0 - margin*2, float(e.get('largura', 20))))
                h = max(1.0, min(100.0 - margin*2, float(e.get('altura', 10))))
                x_min = margin + w/2
                x_max = 100.0 - margin - w/2
                y_min = margin + h/2
                y_max = 100.0 - margin - h/2
                x = max(x_min, min(x_max, float(e.get('x', 50))))
                y = max(y_min, min(y_max, float(e.get('y', 50))))
                if (w, h, x, y) != (float(e.get('largura', 20)), float(e.get('altura', 10)), float(e.get('x', 50)), float(e.get('y', 50))):
                    changed = True
                e['largura'], e['altura'], e['x'], e['y'] = w, h, x, y
            except Exception:
                pass
        if changed:
            try:
                self._designer_redraw()
            except Exception:
                pass
        return changed
    except Exception:
        return False

def _qlabel_preview_apply_profile(self, printer_display, label_display, qty_var=None, info_var=None, render_callback=None, auto_layout=True):
    """
    Aplica impressora + modelo/tamanho no sistema real antes do preview/print.
    """
    try:
        printer_key, printer_info = _qlabel_preview_printer_info_from_display(printer_display)
        label_key = _qlabel_preview_option_key(label_display)

        if printer_key:
            try:
                self.printer_var.set(printer_key)
            except Exception:
                pass

        # Aplica etiqueta no combobox principal
        try:
            found_display = None
            for opt in _qlabel_preview_label_options():
                if _qlabel_preview_option_key(opt) == label_key:
                    found_display = opt
                    break
            self.etiqueta_var.set(found_display or label_key)
        except Exception:
            pass

        # Aplica medidas oficiais do modelo
        wmm, hmm = _qlabel_preview_get_template_mm(label_key, self)
        try:
            self.largura_var.set(float(wmm))
            self.altura_var.set(float(hmm))
        except Exception:
            pass

        # Quantidade de impressões
        if qty_var is not None:
            try:
                q = max(1, min(9999, int(qty_var.get())))
                self.quantity_var.set(q)
            except Exception:
                pass

        # Recomendação inteligente de layout conforme etiqueta/impressora
        if auto_layout:
            try:
                layout_key = _qlabel_preview_recommend_layout(label_key, printer_info, getattr(self, 'product_data', {}))
                if layout_key in LABEL_LAYOUTS:
                    self.layout_var.set(f"{layout_key} - {LABEL_LAYOUTS[layout_key].get('nome', layout_key)}")
                    # Carrega visualmente o layout oficial/recomendado para esse tamanho.
                    try:
                        self._designer_load_selected_layout()
                    except Exception:
                        pass
            except Exception:
                pass

        # Travar elementos dentro da etiqueta
        cut_fixed = _qlabel_preview_clamp_elements(self, margin=3.0)

        # Informação técnica
        try:
            dpi = int(printer_info.get('resolucao', 203) or 203)
            largura_max = float(printer_info.get('largura_max', 104) or 104)
            lang = printer_info.get('linguagem', 'PDF/Driver')
            dots_w = int(round((float(wmm) / 25.4) * dpi))
            dots_h = int(round((float(hmm) / 25.4) * dpi))
            msg = f"Impressora: {printer_key or '-'} | Linguagem: {lang} | {dpi}dpi | Etiqueta: {wmm:g}x{hmm:g}mm | Dots: {dots_w}x{dots_h}"
            if wmm > largura_max:
                msg += f" | ALERTA: etiqueta maior que largura útil ({largura_max:g}mm)"
            if cut_fixed:
                msg += " | Componentes ajustados para não cortar"
            if info_var is not None:
                info_var.set(msg)
        except Exception:
            pass

        try:
            if render_callback:
                render_callback()
        except Exception:
            pass

        return True
    except Exception as e:
        try:
            if info_var is not None:
                info_var.set(f"Erro ao aplicar perfil: {e}")
        except Exception:
            pass
        return False

def _qlabel_preview_formulario_com_impressora_modelo_qtd(self):
    """
    Preview em formulário com dropdown de impressora, modelo/tamanho e quantidade.
    """
    try:
        win = tk.Toplevel(self)
        try:
            win.withdraw()
        except Exception:
            pass

        win.title("Preview da Etiqueta - Impressora / Modelo / Quantidade")
        win.configure(bg="#f8fafc")
        try:
            win._skip_auto_statusbar = True
            win._skip_visual_autopolish = True
            win._quantum_preview_form = True
        except Exception:
            pass

        largura_janela = 760
        altura_janela = 560
        try:
            sw = win.winfo_screenwidth()
            sh = win.winfo_screenheight()
            x = max(0, (sw - largura_janela) // 2)
            y = max(0, (sh - altura_janela) // 2)
            win.geometry(f"{largura_janela}x{altura_janela}+{x}+{y}")
            win.minsize(650, 480)
        except Exception:
            win.geometry("760x560")

        try:
            win.transient(self)
            win.attributes("-topmost", True)
        except Exception:
            pass

        header = ttk.Frame(win)
        header.pack(fill=tk.X, padx=10, pady=(10, 4))
        ttk.Label(header, text="Preview em Formulário", font=("Segoe UI", 13, "bold")).pack(side=tk.LEFT)

        # Controles técnicos
        controls = tk.LabelFrame(win, text="Perfil de Impressão", padx=8, pady=6, bg="#f8fafc")
        controls.pack(fill=tk.X, padx=10, pady=(0, 6))
        controls.columnconfigure(1, weight=1)
        controls.columnconfigure(3, weight=1)

        printer_var = tk.StringVar(value=_qlabel_preview_current_printer_display(self))
        label_var = tk.StringVar(value=_qlabel_preview_current_label_display(self))
        qty_var = tk.IntVar(value=max(1, int(self.quantity_var.get() or 1)))

        ttk.Label(controls, text="Impressora:").grid(row=0, column=0, sticky="w", padx=(0,4), pady=3)
        cb_printer = ttk.Combobox(controls, textvariable=printer_var, values=_qlabel_preview_printer_options(), state="readonly")
        cb_printer.grid(row=0, column=1, sticky="ew", padx=(0,8), pady=3)

        ttk.Label(controls, text="Modelo/Tamanho:").grid(row=0, column=2, sticky="w", padx=(0,4), pady=3)
        cb_label = ttk.Combobox(controls, textvariable=label_var, values=_qlabel_preview_label_options(), state="readonly")
        cb_label.grid(row=0, column=3, sticky="ew", padx=(0,8), pady=3)

        ttk.Label(controls, text="Quantidade:").grid(row=0, column=4, sticky="w", padx=(0,4), pady=3)
        sp_qty = ttk.Spinbox(controls, from_=1, to=9999, textvariable=qty_var, width=8)
        sp_qty.grid(row=0, column=5, sticky="w", pady=3)

        auto_layout_var = tk.BooleanVar(value=True)
        ttk.Checkbutton(controls, text="Aplicar layout oficial/recomendado ao trocar", variable=auto_layout_var).grid(row=1, column=0, columnspan=3, sticky="w", pady=(4,0))
        ttk.Button(controls, text="Aplicar agora", command=lambda: _apply_and_render(), bootstyle="success-outline").grid(row=1, column=3, sticky="e", padx=4, pady=(4,0))
        ttk.Button(controls, text="Auto ajustar sem cortar", command=lambda: (_qlabel_preview_clamp_elements(self, 3.0), _qlabel_render_form_preview(self, canvas, info_var)), bootstyle="warning-outline").grid(row=1, column=4, columnspan=2, sticky="ew", pady=(4,0))

        info_var = tk.StringVar(value="")
        ttk.Label(win, textvariable=info_var, foreground="#475569").pack(fill=tk.X, padx=12, pady=(0, 4))

        wrap = tk.Frame(win, bg="#cbd5e1", bd=1, relief=tk.SUNKEN)
        wrap.pack(fill=tk.BOTH, expand=True, padx=10, pady=6)

        canvas = tk.Canvas(wrap, bg="#e2e8f0", highlightthickness=0)
        canvas.pack(fill=tk.BOTH, expand=True)

        footer = ttk.Frame(win)
        footer.pack(fill=tk.X, padx=10, pady=(4, 10))
        ttk.Label(footer, text="Ao trocar impressora/modelo, o sistema aplica medidas e perfil técnico antes de visualizar/imprimir.", foreground="#64748b").pack(side=tk.LEFT)
        ttk.Button(footer, text="Fechar", command=win.destroy, bootstyle="danger-outline").pack(side=tk.RIGHT, padx=3)
        ttk.Button(footer, text="Imprimir", command=lambda: (_apply_and_render(), self._on_print()), bootstyle="success").pack(side=tk.RIGHT, padx=3)
        ttk.Button(footer, text="Preview PDF", command=lambda: (_apply_and_render(), self._preview_pdf()), bootstyle="secondary-outline").pack(side=tk.RIGHT, padx=3)
        ttk.Button(footer, text="Atualizar", command=lambda: _apply_and_render(auto_layout=False), bootstyle="info-outline").pack(side=tk.RIGHT, padx=3)

        def _render_only():
            _qlabel_render_form_preview(self, canvas, info_var)

        def _apply_and_render(auto_layout=None):
            use_auto = auto_layout_var.get() if auto_layout is None else bool(auto_layout)
            _qlabel_preview_apply_profile(self, printer_var.get(), label_var.get(), qty_var, info_var, _render_only, auto_layout=use_auto)

        def _on_combo_change(_event=None):
            _apply_and_render(auto_layout=auto_layout_var.get())

        cb_printer.bind("<<ComboboxSelected>>", _on_combo_change)
        cb_label.bind("<<ComboboxSelected>>", _on_combo_change)
        try:
            qty_var.trace_add("write", lambda *a: _apply_and_render(auto_layout=False))
        except Exception:
            pass
        canvas.bind("<Configure>", lambda e: _render_only())

        win.after(120, _apply_and_render)

        try:
            win.deiconify()
            win.grab_set()
        except Exception:
            pass

        try:
            _qlabel_preview_form_bring_front(win, self)
        except Exception:
            try:
                win.attributes("-topmost", True)
                win.lift()
                win.focus_force()
            except Exception:
                pass

    except Exception as e:
        try:
            messagebox.showerror("Preview em Formulário", f"Falha ao abrir preview com impressora/modelo: {e}", parent=self)
        except Exception:
            pass

try:
    if "LabelPrintConfigWindow" in globals() and not getattr(LabelPrintConfigWindow, "_quantum_preview_printer_model_qty_patch", False):
        LabelPrintConfigWindow._preview_formulario = _qlabel_preview_formulario_com_impressora_modelo_qtd
        LabelPrintConfigWindow._quantum_preview_printer_model_qty_patch = True
        try:
            print("[ETIQUETAS] Preview com impressora/modelo/quantidade aplicado.")
        except Exception:
            pass
except Exception as _e:
    try:
        print("[ETIQUETAS] Patch preview impressora/modelo/quantidade não aplicado:", _e)
    except Exception:
        pass






