# 🟨 PATCH - CONTROLES NO ESPAÇO AMARELO DO EDITOR VISUAL/DELPHI
# Coloca impressora, modelo/tamanho da etiqueta e quantidade diretamente
# na barra do editor, no espaço ao lado do Zoom.
# ═══════════════════════════════════════════════════════════════════════════════

def _qlabel_editor_toolbar_apply_profile(self, auto_layout=True):
    """Aplica os dropdowns do topo amarelo no editor visual."""
    try:
        printer = getattr(self, 'editor_toolbar_printer_var', None)
        label = getattr(self, 'editor_toolbar_label_var', None)
        qty = getattr(self, 'editor_toolbar_qty_var', None)
        if printer is None or label is None:
            return

        def _after_apply():
            try:
                self._designer_redraw()
                self._designer_fit_canvas()
            except Exception:
                pass

        if '_qlabel_preview_apply_profile' in globals():
            _qlabel_preview_apply_profile(
                self,
                printer.get(),
                label.get(),
                qty,
                None,
                _after_apply,
                auto_layout=bool(auto_layout)
            )
        else:
            # fallback mínimo caso helper não exista
            try:
                self.printer_var.set(_qlabel_preview_option_key(printer.get()))
            except Exception:
                pass
            try:
                self.etiqueta_var.set(label.get())
            except Exception:
                pass
            try:
                if qty is not None:
                    self.quantity_var.set(max(1, int(qty.get() or 1)))
            except Exception:
                pass
            _after_apply()

        try:
            self.designer_status_var.set("Perfil aplicado: impressora, modelo/tamanho e quantidade atualizados.")
        except Exception:
            pass
    except Exception as e:
        try:
            messagebox.showwarning("Perfil de Etiqueta", f"Não foi possível aplicar perfil: {e}", parent=self)
        except Exception:
            pass

def _qlabel_editor_toolbar_sync_from_main(self):
    """Sincroniza dropdowns do topo com os campos principais já existentes."""
    try:
        if not hasattr(self, 'editor_toolbar_printer_var'):
            return
        if '_qlabel_preview_current_printer_display' in globals():
            self.editor_toolbar_printer_var.set(_qlabel_preview_current_printer_display(self))
        else:
            self.editor_toolbar_printer_var.set(str(self.printer_var.get()))
        if '_qlabel_preview_current_label_display' in globals():
            self.editor_toolbar_label_var.set(_qlabel_preview_current_label_display(self))
        else:
            self.editor_toolbar_label_var.set(str(self.etiqueta_var.get()))
        try:
            self.editor_toolbar_qty_var.set(max(1, int(self.quantity_var.get() or 1)))
        except Exception:
            self.editor_toolbar_qty_var.set(1)
    except Exception:
        pass

try:
    if "LabelPrintConfigWindow" in globals() and not getattr(LabelPrintConfigWindow, "_quantum_toolbar_amarelo_patch", False):
        LabelPrintConfigWindow._editor_toolbar_apply_profile = _qlabel_editor_toolbar_apply_profile
        LabelPrintConfigWindow._editor_toolbar_sync_from_main = _qlabel_editor_toolbar_sync_from_main
        LabelPrintConfigWindow._quantum_toolbar_amarelo_patch = True
        try:
            print("[ETIQUETAS] Controles do espaço amarelo aplicados.")
        except Exception:
            pass
except Exception as _e:
    try:
        print("[ETIQUETAS] Patch espaço amarelo não aplicado:", _e)
    except Exception:
        pass






