# ═══════════════════════════════════════════════════════════════════════════════
# 💊 FARMÁCIA - CONTROLE OPCIONAL DE LOTE / VALIDADE E ALERTAS DE VENCIMENTO
# ═══════════════════════════════════════════════════════════════════════════════
_FARMACIA_VALIDADE_ALERTAS_EXIBIDOS_EM = None


def _farmacia_parse_data_validade(data_str):
    """Converte datas de validade aceitando DD/MM/AAAA, AAAA-MM-DD ou datetime."""
    if not data_str:
        return None
    if isinstance(data_str, datetime.datetime):
        return data_str.date()
    if isinstance(data_str, datetime.date):
        return data_str
    texto = str(data_str).strip()
    for fmt in ('%d/%m/%Y', '%Y-%m-%d', '%d-%m-%Y'):
        try:
            return datetime.datetime.strptime(texto, fmt).date()
        except Exception:
            pass
    return None


def verificar_alertas_validade_farmacia(products=None, parent=None, forcar=False):
    """
    Exibe alertas de medicamentos/produtos com controle de lote e validade ativo.

    Regra solicitada:
    - 15 dias antes: informa que está perto de vencer.
    - No dia: informa que é o último dia de validade.
    - Depois da data: informa que está vencido.
    - Se o checkbox não foi marcado no produto/item, nada é alertado.
    """
    global _FARMACIA_VALIDADE_ALERTAS_EXIBIDOS_EM
    try:
        hoje = datetime.date.today()
        if not forcar and _FARMACIA_VALIDADE_ALERTAS_EXIBIDOS_EM == hoje:
            return
        if products is None:
            products = load_data(PRODUCTS_FILE, {})
        proximos, hoje_lista, vencidos = [], [], []
        for produto_id, produto in (products or {}).items():
            if not isinstance(produto, dict):
                continue
            if not bool(produto.get('controlar_lote_validade', False)):
                continue
            validade_txt = produto.get('validade') or produto.get('data_validade') or ''
            validade_data = _farmacia_parse_data_validade(validade_txt)
            if not validade_data:
                continue
            dias = (validade_data - hoje).days
            nome = produto.get('nome', f'Produto {produto_id}')
            lote = produto.get('lote', '') or 'sem lote informado'
            linha = f"• {nome} | Lote: {lote} | Validade: {validade_data.strftime('%d/%m/%Y')}"
            if dias < 0:
                vencidos.append(f"{linha} | vencido há {abs(dias)} dia(s)")
            elif dias == 0:
                hoje_lista.append(f"{linha} | último dia de validade")
            elif dias <= 15:
                proximos.append(f"{linha} | vence em {dias} dia(s)")
        partes = []
        if vencidos:
            partes.append("⛔ PRODUTOS/MEDICAMENTOS VENCIDOS:\n" + "\n".join(vencidos[:30]))
        if hoje_lista:
            partes.append("⚠️ ÚLTIMO DIA DE VALIDADE:\n" + "\n".join(hoje_lista[:30]))
        if proximos:
            partes.append("🟡 PERTO DE VENCER - 15 DIAS OU MENOS:\n" + "\n".join(proximos[:30]))
        if partes:
            _FARMACIA_VALIDADE_ALERTAS_EXIBIDOS_EM = hoje
            messagebox.showwarning("Alertas de Validade - Farmácia", "\n\n".join(partes), parent=parent)
    except Exception as e:
        try:
            print(f"[FARMÁCIA] Erro ao verificar validade/lote: {e}")
        except Exception:
            pass

