        shortcuts_frame.pack(fill=tk.X, padx=30, pady=10)
        
        # Agrupar atalhos por categoria
        categories = {
            "VENDA / PDV": ["F1", "F2", "F3", "F6", "F7", "F8", "F12", "Del", "Enter", "Ctrl+C", "Ctrl+O"],
            "CADASTROS": ["Ctrl+N", "Ctrl+S", "Ctrl+F", "Ctrl+L"],
            "GERAL": ["Esc", "Ctrl+P", "Ctrl+H"]
        }
        
        for cat_name, keys in categories.items():
            tk.Label(shortcuts_frame, text=cat_name, font=("Segoe UI", 10, "bold"), fg=ACCENT, bg=BG_DARK).pack(anchor='w', pady=(10, 5))
            
            s_grid = tk.Frame(shortcuts_frame, bg=BG_DARK)
            s_grid.pack(fill=tk.X)
            
            # Filtra os atalhos reais do sistema para esta categoria
            current_row = 0
            current_col = 0
            for shortcut, (desc, _) in self.DEFAULT_SHORTCUTS.items():
                # Tenta associar pela descrição ou nome da tecla (simplificado)
                if any(k.lower() in shortcut.lower() for k in keys):
                    s_box = tk.Frame(s_grid, bg=BG_DARK)
                    s_box.grid(row=current_row, column=current_col, sticky='w', padx=10, pady=2)
                    
                    tk.Label(s_box, text=f"{shortcut}:", font=("Consolas", 10, "bold"), fg=ACCENT, bg=BG_DARK, width=12, anchor='e').pack(side='left')
