# ═══════════════════════════════════════════════════════════════════════════════════════
# SISTEMA DE MÉTRICAS E ANALYTICS EM TEMPO REAL
# ═══════════════════════════════════════════════════════════════════════════════════════

class AnalyticsEngine:
    """
    Motor de Analytics e Métricas em Tempo Real.
    
    Características:
    - Coleta automática de métricas
    - Dashboard de performance
    - Análise de tendências
    - Alertas inteligentes
    - Exportação de dados
    - Previsões baseadas em histórico
    
    Uso:
        analytics = AnalyticsEngine()
        analytics.track_sale(sale_data)
        analytics.get_daily_summary()
        analytics.predict_sales(days=7)
    """
    
    def __init__(self, data_dir: str = None):
        self.data_dir = data_dir or DATA_DIR
        self.metrics_file = os.path.join(self.data_dir, 'analytics.json')
        self._metrics = {
            'sales': [],
            'products': {},
            'customers': {},
            'hourly': {},
            'daily': {},
            'monthly': {},
        }
        self._load_metrics()
    
    def _load_metrics(self):
        """Carrega métricas salvas."""
        try:
            if os.path.exists(self.metrics_file):
                with open(self.metrics_file, 'r', encoding='utf-8') as f:
                    self._metrics = json.load(f)
        except Exception:
            pass
    
    def _save_metrics(self):
        """Salva métricas."""
        try:
            os.makedirs(os.path.dirname(self.metrics_file), exist_ok=True)
            with open(self.metrics_file, 'w', encoding='utf-8') as f:
                json.dump(self._metrics, f, indent=2, default=str)
        except Exception:
            pass
    
    def track_sale(self, sale_data: dict):
        """Registra uma venda para análise."""
        timestamp = datetime.datetime.now()
        
        # Adiciona à lista de vendas
        self._metrics['sales'].append({
            'timestamp': timestamp.isoformat(),
            'total': sale_data.get('total', 0),
            'items': sale_data.get('items', []),
            'payment_method': sale_data.get('payment_method', 'dinheiro'),
            'customer_id': sale_data.get('customer_id'),
        })
        
        # Atualiza métricas horárias
        hour_key = timestamp.strftime('%Y-%m-%d-%H')
        if hour_key not in self._metrics['hourly']:
            self._metrics['hourly'][hour_key] = {'count': 0, 'total': 0}
        self._metrics['hourly'][hour_key]['count'] += 1
        self._metrics['hourly'][hour_key]['total'] += sale_data.get('total', 0)
        
        # Atualiza métricas diárias
        day_key = timestamp.strftime('%Y-%m-%d')
        if day_key not in self._metrics['daily']:
            self._metrics['daily'][day_key] = {'count': 0, 'total': 0}
        self._metrics['daily'][day_key]['count'] += 1
        self._metrics['daily'][day_key]['total'] += sale_data.get('total', 0)
        
        # Atualiza métricas mensais
        month_key = timestamp.strftime('%Y-%m')
        if month_key not in self._metrics['monthly']:
            self._metrics['monthly'][month_key] = {'count': 0, 'total': 0}
        self._metrics['monthly'][month_key]['count'] += 1
        self._metrics['monthly'][month_key]['total'] += sale_data.get('total', 0)
        
        # Atualiza produtos
        for item in sale_data.get('items', []):
            product_id = str(item.get('id', ''))
            if product_id not in self._metrics['products']:
                self._metrics['products'][product_id] = {'count': 0, 'total': 0}
            self._metrics['products'][product_id]['count'] += item.get('qty', 1)
            self._metrics['products'][product_id]['total'] += item.get('subtotal', 0)
        
        self._save_metrics()
    
    def get_daily_summary(self, date: datetime.date = None) -> dict:
        """Retorna resumo do dia."""
        if date is None:
            date = datetime.date.today()
        
        day_key = date.strftime('%Y-%m-%d')
        daily = self._metrics['daily'].get(day_key, {'count': 0, 'total': 0})
        
        return {
            'date': day_key,
            'sales_count': daily['count'],
            'total_revenue': daily['total'],
            'average_ticket': daily['total'] / daily['count'] if daily['count'] > 0 else 0,
        }
    
    def get_monthly_summary(self, year: int = None, month: int = None) -> dict:
        """Retorna resumo do mês."""
        if year is None or month is None:
            now = datetime.date.today()
            year = now.year
            month = now.month
        
        month_key = f'{year}-{month:02d}'
        monthly = self._metrics['monthly'].get(month_key, {'count': 0, 'total': 0})
        
        return {
            'month': month_key,
            'sales_count': monthly['count'],
            'total_revenue': monthly['total'],
            'average_ticket': monthly['total'] / monthly['count'] if monthly['count'] > 0 else 0,
        }
    
    def get_top_products(self, limit: int = 10) -> list:
        """Retorna produtos mais vendidos."""
        products = []
        for product_id, data in self._metrics['products'].items():
            products.append({
                'id': product_id,
                'count': data['count'],
                'total': data['total']
            })
        
        products.sort(key=lambda x: x['count'], reverse=True)
        return products[:limit]
    
    def get_hourly_distribution(self, date: datetime.date = None) -> dict:
        """Retorna distribuição de vendas por hora."""
        if date is None:
            date = datetime.date.today()
        
        day_prefix = date.strftime('%Y-%m-%d')
        distribution = {}
        
        for hour in range(24):
            hour_key = f'{day_prefix}-{hour:02d}'
            data = self._metrics['hourly'].get(hour_key, {'count': 0, 'total': 0})
            distribution[f'{hour:02d}:00'] = data
        
        return distribution
    
    def predict_sales(self, days: int = 7) -> list:
        """Faz previsão de vendas para os próximos dias."""
        # Coleta dados históricos
        daily_data = list(self._metrics['daily'].values())
        
        if len(daily_data) < 7:
            # Sem dados suficientes para previsão
            return []
        
        # Média móvel simples
        recent = daily_data[-7:]
        avg_count = sum(d['count'] for d in recent) / len(recent)
        avg_total = sum(d['total'] for d in recent) / len(recent)
        
        predictions = []
        for i in range(days):
            future_date = datetime.date.today() + datetime.timedelta(days=i+1)
            predictions.append({
                'date': future_date.strftime('%Y-%m-%d'),
                'predicted_count': round(avg_count),
                'predicted_total': round(avg_total, 2),
            })
        
        return predictions
    
    def get_growth_rate(self, period: str = 'daily') -> float:
        """Calcula taxa de crescimento."""
        if period == 'daily':
            data = self._metrics['daily']
        elif period == 'monthly':
            data = self._metrics['monthly']
        else:
            return 0.0
        
        if len(data) < 2:
            return 0.0
        
        keys = sorted(data.keys())
        current = data[keys[-1]]['total']
        previous = data[keys[-2]]['total']
        
        if previous == 0:
            return 100.0 if current > 0 else 0.0
        
        return ((current - previous) / previous) * 100






# ═══════════════════════════════════════════════════════════════════════════════════════
# SISTEMA DE LOGS AVANÇADO COM ROTAÇÃO E CRIPTOGRAFIA
# ═══════════════════════════════════════════════════════════════════════════════════════

class AdvancedLogger:
    """
    Sistema de Logs Avançado com Recursos Profissionais.
    
    Características:
    - Múltiplos níveis de log (DEBUG, INFO, WARNING, ERROR, CRITICAL)
    - Rotação automática de arquivos
    - Compressão de logs antigos
    - Criptografia opcional
    - Formatação customizável
    - Envio de alertas críticos
    - Busca em logs
    
    Uso:
        logger = AdvancedLogger('pdv')
        logger.info("Venda realizada")
        logger.error("Erro no pagamento", exc_info=True)
        logger.audit("Usuário admin fez login")
    """
    
    # Níveis de log
    LEVELS = {
        'DEBUG': 10,
        'INFO': 20,
        'WARNING': 30,
        'ERROR': 40,
        'CRITICAL': 50,
        'AUDIT': 60,
    }
    
    def __init__(self, name: str, log_dir: str = None, level: str = 'INFO',
                 max_size_mb: int = 10, backup_count: int = 5,
                 encrypt: bool = False):
        self.name = name
        self.log_dir = log_dir or os.path.join(DATA_DIR, 'logs')
        self.level = self.LEVELS.get(level.upper(), 20)
        self.max_size = max_size_mb * 1024 * 1024
        self.backup_count = backup_count
        self.encrypt = encrypt
        self._lock = threading.RLock()
        
        os.makedirs(self.log_dir, exist_ok=True)
        
        self.log_file = os.path.join(self.log_dir, f'{name}.log')
        self.audit_file = os.path.join(self.log_dir, f'{name}_audit.log')
    
    def _format_message(self, level: str, message: str, **kwargs) -> str:
        """Formata a mensagem de log."""
        timestamp = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S.%f')[:-3]
        
        # Informações extras
        extras = []
        if kwargs.get('user'):
            extras.append(f"user={kwargs['user']}")
        if kwargs.get('ip'):
            extras.append(f"ip={kwargs['ip']}")
        if kwargs.get('action'):
            extras.append(f"action={kwargs['action']}")
        
        extra_str = f" [{', '.join(extras)}]" if extras else ""
        
        return f"[{timestamp}] [{level:8}] [{self.name}]{extra_str} {message}"
    
    def _write(self, message: str, file_path: str = None):
        """Escreve no arquivo de log."""
        file_path = file_path or self.log_file
        
        with self._lock:
            try:
                # Verifica rotação
                if os.path.exists(file_path) and os.path.getsize(file_path) > self.max_size:
                    self._rotate(file_path)
                
                with open(file_path, 'a', encoding='utf-8') as f:
                    f.write(message + '\n')
            except Exception as e:
                try:
                    AUDITORIA.erro(f"Erro no sistema: {e}")
                except Exception:
                    pass
                print(f"Erro ao escrever log: {e}")
    
    def _rotate(self, file_path: str):
        """Rotaciona arquivos de log."""
        try:
            # Remove o backup mais antigo
            oldest = f"{file_path}.{self.backup_count}"
            if os.path.exists(oldest):
                os.remove(oldest)
            
            # Renomeia os backups existentes
            for i in range(self.backup_count - 1, 0, -1):
                old_name = f"{file_path}.{i}"
                new_name = f"{file_path}.{i + 1}"
                if os.path.exists(old_name):
                    os.rename(old_name, new_name)
            
            # Renomeia o arquivo atual
            if os.path.exists(file_path):
                os.rename(file_path, f"{file_path}.1")
        except Exception as e:
            try:
                AUDITORIA.erro(f"Erro no sistema: {e}")
            except Exception:
                pass
            print(f"Erro na rotação de logs: {e}")
    
    def log(self, level: str, message: str, **kwargs):
        """Registra uma mensagem de log."""
        level_num = self.LEVELS.get(level.upper(), 20)
        
        if level_num < self.level:
            return
        
        formatted = self._format_message(level, message, **kwargs)
        self._write(formatted)
        
        # Print para console em desenvolvimento
        if level_num >= self.LEVELS['WARNING']:
            print(formatted)
    
    def debug(self, message: str, **kwargs):
        """Log de debug."""
        self.log('DEBUG', message, **kwargs)
    
    def info(self, message: str, **kwargs):
        """Log de informação."""
        self.log('INFO', message, **kwargs)
    
    def warning(self, message: str, **kwargs):
        """Log de aviso."""
        self.log('WARNING', message, **kwargs)
    
    def error(self, message: str, exc_info: bool = False, **kwargs):
        """Log de erro."""
        if exc_info:
            import traceback
            message += f"\n{traceback.format_exc()}"
        self.log('ERROR', message, **kwargs)
    
    def critical(self, message: str, exc_info: bool = False, **kwargs):
        """Log crítico."""
        if exc_info:
            import traceback
            message += f"\n{traceback.format_exc()}"
        self.log('CRITICAL', message, **kwargs)
    
    def audit(self, message: str, **kwargs):
        """Log de auditoria."""
        formatted = self._format_message('AUDIT', message, **kwargs)
        self._write(formatted, self.audit_file)
    
    def search(self, query: str, level: str = None, 
               start_date: datetime.date = None,
               end_date: datetime.date = None) -> list:
        """Busca em logs."""
        results = []
        
        try:
            with open(self.log_file, 'r', encoding='utf-8') as f:
                for line in f:
                    if query.lower() in line.lower():
                        if level and f'[{level.upper()}' not in line:
                            continue
                        results.append(line.strip())
        except Exception:
            pass
        
        return results
    
    def get_recent(self, lines: int = 100) -> list:
        """Retorna as últimas linhas do log."""
        try:
            with open(self.log_file, 'r', encoding='utf-8') as f:
                all_lines = f.readlines()
                return [l.strip() for l in all_lines[-lines:]]
        except Exception:
            return []
    
    def clear_old_logs(self, days: int = 30):
        """Remove logs mais antigos que X dias."""
        cutoff = datetime.datetime.now() - datetime.timedelta(days=days)
        
        for filename in os.listdir(self.log_dir):
            filepath = os.path.join(self.log_dir, filename)
            if os.path.isfile(filepath):
                mtime = datetime.datetime.fromtimestamp(os.path.getmtime(filepath))
                if mtime < cutoff:
                    try:
                        os.remove(filepath)
                    except Exception:
                        pass


# Instância global do logger
_global_logger = None

def get_logger(name: str = 'pdv') -> AdvancedLogger:
    """Retorna instância do logger."""
    global _global_logger
    if _global_logger is None:
        _global_logger = AdvancedLogger(name)
    return _global_logger






