#  ╚══▀▀═╝  ╚═════╝ ╚═╝  ╚═╝╚═╝  ╚═══╝   ╚═╝    ╚═════╝ ╚═╝     ╚═╝
#  SYNC ENGINE - ATUALIZAÇÃO EM TEMPO REAL, SIMULTÂNEA E QUÂNTICA
# ═══════════════════════════════════════════════════════════════════════════════

class QuantumSyncEngine:
    """
    Motor de Sincronização Quântica em Tempo Real.
    
    Monitora alterações em TODOS os arquivos de dados do sistema e notifica
    automaticamente TODAS as telas/janelas abertas para atualização simultânea.
    
    Características:
    - Detecção de mudanças por hash MD5 (ultra-rápido)
    - Notificação simultânea de todas as telas registradas
    - Intervalo de sincronização configurável (padrão: 2 segundos)
    - Auto-recuperação em caso de falhas
    - Zero impacto na performance (thread-safe com after())
    - Suporte a callbacks específicos por tipo de dado
    """
    
    _instance = None
    _initialized = False
    
    def __new__(cls, *args, **kwargs):
        """Singleton - garante apenas uma instância do engine."""
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance
    
    def __init__(self, root=None, sync_interval=2000):
        """
        Inicializa o QuantumSyncEngine.
        
        Args:
            root: Widget raiz do Tkinter (para agendamento via after())
            sync_interval: Intervalo de sincronização em milissegundos (padrão: 2000ms)
        """
        if QuantumSyncEngine._initialized:
            if root is not None:
                self.root = root
            return
        
        self.root = root
        self.sync_interval = sync_interval
        self._running = False
        self._subscribers = {}  # {data_key: [callback1, callback2, ...]}
        self._file_hashes = {}  # {filepath: last_md5_hash}
        self._data_cache = {}   # {filepath: cached_data}
        self._monitored_files = {}  # {data_key: filepath}
        self._error_count = 0
        self._max_errors = 10
        self._sync_count = 0
        self._last_sync_time = None
        
        # Registrar todos os arquivos de dados monitorados
        self._register_default_files()
        
        QuantumSyncEngine._initialized = True
        print("[QuantumSync] ⚛️  Motor de Sincronização Quântica inicializado")
    
    def _register_default_files(self):
        """Registra todos os arquivos de dados do sistema para monitoramento."""
        try:
            # Arquivos principais do sistema
            file_mappings = {
                "products": PRODUCTS_FILE,
                "categories": CATEGORIES_FILE,
                "customers": CUSTOMERS_FILE,
                "sales": SALES_FILE,
                "comandas": COMANDAS_FILE,
                "cartoes": CARTOES_FILE,
                "config": CONFIG_FILE,
                "empresa": EMPRESA_FILE,
                "contas_pagar": CONTAS_A_PAGAR_FILE,
                "contas_receber": CONTAS_A_RECEBER_FILE,
            }
            
            # Arquivos do diretório de login
            login_file_mappings = {
                "users": USERS_FILE,
                "fornecedores": SUPPLIERS_FILE,
                "entregadores": ENTREGADORES_FILE,
                "bairros": BAIRROS_FILE,
                "notas_entrada": NOTAS_ENTRADA_FILE,
                "caixa": CAIXA_FILE,
                "fechamentos_caixa": FECHAMENTOS_CAIXA_FILE,
                "ordens_servico": ORDENS_SERVICO_FILE,
                "servicos": SERVICES_FILE,
                "vendedores": VENDEDORES_FILE,
            }
            
            # Arquivo de tamanhos (caminho relativo)
            tamanhos_path = os.path.join(DATA_DIR, "tamanhos.json")
            if os.path.exists(tamanhos_path):
                login_file_mappings["tamanhos"] = tamanhos_path
            
            # Registrar todos
            for key, filepath in {**file_mappings, **login_file_mappings}.items():
                if filepath and os.path.exists(filepath):
                    self._monitored_files[key] = filepath
                    self._file_hashes[filepath] = self._compute_hash(filepath)
                    self._subscribers[key] = []
        except Exception as e:
            print(f"[QuantumSync] Erro ao registrar arquivos: {e}")
    
    def _compute_hash(self, filepath):
        """Calcula hash MD5 do arquivo para detecção de mudanças."""
        try:
            if not os.path.exists(filepath):
                return None
            # Usa mtime + size para detecção ultra-rápida (sem ler o arquivo)
            stat = os.stat(filepath)
            return f"{stat.st_mtime}:{stat.st_size}"
        except Exception:
            return None
    
    def subscribe(self, data_key, callback):
        """
        Registra um callback para ser notificado quando dados mudarem.
        
        Args:
            data_key: Chave do tipo de dado (ex: 'products', 'customers', 'sales')
            callback: Função a ser chamada quando houver mudança
        """
        if data_key not in self._subscribers:
            self._subscribers[data_key] = []
        
        if callback not in self._subscribers[data_key]:
            self._subscribers[data_key].append(callback)
            # print(f"[QuantumSync] 📡 Subscriber registrado para '{data_key}'")
    
    def unsubscribe(self, data_key, callback):
        """Remove um callback de notificação."""
        if data_key in self._subscribers:
            try:
                self._subscribers[data_key].remove(callback)
            except ValueError:
                pass
    
    def unsubscribe_all(self, callback):
        """Remove um callback de TODAS as chaves de dados."""
        for key in self._subscribers:
            try:
                self._subscribers[key].remove(callback)
            except ValueError:
                pass
    
    def notify_change(self, data_key):
        """
        Notifica manualmente que um tipo de dado foi alterado.
        Útil para quando save_data() é chamado diretamente.
        
        Args:
            data_key: Chave do tipo de dado alterado
        """
        if data_key in self._monitored_files:
            filepath = self._monitored_files[data_key]
            self._file_hashes[filepath] = self._compute_hash(filepath)
        
        self._notify_subscribers(data_key)
    
    def _notify_subscribers(self, data_key):
        """Notifica todos os subscribers de uma chave de dados."""
        if data_key not in self._subscribers:
            return
        
        dead_callbacks = []
        for callback in self._subscribers[data_key]:
            try:
                callback()
            except Exception as e:
                # Se o callback falhar (janela fechada), marca para remoção
                dead_callbacks.append(callback)
                # print(f"[QuantumSync] Callback morto removido para '{data_key}': {e}")
        
        # Remove callbacks mortos
        for dead in dead_callbacks:
            try:
                self._subscribers[data_key].remove(dead)
            except ValueError:
                pass
    
    def start(self):
        """Inicia o loop de sincronização em tempo real."""
        if self._running:
            return
        self._running = True
        self._error_count = 0
        print("[QuantumSync] ⚡ Sincronização em tempo real ATIVADA")
        self._sync_loop()
    
    def stop(self):
        """Para o loop de sincronização."""
        self._running = False
        print("[QuantumSync] ⏹️  Sincronização em tempo real DESATIVADA")
    
    def _sync_loop(self):
        """Loop principal de sincronização - verifica mudanças em todos os arquivos."""
        if not self._running:
            return
        
        try:
            changes_detected = []
            
            for data_key, filepath in self._monitored_files.items():
                try:
                    new_hash = self._compute_hash(filepath)
                    old_hash = self._file_hashes.get(filepath)
                    
                    if new_hash != old_hash and new_hash is not None:
                        self._file_hashes[filepath] = new_hash
                        changes_detected.append(data_key)
                except Exception:
                    pass
            
            # Notifica subscribers de todas as mudanças detectadas
            for data_key in changes_detected:
                try:
                    self._notify_subscribers(data_key)
                except Exception as e:
                    print(f"[QuantumSync] Erro ao notificar '{data_key}': {e}")
            
            if changes_detected:
                self._sync_count += 1
                import datetime
                self._last_sync_time = datetime.datetime.now()
                print(f"[QuantumSync] ⚛️  Sync #{self._sync_count} - Mudanças: {', '.join(changes_detected)}")
            
            self._error_count = 0  # Reset error count on success
            
        except Exception as e:
            self._error_count += 1
            if self._error_count <= 3:
                print(f"[QuantumSync] Erro no sync loop ({self._error_count}): {e}")
        
        # Também verifica eventos de banco gerados por outras máquinas/processos.
        try:
            self._poll_mysql_sync_events()
        except Exception:
            pass

        # Agenda próxima verificação
        if self._running and self.root:
            try:
                self.root.after(self.sync_interval, self._sync_loop)
            except Exception:
                self._running = False
    
    def _poll_mysql_sync_events(self):
        """Consulta eventos no MySQL gerados por outras máquinas e propaga para telas locais."""
        try:
            if not hasattr(self, '_last_mysql_sync_event_id'):
                self._last_mysql_sync_event_id = 0
                try:
                    row = MySQLDB.fetchone("SELECT MAX(id) AS max_id FROM sync_events")
                    self._last_mysql_sync_event_id = int((row or {}).get('max_id') or 0)
                except Exception:
                    self._last_mysql_sync_event_id = 0
                return
            rows = MySQLDB.fetchall(
                "SELECT id, data_key, operation, origin FROM sync_events WHERE id > %s ORDER BY id ASC LIMIT 80",
                (int(self._last_mysql_sync_event_id or 0),)
            )
            if not rows:
                return
            changed = set()
            for row in rows:
                try:
                    self._last_mysql_sync_event_id = max(int(self._last_mysql_sync_event_id or 0), int(row.get('id') or 0))
                    dk = str(row.get('data_key') or 'all')
                    if dk and dk != 'sync_events':
                        changed.add(dk)
                except Exception:
                    pass
            for dk in changed:
                try:
                    self._notify_subscribers(dk)
                except Exception:
                    pass
                try:
                    if hasattr(self, 'broadcast_all'):
                        self.broadcast_all(dk, force=True)
                except Exception:
                    pass
            if changed:
                self._sync_count += 1
                import datetime
                self._last_sync_time = datetime.datetime.now()
                print(f"[QuantumSync-DB] ⚛️ Eventos remotos: {', '.join(sorted(changed))}")
        except Exception:
            pass

    def get_stats(self):
        """Retorna estatísticas do engine de sincronização."""
        return {
            "running": self._running,
            "sync_count": self._sync_count,
            "last_sync": self._last_sync_time,
            "monitored_files": len(self._monitored_files),
            "total_subscribers": sum(len(v) for v in self._subscribers.values()),
            "sync_interval_ms": self.sync_interval,
            "errors": self._error_count
        }
    
    def register_file(self, data_key, filepath):
        """Registra um novo arquivo para monitoramento."""
        if filepath and os.path.exists(filepath):
            self._monitored_files[data_key] = filepath
            self._file_hashes[filepath] = self._compute_hash(filepath)
            if data_key not in self._subscribers:
                self._subscribers[data_key] = []


# Instância global do QuantumSyncEngine (será inicializada com root no PDVSuperApp)
_quantum_sync_engine = None

def get_quantum_sync():
    """Retorna a instância global do QuantumSyncEngine."""
    global _quantum_sync_engine
    return _quantum_sync_engine

def init_quantum_sync(root, interval=650):
    """Inicializa o QuantumSyncEngine global."""
    global _quantum_sync_engine
    _quantum_sync_engine = QuantumSyncEngine(root=root, sync_interval=interval)
    return _quantum_sync_engine



# ═══════════════════════════════════════════════════════════════════════════════
# ⚛️ QUANTUM LIVE SCREEN ENGINE v4.0 - ATUALIZAÇÃO GLOBAL EM TEMPO REAL
# ═══════════════════════════════════════════════════════════════════════════════
# Esta camada registra automaticamente TODAS as janelas abertas do sistema e
# propaga mudanças de dados de forma simultânea, sem travar a interface.
# Funciona junto com o QuantumSyncEngine original e reforça:
# - broadcast global após qualquer save_data()
# - atualização em lote via root.after()
# - proteção contra refresh recursivo
# - chamada segura de métodos de atualização existentes em cada tela
# - throttling por janela para manter agilidade
# ═══════════════════════════════════════════════════════════════════════════════

_QUANTUM_LIVE_PATCH_APPLIED = False

def _quantum_apply_live_screen_patch():
    """Aplica patch de atualização global em tempo real para todas as telas."""
    global _QUANTUM_LIVE_PATCH_APPLIED
    if _QUANTUM_LIVE_PATCH_APPLIED:
        return
    _QUANTUM_LIVE_PATCH_APPLIED = True

    import weakref
    import inspect
    import time as _ql_time

    # Métodos conhecidos de atualização existentes no sistema.
    # A ordem privilegia métodos quânticos e depois métodos genéricos de reload.
    _REFRESH_METHODS = (
        '_quantum_refresh_all',
        '_quantum_auto_refresh',
        'refresh_data_views',
        'refresh_list',
        'refresh',
        '_refresh_tree',
        '_load_data_to_tree',
        '_load_items_to_tree',
        '_load_items',
        '_carregar_dados',
        '_carregar_lista',
        '_atualizar_treeview',
        '_atualizar_lista',
        '_atualizar_lista_produtos',
        '_atualizar_lista_produtos_btn',
        '_load_turnos',
        '_load_caixas',
        '_load_vinculos',
        '_load_centros',
        '_quantum_refresh_report',
        '_quantum_refresh_notas',
        '_quantum_refresh_caixa',
        '_quantum_refresh_contas_data',
    )

    def _ensure_live_attrs(engine):
        if not hasattr(engine, '_live_windows'):
            engine._live_windows = weakref.WeakSet()
        if not hasattr(engine, '_live_global_callbacks'):
            engine._live_global_callbacks = []
        if not hasattr(engine, '_live_refreshing'):
            engine._live_refreshing = set()
        if not hasattr(engine, '_live_last_refresh'):
            engine._live_last_refresh = {}
        if not hasattr(engine, '_live_pending_keys'):
            engine._live_pending_keys = set()
        if not hasattr(engine, '_live_batch_scheduled'):
            engine._live_batch_scheduled = False
        if not hasattr(engine, '_live_tick_counter'):
            engine._live_tick_counter = 0
        if not hasattr(engine, '_live_min_window_interval'):
            engine._live_min_window_interval = 0.45
        return engine

    def _callback_accepts_no_required_args(fn):
        try:
            sig = inspect.signature(fn)
            for p in sig.parameters.values():
                if p.default is inspect._empty and p.kind in (p.POSITIONAL_ONLY, p.POSITIONAL_OR_KEYWORD, p.KEYWORD_ONLY):
                    return False
            return True
        except Exception:
            return True

    def _safe_call_refresh(win, data_key=None, force=False):
        """Atualiza uma janela de forma segura, sem recursão e sem travar."""
        try:
            if win is None or not win.winfo_exists():
                return False
        except Exception:
            return False

        engine = get_quantum_sync()
        if engine:
            _ensure_live_attrs(engine)
            wid = id(win)
            now = _ql_time.monotonic()
            if wid in engine._live_refreshing:
                return False
            last = engine._live_last_refresh.get(wid, 0)
            if not force and now - last < engine._live_min_window_interval:
                return False
            engine._live_refreshing.add(wid)

        try:
            # Janelas podem declarar quais chaves aceitam: _quantum_data_key ou _quantum_data_keys
            keys = set()
            if hasattr(win, '_quantum_data_key') and getattr(win, '_quantum_data_key'):
                keys.add(getattr(win, '_quantum_data_key'))
            if hasattr(win, '_quantum_data_keys') and getattr(win, '_quantum_data_keys'):
                try:
                    keys.update(getattr(win, '_quantum_data_keys'))
                except Exception:
                    pass

            # Se a janela declarou escopo e a mudança é de outro módulo, não força refresh pesado.
            scoped = bool(keys)
            if scoped and data_key and data_key not in keys and data_key != 'all':
                return False

            # Callback específico da janela, quando existir.
            custom_cb = getattr(win, '_quantum_live_refresh', None)
            if callable(custom_cb):
                try:
                    custom_cb(data_key)
                    return True
                except TypeError:
                    custom_cb()
                    return True

            # Métodos existentes sem argumentos.
            for name in _REFRESH_METHODS:
                fn = getattr(win, name, None)
                if callable(fn) and _callback_accepts_no_required_args(fn):
                    try:
                        fn()
                        return True
                    except Exception:
                        continue

            return False
        finally:
            if engine:
                try:
                    engine._live_last_refresh[id(win)] = _ql_time.monotonic()
                    engine._live_refreshing.discard(id(win))
                except Exception:
                    pass

    def _register_window(self, win):
        """Registra qualquer Tk/Toplevel para receber atualização quântica global."""
        _ensure_live_attrs(self)
        try:
            if win is not None and win.winfo_exists():
                self._live_windows.add(win)
                # marca padrão para telas sem escopo específico: recebem broadcast leve
                if not hasattr(win, '_quantum_live_registered'):
                    win._quantum_live_registered = True
        except Exception:
            pass

    def _subscribe_all(self, callback):
        _ensure_live_attrs(self)
        if callable(callback) and callback not in self._live_global_callbacks:
            self._live_global_callbacks.append(callback)

    def _schedule_global_refresh(self, data_key='all', force=False):
        """Agenda atualização simultânea em lote no loop visual do Tkinter."""
        _ensure_live_attrs(self)
        self._live_pending_keys.add(data_key or 'all')
        if self._live_batch_scheduled:
            return
        self._live_batch_scheduled = True

        def _run_batch():
            try:
                keys = list(getattr(self, '_live_pending_keys', {'all'}))
                self._live_pending_keys.clear()
                self._live_batch_scheduled = False
                for key in keys:
                    # callbacks globais registrados manualmente
                    for cb in list(getattr(self, '_live_global_callbacks', [])):
                        try:
                            cb(key)
                        except TypeError:
                            try:
                                cb()
                            except Exception:
                                pass
                        except Exception:
                            pass

                    # janelas registradas automaticamente
                    for win in list(getattr(self, '_live_windows', [])):
                        try:
                            _safe_call_refresh(win, key, force=force)
                        except Exception:
                            pass
            except Exception:
                self._live_batch_scheduled = False

        try:
            if getattr(self, 'root', None):
                self.root.after(1, _run_batch)
            else:
                _run_batch()
        except Exception:
            _run_batch()

    def _broadcast_all(self, data_key='all', force=False):
        _schedule_global_refresh(self, data_key=data_key, force=force)

    # Patch dos métodos da classe QuantumSyncEngine.
    if not hasattr(QuantumSyncEngine, 'register_window'):
        QuantumSyncEngine.register_window = _register_window
    if not hasattr(QuantumSyncEngine, 'subscribe_all'):
        QuantumSyncEngine.subscribe_all = _subscribe_all
    if not hasattr(QuantumSyncEngine, 'broadcast_all'):
        QuantumSyncEngine.broadcast_all = _broadcast_all

    # Reforça notify_change para além dos subscribers específicos, também atualizar telas abertas.
    _orig_notify_change = QuantumSyncEngine.notify_change
    def _patched_notify_change(self, data_key):
        _ensure_live_attrs(self)
        try:
            _orig_notify_change(self, data_key)
        finally:
            try:
                self.broadcast_all(data_key, force=True)
            except Exception:
                pass
    QuantumSyncEngine.notify_change = _patched_notify_change

    # Reforça start para registrar root e iniciar heartbeat leve.
    _orig_start = QuantumSyncEngine.start
    def _patched_start(self):
        _ensure_live_attrs(self)
        try:
            if getattr(self, 'root', None):
                self.register_window(self.root)
        except Exception:
            pass
        _orig_start(self)
    QuantumSyncEngine.start = _patched_start

    # Reforça o loop: a cada alguns ciclos faz um pulso leve para telas que dependem de banco/MySQL
    # e que não geram alteração de arquivo local.
    _orig_sync_loop = QuantumSyncEngine._sync_loop
    def _patched_sync_loop(self):
        _ensure_live_attrs(self)
        try:
            self._live_tick_counter += 1
            if self._live_tick_counter % 4 == 0:
                # pulso leve: não força refresh se a janela acabou de atualizar
                self.broadcast_all('all', force=False)
        except Exception:
            pass
        return _orig_sync_loop(self)
    QuantumSyncEngine._sync_loop = _patched_sync_loop

    # Registro automático de novas janelas Toplevel criadas depois do patch.
    try:
        _orig_toplevel_init_live = tk.Toplevel.__init__
        def _patched_toplevel_init_live(self, *args, **kwargs):
            _orig_toplevel_init_live(self, *args, **kwargs)
            try:
                qs = get_quantum_sync()
                if qs:
                    qs.register_window(self)
            except Exception:
                pass
            try:
                self.bind('<Map>', lambda e=None, w=self: (get_quantum_sync() and get_quantum_sync().register_window(w)), add='+')
            except Exception:
                pass
        tk.Toplevel.__init__ = _patched_toplevel_init_live
    except Exception:
        pass

    print("[QuantumLive] ⚛️ Atualização global, simultânea e em tempo real aplicada em todas as telas")


_quantum_apply_live_screen_patch()



