        self.lbl_total_valor = ttk.Label(total_frame, text="R$ 0,00", font=("Segoe UI", scale_font_size(34 if modo_supermercado else 16, self.root), "bold"), anchor=tk.E, foreground="#16a34a" if modo_supermercado else "#16a34a")
