    def _quantum_refresh_products(self):
        """Atualização quântica: Recarrega produtos em tempo real."""
        try:
            if not self.is_running:
                return
            new_products = load_data(PRODUCTS_FILE, {})
            if new_products != self.products:
                self.products = new_products
                self._filtrar_produtos()
                # Atualiza categorias também
                self.categories = load_data(CATEGORIES_FILE, {})
                self._update_category_filter_options()  # FIX: nome correto do método
        except Exception as e:
            print(f"[QuantumSync] Erro refresh produtos: {e}")
    
