        # Treeview
        cols_v = ('id', 'codigo', 'valor_original', 'valor_restante', 'cliente', 'motivo', 'status', 'data_criacao', 'usuario')
        tree_v = ttk.Treeview(tab_ativos, columns=cols_v, show='headings', height=15)
        
