        tree_v.heading('motivo', text='Motivo')
        tree_v.heading('status', text='Status')
        tree_v.heading('data_criacao', text='Data Criação')
        tree_v.heading('usuario', text='Criado Por')
        
        tree_v.column('id', width=50, anchor=tk.CENTER)
        tree_v.column('codigo', width=90, anchor=tk.CENTER)
        tree_v.column('valor_original', width=110, anchor=tk.E)
        tree_v.column('valor_restante', width=110, anchor=tk.E)
        tree_v.column('cliente', width=180)
        tree_v.column('motivo', width=180)
        tree_v.column('status', width=90, anchor=tk.CENTER)
        tree_v.column('data_criacao', width=140, anchor=tk.CENTER)
        tree_v.column('usuario', width=120)
        
