            def navegar_baixo(event=None):
                """Navega para baixo na lista"""
                if cliente_listbox.size() > 0:
                    current = cliente_listbox.curselection()
                    if current:
                        idx = current[0]
                        if idx < cliente_listbox.size() - 1:
                            cliente_listbox.selection_clear(0, tk.END)
                            cliente_listbox.selection_set(idx + 1)
                            cliente_listbox.see(idx + 1)
                    else:
                        cliente_listbox.selection_set(0)
                return 'break'
            
            def navegar_cima(event=None):
                """Navega para cima na lista"""
                if cliente_listbox.size() > 0:
                    current = cliente_listbox.curselection()
                    if current:
                        idx = current[0]
                        if idx > 0:
                            cliente_listbox.selection_clear(0, tk.END)
                            cliente_listbox.selection_set(idx - 1)
                            cliente_listbox.see(idx - 1)
                return 'break'
            
            # Frame de botões
