# ═══════════════════════════════════════════════════════════════════════════════
# 🚀 BOOT ANTI-TRAVAMENTO APÓS INTEGRIDADE
# ═══════════════════════════════════════════════════════════════════════════════
# Algumas verificações avançadas são úteis, mas não podem prender a abertura do
# sistema. Este executor roda a verificação em thread daemon e libera o boot se
# ultrapassar o limite. A auditoria continua registrando o que acontecer.
def executar_bootstrap_com_timeout(nome, func, timeout_segundos=8, obrigatorio=False):
    resultado = {'ok': False, 'erro': None, 'timeout': False}
    def _runner():
        try:
            resultado['ok'] = bool(func())
        except Exception as e:
            resultado['erro'] = e
            try:
                AUDITORIA.erro(f"Bootstrap {nome} falhou", exception=e)
            except Exception:
                pass
    try:
        import threading as _thread_boot
        t = _thread_boot.Thread(target=_runner, daemon=True, name=f"boot-{str(nome).replace(' ', '-').lower()}")
        t.start()
        t.join(float(timeout_segundos or 8))
        if t.is_alive():
            resultado['timeout'] = True
            msg = f"[BOOT] {nome} excedeu {timeout_segundos}s; sistema continuará abrindo e a tarefa seguirá em segundo plano."
            print(msg)
            try:
                AUDITORIA.erro(msg)
            except Exception:
                pass
            if obrigatorio:
                raise TimeoutError(msg)
            return False
        if resultado['erro'] is not None:
            if obrigatorio:
                raise resultado['erro']
            print(f"[BOOT] Aviso em {nome}: {resultado['erro']}")
            return False
        return bool(resultado['ok'])
    except Exception as e:
        try:
            AUDITORIA.erro(f"Falha no executor anti-travamento {nome}", exception=e)
        except Exception:
            pass
        if obrigatorio:
            raise
        return False

