QUANTUM_BOOT_HEAVY_TASKS_DEFERRED = True

def _quantum_run_background(nome, func, *args, **kwargs):
    def _worker():
        try:
            print(f"[BOOT-BG] Iniciando: {nome}")
            try:
                AUDITORIA.processo(f"Tarefa em segundo plano iniciada: {nome}")
            except Exception:
                pass
            func(*args, **kwargs)
            print(f"[BOOT-BG] Concluído: {nome}")
        except Exception as e:
            print(f"[BOOT-BG] Aviso em {nome}: {e}")
            try:
                AUDITORIA.erro(f"Falha em tarefa de segundo plano: {nome}", exception=e)
            except Exception:
                pass
    try:
        import threading
        t = threading.Thread(target=_worker, daemon=True, name=f"quantum-bg-{nome[:24]}")
        t.start()
        return t
    except Exception as e:
        print(f"[BOOT-BG] Não foi possível iniciar {nome}: {e}")
        return None

def _quantum_agendar_pos_boot(root):
    tarefas = []
    try:
        _cfg_boot = load_data(CONFIG_FILE, DEFAULT_CONFIG) or {}
    except Exception:
        _cfg_boot = dict(DEFAULT_CONFIG)

    # IMPORTANTE: nenhuma verificação pesada deve rodar por padrão.
    # Só agenda tarefas de auditoria/persistência/performance se o usuário ativar
    # explicitamente os checkboxes em Configurações e reiniciar.
    _permitir_verificacoes = bool(_cfg_boot.get('feature_full_migration_on_boot', False))
    _permitir_performance = bool(_cfg_boot.get('feature_full_performance_profile', False))
    _permitir_auto_heal = bool(_cfg_boot.get('feature_auto_heal_startup', False))

    if _permitir_verificacoes and 'verificar_persistencia_total_inicial' in globals():
        tarefas.append(('Persistência total pós-boot', verificar_persistencia_total_inicial))
    if _permitir_performance and 'verificar_performance_senior_inicial' in globals():
        tarefas.append(('Performance Senior pós-boot', verificar_performance_senior_inicial))
    if _permitir_auto_heal and 'aplicar_otimizacoes_boot_seguro' in globals():
        tarefas.append(('Otimizações seguras pós-boot', aplicar_otimizacoes_boot_seguro))
    def _start_all():
        if not tarefas:
            print('[BOOT] Tarefas pesadas pós-boot desativadas nas Configurações.')
            return
        print('[BOOT] Sistema visual aberto; tarefas pesadas autorizadas seguem em segundo plano.')
        for nome, func in tarefas:
            _quantum_run_background(nome, func)
    try:
        root.after(1500, _start_all)
    except Exception:
        _start_all()



