# HOTFIX SÊNIOR - COUVERT/MESAS/COMANDAS SEM TRAVAR + MIGRAÇÃO ACUMULADA
# ═══════════════════════════════════════════════════════════════════════════════
# Objetivo:
# 1) Impedir travamento da janela Configurações ao salvar Couvert.
# 2) Garantir que mesa aberta encontre sua comanda vinculada.
# 3) Persistir mesa_id, mesa_numero e mesa_nome na tabela comandas.
# 4) Manter migração automática para banco antigo, sem apagar dados.
# 5) Evitar dupla gravação pesada no módulo Gerenciamento de Mesas.
# ═══════════════════════════════════════════════════════════════════════════════

_QUANTUM_MESA_COMANDA_COLS_OK = False
_QUANTUM_MESA_COMANDA_COLS_LOCK = threading.RLock()


def _quantum_row_get(row, key, default=''):
    try:
        if row is None:
            return default
        if hasattr(row, 'get'):
            return row.get(key, default)
        return row[key]
    except Exception:
        return default


def quantum_garantir_colunas_comandas_mesa(silencioso=True):
    """Migração leve e idempotente para bancos antigos: adiciona vínculo Mesa ⇄ Comanda."""
    global _QUANTUM_MESA_COMANDA_COLS_OK
    if _QUANTUM_MESA_COMANDA_COLS_OK:
        return True
    with _QUANTUM_MESA_COMANDA_COLS_LOCK:
        if _QUANTUM_MESA_COMANDA_COLS_OK:
            return True
        try:
            conn = MySQLDB.get_connection()
            cur = conn.cursor(dictionary=True)
            try:
                cur.execute("SHOW COLUMNS FROM comandas")
                existentes = {str(r.get('Field') or '').lower() for r in (cur.fetchall() or [])}
            except Exception:
                existentes = set()
            colunas = {
                'mesa_id': "ALTER TABLE comandas ADD COLUMN mesa_id VARCHAR(120) DEFAULT ''",
                'mesa_numero': "ALTER TABLE comandas ADD COLUMN mesa_numero VARCHAR(120) DEFAULT ''",
                'mesa_nome': "ALTER TABLE comandas ADD COLUMN mesa_nome VARCHAR(255) DEFAULT ''",
                'cliente_id': "ALTER TABLE comandas ADD COLUMN cliente_id VARCHAR(120) DEFAULT '1'",
            }
            adicionadas = []
            for nome, ddl in colunas.items():
                if nome.lower() not in existentes:
                    try:
                        cur.execute(ddl)
                        adicionadas.append(nome)
                    except Exception as e:
                        # Coluna já existe ou banco não permite no momento; segue sem travar.
                        if not silencioso:
                            print(f"[MIGRAÇÃO MESAS] Aviso ao adicionar coluna {nome}: {e}")
            try:
                if not getattr(conn, 'autocommit', True):
                    conn.commit()
            except Exception:
                pass
            try:
                cur.close()
            except Exception:
                pass
            _QUANTUM_MESA_COMANDA_COLS_OK = True
            if adicionadas:
                print(f"[MIGRAÇÃO MESAS] Colunas adicionadas em comandas: {', '.join(adicionadas)}")
                try:
                    AUDITORIA.banco_dados(f"Migração mesas/comandas aplicada: {', '.join(adicionadas)}")
                except Exception:
                    pass
            return True
        except Exception as e:
            if not silencioso:
                print(f"[MIGRAÇÃO MESAS] Falha ao verificar colunas de comandas: {e}")
            try:
                AUDITORIA.erro("Falha na migração mesas/comandas", exception=e)
            except Exception:
                pass
            return False


def quantum_salvar_config_rapido(data):
    """Salva Configurações EXCLUSIVAMENTE no config.json.
    Não grava no banco de dados para os checkboxes persistirem exatamente como o usuário marcou/desmarcou.
    """
    try:
        cfg = dict(data or {})
        try:
            _ensure_parent_dir(CONFIG_FILE)
        except Exception:
            pass
        ok = _internal_save(CONFIG_FILE, cfg)
        if ok:
            try:
                if 'QUANTUM_CONFIG_CACHE' in globals():
                    QUANTUM_CONFIG_CACHE.clear()
            except Exception:
                pass
            try:
                _qs = get_quantum_sync()
                if _qs:
                    _qs.notify_change('config')
            except Exception:
                pass
            try:
                AUDITORIA.configuracao(f"Configurações salvas exclusivamente no config.json: {CONFIG_FILE}")
            except Exception:
                pass
        return bool(ok)
    except Exception as e:
        print(f"[CONFIG] Falha ao salvar exclusivamente no config.json: {e}")
        try:
            AUDITORIA.erro("Falha ao salvar configurações no config.json", exception=e)
        except Exception:
            pass
        return False


def _quantum_json_load_items(raw):
    try:
        if not raw:
            return []
        if isinstance(raw, list):
            return raw
        return json.loads(raw)
    except Exception:
        return []


def _quantum_mysql_load_comandas_corrigido():
    """Carrega comandas abertas preservando vínculo com mesa."""
    quantum_garantir_colunas_comandas_mesa(silencioso=True)
    db = get_db()
    rows = db.fetchall("SELECT * FROM comandas WHERE status = 'aberta' ORDER BY numero")
    result = {}
    for row in rows:
        itens_raw = _quantum_json_load_items(_quantum_row_get(row, 'itens', '[]'))
        itens_formatados = []
        for item in itens_raw:
            if not isinstance(item, dict):
                continue
            itens_formatados.append({
                'id': item.get('id'),
                'nome': item.get('nome', 'Produto'),
                'quantidade': item.get('qtd', item.get('quantidade', 1)),
                'qtd': item.get('qtd', item.get('quantidade', 1)),
                'preco_unit': item.get('preco', item.get('preco_unit', 0)),
                'preco': item.get('preco', item.get('preco_unit', 0)),
                'subtotal': item.get('subtotal', 0),
                'observacao': item.get('observacao', ''),
                'feito_cozinha': item.get('feito_cozinha', False),
                'feito_por': item.get('feito_por', ''),
                'feito_em': item.get('feito_em', ''),
                'excluido': item.get('excluido', False),
                # preserva campos extras úteis
                **{k: v for k, v in item.items() if k not in ('id','nome','qtd','quantidade','preco','preco_unit','subtotal','observacao','feito_cozinha','feito_por','feito_em','excluido')}
            })
        numero = str(_quantum_row_get(row, 'numero', '') or '').strip()
        if not numero:
            continue
        result[numero] = {
            'cliente': _quantum_row_get(row, 'cliente', 'Consumidor Final') or 'Consumidor Final',
            'cliente_id': str(_quantum_row_get(row, 'cliente_id', '1') or '1'),
            'observacao': _quantum_row_get(row, 'observacao', '') or '',
            'itens': itens_formatados,
            'status': _quantum_row_get(row, 'status', 'aberta') or 'aberta',
            'abertura': str(_quantum_row_get(row, 'created_at', '') or ''),
            'mesa_id': str(_quantum_row_get(row, 'mesa_id', '') or ''),
            'mesa_numero': str(_quantum_row_get(row, 'mesa_numero', '') or ''),
            'mesa_nome': str(_quantum_row_get(row, 'mesa_nome', '') or ''),
            'sinalizada_para_fechar': bool(_quantum_row_get(row, 'sinalizada_para_fechar', 0)),
            'sinalizada_por': _quantum_row_get(row, 'sinalizada_por', '') or '',
            'concluida_cozinha': bool(_quantum_row_get(row, 'oculto_cozinha', 0)),
            'concluida_cozinha_por': _quantum_row_get(row, 'oculto_cozinha_por', '') or '',
            'concluida_cozinha_em': _quantum_row_get(row, 'oculto_cozinha_em', '') or ''
        }
    return result


def _quantum_mysql_save_comandas_corrigido(data):
    """Salva comandas abertas sem perder mesa_id/mesa_numero e sem fechar comandas de outras máquinas."""
    quantum_garantir_colunas_comandas_mesa(silencioso=True)
    conn = MySQLDB.get_connection()
    cur = conn.cursor(dictionary=True)
    try:
        numeros_ativos = [str(n) for n in (data or {}).keys()]
        # Fecha somente comandas removidas desta estação, mas não mata comandas de outras máquinas se data vier vazio por falha.
        if numeros_ativos:
            placeholders = ','.join(['%s'] * len(numeros_ativos))
            cur.execute(f"UPDATE comandas SET status = 'fechada', updated_at = CURRENT_TIMESTAMP WHERE status = 'aberta' AND numero NOT IN ({placeholders})", tuple(numeros_ativos))
        for numero, comanda_data in (data or {}).items():
            numero = str(numero)
            if not isinstance(comanda_data, dict):
                continue
            itens_json = json.dumps(comanda_data.get('itens', []), ensure_ascii=False)
            params = (
                comanda_data.get('cliente', 'Consumidor Final'),
                str(comanda_data.get('cliente_id', '1') or '1'),
                comanda_data.get('observacao', ''),
                itens_json,
                str(comanda_data.get('mesa_id', '') or ''),
                str(comanda_data.get('mesa_numero', '') or ''),
                str(comanda_data.get('mesa_nome', '') or ''),
                numero
            )
            cur.execute("SELECT id FROM comandas WHERE numero = %s LIMIT 1", (numero,))
            existing = cur.fetchone()
            if existing:
                cur.execute("""
                    UPDATE comandas SET
                        cliente = %s,
                        cliente_id = %s,
                        observacao = %s,
                        itens = %s,
                        mesa_id = %s,
                        mesa_numero = %s,
                        mesa_nome = %s,
                        status = 'aberta',
                        updated_at = CURRENT_TIMESTAMP
                    WHERE numero = %s
                """, params)
            else:
                cur.execute("""
                    INSERT INTO comandas
                        (numero, cliente, cliente_id, observacao, itens, mesa_id, mesa_numero, mesa_nome, status)
                    VALUES
                        (%s, %s, %s, %s, %s, %s, %s, %s, 'aberta')
                """, (
                    numero,
                    comanda_data.get('cliente', 'Consumidor Final'),
                    str(comanda_data.get('cliente_id', '1') or '1'),
                    comanda_data.get('observacao', ''),
                    itens_json,
                    str(comanda_data.get('mesa_id', '') or ''),
                    str(comanda_data.get('mesa_numero', '') or ''),
                    str(comanda_data.get('mesa_nome', '') or '')
                ))
        try:
            if not getattr(conn, 'autocommit', True):
                conn.commit()
        except Exception:
            pass
        return True
    finally:
        try:
            cur.close()
        except Exception:
            pass

# Sobrescreve funções globais para todo o sistema usar a versão corrigida.
_mysql_load_comandas = _quantum_mysql_load_comandas_corrigido
_mysql_save_comandas = _quantum_mysql_save_comandas_corrigido

