# Patches em GerenciamentoMesasWindow: procura por comanda_atual, não bloqueia duplamente e repara vínculo.
def _quantum_gm_comanda_aberta_da_mesa(self, mesa_id, mesa=None):
    mesa = mesa or self.mesas.get(str(mesa_id), {}) or {}
    mid = str(mesa_id)
    numero_mesa = str(mesa.get('numero', '') or '').strip()
    comanda_atual = str(mesa.get('comanda_atual', '') or '').strip()

    # 1) Primeiro respeita o vínculo salvo na própria mesa.
    if comanda_atual:
        dados = (self.comandas or {}).get(comanda_atual)
        if not dados:
            try:
                if self.app is not None and hasattr(self.app, 'comanda_manager'):
                    self.app.comanda_manager.comandas = self.app.comanda_manager._load_comandas()
                    dados = self.app.comanda_manager.comandas.get(comanda_atual)
                    if dados:
                        self.comandas[comanda_atual] = dados
            except Exception:
                dados = None
        if dados and not dados.get('fechada') and not dados.get('paga'):
            # Repara dados antigos que não tinham mesa_id/mesa_numero.
            changed = False
            if not str(dados.get('mesa_id', '') or '').strip():
                dados['mesa_id'] = mid; changed = True
            if numero_mesa and not str(dados.get('mesa_numero', '') or '').strip():
                dados['mesa_numero'] = numero_mesa; changed = True
            if not str(dados.get('mesa_nome', '') or '').strip() and str(mesa.get('nome','') or '').strip():
                dados['mesa_nome'] = str(mesa.get('nome','') or '').strip(); changed = True
            if changed:
                try:
                    self.comandas[comanda_atual] = dados
                    _mysql_save_comandas(self.comandas)
                except Exception:
                    pass
            return comanda_atual, dados

    # 2) Depois procura por mesa_id/mesa_numero dentro das comandas abertas.
    for num, dados in (self.comandas or {}).items():
        if not isinstance(dados, dict) or dados.get('fechada') or dados.get('paga'):
            continue
        if str(dados.get('mesa_id', '') or '').strip() == mid or (numero_mesa and str(dados.get('mesa_numero', '') or '').strip() == numero_mesa):
            return str(num), dados
    return None, None


def _quantum_gm_save_comandas(self):
    try:
        _mysql_save_comandas(self.comandas)
    except Exception:
        try:
            save_data(COMANDAS_FILE, self.comandas)
        except Exception:
            pass
    try:
        if hasattr(self.app, 'comanda_manager'):
            self.app.comanda_manager.comandas = dict(self.comandas or {})
            self.app.comanda_manager._last_comandas_hash = self.app.comanda_manager._get_comandas_hash()
            try:
                self.app.comanda_manager._notify_web_server('updated', None)
            except Exception:
                pass
    except Exception:
        pass


def _quantum_gm_abrir_comanda(self, mesa_id):
    mesa = self.mesas.get(str(mesa_id), {}) or {}
    # Recarrega comandas abertas sem destruir o vínculo local.
    try:
        self.comandas = _mysql_load_comandas()
    except Exception:
        pass
    num, dados = self._comanda_aberta_da_mesa(mesa_id, mesa)
    if not num:
        # Se a mesa está ocupada mas perdeu o número, oferece reparo criando a comanda.
        if str(mesa.get('status', '') or '').lower() == 'ocupada':
            if messagebox.askyesno(
                'Reparar comanda da mesa',
                'Esta mesa está marcada como ocupada, mas o vínculo da comanda não foi encontrado.\n\nDeseja criar/revincular uma nova comanda agora?',
                parent=self
            ):
                return self.ocupar_mesa(mesa_id)
        messagebox.showwarning('Sem comanda', 'Esta mesa não possui comanda aberta vinculada. Use Ocupar/Abrir para criar.', parent=self)
        return
    try:
        if hasattr(self.app, 'comanda_manager'):
            self.app.comanda_manager.comandas = self.app.comanda_manager._load_comandas()
            # Garante que a comanda existe no gerenciador mesmo se veio de cache local.
            if num not in self.app.comanda_manager.comandas and dados:
                self.app.comanda_manager.comandas[num] = dados
            self.app.comanda_manager.gerenciar_comanda(num)
        else:
            messagebox.showinfo('Comanda', f'Comanda #{num} encontrada para esta mesa.', parent=self)
    except Exception as e:
        messagebox.showerror('Erro', f'Não foi possível abrir a comanda #{num}:\n{e}', parent=self)

try:
    GerenciamentoMesasWindow._comanda_aberta_da_mesa = _quantum_gm_comanda_aberta_da_mesa
    GerenciamentoMesasWindow._save_comandas = _quantum_gm_save_comandas
    GerenciamentoMesasWindow.abrir_comanda = _quantum_gm_abrir_comanda
except Exception as _e_patch_mesas:
    print(f'[PATCH MESAS] Aviso: não foi possível aplicar patch de mesas/comandas: {_e_patch_mesas}')

