# 🚀 CARGA PESADA ADIADA - DADOS COMPLETOS APÓS A JANELA APARECER
# ═══════════════════════════════════════════════════════════════════════
def _quantum_carregar_dados_pesados_pos_interface(self):
    """Carrega dados que antes travavam a abertura. Roda após a tela aparecer."""
    import threading as _thr
    def _worker():
        print('[BOOT-DADOS] Carregando dados completos em segundo plano...')
        try:
            dados = {}
            for nome, arquivo, padrao in [
                ('products', PRODUCTS_FILE, {}),
                ('categories', CATEGORIES_FILE, DEFAULT_CATEGORIES),
                ('customers', CUSTOMERS_FILE, DEFAULT_CUSTOMERS),
                ('suppliers', SUPPLIERS_FILE, {}),
                ('entregadores', ENTREGADORES_FILE, {}),
                ('servicos', SERVICES_FILE, {}),
                ('bairros', BAIRROS_FILE, {}),
                ('tamanhos', 'tamanhos.json', {}),
                ('cartoes', CARTOES_FILE, {}),
                ('vendedores', VENDEDORES_FILE, {}),
                ('garcons', GARCONS_FILE, {}),
                ('mesas', MESAS_FILE, {}),
                ('empresa_data', EMPRESA_FILE, DEFAULT_EMPRESA),
            ]:
                try:
                    dados[nome] = load_data(arquivo, padrao)
                except Exception as e:
                    print(f'[BOOT-DADOS] Aviso ao carregar {nome}: {e}')
                    dados[nome] = padrao.copy() if isinstance(padrao, dict) else padrao
            # sales_log pode ser muito grande; deixa sob demanda para relatórios.
            def _aplicar():
                try:
                    for k, v in dados.items():
                        setattr(self, k, v)
                    try:
                        self.refresh_data_views()
                    except Exception as e:
                        print(f'[BOOT-DADOS] Refresh pós-carga ignorado: {e}')
                    print('[BOOT-DADOS] Dados completos aplicados na interface.')
                except Exception as e:
                    print(f'[BOOT-DADOS] Erro ao aplicar dados completos: {e}')
            try:
                self.root.after(0, _aplicar)
            except Exception:
                pass
        except Exception as e:
            print(f'[BOOT-DADOS] Falha na carga de dados em segundo plano: {e}')
    try:
        _thr.Thread(target=_worker, daemon=True, name='quantum-load-data-bg').start()
    except Exception as e:
        print(f'[BOOT-DADOS] Não foi possível iniciar thread: {e}')

try:
    PDVSuperApp._carregar_dados_pesados_pos_interface = _quantum_carregar_dados_pesados_pos_interface
except Exception:
    pass


