try:
    _QUANTUM_CONFIG_JSON_ONLY_ORIGINAL_LOAD_DATA = load_data
    _QUANTUM_CONFIG_JSON_ONLY_ORIGINAL_SAVE_DATA = save_data

    def _quantum_is_config_file_path(_filepath):
        try:
            fp = str(_filepath or '')
            return os.path.basename(fp).lower() == 'config.json' or os.path.abspath(fp) == os.path.abspath(CONFIG_FILE)
        except Exception:
            return 'config.json' in str(_filepath or '').lower()

    def load_data_config_json_only(filepath, default_data=None):
        if _quantum_is_config_file_path(filepath):
            return _load_json_fallback(filepath, default_data if default_data is not None else {})
        return _QUANTUM_CONFIG_JSON_ONLY_ORIGINAL_LOAD_DATA(filepath, default_data)

    def save_data_config_json_only(filepath, data):
        if _quantum_is_config_file_path(filepath):
            return _internal_save(filepath, data)
        return _QUANTUM_CONFIG_JSON_ONLY_ORIGINAL_SAVE_DATA(filepath, data)

    def quantum_salvar_config_rapido(data):
        try:
            return _internal_save(CONFIG_FILE, dict(data or {}))
        except Exception as e:
            print(f"[CONFIG] Falha ao salvar config.json: {e}")
            return False

    load_data = load_data_config_json_only
    save_data = save_data_config_json_only
    globals()['load_data'] = load_data_config_json_only
    globals()['save_data'] = save_data_config_json_only
    globals()['quantum_salvar_config_rapido'] = quantum_salvar_config_rapido
    print(f"[CONFIG] Modo config.json exclusivo ativado: {CONFIG_FILE}")
except Exception as _cfg_json_only_err:
    print(f"[CONFIG] Aviso: não foi possível ativar modo config.json exclusivo: {_cfg_json_only_err}")


