def _qpa_all_permission_labels():
    labels = {}
    try:
        for grupo in globals().get('PERMISSION_GROUPS', {}).values():
            labels.update(grupo)
    except Exception:
        pass
    for grupo in ATOMIC_PERMISSION_GROUPS_FARMA.values():
        labels.update(grupo)
    return labels


def _qpa_all_permissions():
    return sorted(_qpa_all_permission_labels().keys())


def _qpa_expand_wildcards(perms):
    catalogo = _qpa_all_permissions()
    resultado = set()
    for p in perms or []:
        if not p:
            continue
        p = str(p).strip()
        if p == '*':
            return ['*']
        if p.endswith('.*'):
            prefixo = p[:-1]
            achou = False
            for c in catalogo:
                if c.startswith(prefixo):
                    resultado.add(c)
                    achou = True
            if not achou:
                resultado.add(p)
        else:
            resultado.add(p)
    return sorted(resultado)


def _qpa_user_effective_permissions(user_data):
    if not isinstance(user_data, dict):
        return []
    nivel = str(user_data.get('nivel_acesso') or '').strip()
    perms = list(user_data.get('permissoes') or user_data.get('permissions') or [])
    try:
        role = globals().get('ROLES', {}).get(nivel, {})
        for p in role.get('permissions', []) or []:
            if p not in perms:
                perms.append(p)
    except Exception:
        pass
    return _qpa_expand_wildcards(perms)


def _qpa_has_permission(perms, permission):
    if not permission:
        return True, 'sem permissão exigida'
    if '*' in perms or 'admin.total' in perms:
        return True, 'permissão total'
    if permission in perms:
        return True, 'permissão exata'
    parts = str(permission).split('.')
    for i in range(len(parts), 0, -1):
        wildcard = '.'.join(parts[:i]) + '.*'
        if wildcard in perms:
            return True, f'herdada por {wildcard}'
    aliases = []
    aliases.extend(ATOMIC_PERMISSION_ALIASES_FARMA.get(permission, []))
    try:
        aliases.extend(globals().get('PERMISSION_ALIASES', {}).get(permission, []))
    except Exception:
        pass
    for a in aliases:
        ok, motivo = _qpa_has_permission(perms, a)
        if ok:
            return True, f'alias {a} ({motivo})'
    # compatibilidade reversa: se uma permissão atômica aparece como alias de permissão antiga
    for antiga, novas in ATOMIC_PERMISSION_ALIASES_FARMA.items():
        if permission in novas:
            ok, motivo = _qpa_has_permission(perms, antiga)
            if ok:
                return True, f'compatibilidade reversa {antiga} ({motivo})'
    return False, 'não encontrada na matriz efetiva'


def _qpa_integrar_catalogo_permissoes():
    try:
        pg = globals().setdefault('PERMISSION_GROUPS', {})
        for grupo, itens in ATOMIC_PERMISSION_GROUPS_FARMA.items():
            destino = pg.setdefault(grupo, {})
            destino.update(itens)
        labels = globals().setdefault('PERMISSION_LABELS', {})
        labels.update(_qpa_all_permission_labels())
        allp = globals().setdefault('ALL_PERMISSIONS', [])
        for p in _qpa_all_permissions():
            if p not in allp:
                allp.append(p)
        allp[:] = sorted(set(allp))
        aliases = globals().setdefault('PERMISSION_ALIASES', {})
        for k, vals in ATOMIC_PERMISSION_ALIASES_FARMA.items():
            atual = set(aliases.get(k, []))
            atual.update(vals)
            aliases[k] = sorted(atual)
        roles = globals().setdefault('ROLES', {})
        # Não mexe no admin, apenas acrescenta perfis auxiliares caso não existam.
        for nome, perms in ATOMIC_PROFILE_TEMPLATES_FARMA.items():
            key = nome.lower().replace(' ', '_').replace('/', '_')
            if key not in roles and nome != 'Administrador Total':
                roles[key] = {'description': nome, 'permissions': perms}
        if 'admin' in roles:
            roles['admin']['permissions'] = ['*']
        try:
            AUDITORIA.seguranca(f'{QUANTUM_ATOMIC_PERMISSION_PATCH_VERSION}: catálogo atômico integrado com {len(_qpa_all_permissions())} permissões')
        except Exception:
            pass
    except Exception as e:
        print(f'[PERMISSÕES ATÔMICAS] Falha ao integrar catálogo: {e}')


def _qpa_patch_check_permission():
    try:
        if globals().get('_QPA_CHECK_PERMISSION_PATCHED'):
            return
        original = globals().get('check_permission')
        if not callable(original):
            return
        globals()['_QPA_ORIGINAL_CHECK_PERMISSION'] = original
        def check_permission_atomic(permission_name):
            try:
                usuario = globals().get('logged_user')
                dados = globals().get('logged_user_data')
                if usuario in ('adm', 'phda'):
                    return True
                if not dados:
                    return False
                perms = _qpa_user_effective_permissions(dados)
                ok, motivo = _qpa_has_permission(perms, permission_name)
                if ok:
                    return True
                # consulta final ao motor antigo para retrocompatibilidade
                try:
                    antigo_ok = original(permission_name)
                    if antigo_ok:
                        return True
                except Exception:
                    pass
                try:
                    AUDITORIA.seguranca(f"Permissão NEGADA/ATÔMICA: '{permission_name}' usuário='{usuario}' motivo='{motivo}'")
                except Exception:
                    pass
                return False
            except Exception:
                try:
                    return original(permission_name)
                except Exception:
                    return False
        globals()['check_permission'] = check_permission_atomic
        globals()['_QPA_CHECK_PERMISSION_PATCHED'] = True
    except Exception as e:
        print(f'[PERMISSÕES ATÔMICAS] Falha ao reforçar check_permission: {e}')


def _qpa_auditar_cobertura_permissoes():
    """Retorna relatório sênior de cobertura: catálogo, uso no código, aliases e componentes."""
    import re as _re
    rel = []
    labels = _qpa_all_permission_labels()
    catalogo = set(labels.keys())
    usadas = set()
    try:
        with open(__file__, 'r', encoding='utf-8', errors='ignore') as fp:
            codigo = fp.read()
        for m in _re.finditer(r"check_permission(?:_any|_all)?\(([^\)]*)\)", codigo):
            for s in _re.finditer(r"['\"]([a-zA-Z0-9_]+\.[a-zA-Z0-9_*]+)['\"]", m.group(1)):
                usadas.add(s.group(1))
    except Exception as e:
        rel.append(f'Não foi possível ler o código para auditoria: {e}')
    faltantes = sorted(p for p in usadas if p not in catalogo and not p.endswith('.*'))
    sem_uso = sorted(p for p in catalogo if p not in usadas and not any(p.startswith(w[:-1]) for w in usadas if w.endswith('.*')))
    rel.append('RELATÓRIO DE AUDITORIA DE PERMISSÕES ATÔMICAS')
    rel.append('=' * 72)
    rel.append(f'Versão do patch: {QUANTUM_ATOMIC_PERMISSION_PATCH_VERSION}')
    rel.append(f'Total no catálogo: {len(catalogo)}')
    rel.append(f'Permissões chamadas no código: {len(usadas)}')
    rel.append(f'Componentes mapeados: {len(ATOMIC_COMPONENT_POLICY_FARMA)}')
    rel.append(f'Aliases/compatibilidades: {sum(len(v) for v in ATOMIC_PERMISSION_ALIASES_FARMA.values())}')
    rel.append('')
    rel.append('PERMISSÕES CHAMADAS NO CÓDIGO MAS NÃO CADASTRADAS:')
    rel.extend((' - ' + x) for x in (faltantes or ['Nenhuma inconsistência encontrada.']))
    rel.append('')
    rel.append('COMPONENTES ATÔMICOS MAPEADOS:')
    for comp, perm in sorted(ATOMIC_COMPONENT_POLICY_FARMA.items()):
        rel.append(f' - {comp} => {perm}')
    rel.append('')
    rel.append('PERMISSÕES DISPONÍVEIS NO CATÁLOGO AINDA NÃO CHAMADAS DIRETAMENTE NO CÓDIGO:')
    for x in sem_uso[:300]:
        rel.append(' - ' + x)
    if len(sem_uso) > 300:
        rel.append(f' ... mais {len(sem_uso)-300} permissões')
    return '\n'.join(rel)


class QuantumAtomicPermissionsWindow(tk.Toplevel):
    def __init__(self, app=None, master=None):
        super().__init__(master or getattr(app, 'root', None))
        self.app = app
        self.title('🔐 Permissões Atômicas e Granulares - Farmácia/Drogaria')
        self.geometry('1280x780')
        try:
            self.state('zoomed')
        except Exception:
            pass
        self.resizable(True, True)
        self.users_data = {}
        self.selected_user = None
        self.active_permissions = set()
        self.filter_var = tk.StringVar()
        self.test_var = tk.StringVar()
        self.status_var = tk.StringVar(value='Pronto')
        self._build()
        self._load_users()
        self._populate_permissions()

    def _build(self):
        top = tk.Frame(self, bg='#0f766e')
        top.pack(fill='x')
        tk.Label(top, text='🔐 Central Sênior de Permissões Atômicas', bg='#0f766e', fg='white', font=('Segoe UI', 16, 'bold')).pack(side='left', padx=14, pady=10)
        tk.Label(top, text='controle por usuário, perfil, tela, botão, campo, memo, ação e relatório', bg='#0f766e', fg='#ccfbf1', font=('Segoe UI', 10)).pack(side='left', padx=8)

        toolbar = tk.Frame(self)
        toolbar.pack(fill='x', padx=10, pady=8)
        ttk.Button(toolbar, text='🔄 Recarregar usuários', command=self._load_users).pack(side='left', padx=3)
        ttk.Button(toolbar, text='✅ Selecionar tudo', command=self._select_all).pack(side='left', padx=3)
        ttk.Button(toolbar, text='🧹 Limpar tudo', command=self._clear_all).pack(side='left', padx=3)
        ttk.Button(toolbar, text='💾 Salvar usuário', command=self._save_selected_user).pack(side='left', padx=3)
        ttk.Button(toolbar, text='🧪 Testar permissão', command=self._test_permission).pack(side='left', padx=3)
        ttk.Button(toolbar, text='📋 Auditar cobertura', command=self._show_audit).pack(side='left', padx=3)
        ttk.Button(toolbar, text='📤 Exportar TXT', command=self._export_matrix).pack(side='left', padx=3)
        ttk.Label(toolbar, text='Filtro:').pack(side='left', padx=(16, 3))
        ent = ttk.Entry(toolbar, textvariable=self.filter_var, width=32)
        ent.pack(side='left')
        ent.bind('<KeyRelease>', lambda e: self._populate_permissions())

        body = tk.PanedWindow(self, orient='horizontal', sashrelief='raised')
        body.pack(fill='both', expand=True, padx=10, pady=(0, 8))

        left = tk.Frame(body)
        body.add(left, width=330)
        ttk.Label(left, text='Usuários do sistema', font=('Segoe UI', 10, 'bold')).pack(anchor='w')
        self.user_tree = ttk.Treeview(left, columns=('nivel', 'qtd'), show='headings', height=14)
        self.user_tree.heading('nivel', text='Usuário / Nível')
        self.user_tree.heading('qtd', text='Perms')
        self.user_tree.column('nivel', width=230, anchor='w')
        self.user_tree.column('qtd', width=70, anchor='center')
        self.user_tree.pack(fill='both', expand=False, pady=5)
        self.user_tree.bind('<<TreeviewSelect>>', lambda e: self._on_user_select())

        ttk.Label(left, text='Perfis rápidos comerciais', font=('Segoe UI', 10, 'bold')).pack(anchor='w', pady=(10, 0))
        self.profile_list = tk.Listbox(left, height=9)
        self.profile_list.pack(fill='both', expand=False, pady=5)
        for nome in ATOMIC_PROFILE_TEMPLATES_FARMA.keys():
            self.profile_list.insert('end', nome)
        ttk.Button(left, text='Aplicar perfil selecionado ao usuário', command=self._apply_profile).pack(fill='x', pady=4)
        ttk.Label(left, text='Permissão para teste:').pack(anchor='w', pady=(4, 0))
        ttk.Entry(left, textvariable=self.test_var).pack(fill='x', pady=3)

        right = tk.Frame(body)
        body.add(right)
        ttk.Label(right, text='Matriz de permissões: duplo clique para marcar/desmarcar', font=('Segoe UI', 10, 'bold')).pack(anchor='w')
        cols = ('ativo', 'codigo', 'descricao')
        self.perm_tree = ttk.Treeview(right, columns=cols, show='tree headings')
        self.perm_tree.heading('#0', text='Grupo')
        self.perm_tree.heading('ativo', text='Ativo')
        self.perm_tree.heading('codigo', text='Código atômico')
        self.perm_tree.heading('descricao', text='Descrição fiel da ação/componente')
        self.perm_tree.column('#0', width=270, anchor='w')
        self.perm_tree.column('ativo', width=70, anchor='center')
        self.perm_tree.column('codigo', width=310, anchor='w')
        self.perm_tree.column('descricao', width=560, anchor='w')
        vsb = ttk.Scrollbar(right, orient='vertical', command=self.perm_tree.yview)
        self.perm_tree.configure(yscrollcommand=vsb.set)
        self.perm_tree.pack(side='left', fill='both', expand=True, pady=5)
        vsb.pack(side='right', fill='y')
        self.perm_tree.bind('<Double-1>', lambda e: self._toggle_selected_permission())

        status = tk.Label(self, textvariable=self.status_var, anchor='w', bg='#ecfeff', fg='#164e63')
        status.pack(fill='x')

    def _load_users(self):
        try:
            self.users_data = load_users() or {}
            for item in self.user_tree.get_children():
                self.user_tree.delete(item)
            for username, data in sorted(self.users_data.items()):
                nivel = data.get('nivel_acesso', '') if isinstance(data, dict) else ''
                perms = _qpa_user_effective_permissions(data)
                self.user_tree.insert('', 'end', iid=username, values=(f'{username}  [{nivel}]', 'TOTAL' if '*' in perms else len(perms)))
            self.status_var.set(f'{len(self.users_data)} usuário(s) carregado(s). Administrador adm/phda continuam sempre com acesso total.')
        except Exception as e:
            messagebox.showerror('Permissões', f'Erro ao carregar usuários:\n{e}', parent=self)

    def _on_user_select(self):
        sel = self.user_tree.selection()
        if not sel:
            return
        self.selected_user = sel[0]
        data = self.users_data.get(self.selected_user, {})
        perms = list(data.get('permissoes') or data.get('permissions') or []) if isinstance(data, dict) else []
        if self.selected_user in ('adm', 'phda'):
            perms = ['*']
        self.active_permissions = set(_qpa_expand_wildcards(perms))
        if '*' in perms:
            self.active_permissions = {'*'}
        self._populate_permissions()
        self.status_var.set(f'Usuário selecionado: {self.selected_user}')

    def _populate_permissions(self):
        filtro = (self.filter_var.get() or '').strip().lower()
        for item in self.perm_tree.get_children():
            self.perm_tree.delete(item)
        groups = globals().get('PERMISSION_GROUPS', {})
        for group_name, perms in sorted(groups.items()):
            linhas = []
            for codigo, desc in sorted((perms or {}).items()):
                texto = f'{codigo} {desc}'.lower()
                if filtro and filtro not in texto and filtro not in group_name.lower():
                    continue
                ativo = '☑' if ('*' in self.active_permissions or codigo in self.active_permissions or any(codigo.startswith(p[:-1]) for p in self.active_permissions if p.endswith('.*'))) else '☐'
                linhas.append((codigo, desc, ativo))
            if not linhas:
                continue
            gid = self.perm_tree.insert('', 'end', text=group_name, values=('', '', f'{len(linhas)} permissão(ões)'))
            for codigo, desc, ativo in linhas:
                self.perm_tree.insert(gid, 'end', iid='perm::' + codigo, text='', values=(ativo, codigo, desc))
            try:
                self.perm_tree.item(gid, open=True)
            except Exception:
                pass

    def _toggle_selected_permission(self):
        sel = self.perm_tree.selection()
        if not sel:
            return
        item = sel[0]
        if not str(item).startswith('perm::'):
            # alterna grupo inteiro
            filhos = self.perm_tree.get_children(item)
            codigos = [self.perm_tree.set(f, 'codigo') for f in filhos]
            if codigos and all(c in self.active_permissions for c in codigos):
                for c in codigos:
                    self.active_permissions.discard(c)
            else:
                self.active_permissions.update(codigos)
        else:
            codigo = self.perm_tree.set(item, 'codigo')
            if codigo in self.active_permissions:
                self.active_permissions.remove(codigo)
            else:
                self.active_permissions.add(codigo)
        self.active_permissions.discard('*')
        self._populate_permissions()

    def _select_all(self):
        self.active_permissions = set(_qpa_all_permissions())
        self._populate_permissions()

    def _clear_all(self):
        self.active_permissions = set()
        self._populate_permissions()

    def _apply_profile(self):
        sel = self.profile_list.curselection()
        if not sel:
            messagebox.showinfo('Perfil', 'Selecione um perfil rápido.', parent=self)
            return
        nome = self.profile_list.get(sel[0])
        perms = ATOMIC_PROFILE_TEMPLATES_FARMA.get(nome, [])
        self.active_permissions = set(_qpa_expand_wildcards(perms)) if perms != ['*'] else {'*'}
        self._populate_permissions()
        self.status_var.set(f'Perfil aplicado na tela: {nome}. Clique em Salvar usuário para gravar.')

    def _save_selected_user(self):
        if not self.selected_user:
            messagebox.showwarning('Permissões', 'Selecione um usuário.', parent=self)
            return
        if self.selected_user in ('adm', 'phda'):
            messagebox.showinfo('Administrador protegido', 'Usuários adm/phda são administradores blindados e permanecem com permissão total (*).', parent=self)
            self.active_permissions = {'*'}
        try:
            users = load_users() or self.users_data or {}
            data = users.get(self.selected_user)
            if not isinstance(data, dict):
                messagebox.showerror('Permissões', 'Usuário não encontrado para salvar.', parent=self)
                return
            perms = ['*'] if self.selected_user in ('adm', 'phda') or '*' in self.active_permissions else sorted(self.active_permissions)
            data['permissoes'] = perms
            if self.selected_user in ('adm', 'phda'):
                data['nivel_acesso'] = 'admin'
            users[self.selected_user] = data
            save_users(users)
            # Atualiza usuário logado se necessário
            if globals().get('logged_user') == self.selected_user:
                globals()['logged_user_data'] = dict(data)
            self.users_data = users
            self._load_users()
            messagebox.showinfo('Permissões salvas', f'Permissões salvas para {self.selected_user}.\nTotal: {"TOTAL" if "*" in perms else len(perms)}', parent=self)
        except Exception as e:
            messagebox.showerror('Permissões', f'Erro ao salvar permissões:\n{e}', parent=self)

    def _test_permission(self):
        if not self.selected_user:
            messagebox.showwarning('Teste', 'Selecione um usuário.', parent=self)
            return
        perm = (self.test_var.get() or '').strip()
        if not perm:
            messagebox.showwarning('Teste', 'Digite uma permissão, exemplo: produto.editar', parent=self)
            return
        data = self.users_data.get(self.selected_user, {})
        perms = _qpa_user_effective_permissions(data)
        ok, motivo = _qpa_has_permission(perms, perm)
        msg = f'Usuário: {self.selected_user}\nPermissão: {perm}\nResultado: {"LIBERADO" if ok else "BLOQUEADO"}\nMotivo: {motivo}'
        messagebox.showinfo('Teste de permissão efetiva', msg, parent=self)

    def _show_audit(self):
        txt = _qpa_auditar_cobertura_permissoes()
        win = tk.Toplevel(self)
        win.title('📋 Auditoria de Cobertura de Permissões')
        win.geometry('1000x700')
        try: win.state('zoomed')
        except Exception: pass
        text = tk.Text(win, wrap='word')
        text.pack(fill='both', expand=True)
        text.insert('1.0', txt)
        text.configure(state='disabled')

    def _export_matrix(self):
        try:
            base = globals().get('PERSISTENCE_DIR') or globals().get('DATA_DIR') or os.getcwd()
            pasta = os.path.join(base, 'relatorios_permissoes')
            os.makedirs(pasta, exist_ok=True)
            caminho = os.path.join(pasta, 'matriz_permissoes_atomicas_farmacia.txt')
            linhas = [_qpa_auditar_cobertura_permissoes(), '\n\nMATRIZ COMPLETA POR GRUPO\n' + '='*72]
            for grupo, perms in sorted(globals().get('PERMISSION_GROUPS', {}).items()):
                linhas.append('\n[' + grupo + ']')
                for cod, desc in sorted((perms or {}).items()):
                    linhas.append(f'{cod} = {desc}')
            with open(caminho, 'w', encoding='utf-8') as f:
                f.write('\n'.join(linhas))
            try:
                os.startfile(caminho)
            except Exception:
                pass
            messagebox.showinfo('Exportado', f'Matriz exportada em:\n{caminho}', parent=self)
        except Exception as e:
            messagebox.showerror('Exportar', f'Erro ao exportar matriz:\n{e}', parent=self)


def _qpa_open_atomic_permissions(self):
    return QuantumAtomicPermissionsWindow(self, getattr(self, 'root', None))


def _qpa_enforce_admin_access():
    try:
        users = load_users() or {}
        changed = False
        for u in ('adm', 'phda'):
            if u in users and isinstance(users[u], dict):
                if users[u].get('permissoes') != ['*'] or users[u].get('nivel_acesso') != 'admin':
                    users[u]['permissoes'] = ['*']
                    users[u]['nivel_acesso'] = 'admin'
                    changed = True
        if changed:
            save_users(users)
    except Exception as e:
        print(f'[PERMISSÕES ATÔMICAS] Aviso ao blindar administradores: {e}')


def _qpa_patch_app():
    try:
        _qpa_integrar_catalogo_permissoes()
        _qpa_patch_check_permission()
        _qpa_enforce_admin_access()
        if 'PDVSuperApp' not in globals():
            return
        if getattr(PDVSuperApp, '_qpa_patch_aplicado', False):
            return
        # A central atômica foi integrada à tela oficial UserManagerWindow.
        # Não cria mais menu/tela separada para evitar duplicidade e confusão operacional.
        def _qpa_open_user_permissions_integrated(app_self):
            try:
                return UserManagerWindow(getattr(app_self, 'root', app_self), app_self)
            except Exception:
                try:
                    return QuantumAtomicPermissionsWindow(app_self, getattr(app_self, 'root', None))
                except Exception as _e_open_perm:
                    print(f'[PERMISSÕES ATÔMICAS] Falha ao abrir permissões integradas: {_e_open_perm}')
        PDVSuperApp.open_permissoes_atomicas = lambda self: _qpa_open_user_permissions_integrated(self)
        _orig_create_menu = PDVSuperApp._create_menu
        def _patched_create_menu(self, *args, **kwargs):
            resultado = _orig_create_menu(self, *args, **kwargs)
            try:
                self.root.bind('<Control-Alt-p>', lambda event: self.open_permissoes_atomicas())
                self.root.bind('<Control-Alt-P>', lambda event: self.open_permissoes_atomicas())
            except Exception as e:
                print(f'[PERMISSÕES ATÔMICAS] Aviso ao registrar atalho integrado: {e}')
            return resultado
        PDVSuperApp._create_menu = _patched_create_menu
        PDVSuperApp._qpa_patch_aplicado = True
        print('[PERMISSÕES ATÔMICAS] Patch aplicado com sucesso.')
    except Exception as e:
        print(f'[PERMISSÕES ATÔMICAS] Falha ao aplicar patch: {e}')

# Integra o catálogo imediatamente; o patch de menu é aplicado no boot quando PDVSuperApp já existe.
try:
    _qpa_integrar_catalogo_permissoes()
    _qpa_patch_check_permission()
except Exception as _e_qpa_init:
    print(f'[PERMISSÕES ATÔMICAS] Inicialização parcial falhou: {_e_qpa_init}')


# ═══════════════════════════════════════════════════════════════════════════════
# ☁️ PATCH BACKUP AUTOMÁTICO FTP - BANCO DE DADOS
# Adiciona submenu "Backup automático" em Utilitários e rotina agendada.
# Recursos:
# - Host/usuário/senha FTP;
# - checkbox para ativar backup automático do banco;
# - intervalo em minutos;
# - nome do arquivo: nomedaempresa_data_hora.sql;
# - nome da empresa buscado no cadastro da empresa;
# - salvamento persistente em config_data / config.json.
# ═══════════════════════════════════════════════════════════════════════════════
try:
    import os as _qftp_os
    import re as _qftp_re
    import time as _qftp_time
    import ftplib as _qftp_ftplib
    import threading as _qftp_threading
    import datetime as _qftp_datetime
    import tempfile as _qftp_tempfile
except Exception:
    pass

_QUANTUM_FTP_BACKUP_DEFAULTS = {
    "auto_backup_ftp_ativo": False,
    "auto_backup_ftp_host": "",
    "auto_backup_ftp_usuario": "",
    "auto_backup_ftp_senha": "",
    "auto_backup_ftp_intervalo_minutos": "60",
    "auto_backup_ftp_pasta_remota": "",
}

def _qftp_bool(v):
    return str(v).strip().lower() in ("1", "true", "sim", "yes", "on", "ativo", "marcado")

def _qftp_safe_name(txt, padrao="EMPRESA"):
    try:
        s = str(txt or '').strip()
        s = _qftp_re.sub(r'[^A-Za-z0-9_\-]+', '_', s)
        s = _qftp_re.sub(r'_+', '_', s).strip('_')
        return s[:80] or padrao
    except Exception:
        return padrao

def _qftp_get_empresa_nome(app=None):
    try:
        emp = getattr(app, 'empresa_data', {}) or {}
        nome = emp.get('nome') or emp.get('nome_fantasia') or emp.get('razao_social') or emp.get('store_name')
        if nome:
            return str(nome)
    except Exception:
        pass
    try:
        emp = load_data(EMPRESA_FILE, DEFAULT_EMPRESA)
        nome = emp.get('nome') or emp.get('nome_fantasia') or emp.get('razao_social')
        if nome:
            return str(nome)
    except Exception:
        pass
    return "EMPRESA"

def _qftp_cfg(app=None):
    cfg = {}
    try:
        if app is not None and isinstance(getattr(app, 'config_data', None), dict):
            cfg.update(app.config_data)
    except Exception:
        pass
    try:
        if not cfg:
            cfg.update(load_data(CONFIG_FILE, DEFAULT_CONFIG) or {})
    except Exception:
        pass
    for k, v in _QUANTUM_FTP_BACKUP_DEFAULTS.items():
        cfg.setdefault(k, v)
    return cfg

def _qftp_save_cfg(app, cfg):
    try:
        base_cfg = dict(getattr(app, 'config_data', {}) or {})
    except Exception:
        base_cfg = {}
    base_cfg.update({k: cfg.get(k, v) for k, v in _QUANTUM_FTP_BACKUP_DEFAULTS.items()})
    try:
        app.config_data = base_cfg
    except Exception:
        pass
    try:
        save_data(CONFIG_FILE, base_cfg)
    except Exception as e:
        try:
            messagebox.showerror("Backup automático", "Não foi possível salvar a configuração:\n" + str(e))
        except Exception:
            pass
        return False
    return True

def _qftp_backup_dir():
    try:
        p = _qftp_os.path.join(r"C:\Quantum", "backups", "automatico")
        _qftp_os.makedirs(p, exist_ok=True)
        return p
    except Exception:
        p = _qftp_os.path.join(_qftp_os.getcwd(), "backups", "automatico")
        _qftp_os.makedirs(p, exist_ok=True)
        return p

def _qftp_sql_quote(v):
    if v is None:
        return 'NULL'
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        return str(v)
    s = str(v).replace('\\', '\\\\').replace("'", "\\'").replace('\n', '\\n').replace('\r', '\\r')
    return "'" + s + "'"

def _qftp_gerar_dump_sql(app=None):
    """Gera backup SQL simples do MySQL usando o conector já usado pelo sistema."""
    empresa = _qftp_safe_name(_qftp_get_empresa_nome(app))
    agora = _qftp_datetime.datetime.now().strftime('%Y%m%d_%H%M%S')
    arquivo = _qftp_os.path.join(_qftp_backup_dir(), f"{empresa}_{agora}.sql")
    db = get_db()
    tabelas = []
    try:
        rows = db.fetchall("SHOW TABLES")
        for r in rows or []:
            try:
                tabelas.append(list(r.values())[0])
            except Exception:
                pass
    except Exception as e:
        raise RuntimeError("Não foi possível listar tabelas do banco: " + str(e))
    with open(arquivo, 'w', encoding='utf-8') as f:
        f.write("-- Backup automático Quantum\n")
        f.write("-- Empresa: " + _qftp_get_empresa_nome(app) + "\n")
        f.write("-- Gerado em: " + _qftp_datetime.datetime.now().strftime('%d/%m/%Y %H:%M:%S') + "\n")
        f.write("SET FOREIGN_KEY_CHECKS=0;\nSET NAMES utf8mb4;\n\n")
        for tabela in tabelas:
            try:
                f.write(f"\n-- ------------------------------------------------------------\n")
                f.write(f"-- Tabela `{tabela}`\n")
                f.write(f"DROP TABLE IF EXISTS `{tabela}`;\n")
                create_row = db.fetchone(f"SHOW CREATE TABLE `{tabela}`")
                create_sql = None
                if create_row:
                    for k, v in create_row.items():
                        if 'create table' in str(k).lower():
                            create_sql = v
                            break
                    if create_sql is None:
                        vals = list(create_row.values())
                        if len(vals) >= 2:
                            create_sql = vals[1]
                if create_sql:
                    f.write(str(create_sql) + ";\n")
                rows = db.fetchall(f"SELECT * FROM `{tabela}`")
                for row in rows or []:
                    cols = list(row.keys())
                    col_sql = ', '.join('`' + c.replace('`','') + '`' for c in cols)
                    val_sql = ', '.join(_qftp_sql_quote(row.get(c)) for c in cols)
                    f.write(f"INSERT INTO `{tabela}` ({col_sql}) VALUES ({val_sql});\n")
            except Exception as e:
                f.write(f"\n-- ERRO AO EXPORTAR `{tabela}`: {e}\n")
        f.write("\nSET FOREIGN_KEY_CHECKS=1;\n")
    return arquivo

def _qftp_enviar_ftp(local_path, cfg):
    host = str(cfg.get('auto_backup_ftp_host') or '').strip()
    user = str(cfg.get('auto_backup_ftp_usuario') or '').strip()
    pwd = str(cfg.get('auto_backup_ftp_senha') or '').strip()
    pasta = str(cfg.get('auto_backup_ftp_pasta_remota') or '').strip().strip('/')
    if not host:
        raise RuntimeError("Host FTP não informado.")
    if not user:
        raise RuntimeError("Usuário FTP não informado.")
    ftp = _qftp_ftplib.FTP(host, timeout=45)
    ftp.login(user=user, passwd=pwd)
    if pasta:
        for parte in [p for p in pasta.split('/') if p]:
            try:
                ftp.cwd(parte)
            except Exception:
                ftp.mkd(parte)
                ftp.cwd(parte)
    with open(local_path, 'rb') as fh:
        ftp.storbinary('STOR ' + _qftp_os.path.basename(local_path), fh)
    try:
        ftp.quit()
    except Exception:
        ftp.close()
    return True

def _qftp_executar_backup(app=None, manual=False):
    cfg = _qftp_cfg(app)
    if not manual and not _qftp_bool(cfg.get('auto_backup_ftp_ativo')):
        return False
    try:
        local = _qftp_gerar_dump_sql(app)
        _qftp_enviar_ftp(local, cfg)
        msg = "Backup automático enviado: " + _qftp_os.path.basename(local)
        try:
            print("[BACKUP-FTP]", msg)
        except Exception:
            pass
        if manual:
            messagebox.showinfo("Backup automático", msg + "\n\nTambém foi salvo localmente em:\n" + local)
        return True
    except Exception as e:
        try:
            print("[BACKUP-FTP] Erro:", e)
        except Exception:
            pass
        if manual:
            messagebox.showerror("Backup automático", "Falha ao gerar/enviar backup:\n" + str(e))
        return False

def _qftp_agendar_proximo(app):
    try:
        cfg = _qftp_cfg(app)
        if not _qftp_bool(cfg.get('auto_backup_ftp_ativo')):
            return
        minutos = int(float(str(cfg.get('auto_backup_ftp_intervalo_minutos') or '60').replace(',', '.')))
        minutos = max(1, minutos)
        ms = minutos * 60 * 1000
        app._qftp_after_id = app.root.after(ms, lambda: _qftp_tick(app))
        print(f"[BACKUP-FTP] Próximo backup em {minutos} minuto(s).")
    except Exception as e:
        print("[BACKUP-FTP] Falha ao agendar:", e)

def _qftp_tick(app):
    def run():
        try:
            _qftp_executar_backup(app, manual=False)
        finally:
            try:
                app.root.after(1000, lambda: _qftp_agendar_proximo(app))
            except Exception:
                pass
    try:
        _qftp_threading.Thread(target=run, daemon=True, name="QuantumFTPBackupAuto").start()
    except Exception:
        run()

def _qftp_iniciar_monitor(app):
    try:
        if getattr(app, '_qftp_monitor_started', False):
            return
        app._qftp_monitor_started = True
        _qftp_agendar_proximo(app)
    except Exception as e:
        print("[BACKUP-FTP] Monitor não iniciado:", e)

def _qftp_show_window(self):
    try:
        if not check_permission_any("backup.automatico.acessar", "util.backup_automatico", "config.backup"):
            messagebox.showerror("Acesso negado", "Você não tem permissão para acessar Backup automático.")
            return
    except Exception:
        pass
    cfg = _qftp_cfg(self)
    win = tk.Toplevel(self.root)
    win.title("☁️ Backup automático do banco de dados por FTP")
    try:
        win.geometry("760x520")
        win.minsize(720, 480)
        win.transient(self.root)
        win.grab_set()
    except Exception:
        pass
    main = ttk.Frame(win, padding=16)
    main.pack(fill=tk.BOTH, expand=True)
    ttk.Label(main, text="☁️ Backup automático do banco de dados", font=("Segoe UI", 16, "bold")).pack(anchor='w')
    ttk.Label(main, text="Configure o envio automático do backup SQL para um servidor FTP. O nome do arquivo usa o cadastro da empresa: nomedaempresa_data_hora.sql.", wraplength=700).pack(anchor='w', pady=(2, 14))

    form = ttk.LabelFrame(main, text="Configuração FTP e periodicidade")
    form.pack(fill=tk.X, pady=(0, 5))
    ativo_var = tk.BooleanVar(value=_qftp_bool(cfg.get('auto_backup_ftp_ativo')))
    host_var = tk.StringVar(value=str(cfg.get('auto_backup_ftp_host') or ''))
    user_var = tk.StringVar(value=str(cfg.get('auto_backup_ftp_usuario') or ''))
    senha_var = tk.StringVar(value=str(cfg.get('auto_backup_ftp_senha') or ''))
    intervalo_var = tk.StringVar(value=str(cfg.get('auto_backup_ftp_intervalo_minutos') or '60'))
    pasta_var = tk.StringVar(value=str(cfg.get('auto_backup_ftp_pasta_remota') or ''))

    ttk.Checkbutton(form, text="Ativar backup automático do banco de dados", variable=ativo_var).grid(row=0, column=0, columnspan=2, sticky='w', padx=10, pady=(10, 6))
    labels = [
        ("Host FTP:", host_var, False),
        ("Usuário FTP:", user_var, False),
        ("Senha FTP:", senha_var, True),
        ("De quanto em quanto tempo (minutos):", intervalo_var, False),
        ("Pasta remota no FTP (opcional):", pasta_var, False),
    ]
    for i, (lbl, var, secret) in enumerate(labels, start=1):
        ttk.Label(form, text=lbl).grid(row=i, column=0, sticky='w', padx=10, pady=5)
        ent = ttk.Entry(form, textvariable=var, width=48, show='*' if secret else '')
        ent.grid(row=i, column=1, sticky='ew', padx=10, pady=5)
    form.columnconfigure(1, weight=1)

    empresa_nome = _qftp_get_empresa_nome(self)
    exemplo = _qftp_safe_name(empresa_nome) + "_" + _qftp_datetime.datetime.now().strftime('%Y%m%d_%H%M%S') + ".sql"
    info = ttk.LabelFrame(main, text="Como o backup será salvo")
    info.pack(fill=tk.X, pady=(0, 5))
    ttk.Label(info, text="Empresa detectada: " + empresa_nome).pack(anchor='w', padx=10, pady=(8, 2))
    ttk.Label(info, text="Exemplo de arquivo: " + exemplo).pack(anchor='w', padx=10, pady=(2, 8))

    status_var = tk.StringVar(value="Preencha os dados e clique em Salvar. Use Testar backup agora para validar o FTP.")
    ttk.Label(main, textvariable=status_var, foreground="#047857", wraplength=700).pack(anchor='w', pady=(0, 8))

    def salvar():
        try:
            if not check_permission_any("backup.automatico.salvar_configuracao", "backup.automatico.configurar_ftp", "config.backup"):
                messagebox.showerror("Acesso negado", "Você não tem permissão para salvar a configuração do backup automático.", parent=win)
                return
        except Exception:
            pass
        try:
            intervalo = int(float(str(intervalo_var.get() or '60').replace(',', '.')))
            if intervalo < 1:
                raise ValueError()
        except Exception:
            messagebox.showwarning("Backup automático", "Informe um intervalo válido em minutos. Exemplo: 30")
            return
        novo = dict(_qftp_cfg(self))
        novo.update({
            'auto_backup_ftp_ativo': bool(ativo_var.get()),
            'auto_backup_ftp_host': host_var.get().strip(),
            'auto_backup_ftp_usuario': user_var.get().strip(),
            'auto_backup_ftp_senha': senha_var.get().strip(),
            'auto_backup_ftp_intervalo_minutos': str(intervalo),
            'auto_backup_ftp_pasta_remota': pasta_var.get().strip(),
        })
        if _qftp_save_cfg(self, novo):
            try:
                if hasattr(self, '_qftp_after_id'):
                    self.root.after_cancel(self._qftp_after_id)
            except Exception:
                pass
            self._qftp_monitor_started = False
            _qftp_iniciar_monitor(self)
            messagebox.showinfo("Backup automático", "Configuração salva com sucesso.")
            status_var.set("Configuração salva. Backup automático " + ("ATIVO." if ativo_var.get() else "DESATIVADO."))

    def testar():
        try:
            if not check_permission_any("backup.automatico.testar_agora", "backup.automatico.executar", "config.backup"):
                messagebox.showerror("Acesso negado", "Você não tem permissão para testar/executar o backup automático.", parent=win)
                return
        except Exception:
            pass
        salvar()
        status_var.set("Gerando backup e enviando para o FTP. Aguarde...")
        def run():
            ok = _qftp_executar_backup(self, manual=True)
            try:
                win.after(100, lambda: status_var.set("Teste concluído com sucesso." if ok else "Teste concluído com erro. Confira os dados FTP."))
            except Exception:
                pass
        _qftp_threading.Thread(target=run, daemon=True, name="QuantumFTPBackupManual").start()

    botoes = ttk.Frame(main)
    botoes.pack(fill=tk.X, pady=(6, 0))
    ttk.Button(botoes, text="💾 Salvar", command=salvar).pack(side=tk.LEFT, padx=(0, 8))
    ttk.Button(botoes, text="🧪 Testar backup agora", command=testar).pack(side=tk.LEFT, padx=(0, 8))
    ttk.Button(botoes, text="Fechar", command=win.destroy).pack(side=tk.RIGHT)

try:
    if 'PDVSuperApp' in globals():
        PDVSuperApp.show_auto_backup_ftp_window = _qftp_show_window

        _qftp_orig_create_menu = getattr(PDVSuperApp, '_create_menu', None)
        if callable(_qftp_orig_create_menu) and not getattr(PDVSuperApp, '_qftp_menu_patch', False):
            def _qftp_create_menu_patched(self, *args, **kwargs):
                result = _qftp_orig_create_menu(self, *args, **kwargs)
                try:
                    mb = self.root.nametowidget(self.root['menu'])
                    end = mb.index('end')
                    util_menu = None
                    for i in range((end or 0) + 1):
                        try:
                            lbl = str(mb.entrycget(i, 'label')).lower()
                            if 'utilit' in lbl:
                                util_menu = mb.nametowidget(mb.entrycget(i, 'menu'))
                                break
                        except Exception:
                            pass
                    if util_menu is not None:
                        labels = []
                        try:
                            uend = util_menu.index('end')
                            for j in range((uend or 0) + 1):
                                labels.append(str(util_menu.entrycget(j, 'label')))
                        except Exception:
                            pass
                        if not any('backup automático' in x.lower() or 'backup automatico' in x.lower() for x in labels):
                            try:
                                util_menu.add_separator()
                            except Exception:
                                pass
                            
                            if check_permission_any("backup.automatico.acessar", "util.backup_automatico", "config.backup"):
                                util_menu.add_command(label="6.7  ☁️ Backup automático", command=self.show_auto_backup_ftp_window)
                except Exception as e:
                    print('[BACKUP-FTP] Não foi possível adicionar submenu:', e)
                return result
            PDVSuperApp._create_menu = _qftp_create_menu_patched
            PDVSuperApp._qftp_menu_patch = True

        _qftp_orig_init = getattr(PDVSuperApp, '__init__', None)
        if callable(_qftp_orig_init) and not getattr(PDVSuperApp, '_qftp_init_patch', False):
            def _qftp_init_patched(self, *args, **kwargs):
                _qftp_orig_init(self, *args, **kwargs)
                try:
                    cfg = _qftp_cfg(self)
                    for k, v in _QUANTUM_FTP_BACKUP_DEFAULTS.items():
                        self.config_data.setdefault(k, v)
                    self.root.after(2500, lambda: _qftp_iniciar_monitor(self))
                except Exception as e:
                    print('[BACKUP-FTP] Falha no init:', e)
            PDVSuperApp.__init__ = _qftp_init_patched
            PDVSuperApp._qftp_init_patch = True
        print('[BACKUP-FTP] Patch do backup automático FTP aplicado.')
except Exception as _qftp_e:
    try:
        print('[BACKUP-FTP] Falha ao aplicar patch:', _qftp_e)
    except Exception:
        pass




# ═══════════════════════════════════════════════════════════════════════════════
# ✅ PATCH: AUTOATUALIZAÇÃO DE TABELAS E COLUNAS DO BACKUP AUTOMÁTICO FTP
# Evita erro de tabela/coluna faltando na abertura do sistema.
# Cria/ajusta as estruturas necessárias para a nova funcionalidade sem apagar dados.
# ═══════════════════════════════════════════════════════════════════════════════
_QUANTUM_SCHEMA_BACKUP_FTP_COLUMNS = {
    'id': "INT AUTO_INCREMENT PRIMARY KEY",
    'ativo': "TINYINT(1) NOT NULL DEFAULT 0",
    'host_ftp': "VARCHAR(255) NULL",
    'usuario_ftp': "VARCHAR(255) NULL",
    'senha_ftp': "TEXT NULL",
    'pasta_remota': "VARCHAR(500) NULL",
    'intervalo_minutos': "INT NOT NULL DEFAULT 60",
    'ultimo_backup_em': "DATETIME NULL",
    'ultimo_arquivo': "VARCHAR(500) NULL",
    'ultimo_status': "TEXT NULL",
    'criado_em': "DATETIME NULL DEFAULT CURRENT_TIMESTAMP",
    'atualizado_em': "DATETIME NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP",
}

_QUANTUM_SCHEMA_CONFIG_COLUMNS = {
    'chave': "VARCHAR(190) NOT NULL PRIMARY KEY",
    'valor': "LONGTEXT NULL",
    'grupo': "VARCHAR(80) NULL DEFAULT 'geral'",
    'descricao': "VARCHAR(255) NULL",
    'atualizado_em': "DATETIME NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP",
}

def _quantum_db_execute_safe(sql, params=None):
    try:
        db = get_db()
        try:
            return db.execute(sql, params or ())
        except TypeError:
            return db.execute(sql)
    except Exception as e:
        try:
            print('[SCHEMA-AUTO] Aviso SQL:', str(e)[:250], '| SQL:', str(sql)[:120])
        except Exception:
            pass
        return None

def _quantum_db_fetchone_safe(sql, params=None):
    try:
        db = get_db()
        try:
            return db.fetchone(sql, params or ())
        except TypeError:
            return db.fetchone(sql)
    except Exception:
        return None

def _quantum_table_exists(table_name):
    try:
        row = _quantum_db_fetchone_safe("""
            SELECT COUNT(*) AS total
            FROM INFORMATION_SCHEMA.TABLES
            WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = %s
        """, (table_name,))
        return bool(row and int(row.get('total', 0)) > 0)
    except Exception:
        return False

def _quantum_column_exists(table_name, column_name):
    try:
        row = _quantum_db_fetchone_safe("""
            SELECT COUNT(*) AS total
            FROM INFORMATION_SCHEMA.COLUMNS
            WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = %s AND COLUMN_NAME = %s
        """, (table_name, column_name))
        return bool(row and int(row.get('total', 0)) > 0)
    except Exception:
        return False

def _quantum_auto_atualizar_tabelas_colunas_backup_ftp():
    """Cria e atualiza automaticamente as tabelas/colunas usadas pelo Backup automático FTP."""
    try:
        # Tabela própria da configuração do backup automático.
        _quantum_db_execute_safe("""
            CREATE TABLE IF NOT EXISTS quantum_backup_automatico_ftp (
                id INT AUTO_INCREMENT PRIMARY KEY,
                ativo TINYINT(1) NOT NULL DEFAULT 0,
                host_ftp VARCHAR(255) NULL,
                usuario_ftp VARCHAR(255) NULL,
                senha_ftp TEXT NULL,
                pasta_remota VARCHAR(500) NULL,
                intervalo_minutos INT NOT NULL DEFAULT 60,
                ultimo_backup_em DATETIME NULL,
                ultimo_arquivo VARCHAR(500) NULL,
                ultimo_status TEXT NULL,
                criado_em DATETIME NULL DEFAULT CURRENT_TIMESTAMP,
                atualizado_em DATETIME NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
        """)
        if _quantum_table_exists('quantum_backup_automatico_ftp'):
            for col, definition in _QUANTUM_SCHEMA_BACKUP_FTP_COLUMNS.items():
                if col == 'id':
                    continue
                if not _quantum_column_exists('quantum_backup_automatico_ftp', col):
                    _quantum_db_execute_safe(f"ALTER TABLE quantum_backup_automatico_ftp ADD COLUMN {col} {definition}")

        # Tabela genérica de configurações, para futuras funções e persistência segura.
        _quantum_db_execute_safe("""
            CREATE TABLE IF NOT EXISTS quantum_configuracoes_automaticas (
                chave VARCHAR(190) NOT NULL PRIMARY KEY,
                valor LONGTEXT NULL,
                grupo VARCHAR(80) NULL DEFAULT 'geral',
                descricao VARCHAR(255) NULL,
                atualizado_em DATETIME NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
        """)
        if _quantum_table_exists('quantum_configuracoes_automaticas'):
            for col, definition in _QUANTUM_SCHEMA_CONFIG_COLUMNS.items():
                if col == 'chave':
                    continue
                if not _quantum_column_exists('quantum_configuracoes_automaticas', col):
                    _quantum_db_execute_safe(f"ALTER TABLE quantum_configuracoes_automaticas ADD COLUMN {col} {definition}")

        # Garante uma linha padrão de configuração, sem sobrescrever dados existentes.
        _quantum_db_execute_safe("""
            INSERT IGNORE INTO quantum_backup_automatico_ftp
            (id, ativo, host_ftp, usuario_ftp, senha_ftp, pasta_remota, intervalo_minutos, ultimo_status)
            VALUES (1, 0, '', '', '', '', 60, 'Criado automaticamente na abertura do sistema')
        """)

        try:
            print('[SCHEMA-AUTO] Estrutura do Backup automático FTP verificada/criada com sucesso.')
        except Exception:
            pass
        return True
    except Exception as e:
        try:
            print('[SCHEMA-AUTO] Falha não fatal ao atualizar tabelas/colunas:', e)
        except Exception:
            pass
        return False

def _qftp_ler_cfg_banco():
    try:
        _quantum_auto_atualizar_tabelas_colunas_backup_ftp()
        row = _quantum_db_fetchone_safe("SELECT * FROM quantum_backup_automatico_ftp WHERE id = 1")
        if not row:
            return {}
        return {
            'auto_backup_ftp_ativo': bool(row.get('ativo')),
            'auto_backup_ftp_host': row.get('host_ftp') or '',
            'auto_backup_ftp_usuario': row.get('usuario_ftp') or '',
            'auto_backup_ftp_senha': row.get('senha_ftp') or '',
            'auto_backup_ftp_pasta_remota': row.get('pasta_remota') or '',
            'auto_backup_ftp_intervalo_minutos': str(row.get('intervalo_minutos') or '60'),
        }
    except Exception:
        return {}

def _qftp_salvar_cfg_banco(cfg):
    try:
        _quantum_auto_atualizar_tabelas_colunas_backup_ftp()
        ativo = 1 if _qftp_bool(cfg.get('auto_backup_ftp_ativo')) else 0
        intervalo = int(float(str(cfg.get('auto_backup_ftp_intervalo_minutos') or '60').replace(',', '.')))
        intervalo = max(1, intervalo)
        _quantum_db_execute_safe("""
            INSERT INTO quantum_backup_automatico_ftp
            (id, ativo, host_ftp, usuario_ftp, senha_ftp, pasta_remota, intervalo_minutos, ultimo_status)
            VALUES (1, %s, %s, %s, %s, %s, %s, 'Configuração salva pelo usuário')
            ON DUPLICATE KEY UPDATE
                ativo = VALUES(ativo),
                host_ftp = VALUES(host_ftp),
                usuario_ftp = VALUES(usuario_ftp),
                senha_ftp = VALUES(senha_ftp),
                pasta_remota = VALUES(pasta_remota),
                intervalo_minutos = VALUES(intervalo_minutos),
                ultimo_status = VALUES(ultimo_status),
                atualizado_em = CURRENT_TIMESTAMP
        """, (
            ativo,
            str(cfg.get('auto_backup_ftp_host') or '').strip(),
            str(cfg.get('auto_backup_ftp_usuario') or '').strip(),
            str(cfg.get('auto_backup_ftp_senha') or '').strip(),
            str(cfg.get('auto_backup_ftp_pasta_remota') or '').strip(),
            intervalo,
        ))
        # Espelha também na tabela genérica para futuras migrações.
        for k, v in (cfg or {}).items():
            if str(k).startswith('auto_backup_ftp_'):
                _quantum_db_execute_safe("""
                    INSERT INTO quantum_configuracoes_automaticas (chave, valor, grupo, descricao)
                    VALUES (%s, %s, 'backup_automatico_ftp', 'Configuração do backup automático FTP')
                    ON DUPLICATE KEY UPDATE valor = VALUES(valor), atualizado_em = CURRENT_TIMESTAMP
                """, (str(k), str(v)))
        return True
    except Exception as e:
        try:
            print('[SCHEMA-AUTO] Não foi possível salvar config do backup no banco:', e)
        except Exception:
            pass
        return False

# Reforça as funções de configuração para usar JSON + banco sem quebrar versões antigas.
try:
    _qftp_cfg_anterior_schema = _qftp_cfg
    def _qftp_cfg(app=None):
        cfg = {}
        try:
            if callable(_qftp_cfg_anterior_schema):
                cfg.update(_qftp_cfg_anterior_schema(app) or {})
        except Exception:
            pass
        try:
            banco_cfg = _qftp_ler_cfg_banco()
            # Só prioriza banco quando ele tiver dados reais de FTP ou estiver ativo.
            if banco_cfg and (banco_cfg.get('auto_backup_ftp_host') or _qftp_bool(banco_cfg.get('auto_backup_ftp_ativo'))):
                cfg.update(banco_cfg)
        except Exception:
            pass
        for k, v in _QUANTUM_FTP_BACKUP_DEFAULTS.items():
            cfg.setdefault(k, v)
        return cfg
except Exception:
    pass

try:
    _qftp_save_cfg_anterior_schema = _qftp_save_cfg
    def _qftp_save_cfg(app, cfg):
        ok_json = True
        try:
            ok_json = bool(_qftp_save_cfg_anterior_schema(app, cfg))
        except Exception:
            ok_json = False
        ok_db = _qftp_salvar_cfg_banco(cfg)
        return bool(ok_json or ok_db)
except Exception:
    pass

try:
    if 'PDVSuperApp' in globals():
        _schema_orig_init = getattr(PDVSuperApp, '__init__', None)
        if callable(_schema_orig_init) and not getattr(PDVSuperApp, '_schema_backup_ftp_init_patch', False):
            def _schema_backup_ftp_init_patched(self, *args, **kwargs):
                _schema_orig_init(self, *args, **kwargs)
                try:
                    _quantum_auto_atualizar_tabelas_colunas_backup_ftp()
                    # Garante também as chaves no config_data em memória.
                    if isinstance(getattr(self, 'config_data', None), dict):
                        for k, v in _QUANTUM_FTP_BACKUP_DEFAULTS.items():
                            self.config_data.setdefault(k, v)
                except Exception as e:
                    try:
                        print('[SCHEMA-AUTO] Autoatualização não fatal no init:', e)
                    except Exception:
                        pass
            PDVSuperApp.__init__ = _schema_backup_ftp_init_patched
            PDVSuperApp._schema_backup_ftp_init_patch = True
        print('[SCHEMA-AUTO] Patch de autoatualização de tabelas/colunas aplicado.')
except Exception as _schema_auto_e:
    try:
        print('[SCHEMA-AUTO] Falha ao aplicar patch:', _schema_auto_e)
    except Exception:
        pass




