def _qperm_descricao_automatica(perm):
    try:
        partes = str(perm).split(".")
        modulo = partes[0]
        acao = ".".join(partes[1:]) if len(partes) > 1 else ""
        nome_modulo = _QPERM_MODULO_NOME.get(modulo, modulo.replace("_", " ").title())
        nome_acao = _QPERM_ACAO_NOME.get(acao, _QPERM_ACAO_NOME.get(partes[-1], acao.replace("_", " ").replace(".", " / ").title()))
        return f"{nome_acao} em {nome_modulo}"
    except Exception:
        return str(perm)

def _qperm_grupo_para_perm(perm):
    try:
        prefixo = str(perm).split(".")[0]
        return _QPERM_MODULO_NOME.get(prefixo, "Permissões Revisadas")
    except Exception:
        return "Permissões Revisadas"

def _qperm_catalogo_plano():
    plano = {}
    try:
        for _grupo, _perms in (PERMISSION_GROUPS or {}).items():
            try:
                for _p, _d in (_perms or {}).items():
                    plano[_p] = _d
            except Exception:
                pass
    except Exception:
        pass
    return plano

