def _qperm_expandir_wildcards(permissoes):
    try:
        todas = set(_qperm_catalogo_plano().keys())
        resultado = set()
        for perm in permissoes or []:
            if perm == "*":
                return ["*"]
            if isinstance(perm, str) and perm.endswith(".*"):
                prefixo = perm[:-2] + "."
                resultado.add(perm)
                resultado.update(p for p in todas if p.startswith(prefixo))
            else:
                resultado.add(perm)
        return sorted(resultado)
    except Exception:
        return sorted(set(permissoes or []))

