def _qperm_aplicar_matriz_niveis():
    try:
        if "ROLES" not in globals():
            return False

        for nivel, permissoes in _QPERM_ROLE_PATCH.items():
            ROLES.setdefault(nivel, {"description": nivel.title(), "permissions": []})
            if nivel == "admin":
                ROLES[nivel]["permissions"] = ["*"]
                continue
            atuais = set(ROLES[nivel].get("permissions", []) or [])
            # União para não perder permissões antigas já existentes do nível.
            ROLES[nivel]["permissions"] = sorted(atuais | set(permissoes))

        # Garante que wildcards sejam válidos para todos os módulos existentes.
        _catalogo = _qperm_catalogo_plano()
        _prefixos = set(p.split(".")[0] for p in _catalogo if "." in p)
        for nivel, dados in ROLES.items():
            if "*" in (dados.get("permissions") or []):
                continue
            limpas = []
            for perm in dados.get("permissions", []) or []:
                if perm == "*":
                    limpas.append(perm)
                elif isinstance(perm, str) and perm.endswith(".*"):
                    if perm[:-2] in _prefixos:
                        limpas.append(perm)
                elif perm in _catalogo:
                    limpas.append(perm)
                else:
                    # Mantém por segurança, mas cria descrição fiel automática para não virar órfã.
                    _grupo = _qperm_grupo_para_perm(perm)
                    PERMISSION_GROUPS.setdefault(_grupo, {})[perm] = _qperm_descricao_automatica(perm)
                    limpas.append(perm)
            dados["permissions"] = sorted(set(limpas))
        return True
    except Exception as _e:
        try:
            print("[PERMISSÕES] Falha ao aplicar matriz de níveis:", _e)
        except Exception:
            pass
        return False

def permissoes_efetivas_do_nivel(nivel_acesso):
    """Retorna permissões efetivas do nível, expandindo módulos com .* e aliases."""
    try:
        nivel = str(nivel_acesso or "caixa").lower()
        role = ROLES.get(nivel) or ROLES.get("caixa", {"permissions": []})
        perms = list(role.get("permissions", []) or [])
        if "*" in perms:
            return ["*"]
        efetivas = set(_qperm_expandir_wildcards(perms))
        try:
            aliases_map = globals().get("PERMISSION_ALIASES", {})
            for p in list(efetivas):
                for a in aliases_map.get(p, []) or []:
                    efetivas.add(a)
        except Exception:
            pass
        return sorted(efetivas)
    except Exception:
        return []

def _qperm_ensure_revision_table():
    try:
        db = get_db()
        db.execute("""
            CREATE TABLE IF NOT EXISTS quantum_permissoes_revisoes_usuarios (
                id INT AUTO_INCREMENT PRIMARY KEY,
                usuario VARCHAR(120) NOT NULL,
                revisao VARCHAR(80) NOT NULL,
                aplicado_em DATETIME DEFAULT CURRENT_TIMESTAMP,
                UNIQUE KEY uq_qperm_user_rev (usuario, revisao)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
        """)
        return True
    except Exception:
        return False

def _qperm_usuario_ja_revisado(username):
    try:
        _qperm_ensure_revision_table()
        db = get_db()
        row = db.fetchone(
            "SELECT id FROM quantum_permissoes_revisoes_usuarios WHERE usuario=%s AND revisao=%s LIMIT 1",
            (str(username or "").lower(), QUANTUM_PERMISSOES_REVISAO_ATUAL)
        )
        return bool(row)
    except Exception:
        return False

def _qperm_marcar_usuario_revisado(username):
    try:
        _qperm_ensure_revision_table()
        db = get_db()
        db.execute(
            "INSERT IGNORE INTO quantum_permissoes_revisoes_usuarios (usuario, revisao) VALUES (%s, %s)",
            (str(username or "").lower(), QUANTUM_PERMISSOES_REVISAO_ATUAL)
        )
    except Exception:
        pass

def sincronizar_permissoes_usuario_com_nivel(username, user_data):
    """
    Sincroniza permissões de usuário antigo com o nível, uma única vez por revisão.
    Depois que a revisão é marcada, se o administrador desmarcar uma permissão,
    ela NÃO será reativada automaticamente no próximo boot.
    """
    try:
        username_norm = str(username or user_data.get("usuario") or "").strip().lower()
        if not username_norm:
            return False
        if username_norm in ("adm", "phda", "admin"):
            return False
        nivel = str(user_data.get("nivel_acesso") or user_data.get("nivel") or "caixa").lower()
        if nivel not in ROLES or nivel == "admin":
            return False
        if _qperm_usuario_ja_revisado(username_norm):
            return False

        atuais = set(user_data.get("permissoes", []) or [])
        if "*" in atuais:
            _qperm_marcar_usuario_revisado(username_norm)
            return False

        efetivas = set(permissoes_efetivas_do_nivel(nivel))
        if not efetivas:
            return False

        novas = efetivas - atuais
        if novas:
            user_data["permissoes"] = sorted(atuais | efetivas)
            user_data["permissoes_revisadas_em"] = QUANTUM_PERMISSOES_REVISAO_ATUAL
            return True
        else:
            _qperm_marcar_usuario_revisado(username_norm)
            return False
    except Exception:
        return False

def sincronizar_todos_usuarios_com_niveis(users_data, salvar=True):
    alterou = False
    revisados = []
    try:
        for username, user_data in (users_data or {}).items():
            if sincronizar_permissoes_usuario_com_nivel(username, user_data):
                alterou = True
                revisados.append(str(username or user_data.get("usuario") or "").lower())
        if alterou and salvar and "_mysql_save_users" in globals():
            try:
                _mysql_save_users(users_data)
                for u in revisados:
                    _qperm_marcar_usuario_revisado(u)
                print("[PERMISSÕES] Usuários existentes sincronizados uma vez com a revisão", QUANTUM_PERMISSOES_REVISAO_ATUAL)
            except Exception as e:
                print(f"[PERMISSÕES] Aviso: não foi possível persistir sincronização automática: {e}")
    except Exception as e:
        print(f"[PERMISSÕES] Erro ao sincronizar usuários com níveis: {e}")
    return users_data

def _qperm_auditar_catalogo_niveis():
    try:
        catalogo = _qperm_catalogo_plano()
        usadas = set(_QPERM_USADAS_NO_CODIGO_20260616)
        faltantes = sorted(p for p in usadas if p not in catalogo)
        niveis_info = {}
        for nivel, dados in (ROLES or {}).items():
            perms = dados.get("permissions", []) or []
            if "*" in perms:
                niveis_info[nivel] = "TOTAL"
            else:
                efetivas = permissoes_efetivas_do_nivel(nivel)
                niveis_info[nivel] = len(efetivas)
        if faltantes:
            print("[PERMISSÕES] Atenção: catálogo ainda tem permissões faltantes:", faltantes[:20])
        else:
            print("[PERMISSÕES] Catálogo revisado: todas as permissões usadas no código foram catalogadas.")
        print("[PERMISSÕES] Níveis revisados:", niveis_info)
        return not faltantes
    except Exception as e:
        print("[PERMISSÕES] Auditoria não fatal falhou:", e)
        return False

