_QMYSQL_EXT_PRO_REV = "2026.06.16-sync-full"
_QMYSQL_EXT_PRO_APPS = []
_QMYSQL_EXT_PRO_SYNC_LOCK = None
_QMYSQL_EXT_PRO_PATCHED_DB = False

_QMYSQL_EXT_PRO_ANTIBOT = {"cookie": None}
_QMYSQL_EXT_PRO_UA = (
    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
    "AppleWebKit/537.36 (KHTML, like Gecko) "
    "Chrome/120.0.0.0 Safari/537.36"
)
_QMYSQL_EXT_PRO_DIRTY = set()
_QMYSQL_EXT_PRO_DIRTY_LOCK = None

def _qmysql_ext_pro_dirty_add(table):
    global _QMYSQL_EXT_PRO_DIRTY_LOCK
    try:
        import threading
        if _QMYSQL_EXT_PRO_DIRTY_LOCK is None:
            _QMYSQL_EXT_PRO_DIRTY_LOCK = threading.Lock()
        if table:
            with _QMYSQL_EXT_PRO_DIRTY_LOCK:
                _QMYSQL_EXT_PRO_DIRTY.add(str(table))
    except Exception:
        try:
            if table:
                _QMYSQL_EXT_PRO_DIRTY.add(str(table))
        except Exception:
            pass

def _qmysql_ext_pro_dirty_take():
    global _QMYSQL_EXT_PRO_DIRTY_LOCK
    try:
        import threading
        if _QMYSQL_EXT_PRO_DIRTY_LOCK is None:
            _QMYSQL_EXT_PRO_DIRTY_LOCK = threading.Lock()
        with _QMYSQL_EXT_PRO_DIRTY_LOCK:
            atual = set(_QMYSQL_EXT_PRO_DIRTY)
            _QMYSQL_EXT_PRO_DIRTY.clear()
            return atual
    except Exception:
        try:
            atual = set(_QMYSQL_EXT_PRO_DIRTY)
            _QMYSQL_EXT_PRO_DIRTY.clear()
            return atual
        except Exception:
            return set()

def _qmysql_ext_pro_table_from_sql(sql):
    import re
    s = str(sql or "")
    m = re.search(
        r"(?is)\b(?:insert(?:\s+ignore)?\s+into|replace(?:\s+into)?|update|delete\s+from|truncate(?:\s+table)?|alter\s+table|create\s+table(?:\s+if\s+not\s+exists)?|drop\s+table(?:\s+if\s+exists)?)\s+`?([A-Za-z0-9_]+)`?",
        s)
    return m.group(1) if m else None

