def _qmysql_ext_pro_normalize_value(v):
    import datetime as _dt
    from decimal import Decimal as _Dec
    if v is None:
        return None
    if isinstance(v, bool):
        return 1 if v else 0
    if isinstance(v, _Dec):
        return str(v)
    if isinstance(v, _dt.datetime):
        return v.strftime("%Y-%m-%d %H:%M:%S")
    if isinstance(v, _dt.date):
        return v.strftime("%Y-%m-%d")
    if isinstance(v, _dt.time):
        return v.strftime("%H:%M:%S")
    if isinstance(v, (bytes, bytearray)):
        for enc in ("utf-8", "latin-1"):
            try:
                return bytes(v).decode(enc)
            except Exception:
                continue
        return None
    return v

def _qmysql_ext_pro_table_columns(local_db, table):
    """Lê estrutura da tabela local (MySQL) e devolve (columns_defs, nomes, pks)."""
    rows = local_db.fetchall("SHOW COLUMNS FROM `{}`".format(table)) or []
    columns = []
    names = []
    pks = []
    for r in rows:
        if isinstance(r, dict):
            low = {str(k).lower(): val for k, val in r.items()}
            field = low.get("field")
            ctype = low.get("type")
            key = str(low.get("key") or "")
        else:
            vals = list(r)
            field = vals[0] if len(vals) > 0 else None
            ctype = vals[1] if len(vals) > 1 else None
            key = str(vals[3]) if len(vals) > 3 else ""
        if not field:
            continue
        field = str(field)
        ctype = str(ctype or "TEXT")
        names.append(field)
        columns.append({"name": field, "type": ctype})
        if key.upper() == "PRI":
            pks.append(field)
    return columns, names, pks

