def _qmysql_ext_pro_marcar_pendente(table=None):
    try:
        if table:
            _qmysql_ext_pro_dirty_add(table)
    except Exception:
        pass
    try:
        _qmysql_ext_pro_status_local("Alteração local detectada; sincronização externa pendente.", True)
    except Exception:
        pass
    for app in list(_QMYSQL_EXT_PRO_APPS):
        try:
            app._qmysql_ext_pending = True
        except Exception:
            pass

def _qmysql_ext_pro_patch_db_writes():
    """Marca sincronização pendente sempre que o banco local recebe escrita."""
    global _QMYSQL_EXT_PRO_PATCHED_DB
    if _QMYSQL_EXT_PRO_PATCHED_DB:
        return
    try:
        if "MySQLDB" not in globals():
            return
        cls = MySQLDB
        orig = getattr(cls, "execute", None)
        if not callable(orig):
            return

        def _is_write(sql):
            s = str(sql or "").lstrip().lower()
            return s.startswith(("insert ", "update ", "delete ", "replace ", "create ", "alter ", "drop ", "truncate "))

        def _ignore(sql):
            s = str(sql or "").lower()
            return (
                "quantum_envio_mysql_externo" in s or
                "quantum_permissoes_revisoes_usuarios" in s or
                "schema_migrations" in s or
                "__qsync_" in s
            )

        def patched_execute(inner_cls, query, params=()):
            result = orig(query, params)
            try:
                if _is_write(query) and not _ignore(query):
                    _qmysql_ext_pro_marcar_pendente(_qmysql_ext_pro_table_from_sql(query))
            except Exception:
                pass
            return result

        cls.execute = classmethod(patched_execute)
        _QMYSQL_EXT_PRO_PATCHED_DB = True
        try:
            print("[MYSQL-EXTERNO] Monitor de escritas locais aplicado.")
        except Exception:
            pass
    except Exception as e:
        try:
            print("[MYSQL-EXTERNO] Não foi possível aplicar monitor de escritas:", e)
        except Exception:
            pass

def _qmysql_ext_pro_local_tables(local_db):
    rows = []
    try:
        rows = local_db.fetchall("SHOW FULL TABLES WHERE Table_type = 'BASE TABLE'")
    except Exception:
        try:
            rows = local_db.fetchall("SHOW TABLES")
        except Exception:
            rows = []
    tables = []
    for r in rows or []:
        try:
            vals = list(r.values()) if isinstance(r, dict) else list(r)
            if vals:
                t = str(vals[0])
                if not t.startswith("__qsync_"):
                    tables.append(t)
        except Exception:
            pass
    # Tabelas de controle podem ir por último.
    return [t for t in tables if t not in ("quantum_envio_mysql_externo",)] + [t for t in tables if t in ("quantum_envio_mysql_externo",)]

def _qmysql_ext_pro_sync_all(app=None, manual=False, status_cb=None, tables=None):
    """
    Sincronização via API PHP (HTTP).
    - tables=None: espelho completo (todas as tabelas).
    - tables=[...]: sincronização INCREMENTAL apenas das tabelas informadas.
    Cada tabela é carregada numa tabela temporária no servidor e trocada de forma
    ATÔMICA (RENAME TABLE), então o destino nunca fica vazio/parcial.
    """
    global _QMYSQL_EXT_PRO_SYNC_LOCK
    os, re, time, threading, hashlib, traceback, _tk, _ttk, _mb, _sd, _mc = _qmysql_ext_pro_imports()
    if _QMYSQL_EXT_PRO_SYNC_LOCK is None:
        _QMYSQL_EXT_PRO_SYNC_LOCK = threading.Lock()

    cfg = _qmysql_ext_pro_cfg(app)
    if not manual and not _qmysql_ext_pro_bool(cfg.get("envio_mysql_externo_ativo")):
        return False

    if not cfg.get("envio_mysql_externo_api_url") or not cfg.get("envio_mysql_externo_api_key"):
        msg = "Dados da API PHP incompletos (informe URL e Chave da API)."
        _qmysql_ext_pro_status_local(msg, True)
        if manual:
            raise RuntimeError(msg)
        return False

    if not _QMYSQL_EXT_PRO_SYNC_LOCK.acquire(blocking=False):
        if status_cb:
            status_cb("Sincronização já em andamento.")
        try:
            for _t in (tables or []):
                _qmysql_ext_pro_dirty_add(_t)
        except Exception:
            pass
        return False

    incremental = tables is not None
    try:
        batch = _qmysql_ext_pro_int(cfg.get("envio_mysql_externo_batch"), 500)
        if batch < 1:
            batch = 500

        banco = "?"
        if not incremental:
            if status_cb:
                status_cb("Testando conexão com a API PHP...")
            ping = _qmysql_ext_pro_api_ping(cfg)
            banco = ping.get("database", "?")

        local = get_db()
        existentes = _qmysql_ext_pro_local_tables(local)
        if incremental:
            alvo_set = set(tables)
            alvo = [t for t in existentes if t in alvo_set]
        else:
            alvo = existentes
        total_tables = len(alvo)
        total_rows = 0

        for idx, table in enumerate(alvo, start=1):
            if status_cb:
                status_cb("Sincronizando {}/{}: {}".format(idx, total_tables, table))
            columns, names, pks = _qmysql_ext_pro_table_columns(local, table)
            if not names:
                continue

            h = hashlib.md5(table.encode("utf-8", errors="ignore")).hexdigest()[:10]
            tmp = ("__qsync_tmp_" + h)[:60]

            # Cria a tabela temporária limpa (fresh=True recria do zero no servidor).
            _qmysql_ext_pro_api_create_table(cfg, tmp, columns, pks, fresh=True)

            try:
                rows = local.fetchall("SELECT * FROM `{}`".format(table)) or []
            except Exception:
                rows = []

            lote = []
            enviados = 0
            for r in rows:
                if isinstance(r, dict):
                    valores = [_qmysql_ext_pro_normalize_value(r.get(c)) for c in names]
                else:
                    seq = list(r)
                    valores = [_qmysql_ext_pro_normalize_value(seq[i]) if i < len(seq) else None for i in range(len(names))]
                lote.append(valores)
                if len(lote) >= batch:
                    _qmysql_ext_pro_api_sync_batch(cfg, tmp, names, lote)
                    enviados += len(lote)
                    lote = []
            if lote:
                _qmysql_ext_pro_api_sync_batch(cfg, tmp, names, lote)
                enviados += len(lote)
            total_rows += enviados

            # Troca atômica no servidor: tmp -> tabela final.
            _qmysql_ext_pro_api_swap(cfg, tmp, table)

        try:
            if app is not None:
                app._qmysql_ext_last_sync_ok = time.time()
                if not incremental:
                    app._qmysql_ext_last_full_sync = time.time()
        except Exception:
            pass

        escopo = "incremental" if incremental else "completa"
        msg = "Sincronização MySQL externo ({}) OK: {} tabela(s), {} registro(s).".format(
            escopo, total_tables, total_rows)
        if not incremental:
            msg += " Banco: {}".format(banco)
        _qmysql_ext_pro_status_local(msg, False)
        if status_cb:
            status_cb(msg)
        return True
    except Exception as e:
        try:
            for _t in (tables or []):
                _qmysql_ext_pro_dirty_add(_t)
        except Exception:
            pass
        msg = "Falha na sincronização MySQL externo: {}".format(e)
        _qmysql_ext_pro_status_local(msg, True)
        try:
            if app is not None:
                app._qmysql_ext_pending = True
        except Exception:
            pass
        if status_cb:
            status_cb(msg)
        if manual:
            raise
        return False
    finally:
        try:
            _QMYSQL_EXT_PRO_SYNC_LOCK.release()
        except Exception:
            pass

def _qmysql_ext_pro_sync_async(app, manual=False, status_cb=None, done_cb=None, tables=None):
    os, re, time, threading, hashlib, traceback, _tk, _ttk, _mb, _sd, _mc = _qmysql_ext_pro_imports()
    def run():
        ok = False
        erro = None
        try:
            app._qmysql_ext_syncing = True
        except Exception:
            pass
        try:
            ok = _qmysql_ext_pro_sync_all(app, manual=manual, status_cb=status_cb, tables=tables)
        except Exception as e:
            erro = e
            if status_cb:
                status_cb("Erro: {}".format(e))
        finally:
            try:
                app._qmysql_ext_syncing = False
            except Exception:
                pass
        try:
            if done_cb:
                app.root.after(50, lambda: done_cb(ok, erro))
        except Exception:
            pass
    threading.Thread(target=run, daemon=True, name="QuantumMySQLExternoSync").start()

def _qmysql_ext_pro_monitor_tick(app):
    try:
        cfg = _qmysql_ext_pro_cfg(app)
        if not _qmysql_ext_pro_bool(cfg.get("envio_mysql_externo_ativo")):
            app._qmysql_ext_monitor_after = app.root.after(3000, lambda: _qmysql_ext_pro_monitor_tick(app))
            return

        import time
        pending = bool(getattr(app, "_qmysql_ext_pending", True))
        last_full = float(getattr(app, "_qmysql_ext_last_full_sync", 0) or 0)
        running = bool(getattr(app, "_qmysql_ext_syncing", False))

        if not running:
            full_due = (time.time() - last_full) > 300
            if full_due:
                # Espelho completo de segurança (cobre tabelas perdidas/deletadas) a cada ~5 min.
                app._qmysql_ext_pending = False
                _qmysql_ext_pro_sync_async(app, manual=False, tables=None,
                                           status_cb=lambda m: print("[MYSQL-EXTERNO]", m))
            elif pending or _QMYSQL_EXT_PRO_DIRTY:
                # Incremental imediato: envia somente as tabelas alteradas.
                app._qmysql_ext_pending = False
                sujas = _qmysql_ext_pro_dirty_take()
                if sujas:
                    _qmysql_ext_pro_sync_async(app, manual=False, tables=sorted(sujas),
                                               status_cb=lambda m: print("[MYSQL-EXTERNO]", m))
                else:
                    _qmysql_ext_pro_sync_async(app, manual=False, tables=None,
                                               status_cb=lambda m: print("[MYSQL-EXTERNO]", m))
        # Verificação rápida (~1,5s) para resposta quase em tempo real.
        # Sem alterações, é apenas uma checagem local barata (não acessa a rede).
        app._qmysql_ext_monitor_after = app.root.after(1500, lambda: _qmysql_ext_pro_monitor_tick(app))
    except Exception as e:
        try:
            print("[MYSQL-EXTERNO] Monitor falhou:", e)
        except Exception:
            pass
        try:
            app._qmysql_ext_monitor_after = app.root.after(4000, lambda: _qmysql_ext_pro_monitor_tick(app))
        except Exception:
            pass

def _qmysql_ext_pro_start_monitor(app):
    try:
        if app not in _QMYSQL_EXT_PRO_APPS:
            _QMYSQL_EXT_PRO_APPS.append(app)
    except Exception:
        pass
    try:
        _qmysql_ext_pro_patch_db_writes()
    except Exception:
        pass
    try:
        if getattr(app, "_qmysql_ext_monitor_started", False):
            return
        app._qmysql_ext_monitor_started = True
        app._qmysql_ext_pending = True
        app.root.after(2500, lambda: _qmysql_ext_pro_monitor_tick(app))
        print("[MYSQL-EXTERNO] Monitor de sincronização iniciado.")
    except Exception as e:
        try:
            print("[MYSQL-EXTERNO] Não foi possível iniciar monitor:", e)
        except Exception:
            pass

def _qmysql_ext_pro_show_window(self):
    os, re, time, threading, hashlib, traceback, _tk, _ttk, _mb, _sd, _mc = _qmysql_ext_pro_imports()

    if not _qmysql_ext_pro_pedir_senha_mestra(self):
        return

    cfg = _qmysql_ext_pro_cfg(self)
    win = _tk.Toplevel(self.root)
    win.title("🌐 Envio mysql externo")
    try:
        win.geometry("680x500")
        win.minsize(640, 460)
        win.transient(self.root)
        win.grab_set()
    except Exception:
        pass

    main = _ttk.Frame(win, padding=18)
    main.pack(fill=_tk.BOTH, expand=True)

    _ttk.Label(main, text="🌐 Envio mysql externo", font=("Segoe UI", 15, "bold")).pack(anchor="w")
    _ttk.Label(
        main,
        text=("O envio agora usa uma API PHP hospedada no próprio servidor web (ex.: InfinityFree). "
              "O sistema envia os dados por HTTPS para o arquivo sync_api.php, que grava no MySQL local "
              "da hospedagem. Assim funciona mesmo onde a conexão MySQL remota é bloqueada. Os dados do "
              "MySQL (host, usuário, senha) ficam no arquivo sync_config.php, no servidor."),
        wraplength=620
    ).pack(anchor="w", pady=(2, 12))

    form = _ttk.LabelFrame(main, text="Dados da API PHP")
    form.pack(fill=_tk.X, expand=False)
    form.columnconfigure(1, weight=1)

    api_url_var = _tk.StringVar(value=str(cfg.get("envio_mysql_externo_api_url") or ""))
    api_key_var = _tk.StringVar(value=str(cfg.get("envio_mysql_externo_api_key") or ""))
    ativo_var = _tk.BooleanVar(value=_qmysql_ext_pro_bool(cfg.get("envio_mysql_externo_ativo")))

    def _row(r, label, var, show=None):
        _ttk.Label(form, text=label).grid(row=r, column=0, sticky="w", padx=10, pady=7)
        ent = _ttk.Entry(form, textvariable=var, show=show or "")
        ent.grid(row=r, column=1, sticky="ew", padx=10, pady=7)
        return ent

    ent_url = _row(0, "URL da API PHP:", api_url_var)
    _row(1, "Chave da API (API_KEY):", api_key_var)
    _ttk.Checkbutton(form, text="Ativar", variable=ativo_var).grid(row=2, column=1, sticky="w", padx=10, pady=(8, 6))
    _ttk.Label(
        form,
        text="Ex.: https://seusite.infinityfreeapp.com/sync_api.php",
        foreground="#64748b"
    ).grid(row=3, column=1, sticky="w", padx=10, pady=(0, 10))

    status_var = _tk.StringVar(value="Informe a URL da API e a chave, depois clique em Testar, Gravar ou Cancelar.")
    _ttk.Label(main, textvariable=status_var, foreground="#475569", wraplength=620).pack(anchor="w", pady=(10, 0))

    def _get_novo():
        return {
            "envio_mysql_externo_ativo": bool(ativo_var.get()),
            "envio_mysql_externo_api_url": api_url_var.get().strip(),
            "envio_mysql_externo_api_key": api_key_var.get().strip(),
        }

    def _status(msg):
        try:
            win.after(10, lambda: status_var.set(str(msg)))
        except Exception:
            pass

    def testar():
        novo = _qmysql_ext_pro_cfg(self)
        novo.update(_get_novo())
        status_var.set("Testando conexão com a API PHP...")
        def run():
            ok = False
            msg = ""
            try:
                msg = _qmysql_ext_pro_testar_conexao(novo)
                ok = True
            except Exception as e:
                msg = "Falha no teste: {}".format(e)
            def done():
                status_var.set(msg)
                if ok:
                    _mb.showinfo("Envio mysql externo", msg, parent=win)
                else:
                    _mb.showerror("Envio mysql externo", msg, parent=win)
            try:
                win.after(50, done)
            except Exception:
                pass
        threading.Thread(target=run, daemon=True, name="QuantumMySQLExternoTeste").start()

    def gravar():
        novo = _get_novo()
        try:
            if "_qmysql_ext_save_cfg" in globals():
                _qmysql_ext_save_cfg(self, novo)
            else:
                if not hasattr(self, "config_data") or self.config_data is None:
                    self.config_data = {}
                self.config_data.update(novo)
                try:
                    save_data(CONFIG_FILE, self.config_data)
                except Exception:
                    pass
        except Exception:
            pass

        _qmysql_ext_pro_ensure_local_table()
        _qmysql_ext_pro_status_local("Configuração da API PHP gravada.", True if novo.get("envio_mysql_externo_ativo") else False)

        if novo.get("envio_mysql_externo_ativo"):
            self._qmysql_ext_pending = True
            _qmysql_ext_pro_start_monitor(self)
            status_var.set("Configuração gravada. Iniciando sincronização completa via API...")
            _qmysql_ext_pro_sync_async(
                self,
                manual=True,
                status_cb=_status,
                done_cb=lambda ok, err: _mb.showinfo("Envio mysql externo", "Configuração salva e sincronização concluída." if ok else "Configuração salva, mas a sincronização falhou. O sistema tentará novamente automaticamente.", parent=win)
            )
        else:
            status_var.set("Configuração gravada. Envio MySQL externo DESATIVADO.")
            _mb.showinfo("Envio mysql externo", "Configuração gravada. Envio MySQL externo desativado.", parent=win)

    botoes = _ttk.Frame(main)
    botoes.pack(fill=_tk.X, pady=(16, 0))
    _ttk.Button(botoes, text="Testar", command=testar).pack(side=_tk.LEFT, padx=(0, 8))
    _ttk.Button(botoes, text="Gravar", command=gravar).pack(side=_tk.LEFT, padx=(0, 8))
    _ttk.Button(botoes, text="Cancelar", command=win.destroy).pack(side=_tk.LEFT)

    try:
        ent_url.focus_set()
    except Exception:
        pass
    try:
        quantum_autofit_form_dialog(win, min_w=680, min_h=500, extra_h=40)
    except Exception:
        pass

def _qmysql_ext_pro_add_menu(app):
    try:
        mb = app.root.nametowidget(app.root["menu"])
        end = mb.index("end")
        util_menu = None
        for i in range((end or 0) + 1):
            try:
                lbl = str(mb.entrycget(i, "label")).lower()
                if "utilit" in lbl:
                    util_menu = mb.nametowidget(mb.entrycget(i, "menu"))
                    break
            except Exception:
                pass
        if util_menu is None:
            return False

        labels = []
        try:
            uend = util_menu.index("end")
            for j in range((uend or 0) + 1):
                try:
                    labels.append(str(util_menu.entrycget(j, "label")))
                except Exception:
                    pass
        except Exception:
            pass

        if not any("envio mysql externo" in str(x).lower() for x in labels):
            try:
                util_menu.add_separator()
            except Exception:
                pass
            util_menu.add_command(label="6.8  🌐 Envio mysql externo", command=app.show_envio_mysql_externo_window)
        return True
    except Exception as e:
        try:
            print("[MYSQL-EXTERNO] Falha ao adicionar menu:", e)
        except Exception:
            pass
        return False

try:
    if "PDVSuperApp" in globals():
        PDVSuperApp.show_envio_mysql_externo_window = _qmysql_ext_pro_show_window

        _qmysql_ext_pro_orig_menu = getattr(PDVSuperApp, "_create_menu", None)
        if callable(_qmysql_ext_pro_orig_menu) and not getattr(PDVSuperApp, "_qmysql_ext_pro_menu_patch", False):
            def _qmysql_ext_pro_create_menu(self, *args, **kwargs):
                result = _qmysql_ext_pro_orig_menu(self, *args, **kwargs)
                try:
                    _qmysql_ext_pro_add_menu(self)
                except Exception:
                    pass
                return result
            PDVSuperApp._create_menu = _qmysql_ext_pro_create_menu
            PDVSuperApp._qmysql_ext_pro_menu_patch = True

        _qmysql_ext_pro_orig_init = getattr(PDVSuperApp, "__init__", None)
        if callable(_qmysql_ext_pro_orig_init) and not getattr(PDVSuperApp, "_qmysql_ext_pro_init_patch", False):
            def _qmysql_ext_pro_init(self, *args, **kwargs):
                _qmysql_ext_pro_orig_init(self, *args, **kwargs)
                try:
                    if self not in _QMYSQL_EXT_PRO_APPS:
                        _QMYSQL_EXT_PRO_APPS.append(self)
                    _qmysql_ext_pro_ensure_local_table()
                    _qmysql_ext_pro_patch_db_writes()
                    self.root.after(900, lambda: _qmysql_ext_pro_add_menu(self))
                    self.root.after(3500, lambda: _qmysql_ext_pro_start_monitor(self))
                except Exception as e:
                    try:
                        print("[MYSQL-EXTERNO] Falha no init PRO:", e)
                    except Exception:
                        pass
            PDVSuperApp.__init__ = _qmysql_ext_pro_init
            PDVSuperApp._qmysql_ext_pro_init_patch = True

        print("[MYSQL-EXTERNO] PRO aplicado: senha mestra, teste e sincronização via API PHP.")
except Exception as _qmysql_ext_pro_e:
    try:
        print("[MYSQL-EXTERNO] PRO não aplicado:", _qmysql_ext_pro_e)
    except Exception:
        pass






# ═══════════════════════════════════════════════════════════════════════════════
# 🖨️ PATCH QUANTUM - JANELAS DE IMPRESSÃO SEMPRE NA FRENTE
# Corrige tela de impressão/recibo do final da venda ficando por trás.
# ═══════════════════════════════════════════════════════════════════════════════

def _quantum_is_print_window_title(_title):
    try:
        t = str(_title or "").lower()
        return any(k in t for k in (
            "recibo", "cupom", "impress", "impressão", "reimpress",
            "imprimir", "preview", "visualização de impressão", "salvar pdf"
        ))
    except Exception:
        return False

def _quantum_force_print_window_front(win):
    """
    Mantém janelas de cupom/recibo/impressão sempre visíveis por cima.

    Correção:
    A versão anterior soltava o topmost após 250ms para evitar tremor.
    Em alguns fluxos, principalmente cupom final, outra janela tomava foco depois
    e a tela de impressão ficava atrás. Agora a janela permanece topmost até
    ser fechada pelo usuário.
    """
    try:
        if win is None or not win.winfo_exists():
            return
    except Exception:
        return

    try:
        win._skip_auto_statusbar = True
        win._skip_visual_autopolish = True
        win._quantum_print_front = True
        win._quantum_keep_topmost = True
    except Exception:
        pass

    def _raise_once():
        try:
            if not win.winfo_exists():
                return
            try:
                win.deiconify()
            except Exception:
                pass
            try:
                win.attributes("-topmost", True)
            except Exception:
                pass
            try:
                win.lift()
                win.focus_force()
            except Exception:
                pass
        except Exception:
            pass

    _raise_once()

    # Reforços curtos enquanto a janela está terminando de montar.
    # Não muda tamanho/posição, então não causa tremedeira.
    for _ms in (50, 150, 350, 800, 1500):
        try:
            win.after(_ms, _raise_once)
        except Exception:
            pass

    # Reforço leve enquanto existir, para impedir que pagamento/relatório/Windows
    # jogue o cupom para trás. Não altera geometria.
    def _keep_front():
        try:
            if not win.winfo_exists():
                return
            if getattr(win, "_quantum_keep_topmost", False):
                try:
                    win.attributes("-topmost", True)
                    win.lift()
                except Exception:
                    pass
                try:
                    win.after(1200, _keep_front)
                except Exception:
                    pass
        except Exception:
            pass

    try:
        win.after(1200, _keep_front)
    except Exception:
        pass


def _quantum_install_print_window_front_patch():
    try:
        import tkinter as _tk
        if getattr(_tk.Toplevel, "_quantum_print_front_title_patch", False):
            return
        _orig_title = _tk.Toplevel.title

        def _title_patched(self, *args, **kwargs):
            result = _orig_title(self, *args, **kwargs)
            try:
                titulo = args[0] if args else _orig_title(self)
                if _quantum_is_print_window_title(titulo):
                    _quantum_force_print_window_front(self)
            except Exception:
                pass
            return result

        _tk.Toplevel.title = _title_patched
        _tk.Toplevel._quantum_print_front_title_patch = True
        try:
            print("[IMPRESSÃO] Patch de janela sempre na frente aplicado.")
        except Exception:
            pass
    except Exception as _e:
        try:
            print("[IMPRESSÃO] Falha ao aplicar patch de janela na frente:", _e)
        except Exception:
            pass

try:
    _quantum_install_print_window_front_patch()
except Exception:
    pass






# ═══════════════════════════════════════════════════════════════════════════════
# 📐 PATCH FORÇADO - ABERTURA/FECHAMENTO DE CAIXA 600x600
# Corrige casos em que responsive_geometry/autopolish reduz a janela depois de abrir.
# ═══════════════════════════════════════════════════════════════════════════════

def _quantum_caixa_titulo_600x600(_title):
    try:
        t = str(_title or "").lower()
        return (
            "abertura de caixa" in t or
            "relatório de fechamento de caixa" in t or
            "relatorio de fechamento de caixa" in t or
            "fechamento de caixa" in t
        )
    except Exception:
        return False

def _quantum_force_window_600x600(win):
    """
    Aplica 600x600 diretamente, sem responsive_geometry, sem animação e sem
    reprocessar a geometria na fase de exibição.
    """
    try:
        if win is None or not win.winfo_exists():
            return
    except Exception:
        return

    try:
        win._skip_auto_statusbar = True
        win._skip_visual_autopolish = True
        win._quantum_no_autofit = True
        win._quantum_fixed_600x600 = True
    except Exception:
        pass

    try:
        sw = win.winfo_screenwidth()
        sh = win.winfo_screenheight()
        x = max(0, (sw - 600) // 2)
        y = max(0, (sh - 600) // 2)
        win.geometry(f"600x600+{x}+{y}")
    except Exception:
        try:
            win.geometry("600x600")
        except Exception:
            pass

    try:
        win.minsize(600, 600)
        win.maxsize(600, 600)
        win.resizable(False, False)
    except Exception:
        pass

def _quantum_prepare_window_600x600(win, title_text=None, parent=None, modal=False):
    """
    Prepara a janela ANTES de aparecer:
    1) withdraw imediato
    2) flags anti-autofit
    3) title
    4) geometry 600x600
    5) transient
    6) geometry 600x600 novamente após transient
    Assim ela já nasce no tamanho/posição corretos, sem pulo.
    """
    try:
        if win is None:
            return
        try:
            win.withdraw()
        except Exception:
            pass

        try:
            win._skip_auto_statusbar = True
            win._skip_visual_autopolish = True
            win._quantum_no_autofit = True
            win._quantum_fixed_600x600 = True
        except Exception:
            pass

        if title_text is not None:
            try:
                win.title(title_text)
            except Exception:
                pass

        _quantum_force_window_600x600(win)

        if parent is not None:
            try:
                win.transient(parent)
            except Exception:
                pass

        # Alguns gerenciadores de janela mexem na posição após transient.
        _quantum_force_window_600x600(win)

        if modal:
            try:
                win.grab_set()
            except Exception:
                pass
    except Exception:
        pass

def _quantum_show_window_ready_600x600(win, focus_widget=None, grab=True):
    """
    Mostra a janela já pronta, sem recalcular tamanho/posição na hora de abrir.
    """
    try:
        if win is None:
            return
        try:
            win.deiconify()
        except Exception:
            pass
        try:
            win.lift()
            win.focus_force()
        except Exception:
            pass
        try:
            if focus_widget is not None:
                focus_widget.focus_set()
        except Exception:
            pass
        if grab:
            try:
                win.grab_set()
            except Exception:
                pass
    except Exception:
        pass

def _quantum_install_caixa_600x600_title_patch():
    """
    Desativado.
    O patch global por título causava tremedeira porque mexia no tamanho da janela
    no momento em que o title era aplicado. Agora o tamanho 600x600 é aplicado
    diretamente somente nas telas certas, antes de exibir a janela.
    """
    return

try:
    _quantum_install_caixa_600x600_title_patch()
except Exception:
    pass






# ═══════════════════════════════════════════════════════════════════════════════
# 🛡️ QUANTUM ANTI "SISTEMA NÃO RESPONDENDO" / ANTI CLIQUE REPETIDO
# Objetivo:
# - Reduzir travamentos aparentes durante processos demorados.
# - Dar retorno visual de "Processando".
# - Evitar que o usuário clique várias vezes e piore a fila de comandos.
# - Bloquear fechamento brusco durante operação em andamento.
# - Bombear eventos em esperas time.sleep() na thread principal.
# Observação honesta: nenhuma proteção genérica consegue tornar instantânea uma
# operação pesada síncrona de banco/relatório/Windows, mas isto reduz bastante
# o "não respondendo" e impede reentrância/double click.
# ═══════════════════════════════════════════════════════════════════════════════

_QUANTUM_UI_GUARD = {
    "busy": False,
    "busy_since": 0.0,
    "last_click": 0.0,
    "overlay": None,
    "depth": 0,
    "patched": False,
    "sleep_patched": False,
    "roots": [],
}

def _qguard_now():
    try:
        import time
        return time.time()
    except Exception:
        return 0.0

def _qguard_get_root(widget=None):
    try:
        if widget is not None:
            return widget.winfo_toplevel()
    except Exception:
        pass
    try:
        import tkinter as tk
        root = tk._default_root
        if root is not None:
            return root
    except Exception:
        pass
    return None

def _qguard_register_root(root):
    try:
        if root is not None and root not in _QUANTUM_UI_GUARD["roots"]:
            _QUANTUM_UI_GUARD["roots"].append(root)
    except Exception:
        pass

def _qguard_set_wait_cursor(root, active=True):
    try:
        if root is None or not root.winfo_exists():
            return
        cursor = "watch" if active else ""
        try:
            root.configure(cursor=cursor)
        except Exception:
            pass
        for w in list(root.winfo_children()):
            try:
                if hasattr(w, "configure"):
                    w.configure(cursor=cursor)
            except Exception:
                pass
    except Exception:
        pass

def _qguard_overlay_show(root, mensagem="Processando... aguarde"):
    """Overlay pequeno e estável, sem mexer no tamanho da tela principal."""
    try:
        import tkinter as tk
        from tkinter import ttk
        if root is None or not root.winfo_exists():
            return
        _qguard_register_root(root)

        ov = _QUANTUM_UI_GUARD.get("overlay")
        try:
            if ov is not None and ov.winfo_exists():
                return
        except Exception:
            pass

        ov = tk.Toplevel(root)
        _QUANTUM_UI_GUARD["overlay"] = ov
        try:
            ov.withdraw()
            ov.overrideredirect(True)
            ov.attributes("-topmost", True)
            ov.configure(bg="#0f172a")
        except Exception:
            pass

        frame = tk.Frame(ov, bg="#0f172a", padx=14, pady=10)
        frame.pack(fill=tk.BOTH, expand=True)

        ttk.Label(frame, text="⏳", font=("Segoe UI Emoji", 14)).pack(side=tk.LEFT, padx=(0, 8))
        tk.Label(frame, text=mensagem, bg="#0f172a", fg="#ffffff", font=("Segoe UI", 9, "bold")).pack(side=tk.LEFT)

        try:
            root.update_idletasks()
            w, h = 260, 52
            rx = root.winfo_rootx()
            ry = root.winfo_rooty()
            rw = root.winfo_width()
            rh = root.winfo_height()
            if rw <= 1:
                rw = root.winfo_screenwidth()
            if rh <= 1:
                rh = root.winfo_screenheight()
            x = rx + max(0, (rw - w) // 2)
            y = ry + 24
            ov.geometry(f"{w}x{h}+{x}+{y}")
            ov.deiconify()
            ov.lift()
            ov.update_idletasks()
        except Exception:
            try:
                ov.geometry("260x52+80+80")
                ov.deiconify()
            except Exception:
                pass
    except Exception:
        pass

def _qguard_overlay_hide():
    try:
        ov = _QUANTUM_UI_GUARD.get("overlay")
        if ov is not None and ov.winfo_exists():
            ov.destroy()
    except Exception:
        pass
    _QUANTUM_UI_GUARD["overlay"] = None

def _qguard_pump_events(max_cycles=1):
    """
    Bombeia eventos para evitar "não respondendo".
    Usado com cuidado para não entrar em loop pesado.
    """
    try:
        roots = list(_QUANTUM_UI_GUARD.get("roots") or [])
        root = _qguard_get_root()
        if root is not None and root not in roots:
            roots.append(root)
        for r in roots:
            try:
                if r is not None and r.winfo_exists():
                    for _ in range(max(1, int(max_cycles))):
                        r.update_idletasks()
                        # update processa fila de eventos; o bloqueio de reentrância abaixo
                        # impede clique repetido de disparar operações novas.
                        r.update()
            except Exception:
                pass
    except Exception:
        pass

def quantum_ui_yield():
    """Função pública para processos longos chamarem entre etapas."""
    try:
        _qguard_pump_events(1)
    except Exception:
        pass

def quantum_busy_start(root=None, mensagem="Processando... aguarde"):
    try:
        root = root or _qguard_get_root()
        _qguard_register_root(root)
        _QUANTUM_UI_GUARD["depth"] = int(_QUANTUM_UI_GUARD.get("depth") or 0) + 1
        if not _QUANTUM_UI_GUARD.get("busy"):
            _QUANTUM_UI_GUARD["busy"] = True
            _QUANTUM_UI_GUARD["busy_since"] = _qguard_now()
            _qguard_set_wait_cursor(root, True)
            _qguard_overlay_show(root, mensagem)
            try:
                if root is not None:
                    root.update_idletasks()
            except Exception:
                pass
    except Exception:
        pass

def quantum_busy_end(root=None):
    try:
        _QUANTUM_UI_GUARD["depth"] = max(0, int(_QUANTUM_UI_GUARD.get("depth") or 0) - 1)
        if int(_QUANTUM_UI_GUARD.get("depth") or 0) <= 0:
            _QUANTUM_UI_GUARD["busy"] = False
            root = root or _qguard_get_root()
            _qguard_set_wait_cursor(root, False)
            _qguard_overlay_hide()
    except Exception:
        _QUANTUM_UI_GUARD["busy"] = False
        _qguard_overlay_hide()

def quantum_run_guarded(func, root=None, mensagem="Processando... aguarde"):
    """Executa uma rotina protegida contra clique repetido/reentrância."""
    root = root or _qguard_get_root()
    if _QUANTUM_UI_GUARD.get("busy"):
        try:
            _qguard_overlay_show(root, "Aguarde terminar...")
            if root is not None:
                root.bell()
        except Exception:
            pass
        return None

    quantum_busy_start(root, mensagem)
    try:
        _qguard_pump_events(1)
        return func()
    finally:
        try:
            quantum_busy_end(root)
        except Exception:
            pass

def _qguard_patch_sleep():
    """
    Corrige sleeps longos na thread principal.
    Em vez de ficar parado e o Windows marcar "Não respondendo",
    divide o sleep em fatias pequenas e processa eventos.
    """
    try:
        if _QUANTUM_UI_GUARD.get("sleep_patched"):
            return
        import time as _time
        import threading as _threading
        _orig_sleep = _time.sleep

        def _sleep_patched(seconds):
            try:
                seconds = float(seconds or 0)
            except Exception:
                return _orig_sleep(seconds)
            if seconds <= 0:
                return _orig_sleep(seconds)
            # Só bombeia eventos na thread principal.
            try:
                is_main = _threading.current_thread() is _threading.main_thread()
            except Exception:
                is_main = True
            if not is_main or seconds < 0.18:
                return _orig_sleep(seconds)

            end = _orig_time_time() + seconds if "_orig_time_time" in globals() else None
            restante = seconds
            while restante > 0:
                fatia = min(0.06, restante)
                _orig_sleep(fatia)
                try:
                    _qguard_pump_events(1)
                except Exception:
                    pass
                try:
                    restante = end - _orig_time_time()
                except Exception:
                    restante -= fatia

        try:
            globals()["_orig_time_time"] = _time.time
        except Exception:
            pass
        _time.sleep = _sleep_patched
        _QUANTUM_UI_GUARD["sleep_patched"] = True
        try:
            print("[ANTI-TRAVA] time.sleep protegido contra 'não respondendo'.")
        except Exception:
            pass
    except Exception as e:
        try:
            print("[ANTI-TRAVA] Falha ao proteger sleep:", e)
        except Exception:
            pass

def _qguard_patch_buttons_and_menus():
    """Protege botões e menus contra clique repetido enquanto processo está rodando."""
    try:
        if _QUANTUM_UI_GUARD.get("patched"):
            return
        import tkinter as tk
        from tkinter import ttk

        # Tk/ttk Button
        for cls in (tk.Button, ttk.Button):
            try:
                if getattr(cls, "_quantum_guard_patched", False):
                    continue
                _orig_invoke = cls.invoke

                def _make_patched(_orig):
                    def _invoke_guarded(self, *args, **kwargs):
                        try:
                            root = _qguard_get_root(self)
                            _qguard_register_root(root)
                            agora = _qguard_now()
                            if _QUANTUM_UI_GUARD.get("busy"):
                                try:
                                    if root is not None:
                                        root.bell()
                                except Exception:
                                    pass
                                return "break"
                            if agora - float(_QUANTUM_UI_GUARD.get("last_click") or 0) < 0.55:
                                return "break"
                            _QUANTUM_UI_GUARD["last_click"] = agora

                            # Desabilita o próprio botão por curto período para impedir fila de cliques.
                            old_state = None
                            try:
                                old_state = self.cget("state")
                                self.configure(state="disabled")
                                if root is not None:
                                    root.after(900, lambda w=self, s=old_state: w.configure(state=s) if w.winfo_exists() else None)
                            except Exception:
                                pass

                            quantum_busy_start(root, "Processando... aguarde")
                            try:
                                _qguard_pump_events(1)
                                return _orig(self, *args, **kwargs)
                            finally:
                                try:
                                    if root is not None:
                                        root.after(120, lambda r=root: quantum_busy_end(r))
                                    else:
                                        quantum_busy_end(root)
                                except Exception:
                                    quantum_busy_end(root)
                        except Exception:
                            return _orig(self, *args, **kwargs)
                    return _invoke_guarded

                cls.invoke = _make_patched(_orig_invoke)
                cls._quantum_guard_patched = True
            except Exception:
                pass

        # Menu.invoke
        try:
            if not getattr(tk.Menu, "_quantum_guard_patched", False):
                _orig_menu_invoke = tk.Menu.invoke
                def _menu_invoke_guarded(self, index, *args, **kwargs):
                    try:
                        root = _qguard_get_root(self)
                        _qguard_register_root(root)
                        if _QUANTUM_UI_GUARD.get("busy"):
                            try:
                                if root is not None:
                                    root.bell()
                            except Exception:
                                pass
                            return "break"
                        agora = _qguard_now()
                        if agora - float(_QUANTUM_UI_GUARD.get("last_click") or 0) < 0.45:
                            return "break"
                        _QUANTUM_UI_GUARD["last_click"] = agora
                        quantum_busy_start(root, "Abrindo... aguarde")
                        try:
                            _qguard_pump_events(1)
                            return _orig_menu_invoke(self, index, *args, **kwargs)
                        finally:
                            try:
                                if root is not None:
                                    root.after(120, lambda r=root: quantum_busy_end(r))
                                else:
                                    quantum_busy_end(root)
                            except Exception:
                                quantum_busy_end(root)
                    except Exception:
                        return _orig_menu_invoke(self, index, *args, **kwargs)
                tk.Menu.invoke = _menu_invoke_guarded
                tk.Menu._quantum_guard_patched = True
        except Exception:
            pass

        _QUANTUM_UI_GUARD["patched"] = True
        try:
            print("[ANTI-TRAVA] Proteção contra clique repetido aplicada.")
        except Exception:
            pass
    except Exception as e:
        try:
            print("[ANTI-TRAVA] Falha no patch de botões/menus:", e)
        except Exception:
            pass

def _qguard_patch_close_behavior():
    """Impede fechar janela durante operação em andamento."""
    try:
        import tkinter as tk
        if getattr(tk.Toplevel, "_quantum_close_guard_patched", False):
            return
        _orig_destroy = tk.Toplevel.destroy

        def _destroy_guarded(self, *args, **kwargs):
            try:
                if _QUANTUM_UI_GUARD.get("busy") and not getattr(self, "_quantum_allow_destroy_busy", False):
                    root = _qguard_get_root(self)
                    try:
                        _qguard_overlay_show(root, "Aguarde terminar...")
                        root.bell()
                    except Exception:
                        pass
                    return
            except Exception:
                pass
            return _orig_destroy(self, *args, **kwargs)

        tk.Toplevel.destroy = _destroy_guarded
        tk.Toplevel._quantum_close_guard_patched = True
    except Exception:
        pass

try:
    _qguard_patch_sleep()
    _qguard_patch_buttons_and_menus()
    _qguard_patch_close_behavior()
except Exception:
    pass




