# 🛡️ INSTALAÇÃO NO APP - ANTI NÃO RESPONDENDO
# ═══════════════════════════════════════════════════════════════════════════════
try:
    if "PDVSuperApp" in globals() and not getattr(PDVSuperApp, "_anti_nao_respondendo_init_patch", False):
        _anti_nr_orig_init = getattr(PDVSuperApp, "__init__", None)
        if callable(_anti_nr_orig_init):
            def _anti_nr_init(self, *args, **kwargs):
                _anti_nr_orig_init(self, *args, **kwargs)
                try:
                    _qguard_register_root(self.root)
                    _qguard_patch_buttons_and_menus()
                    _qguard_patch_sleep()
                    # Heartbeat leve: mantém o app vivo quando não está ocupado.
                    def _heartbeat():
                        try:
                            if not _QUANTUM_UI_GUARD.get("busy"):
                                self.root.update_idletasks()
                        except Exception:
                            pass
                        try:
                            self.root.after(1000, _heartbeat)
                        except Exception:
                            pass
                    self.root.after(1000, _heartbeat)

                    # Fechamento protegido.
                    _old_close = getattr(self, "on_closing", None)
                    def _close_guarded(*a, **k):
                        if _QUANTUM_UI_GUARD.get("busy"):
                            try:
                                messagebox.showwarning("Processando", "Aguarde o processo terminar antes de fechar o sistema.", parent=self.root)
                            except Exception:
                                pass
                            return
                        if callable(_old_close):
                            return _old_close(*a, **k)
                        return self.root.destroy()
                    try:
                        self.root.protocol("WM_DELETE_WINDOW", _close_guarded)
                    except Exception:
                        pass

                    print("[ANTI-TRAVA] Proteção anti 'Sistema não respondendo' ativada no app.")
                except Exception as _e:
                    try:
                        print("[ANTI-TRAVA] Falha no init:", _e)
                    except Exception:
                        pass
            PDVSuperApp.__init__ = _anti_nr_init
            PDVSuperApp._anti_nao_respondendo_init_patch = True
except Exception as _anti_nr_e:
    try:
        print("[ANTI-TRAVA] Patch app não aplicado:", _anti_nr_e)
    except Exception:
        pass





