def quantum_perf_yield(root=None):
    """Mantém a interface respirando sem fazer reentrada pesada."""
    try:
        if root is None:
            import tkinter as _tk
            root = _tk._default_root
        if root is not None:
            root.update_idletasks()
    except Exception:
        pass

def quantum_perf_trim_cache():
    """Evita cache crescer demais."""
    try:
        cache = _QUANTUM_PERF_CACHE.get("image_cache", {})
        max_images = int(_QUANTUM_PERF_CACHE.get("max_images", 80))
        if len(cache) > max_images:
            # remove os mais antigos pela ordem de inserção do dict
            for k in list(cache.keys())[:max(1, len(cache) - max_images)]:
                cache.pop(k, None)
    except Exception:
        pass

try:
    print("[PERFORMANCE] Quantum Performance Senior Full ativado.")
except Exception:
    pass






