def _quantum_center_600x600_window(win):
    """Centraliza janela 600x600 na tela sem alterar o conteúdo."""
    try:
        if win is None or not win.winfo_exists():
            return
    except Exception:
        return
    try:
        win.update_idletasks()
    except Exception:
        pass
    try:
        sw = win.winfo_screenwidth()
        sh = win.winfo_screenheight()
        x = max(0, (sw - 600) // 2)
        y = max(0, (sh - 600) // 2)
        win.geometry(f"600x600+{x}+{y}")
    except Exception:
        try:
            win.geometry("600x600")
        except Exception:
            pass
    try:
        win.minsize(600, 600)
        win.maxsize(600, 600)
        win.resizable(False, False)
    except Exception:
        pass





