try:
    INVENTARIO_BALANCOS_FILE = os.path.join(DATA_DIR, "inventario_balancos.json")
except Exception:
    INVENTARIO_BALANCOS_FILE = os.path.join(os.getcwd(), "inventario_balancos.json")


def _inv_float(v, default=0.0):
    try:
        if 'parse_br_float' in globals():
            r = parse_br_float(v)
            return default if r is None else float(r)
    except Exception:
        pass
    try:
        return float(str(v).replace('R$', '').replace('.', '').replace(',', '.').strip())
    except Exception:
        try:
            return float(v)
        except Exception:
            return default


def _inv_money(v):
    try:
        if 'format_br_currency' in globals():
            return format_br_currency(_inv_float(v, 0.0))
    except Exception:
        pass
    try:
        return ("R$ %.2f" % _inv_float(v, 0.0)).replace('.', ',')
    except Exception:
        return "R$ 0,00"


def _inv_now():
    try:
        return datetime.datetime.now().strftime("%d/%m/%Y %H:%M:%S")
    except Exception:
        return ""


def _inv_now_file():
    try:
        return datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    except Exception:
        return "inventario"


def _inv_load_history():
    try:
        return load_data(INVENTARIO_BALANCOS_FILE, {})
    except Exception:
        try:
            if os.path.exists(INVENTARIO_BALANCOS_FILE):
                with open(INVENTARIO_BALANCOS_FILE, 'r', encoding='utf-8') as f:
                    return json.load(f)
        except Exception:
            pass
    return {}


def _inv_save_history(data):
    try:
        return save_data(INVENTARIO_BALANCOS_FILE, data)
    except Exception:
        try:
            os.makedirs(os.path.dirname(INVENTARIO_BALANCOS_FILE), exist_ok=True)
            with open(INVENTARIO_BALANCOS_FILE, 'w', encoding='utf-8') as f:
                json.dump(data, f, indent=2, ensure_ascii=False)
            return True
        except Exception:
            return False


