# ═══════════════════════════════════════════════════════════════════════════════
# 🖥️ PATCH - MAXIMIZAR TELAS DE INVENTÁRIO/BALANÇO E BALANÇAS
# ═══════════════════════════════════════════════════════════════════════════════
def _quantum_force_maximized_window(win, min_w=900, min_h=600):
    """Maximiza uma janela Tk/Toplevel com fallback seguro e mantém foco."""
    try:
        if win is None or not win.winfo_exists():
            return
    except Exception:
        return
    try:
        win.minsize(int(min_w), int(min_h))
    except Exception:
        pass
    try:
        win.update_idletasks()
    except Exception:
        pass
    try:
        sw = win.winfo_screenwidth()
        sh = win.winfo_screenheight()
        w = max(int(min_w), int(sw * 0.92))
        h = max(int(min_h), int(sh * 0.86))
        x = max(0, (sw - w) // 2)
        y = max(0, (sh - h) // 2)
        win.geometry(f"{w}x{h}+{x}+{y}")
    except Exception:
        pass
    try:
        win.state('zoomed')
    except Exception:
        try:
            win.attributes('-zoomed', True)
        except Exception:
            try:
                sw = win.winfo_screenwidth()
                sh = win.winfo_screenheight()
                win.geometry(f"{sw}x{sh}+0+0")
            except Exception:
                pass
    try:
        win.lift()
        win.focus_force()
    except Exception:
        pass

def _quantum_schedule_maximized_window(win, min_w=900, min_h=600):
    try:
        _quantum_force_maximized_window(win, min_w, min_h)
        win.after(150, lambda: _quantum_force_maximized_window(win, min_w, min_h))
        win.after(500, lambda: _quantum_force_maximized_window(win, min_w, min_h))
    except Exception:
        pass






