# 🏢 PATCH - NOME DA EMPRESA SEM ALTERAR LAYOUT
# Não troca grid/pack, não muda frames, não altera tamanhos.
# Apenas troca o texto exibido no cabeçalho e no caption da janela.
# ═══════════════════════════════════════════════════════════════════════════════

def quantum_empresa_nome_exibicao_sem_layout(empresa_data=None, default_nome="QUANTUM"):
    try:
        dados = empresa_data if isinstance(empresa_data, dict) else None
        if not dados:
            try:
                dados = load_data(EMPRESA_FILE, DEFAULT_EMPRESA)
            except Exception:
                dados = {}
        for chave in ("nome", "nome_fantasia", "razao_social", "empresa", "fantasia"):
            valor = str((dados or {}).get(chave, "") or "").strip()
            if valor:
                return valor
    except Exception:
        pass
    return str(default_nome or "QUANTUM")

def quantum_aplicar_nome_empresa_sem_mudar_layout(app, default_nome="QUANTUM"):
    """Aplica nome cadastrado sem mexer em layout, pack, grid ou tamanho."""
    try:
        nome = quantum_empresa_nome_exibicao_sem_layout(getattr(app, "empresa_data", None), default_nome)
        usuario = globals().get("logged_user", "")
        root = getattr(app, "root", None)
        if root is not None:
            try:
                root.title(f"{nome} - Usuário: {usuario}")
            except Exception:
                pass

            # Troca somente texto dos labels já existentes.
            # Não troca pack/grid/place, não recria widget e não muda fonte.
            alvos = (
                "FARMA QUANTUM",
                "💊 FARMA QUANTUM",
                "⚕️ FARMA QUANTUM",
                "LOJA QUANTUM",
                "🏪 LOJA QUANTUM",
                "🛒 LOJA QUANTUM",
            )

            def _varrer(widget):
                try:
                    atual = str(widget.cget("text"))
                    if atual in alvos:
                        widget.configure(text=nome)
                except Exception:
                    pass
                try:
                    for child in widget.winfo_children():
                        _varrer(child)
                except Exception:
                    pass

            _varrer(root)
        return nome
    except Exception:
        return str(default_nome or "QUANTUM")

try:
    if "PDVSuperApp" in globals() and not getattr(PDVSuperApp, "_quantum_empresa_nome_sem_layout_patch", False):
        _orig_init_nome_empresa_sem_layout = PDVSuperApp.__init__

        def _init_nome_empresa_sem_layout(self, *args, **kwargs):
            _orig_init_nome_empresa_sem_layout(self, *args, **kwargs)
            try:
                quantum_aplicar_nome_empresa_sem_mudar_layout(self, "FARMA QUANTUM")
            except Exception:
                pass
            try:
                self.root.after(300, lambda: quantum_aplicar_nome_empresa_sem_mudar_layout(self, "FARMA QUANTUM"))
                self.root.after(1200, lambda: quantum_aplicar_nome_empresa_sem_mudar_layout(self, "FARMA QUANTUM"))
            except Exception:
                pass

        PDVSuperApp.__init__ = _init_nome_empresa_sem_layout
        PDVSuperApp._quantum_empresa_nome_sem_layout_patch = True
except Exception:
    pass

