# 📦 PATCH - VISIBILIDADE REAL DO MENU INVENTÁRIO PELO CHECKBOX
# Reforça a remoção do menu Inventário quando o checkbox estiver desmarcado.
# ═══════════════════════════════════════════════════════════════════════════════

def _quantum_bool_cfg_inventario(valor, default=True):
    try:
        if valor is None:
            return bool(default)
        if isinstance(valor, bool):
            return valor
        if isinstance(valor, (int, float)):
            return bool(valor)
        s = str(valor).strip().lower()
        if s in ("1", "true", "sim", "s", "yes", "y", "on", "marcado"):
            return True
        if s in ("0", "false", "nao", "não", "n", "no", "off", "desmarcado"):
            return False
    except Exception:
        pass
    return bool(default)

def _quantum_inventario_visivel_cfg(app):
    """Lê menu_inventario_visivel do app, config.json e banco, com prioridade para valor salvo."""
    key = "menu_inventario_visivel"
    default = True

    # 1. app.config_data
    try:
        cfg = getattr(app, "config_data", {}) or {}
        if key in cfg:
            return _quantum_bool_cfg_inventario(cfg.get(key), default)
    except Exception:
        pass

    # 2. config.json
    try:
        cfg_file = load_data(CONFIG_FILE, DEFAULT_CONFIG)
        if isinstance(cfg_file, dict) and key in cfg_file:
            try:
                if getattr(app, "config_data", None) is not None:
                    app.config_data[key] = cfg_file.get(key)
            except Exception:
                pass
            return _quantum_bool_cfg_inventario(cfg_file.get(key), default)
    except Exception:
        pass

    # 3. banco configuracoes
    try:
        db = get_db()
        row = db.fetchone("SELECT valor FROM configuracoes WHERE chave=%s", (key,))
        if row:
            val = row.get("valor") if isinstance(row, dict) else row[0]
            try:
                if getattr(app, "config_data", None) is not None:
                    app.config_data[key] = _quantum_bool_cfg_inventario(val, default)
            except Exception:
                pass
            return _quantum_bool_cfg_inventario(val, default)
    except Exception:
        pass

    return default

def _quantum_menu_label_norm(txt):
    try:
        import unicodedata
        s = unicodedata.normalize("NFKD", str(txt or ""))
        s = "".join(c for c in s if not unicodedata.combining(c))
        return s.lower()
    except Exception:
        return str(txt or "").lower()

def _quantum_remover_menu_inventario_se_desmarcado(app):
    """Remove menu Inventário real do menubar quando checkbox estiver desmarcado."""
    try:
        if _quantum_inventario_visivel_cfg(app):
            return
        root = getattr(app, "root", None)
        if root is None:
            return
        menubar = root.nametowidget(root.cget("menu"))
        end = menubar.index("end")
        if end is None:
            return
        for i in range(end, -1, -1):
            try:
                if menubar.type(i) != "cascade":
                    continue
                label = menubar.entrycget(i, "label")
                norm = _quantum_menu_label_norm(label)
                if "inventario" in norm:
                    menubar.delete(i)
            except Exception:
                pass
    except Exception:
        pass

def _quantum_agendar_ocultar_menu_inventario(app):
    try:
        _quantum_remover_menu_inventario_se_desmarcado(app)
        root = getattr(app, "root", None)
        if root is not None:
            for ms in (100, 500, 1500, 3000):
                try:
                    root.after(ms, lambda app=app: _quantum_remover_menu_inventario_se_desmarcado(app))
                except Exception:
                    pass
    except Exception:
        pass

try:
    if "PDVSuperApp" in globals() and not getattr(PDVSuperApp, "_quantum_inventario_visibilidade_real_patch", False):
        _orig_pdv_create_menu_inv_vis = PDVSuperApp._create_menu

        def _patched_create_menu_inv_vis(self, *args, **kwargs):
            resultado = _orig_pdv_create_menu_inv_vis(self, *args, **kwargs)
            try:
                _quantum_agendar_ocultar_menu_inventario(self)
            except Exception:
                pass
            return resultado

        PDVSuperApp._create_menu = _patched_create_menu_inv_vis

        _orig_pdv_init_inv_vis = PDVSuperApp.__init__

        def _patched_init_inv_vis(self, *args, **kwargs):
            _orig_pdv_init_inv_vis(self, *args, **kwargs)
            try:
                _quantum_agendar_ocultar_menu_inventario(self)
            except Exception:
                pass

        PDVSuperApp.__init__ = _patched_init_inv_vis
        PDVSuperApp._quantum_inventario_visibilidade_real_patch = True
except Exception:
    pass






