def _fq_extras_ensure_db():
    db = get_db()
    db.execute("CREATE TABLE IF NOT EXISTS configuracoes (id INT AUTO_INCREMENT PRIMARY KEY, chave VARCHAR(191), valor TEXT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci")
    try:
        db.execute("ALTER TABLE configuracoes ADD COLUMN valor TEXT")
    except Exception:
        pass
    return db

def _fq_extras_persist_db(cfg):
    try:
        db = _fq_extras_ensure_db()
        for _k in ("menu_relatorios_farma_visivel", "menu_farmacia_pro_visivel", "menu_ambulatorio_visivel", "menu_tratamento_visivel", "menu_balanca_ultra_visivel", "menu_inventario_visivel"):
            _v = "1" if cfg.get(_k) else "0"
            ex = db.fetchone("SELECT id FROM configuracoes WHERE chave=%s", (_k,))
            if ex:
                db.execute("UPDATE configuracoes SET valor=%s WHERE chave=%s", (_v, _k))
            else:
                db.execute("INSERT INTO configuracoes (chave, valor) VALUES (%s, %s)", (_k, _v))
    except Exception as _e:
        print("[EXTRAS] persist db:", _e)

def _fq_extras_load_db(cfg):
    try:
        db = _fq_extras_ensure_db()
        rows = db.fetchall("SELECT chave, valor FROM configuracoes WHERE chave IN ('menu_relatorios_farma_visivel','menu_farmacia_pro_visivel','menu_ambulatorio_visivel','menu_tratamento_visivel','menu_balanca_ultra_visivel','menu_inventario_visivel')")
        for r in (rows or []):
            cfg[r["chave"]] = (str(r["valor"]) in ("1", "True", "true"))
    except Exception:
        pass
    return cfg

def _fq_norm_lbl(s):
    import unicodedata
    s = unicodedata.normalize("NFKD", str(s))
    s = "".join(c for c in s if not unicodedata.combining(c))
    return s.lower()

def _fq_aplicar_visibilidade_menus_farma(app):
    import unicodedata
    def _nl(s):
        s = unicodedata.normalize("NFKD", str(s))
        return "".join(c for c in s if not unicodedata.combining(c)).lower()
    alvos = [
        ("menu_relatorios_farma_visivel", ["relatorio"]),
        ("menu_farmacia_pro_visivel", ["farmacia pro", "farma pro", "farmacia profissional"]),
        ("menu_ambulatorio_visivel", ["ambulator", "prontuario"]),
        ("menu_tratamento_visivel", ["tratamento"]),
        ("menu_balanca_ultra_visivel", ["balanca ultra", "balança ultra"]),
        ("menu_inventario_visivel", ["inventario", "inventário"]),
    ]
    primeira = not getattr(app, "_fq_menu_diag", False)
    def _varre(menu, depth):
        try:
            fim = menu.index("end")
        except Exception:
            return
        if fim is None:
            return
        for i in range(fim, -1, -1):
            try:
                if menu.type(i) != "cascade":
                    continue
                lbl = menu.entrycget(i, "label")
            except Exception:
                continue
            nl = _nl(lbl)
            if primeira:
                print("[EXTRAS-MENU]", ("  " * depth) + repr(lbl))
            achou = False
            for chave, kws in alvos:
                if any(k in nl for k in kws):
                    achou = True
                    if not app.config_data.get(chave, False):
                        try:
                            menu.delete(i)
                        except Exception:
                            pass
                    break
            if not achou:
                try:
                    sub = menu.nametowidget(menu.entrycget(i, "menu"))
                    _varre(sub, depth + 1)
                except Exception:
                    pass
    try:
        mb = app.root.nametowidget(app.root["menu"])
        _varre(mb, 0)
        app._fq_menu_diag = True
    except Exception as _e:
        print("[EXTRAS-MENU] erro:", _e)
    try:
        app.root.after(2500, lambda: _fq_aplicar_visibilidade_menus_farma(app))
    except Exception:
        pass
try:
    _FQ_OrigInit = PDVSuperApp.__init__
    def _fq_new_init(self, *a, **k):
        _FQ_OrigInit(self, *a, **k)
        try:
            _fq_extras_load_db(self.config_data)
        except Exception:
            pass
        try:
            self.root.after(1500, lambda: _fq_aplicar_visibilidade_menus_farma(self))
        except Exception:
            pass
    PDVSuperApp.__init__ = _fq_new_init

    def _fq_renomear_admin(self, novo):
        global logged_user, logged_user_data
        from tkinter import messagebox as _mb
        novo = (novo or "").strip()
        if not novo:
            _mb.showwarning("Renomear", "Informe o novo nome do admin.")
            return
        novo_login = novo.lower()
        try:
            db = get_db()

            # Garante colunas usadas pelo login/renomeação em bancos antigos.
            for _col, _def in {
                "username": "VARCHAR(80) DEFAULT ''",
                "usuario": "VARCHAR(80) DEFAULT ''",
                "nome": "VARCHAR(160) DEFAULT ''",
                "password_hash": "VARCHAR(255) DEFAULT ''",
                "senha": "VARCHAR(255) DEFAULT ''",
                "nivel_acesso": "VARCHAR(50) DEFAULT 'admin'",
                "nivel": "VARCHAR(50) DEFAULT 'admin'",
                "permissoes": "LONGTEXT NULL",
                "ativo": "TINYINT DEFAULT 1",
                "updated_at": "DATETIME NULL",
            }.items():
                try:
                    db.execute(f"ALTER TABLE usuarios ADD COLUMN {_col} {_def}")
                except Exception:
                    pass

            try:
                atual = logged_user
            except Exception:
                atual = "adm"
            atual = (atual or "adm").strip().lower()

            # Localiza o admin de forma robusta. Em bancos antigos ele pode estar em
            # username, em usuario, ou apenas ser o primeiro admin com permissao total.
            row = db.fetchone("""
                SELECT id, username, usuario, password_hash, senha
                FROM usuarios
                WHERE LOWER(COALESCE(username,'')) = %s
                   OR LOWER(COALESCE(usuario,'')) = %s
                   OR LOWER(COALESCE(username,'')) = 'adm'
                   OR LOWER(COALESCE(usuario,'')) = 'adm'
                ORDER BY CASE
                    WHEN LOWER(COALESCE(username,'')) = %s THEN 0
                    WHEN LOWER(COALESCE(usuario,'')) = %s THEN 1
                    WHEN LOWER(COALESCE(username,'')) = 'adm' THEN 2
                    ELSE 3
                END
                LIMIT 1
            """, (atual, atual, atual, atual))

            if not row:
                row = db.fetchone("""
                    SELECT id, username, usuario, password_hash, senha
                    FROM usuarios
                    WHERE ativo = 1 AND (nivel_acesso = 'admin' OR nivel = 'admin' OR permissoes LIKE '%*%')
                    ORDER BY id ASC
                    LIMIT 1
                """)

            if not row:
                _mb.showerror("Renomear", "Não encontrei o usuário administrador para renomear.")
                return

            admin_id = row.get('id') if isinstance(row, dict) else row[0]

            # Evita duplicar caso já exista outro usuário com o novo login.
            duplicado = db.fetchone("""
                SELECT id FROM usuarios
                WHERE (LOWER(COALESCE(username,'')) = %s OR LOWER(COALESCE(usuario,'')) = %s)
                  AND id <> %s
                LIMIT 1
            """, (novo_login, novo_login, admin_id))
            if duplicado:
                _mb.showwarning("Renomear", "Já existe outro usuário com esse login. Escolha outro nome.")
                return

            senha_atual = ""
            try:
                senha_atual = str((row.get('password_hash') or row.get('senha') or '') if isinstance(row, dict) else '')
            except Exception:
                senha_atual = ""
            if not senha_atual.strip():
                senha_atual = hash_password("9652")

            permissoes_admin = json.dumps(["*"], ensure_ascii=False)

            # Importante: atualiza username E usuario. Assim o admin continua aparecendo
            # na tela de login e não fica preso ao nome antigo.
            db.execute("""
                UPDATE usuarios SET
                    username = %s,
                    usuario = %s,
                    nome = %s,
                    password_hash = %s,
                    senha = %s,
                    nivel_acesso = 'admin',
                    nivel = 'admin',
                    permissoes = %s,
                    ativo = 1,
                    updated_at = CURRENT_TIMESTAMP
                WHERE id = %s
            """, (novo_login, novo_login, novo, senha_atual, senha_atual, permissoes_admin, admin_id))

            try:
                logged_user = novo_login
                if isinstance(logged_user_data, dict):
                    logged_user_data['usuario'] = novo_login
                    logged_user_data['nome'] = novo
                    logged_user_data['nivel_acesso'] = 'admin'
                    logged_user_data['permissoes'] = ['*']
            except Exception:
                pass

            _mb.showinfo("Renomear", "Admin renomeado para '" + novo_login + "'. Ele continuará aparecendo na tela de login com esse novo nome.")
        except Exception as _e:
            _mb.showerror("Renomear", "Falha ao renomear: " + str(_e))
    PDVSuperApp._fq_renomear_admin = _fq_renomear_admin
except Exception as _e:
    print("[EXTRAS] wrap init:", _e)



