def _qmysql_ext_ensure_table():
    """Cria a tabela de configuração do envio MySQL externo sem apagar dados."""
    try:
        _qmysql_ext_db_execute("""
            CREATE TABLE IF NOT EXISTS quantum_envio_mysql_externo (
                id INT AUTO_INCREMENT PRIMARY KEY,
                ativo TINYINT(1) NOT NULL DEFAULT 0,
                servidor_mysql VARCHAR(255) NULL,
                nome_banco_mysql VARCHAR(255) NULL,
                usuario_mysql VARCHAR(255) NULL,
                senha_mysql TEXT NULL,
                criado_em DATETIME NULL DEFAULT CURRENT_TIMESTAMP,
                atualizado_em DATETIME NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
        """)
        for _col, _def in {
            "ativo": "TINYINT(1) NOT NULL DEFAULT 0",
            "servidor_mysql": "VARCHAR(255) NULL",
            "nome_banco_mysql": "VARCHAR(255) NULL",
            "usuario_mysql": "VARCHAR(255) NULL",
            "senha_mysql": "TEXT NULL",
            "criado_em": "DATETIME NULL DEFAULT CURRENT_TIMESTAMP",
            "atualizado_em": "DATETIME NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP",
        }.items():
            try:
                _qmysql_ext_db_execute(f"ALTER TABLE quantum_envio_mysql_externo ADD COLUMN {_col} {_def}")
            except Exception:
                pass
        try:
            _qmysql_ext_db_execute("""
                INSERT IGNORE INTO quantum_envio_mysql_externo
                (id, ativo, servidor_mysql, nome_banco_mysql, usuario_mysql, senha_mysql)
                VALUES (1, 0, '', '', '', '')
            """)
        except Exception:
            pass
        return True
    except Exception as _e:
        try:
            print("[MYSQL-EXTERNO] Aviso ao criar/verificar tabela:", _e)
        except Exception:
            pass
        return False


def _qmysql_ext_bool(v):
    try:
        return str(v).strip().lower() in ("1", "true", "sim", "yes", "on", "ativo", "marcado")
    except Exception:
        return bool(v)


def _qmysql_ext_load_cfg(app=None):
    cfg = dict(_QUANTUM_MYSQL_EXTERNO_DEFAULTS)
    try:
        if app is not None:
            cfg.update({k: (getattr(app, "config_data", {}) or {}).get(k, v) for k, v in _QUANTUM_MYSQL_EXTERNO_DEFAULTS.items()})
    except Exception:
        pass
    try:
        _qmysql_ext_ensure_table()
        row = _qmysql_ext_db_fetchone("SELECT * FROM quantum_envio_mysql_externo WHERE id = 1")
        if row:
            cfg.update({
                "envio_mysql_externo_ativo": bool(row.get("ativo")),
                "envio_mysql_externo_servidor": row.get("servidor_mysql") or "",
                "envio_mysql_externo_banco": row.get("nome_banco_mysql") or "",
                "envio_mysql_externo_usuario": row.get("usuario_mysql") or "",
                "envio_mysql_externo_senha": row.get("senha_mysql") or "",
            })
    except Exception:
        pass
    return cfg


def _qmysql_ext_save_cfg(app, cfg):
    try:
        if app is not None:
            if not hasattr(app, "config_data") or app.config_data is None:
                app.config_data = {}
            app.config_data.update(cfg)
            try:
                save_data(CONFIG_FILE, app.config_data)
            except Exception:
                try:
                    quantum_salvar_config_rapido(app.config_data)
                except Exception:
                    pass
    except Exception:
        pass

    try:
        _qmysql_ext_ensure_table()
        _qmysql_ext_db_execute("""
            INSERT INTO quantum_envio_mysql_externo
            (id, ativo, servidor_mysql, nome_banco_mysql, usuario_mysql, senha_mysql)
            VALUES (1, %s, %s, %s, %s, %s)
            ON DUPLICATE KEY UPDATE
                ativo = VALUES(ativo),
                servidor_mysql = VALUES(servidor_mysql),
                nome_banco_mysql = VALUES(nome_banco_mysql),
                usuario_mysql = VALUES(usuario_mysql),
                senha_mysql = VALUES(senha_mysql),
                atualizado_em = CURRENT_TIMESTAMP
        """, (
            1 if _qmysql_ext_bool(cfg.get("envio_mysql_externo_ativo")) else 0,
            cfg.get("envio_mysql_externo_servidor") or "",
            cfg.get("envio_mysql_externo_banco") or "",
            cfg.get("envio_mysql_externo_usuario") or "",
            cfg.get("envio_mysql_externo_senha") or "",
        ))
    except Exception as _e:
        try:
            print("[MYSQL-EXTERNO] Aviso ao salvar no banco:", _e)
        except Exception:
            pass
    return True


def _qmysql_ext_show_window(self):
    cfg = _qmysql_ext_load_cfg(self)

    win = tk.Toplevel(self.root)
    win.title("🌐 Envio mysql externo")
    try:
        win.geometry("560x360")
        win.minsize(520, 320)
        win.transient(self.root)
        win.grab_set()
    except Exception:
        pass

    main = ttk.Frame(win, padding=18)
    main.pack(fill=tk.BOTH, expand=True)

    ttk.Label(main, text="🌐 Envio mysql externo", font=("Segoe UI", 15, "bold")).pack(anchor="w")
    ttk.Label(
        main,
        text="Configure os dados do servidor MySQL externo para futura integração/envio de dados.",
        wraplength=500
    ).pack(anchor="w", pady=(2, 12))

    form = ttk.LabelFrame(main, text="Dados do MySQL externo")
    form.pack(fill=tk.X, expand=False)

    servidor_var = tk.StringVar(value=str(cfg.get("envio_mysql_externo_servidor") or ""))
    banco_var = tk.StringVar(value=str(cfg.get("envio_mysql_externo_banco") or ""))
    usuario_var = tk.StringVar(value=str(cfg.get("envio_mysql_externo_usuario") or ""))
    senha_var = tk.StringVar(value=str(cfg.get("envio_mysql_externo_senha") or ""))
    ativo_var = tk.BooleanVar(value=_qmysql_ext_bool(cfg.get("envio_mysql_externo_ativo")))

    def _row(r, label, var, show=None):
        ttk.Label(form, text=label).grid(row=r, column=0, sticky="w", padx=10, pady=7)
        ent = ttk.Entry(form, textvariable=var, show=show or "")
        ent.grid(row=r, column=1, sticky="ew", padx=10, pady=7)
        return ent

    form.columnconfigure(1, weight=1)

    ent_servidor = _row(0, "Servidor Mysql:", servidor_var)
    ent_banco = _row(1, "Nome do banco Mysql:", banco_var)
    ent_usuario = _row(2, "Usuario Mysql:", usuario_var)
    ent_senha = _row(3, "SenhaMysql:", senha_var, show="*")

    ttk.Checkbutton(form, text="Ativar", variable=ativo_var).grid(row=4, column=1, sticky="w", padx=10, pady=(8, 10))

    status_var = tk.StringVar(value="Informe os dados e clique em Gravar.")
    ttk.Label(main, textvariable=status_var, foreground="#475569").pack(anchor="w", pady=(8, 0))

    def gravar():
        novo = {
            "envio_mysql_externo_ativo": bool(ativo_var.get()),
            "envio_mysql_externo_servidor": servidor_var.get().strip(),
            "envio_mysql_externo_banco": banco_var.get().strip(),
            "envio_mysql_externo_usuario": usuario_var.get().strip(),
            "envio_mysql_externo_senha": senha_var.get().strip(),
        }
        _qmysql_ext_save_cfg(self, novo)
        status_var.set("Configuração gravada com sucesso.")
        try:
            messagebox.showinfo("Envio mysql externo", "Configuração gravada com sucesso.", parent=win)
        except Exception:
            pass

    botoes = ttk.Frame(main)
    botoes.pack(fill=tk.X, pady=(14, 0))
    ttk.Button(botoes, text="Gravar", command=gravar).pack(side=tk.LEFT, padx=(0, 8))
    ttk.Button(botoes, text="Cancelar", command=win.destroy).pack(side=tk.LEFT)

    try:
        ent_servidor.focus_set()
    except Exception:
        pass

    try:
        quantum_autofit_form_dialog(win, min_w=560, min_h=360, extra_h=30)
    except Exception:
        pass


def _qmysql_ext_add_menu(app):
    try:
        mb = app.root.nametowidget(app.root["menu"])
        end = mb.index("end")
        util_menu = None
        for i in range((end or 0) + 1):
            try:
                lbl = str(mb.entrycget(i, "label")).lower()
                if "utilit" in lbl:
                    util_menu = mb.nametowidget(mb.entrycget(i, "menu"))
                    break
            except Exception:
                pass
        if util_menu is None:
            return False

        labels = []
        try:
            uend = util_menu.index("end")
            for j in range((uend or 0) + 1):
                try:
                    labels.append(str(util_menu.entrycget(j, "label")))
                except Exception:
                    pass
        except Exception:
            pass

        if any("envio mysql externo" in str(x).lower() for x in labels):
            return True

        try:
            util_menu.add_separator()
        except Exception:
            pass
        util_menu.add_command(label="6.8  🌐 Envio mysql externo", command=app.show_envio_mysql_externo_window)
        return True
    except Exception as _e:
        try:
            print("[MYSQL-EXTERNO] Não foi possível adicionar submenu:", _e)
        except Exception:
            pass
        return False


try:
    if "PDVSuperApp" in globals():
        PDVSuperApp.show_envio_mysql_externo_window = _qmysql_ext_show_window

        _qmysql_ext_orig_create_menu = getattr(PDVSuperApp, "_create_menu", None)
        if callable(_qmysql_ext_orig_create_menu) and not getattr(PDVSuperApp, "_qmysql_ext_menu_patch", False):
            def _qmysql_ext_create_menu_patched(self, *args, **kwargs):
                result = _qmysql_ext_orig_create_menu(self, *args, **kwargs)
                try:
                    _qmysql_ext_add_menu(self)
                except Exception as _e:
                    try:
                        print("[MYSQL-EXTERNO] Falha ao inserir submenu:", _e)
                    except Exception:
                        pass
                return result
            PDVSuperApp._create_menu = _qmysql_ext_create_menu_patched
            PDVSuperApp._qmysql_ext_menu_patch = True

        _qmysql_ext_orig_init = getattr(PDVSuperApp, "__init__", None)
        if callable(_qmysql_ext_orig_init) and not getattr(PDVSuperApp, "_qmysql_ext_init_patch", False):
            def _qmysql_ext_init_patched(self, *args, **kwargs):
                _qmysql_ext_orig_init(self, *args, **kwargs)
                try:
                    for _k, _v in _QUANTUM_MYSQL_EXTERNO_DEFAULTS.items():
                        self.config_data.setdefault(_k, _v)
                    _qmysql_ext_ensure_table()
                    self.root.after(800, lambda: _qmysql_ext_add_menu(self))
                except Exception as _e:
                    try:
                        print("[MYSQL-EXTERNO] Falha no init:", _e)
                    except Exception:
                        pass
            PDVSuperApp.__init__ = _qmysql_ext_init_patched
            PDVSuperApp._qmysql_ext_init_patch = True

        try:
            print("[MYSQL-EXTERNO] Patch Envio mysql externo aplicado.")
        except Exception:
            pass
except Exception as _e:
    try:
        print("[MYSQL-EXTERNO] Patch não aplicado:", _e)
    except Exception:
        pass

